function moop_v1_expression_describe(array $e): array {
    $groups = [];
    foreach ($e['samples'] as $s) $groups[$s['group_name']] = ($groups[$s['group_name']] ?? 0) + 1;
    return ['experiment' => $e['slug'], 'label' => $e['label'], 'unit' => $e['unit'],
            'citation' => (string) ($e['meta']['citation'] ?? ''), 'assay' => (string) ($e['meta']['assay'] ?? ''),
            'detect_threshold' => $e['detect_threshold'],
            'groups' => array_map(fn($k, $v) => ['group' => $k, 'samples' => $v], array_keys($groups), $groups)];
}

functions.comment:
/**
* One organism database, all its gene sets in scope at once (the annotation scan is per database).
* @param list<int> $gene_set_ids
* @return array{by_set: array<int, array<string, list<array>>>, hgnc_symbols: array<string,string>}
*/

functions.code:
function moop_v1_human_genes(string $db_file, array $gene_set_ids, array $symbols, array $hgnc): array {
    $dbh = getDbConnection($db_file);
    // 1. The asked-for annotations: one pass over the four human sources' rows (no index on the source
    //    column, so this is the scan -- done once per database, not once per gene set: 26 s -> see below).
    $st = $dbh->prepare("SELECT a.annotation_id, s.annotation_source_name, a.annotation_accession, a.annotation_description,
                                upper(substr(a.annotation_description, 1, instr(a.annotation_description, ':') - 1))
                           FROM annotation_source s
                          CROSS JOIN annotation a ON a.annotation_source_id = s.annotation_source_id
                          WHERE s.annotation_source_name IN (SELECT value FROM json_each(?))
                            AND (upper(substr(a.annotation_description, 1, instr(a.annotation_description, ':') - 1)) IN (SELECT value FROM json_each(?))
                                 OR a.annotation_accession IN (SELECT value FROM json_each(?)))");
    $st->execute([json_encode(array_keys(HUMAN_V1_SOURCES)), json_encode($symbols), json_encode($hgnc)]);
    $ann = [];
    $hgnc_symbols = [];
    foreach ($st->fetchAll(PDO::FETCH_NUM) as [$id, $src, $acc, $d, $sym]) {
        if (str_starts_with((string) $acc, 'HGNC:')) $hgnc_symbols[$acc] = (string) $sym;
        $ann[(int) $id] = ['sym' => (string) $sym] + moop_v1_human_evidence((string) $src, (string) $d);
    }
    if (!$ann) return ['by_set' => [], 'hgnc_symbols' => $hgnc_symbols];

    // 2. Their features in the gene sets asked for (annotation_id is indexed), up to the gene.
    $st = $dbh->prepare("SELECT fa.annotation_id, f.gene_set_id, COALESCE(f.parent_feature_id, f.feature_id)
                           FROM feature_annotation fa CROSS JOIN feature f ON f.feature_id = fa.feature_id
                          WHERE fa.annotation_id IN (SELECT value FROM json_each(?))
                            AND f.gene_set_id IN (SELECT value FROM json_each(?))");
    $st->execute([json_encode(array_keys($ann)), json_encode($gene_set_ids)]);
    $hits = [];   // gene_set_id => "sym\x1fgene" => evidence list
    foreach ($st->fetchAll(PDO::FETCH_NUM) as [$aid, $gsid, $gene]) {
        $a = $ann[(int) $aid];
        $e = ['source' => $a['source'], 'relation' => $a['relation'], 'rank' => $a['rank']];
        $k = $a['sym'] . "\x1f" . (int) $gene;
        if (!in_array($e, $hits[(int) $gsid][$k] ?? [], true)) $hits[(int) $gsid][$k][] = $e;
    }
    $gene_ids = [];
    foreach ($hits as $set) foreach (array_keys($set) as $k) $gene_ids[(int) explode("\x1f", $k)[1]] = true;
    if (!$gene_ids) return ['by_set' => [], 'hgnc_symbols' => $hgnc_symbols];
    $st = $dbh->prepare("SELECT f.feature_id, f.feature_uniquename, " . moop_gene_name_sql('f') . ", f.feature_description
                           FROM feature f WHERE f.feature_id IN (SELECT value FROM json_each(?))");
    $st->execute([json_encode(array_keys($gene_ids))]);
    $info = [];
    foreach ($st->fetchAll(PDO::FETCH_NUM) as [$id, $u, $n, $d]) {
        $info[(int) $id] = ['gene' => $u, 'name' => moop_gene_symbol($n, $u), 'description' => (string) $d];
    }

    $by_set = [];
    foreach ($hits as $gsid => $set) {
        $by_human = [];
        foreach ($set as $k => $ev) {
            [$sym, $gid] = explode("\x1f", $k);
            if (!isset($info[(int) $gid])) continue;
            usort($ev, fn($a, $b) => $a['rank'] <=> $b['rank']);
            $by_human[$sym][] = $info[(int) $gid] + ['_best' => $ev[0]['rank'],
                'evidence' => array_map(fn($e) => array_diff_key($e, ['rank' => 1]), $ev)];
        }
        foreach ($by_human as &$genes) {
            usort($genes, fn($a, $b) => [$a['_best'], $a['gene']] <=> [$b['_best'], $b['gene']]);
            $genes = array_map(fn($g) => array_diff_key($g, ['_best' => 1]), $genes);
        }
        unset($genes);
        ksort($by_human);
        $by_set[$gsid] = $by_human;
    }
    return ['by_set' => $by_set, 'hgnc_symbols' => $hgnc_symbols];
}

functions.comment:
/**
* One annotation's evidence: {source label, relation, rank}. OMA rows end "(1:many)" or "(1:1, HOG:...)";
* the closest-gene rows end "[OMA ortholog (1:1)]" / "[via mouse ortholog (OMA 1:1) > Ensembl Compara
* (one2one)]" (orthology) or "[reciprocal best hit (MMseqs2)]" / "[best DIAMOND hit ...]" (similarity).
*/

functions.code:
function moop_v1_human_evidence(string $src, string $d): array {
    [$label, $rank] = HUMAN_V1_SOURCES[$src];
    if ($src === 'Closest human gene (HGNC)') {
        $how = preg_match('/\[([^\[\]]*)\]\s*$/', $d, $m) ? trim($m[1]) : '';
        $orth = preg_match('/ortholog|Compara/i', $how);
        return ['source' => $orth ? 'closest human gene: ortholog' : 'closest human gene: homolog by similarity (not shown to be an ortholog)',
                'relation' => $how, 'rank' => $orth ? 4 : 5];
    }
    $rel = preg_match('/\(([^()]*)\)\s*$/', $d, $m) ? trim(preg_replace('/,?\s*(HOG|OMA group)\b.*$/', '', $m[1])) : '';
    return ['source' => $label, 'relation' => $rel, 'rank' => $rank];
}

function moop_v1_search_genes(string $db_file, int $gene_set_id, array $rows): array {
    $uniq = array_values(array_unique(array_column($rows, 'feature_uniquename')));
    $dbh  = getDbConnection($db_file);
    // Each matched feature -> its root (the gene). Transcripts are one level down, proteins/CDS two.
    $st = $dbh->prepare("WITH RECURSIVE up(start, id, parent, depth) AS (
                             SELECT feature_uniquename, feature_id, parent_feature_id, 0 FROM feature
                              WHERE gene_set_id = ? AND feature_uniquename IN (SELECT value FROM json_each(?))
                             UNION ALL
                             SELECT up.start, f.feature_id, f.parent_feature_id, up.depth + 1
                               FROM feature f JOIN up ON f.feature_id = up.parent WHERE up.depth < 4)
                         SELECT up.start, f.feature_uniquename, " . moop_gene_name_sql('f') . " AS name, f.feature_description
                           FROM up JOIN feature f ON f.feature_id = up.id WHERE up.parent IS NULL");
    $st->execute([$gene_set_id, json_encode($uniq)]);
    $root = [];
    foreach ($st->fetchAll(PDO::FETCH_NUM) as [$start, $gene, $name, $desc]) {
        $root[$start] = ['gene' => $gene, 'name' => moop_gene_symbol($name, $gene), 'description' => (string) $desc];
    }
    $genes = [];
    foreach ($rows as $r) {
        $g = $root[$r['feature_uniquename']] ?? null;
        if (!$g) continue;
        $e = &$genes[$g['gene']];
        $e ??= $g + ['matched_in' => []];
        $why = ($r['annotation_accession'] ?? '') !== ''
            ? ['source' => (string) $r['annotation_source_name'], 'accession' => (string) $r['annotation_accession'],
               'text' => mb_substr(decodeAnnotationText((string) ($r['annotation_description'] ?? '')), 0, 160)]
            : ['source' => 'gene', 'accession' => '', 'text' => 'name, description or ID'];
        if (count($e['matched_in']) < 3 && !in_array($why, $e['matched_in'], true)) $e['matched_in'][] = $why;
        unset($e);
    }
    return array_values($genes);
}

functions.comment:
/**
* Private constructor - use getInstance() instead
*/

functions.code:
public static function getInstance()
    {
        if (self::$instance === null) {
            self::$instance = new self();
        }
        return self::$instance;
    }

public function initialize($site_config_path, $tools_config_path)
    {
        if ($this->loaded) {
            return true; // Already loaded
        }

        // Load site configuration
        if (!file_exists($site_config_path)) {
            $this->errors[] = "Site config not found: $site_config_path";
            return false;
        }

        $this->config = include $site_config_path;
        if (!is_array($this->config)) {
            $this->errors[] = "Site config must return an array";
            return false;
        }
        $this->shipped = $this->config;

        // Load editable configuration (overrides defaults from site_config.php)
        $editable_config_path = dirname($site_config_path) . '/config_editable.json';
        if (file_exists($editable_config_path)) {
            $editable_config = loadJsonFile($editable_config_path, []);
            if (is_array($editable_config)) {
                // Use the centralized whitelist
                foreach ($this->editableConfigKeys as $key) {
                    // Only override if value is set AND non-empty (preserve site_config defaults for empty values)
                    if (isset($editable_config[$key]) && ($editable_config[$key] !== '' && $editable_config[$key] !== null)) {
                        // Special handling for nested arrays - deep merge to preserve defaults
                        if (in_array($key, ['sequence_types', 'jbrowse2', 'blast_linkouts']) && is_array($editable_config[$key]) && is_array($this->config[$key] ?? [])) {
                            foreach ($editable_config[$key] as $sub_key => $sub_value) {
                                if ($key === 'sequence_types' && isset($this->config[$key][$sub_key])) {
                                    $this->config[$key][$sub_key] = array_merge($this->config[$key][$sub_key], $sub_value);
                                } else {
                                    $this->config[$key][$sub_key] = $sub_value;
                                }
                            }
                        } elseif ($key === 'turnstile' && is_array($editable_config[$key])) {
                            // The SECRET only ever comes from secrets.php (via site_config.php).
                            // Saving Site Configuration used to copy it into this file, where it
                            // then overrode secrets.php — a rotated secret was silently ignored.
                            $ts = $editable_config[$key];
                            unset($ts['secret_key']);
                            // An EMPTY site key saved from the form means "not set here" -- the same
                            // rule as every other setting -- so a site key kept in secrets.php is not
                            // blanked by an empty box (cuttingclass, 2026-11-09).
                            if (trim((string) ($ts['site_key'] ?? '')) === '') unset($ts['site_key']);
                            $this->config[$key] = array_merge($this->config[$key] ?? [], $ts);
                        } else {
                            $this->config[$key] = $editable_config[$key];
                        }
                    }
                }
            }
        }

        // Load tool configuration
        if (!file_exists($tools_config_path)) {
            $this->errors[] = "Tools config not found: $tools_config_path";
            return false;
        }

        $this->tools = include $tools_config_path;
        if (!is_array($this->tools)) {
            $this->errors[] = "Tools config must return an array";
            return false;
        }

        $this->loaded = true;
        return true;
    }

private function ensureLoaded()
    {
        if (!$this->loaded) {
            trigger_error('ConfigManager not initialized. Call initialize() first.', E_USER_WARNING);
            return false;
        }
        return true;
    }

public function get($key, $default = null)
    {
        if (!$this->ensureLoaded()) {
            return $default;
        }

        // Special handling: construct favicon_path from favicon_filename
        if ($key === 'favicon_path') {
            $site = $this->config['site'] ?? '';
            $images_dir = $this->config['images_dir'] ?? 'images';
            $favicon_filename = $this->config['favicon_filename'] ?? 'favicon.ico';
            return moop_url_base() . "/$images_dir/$favicon_filename";
        }

        if (array_key_exists($key, $this->config) || strpos($key, '.') === false) {
            return $this->config[$key] ?? $default;
        }
        $value = $this->config;
        foreach (explode('.', $key) as $k) {
