public function validate()
    {
        if (!$this->ensureLoaded()) {
            return false;
        }

        $this->errors = [];

        foreach ($this->requiredKeys as $key) {
            if (!isset($this->config[$key])) {
                $this->errors[] = "Missing required config: $key";
            }
