function has_access($required_level = 'PUBLIC', $resource_name = null) {
    $access_level = get_access_level();
    $user_access = get_user_access();

    // Level names are case-insensitive. $required_level is caller-supplied, and the
    // IP_IN_RANGE branch below decides on `!== 'ADMIN'` — so a caller writing
    // has_access('admin') would otherwise hand the whole trusted subnet admin rights.
    // Normalised inline (not via lib/functions_access.php) to keep this file, which is
    // loaded on every request, free of includes it does not already have.
    $required_level = strtoupper(trim((string)$required_level));
    $access_level   = strtoupper(trim((string)$access_level));

    // ADMIN can do everything, including satisfy an ADMIN requirement.
    if ($access_level === 'ADMIN') {
        return true;
    }

    // IP_IN_RANGE gets full DATA access (equivalent to a collaborator with every
    // organism) but is NOT an administrator — it must never satisfy an ADMIN
    // requirement, or the whole trusted subnet would gain admin privileges.
    if ($access_level === 'IP_IN_RANGE') {
        return $required_level !== 'ADMIN';
    }

    // Public access is always allowed
    if ($required_level === 'PUBLIC') {
        return true;
    }

    // Collaborator access check
    if ($required_level === 'COLLABORATOR' && $access_level === 'COLLABORATOR') {
        // If no specific resource is requested, grant access
        if ($resource_name === null) {
            return true;
        }
        // Check if user has access to this specific resource
        if (isset($user_access[$resource_name])) {
            return true;
        }
    }

    return false;
}

function require_access($required_level = 'COLLABORATOR', $resource_name = null) {
    if (!has_access($required_level, $resource_name)) {
        $config = ConfigManager::getInstance();
        $site = $config->getString('site');
        header("Location: " . moop_url_base() . "/access_denied.php");
        exit;
    }
}

function has_assembly_access($organism_name, $assembly_name) {
    // ADMIN and IP_IN_RANGE have access to everything
    if (has_access('ADMIN') || has_access('IP_IN_RANGE')) {
        return true;
    }

    // Public assemblies are accessible to everyone
    if (is_public_assembly($organism_name, $assembly_name)) {
        return true;
    }

    // Collaborators check their specific access list
    if (has_access('COLLABORATOR')) {
        $user_access = get_user_access();
        if (isset($user_access[$organism_name][$assembly_name])) {
            return true;
        }
    }

    return false;
}

function has_gene_set_access($organism_name, $assembly_name, $gene_set) {
    if (has_access('ADMIN') || has_access('IP_IN_RANGE')) {
        return true;
    }

    if (is_public_gene_set($organism_name, $assembly_name, $gene_set)) {
        return true;
    }

    return moop_collaborator_allows($organism_name, $assembly_name, $gene_set);
}

function moop_dataset_visible(string $organism, string $assembly, string $gene_set, string $analysis = ''): bool {
    static $memo = [];
    $key = "$organism\0$assembly\0$gene_set\0" . get_access_level() . "\0" . (get_username() ?? '');
    if (!isset($memo[$key])) {
        $ok = false;
        if ($gene_set === MOOP_BLAST_ONLY) {
            // The assembly itself, as a BLAST-only genome (moop_blast_only_genome()).
            $ok = moop_blast_only_genome($organism, $assembly) !== null
               && has_gene_set_access($organism, $assembly, MOOP_BLAST_ONLY);
        } elseif (moop_plain_name($organism) && moop_plain_name($assembly) && moop_plain_name($gene_set)) {
            $dir = rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/') . "/$organism/$assembly/$gene_set";
            $ok = is_dir($dir) && has_gene_set_access($organism, $assembly, $gene_set);
        }
        $memo[$key] = $ok;
    }
    if (!$memo[$key] || $analysis === '') return $memo[$key];
    // An analysis can only narrow its data set (lib/access_rules.php): both must pass.
    require_once __DIR__ . '/../lib/access_rules.php';
    return moop_analysis_allows($analysis);
}

function moop_blast_only_genome(string $organism, string $assembly): ?string {
    if (!moop_plain_name($organism) || !moop_plain_name($assembly)) return null;
    $config  = ConfigManager::getInstance();
    $org_dir = rtrim($config->getPath('organism_data'), '/') . "/$organism";
    $asm_dir = "$org_dir/$assembly";
    if (!is_file("$org_dir/organism.sqlite") || !is_dir($asm_dir)) return null;
    // Once the assembly has a gene set, that gene set's BLAST entry already offers this genome
    // (getBlastDatabases() looks one level up); a leftover blast_only entry would list it twice, so
    // it goes stale instead and Manage Groups offers to delete it.
    if (glob("$asm_dir/*", GLOB_ONLYDIR)) return null;
    require_once __DIR__ . '/../lib/genome_meta.php';
    if (!moop_genome_declares_blast_only($asm_dir)) return null;
    $pattern = $config->getSequenceTypes()['genome']['pattern'] ?? 'genome.fa';
    return (is_file("$asm_dir/$pattern") || is_file("$asm_dir/$pattern.nin")) ? $asm_dir : null;
}

function moop_collaborator_allows($organism_name, $assembly_name, $gene_set) {
    if (!has_access('COLLABORATOR')) {
        return false;
    }
    return moop_user_access_allows(get_user_access(), $organism_name, $assembly_name, $gene_set);
}

function moop_user_access_allows($user_access, $organism_name, $assembly_name, $gene_set): bool {
    if (!is_array($user_access) || !is_array($user_access[$organism_name] ?? null)) return false;
    $allowed = $user_access[$organism_name][$assembly_name] ?? [];

    // users.json carries TWO access shapes (admin/manage_users.php:277 handles both):
    //   new  {org: {asm: [gene_set, ...]}}
    //   old  {org: [asm, ...]}            -- a list, so [$assembly] misses and we deny
    // A third, `{asm: true}`, means "the whole assembly" and predates gene sets.
    // Without this coercion in_array() receives a bool and PHP 8 throws a TypeError,
    // which is a 500 on every page that resolves access -- not a denial.
    if ($allowed === true)  return true;
    if (!is_array($allowed)) return false;

    return in_array('*', $allowed, true) || in_array($gene_set, $allowed, true);
}

function moop_visible_group_entries(array $group_data) {
    $sees_all = has_access('ADMIN') || has_access('IP_IN_RANGE');
    return array_values(array_filter($group_data, function ($entry) use ($sees_all) {
        return $sees_all
            || entry_is_public($entry)
            || (($entry['gene_set'] ?? '') !== ''
                && moop_collaborator_allows($entry['organism'] ?? '', $entry['assembly'] ?? '', $entry['gene_set']));
    }));
}

function generate_csrf_token() {
    if (empty($_SESSION['csrf_token'])) {
        $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
    }
    return $_SESSION['csrf_token'];
}

function verify_csrf_token($submitted_token) {
    $session_token = $_SESSION['csrf_token'] ?? '';
    if (empty($session_token) || empty($submitted_token)) {
        return false;
    }
    return hash_equals($session_token, $submitted_token);
}

function csrf_input_field() {
    return '<input type="hidden" name="csrf_token" value="' . htmlspecialchars(generate_csrf_token(), ENT_QUOTES) . '">';
}

function get_csrf_token_from_request() {
    // HTTP header (jQuery AJAX - set up in layout.php)
    $header = $_SERVER['HTTP_X_CSRF_TOKEN'] ?? '';
    if (!empty($header)) {
        return $header;
    }
    // Form POST field
    return $_POST['csrf_token'] ?? '';
}

function request_expects_json(): bool {
    $script = $_SERVER['SCRIPT_NAME'] ?? ($_SERVER['PHP_SELF'] ?? '');
    return strpos($script, '/api/') !== false
        || ($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '') === 'XMLHttpRequest'
        || !empty($_SERVER['HTTP_X_CSRF_TOKEN'])
        || strpos($_SERVER['HTTP_ACCEPT'] ?? '', 'application/json') !== false;
}

function csrf_protect($json_response = false) {
    $token = get_csrf_token_from_request();
    if (!verify_csrf_token($token)) {
        $ip = $_SERVER['REMOTE_ADDR'] ?? 'unknown';
        error_log("MOOP SECURITY: CSRF token mismatch from IP $ip, URI: " . ($_SERVER['REQUEST_URI'] ?? ''));
        // Answer AJAX/API callers with JSON even if the caller didn't explicitly ask
        // for it — an HTML page here breaks a fetch()/$.ajax caller with a JSON parse error.
        if ($json_response || request_expects_json()) {
            http_response_code(403);
            header('Content-Type: application/json');
            echo json_encode(['success' => false, 'message' => 'Invalid security token. Please reload the page and try again.']);
            exit;
        }
        http_response_code(403);
        // Show a simple error - the user can go back and resubmit
        $config = ConfigManager::getInstance();
        $site   = $config->getString('site');
        echo '<!DOCTYPE html><html><body>';
        echo '<h2>Security Error</h2>';
        echo '<p>Your form submission could not be verified. This can happen if your session expired or the page was open in multiple tabs.</p>';
        echo '<p><a href="javascript:history.back()">Go back and try again</a></p>';
        echo '</body></html>';
        exit;
    }
}

function moop_asset_url(string $app_relative): string
    {
        $site = ConfigManager::getInstance()->getString('site');
        $rel  = ltrim($app_relative, '/');
        // Missing file: emit the URL unversioned rather than fail. A 404 on a real asset
        // is the web server's job to report; this helper must never be the thing that
        // breaks a page.
        $ver = @filemtime(dirname(__DIR__) . '/' . $rel);
        return moop_url_base() . '/' . htmlspecialchars($rel) . ($ver ? '?v=' . $ver : '');
    }

function moop_asset_url_from_site_path(string $url): string
    {
        $site   = ConfigManager::getInstance()->getString('site');
        $prefix = moop_url_base() . '/';
        if (strpos($url, $prefix) !== 0) {
            return htmlspecialchars($url);
        }
        return moop_asset_url(substr($url, strlen($prefix)));
    }

