function moop_page_records_each(string $organism, array $spec, string $text, callable $each): int {
    $db = moop_page_open($organism);
    if (!$db || !$spec['ok']) return 0;
    [$where, $params] = moop_page_spec_where($spec);
    $base = 'FROM curation c LEFT JOIN publication p ON p.pmid = c.pmid WHERE ' . implode(' AND ', $where);
    [$fsql, $fparams] = moop_page_text_filter($organism, $text);
    if ($fsql !== '') { $base .= " AND $fsql"; $params = array_merge($params, $fparams); }
    $st = $db->prepare("SELECT c.accession, c.term_id, c.evidence_id, c.stage_id, c.specimen_id, c.pmid, c.curated_on,
                               p.title, p.authors, p.journal, p.year $base ORDER BY p.year DESC, c.pmid, c.accession");
    $st->execute($params);
    $n = 0;
    while ($r = $st->fetch(PDO::FETCH_ASSOC)) { $each($r); $n++; }
    return $n;
}

function moop_page_visible_organism(): string {
    $base = rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/');
    foreach (array_keys(moop_page_sources()) as $o) {
        if (!moop_page_meta($o)) continue;
        if (!is_file("$base/$o/organism.sqlite")) return $o;
        if (moop_session_is_admin() || is_public_organism($o) || has_access('COLLABORATOR', $o)) return $o;
    }
    return '';
}

function moop_gene_page_section(string $organism, string $gene_id, array $child_ids): array {
    if (!moop_crosswalk_open($organism) && !moop_page_open($organism)) return [null, null];
    $self = array_merge([$gene_id], $child_ids);
    $refs = [];
    foreach (moop_crosswalk_genes($organism, $self) as $rows) $refs = array_merge($refs, array_column($rows, 'ref_id'));
    $members = moop_crosswalk_members($organism, array_merge($self, $refs));
    $accs    = array_merge($self, array_column($members, 'accession'));
    // ...and the GENE ids of those that are transcripts: a crosswalk can map a gene set by transcript
    // while its pictures/curations are filed by gene (lib/crosswalk.php moop_crosswalk_parent_genes).
    // Looked up, not shown: 'aka' stays the crosswalk's own list.
    $accs    = array_values(array_unique(array_merge($accs, moop_crosswalk_parent_genes($organism, array_column($members, 'accession')))));
    $cur     = moop_page_for_accessions($organism, $accs);
    // An ambiguous id (Contig…) reached through one assembly's sources must not bring the records of
    // papers that used the other assembly -- there it is a different gene (lib/crosswalk.php).
    $excl    = moop_crosswalk_exclusions($organism, $members, $self);
    if ($excl) $cur = array_values(array_filter($cur, fn($r) => !in_array((string) $r['pmid'], $excl[mb_strtolower((string) $r['accession'])] ?? [], true)));
    $ids     = [];
    foreach ($cur as $r) array_push($ids, $r['term_id'], $r['stage_id'], $r['specimen_id']);
    $section = [
        'curations' => $cur,
        'labels'    => moop_ontology_labels($ids, moop_ontology_by_purpose('anatomy'))
                     + moop_ontology_labels(array_column($cur, 'evidence_id'), moop_ontology_by_purpose('evidence')),
        'aka'       => array_values(array_filter($members, fn($m) => !in_array($m['accession'], $self, true))),
        'name'      => (string) (moop_crosswalk_sources()[$organism]['name'] ?? ''),
        'source'    => (string) (moop_page_sources()[$organism]['source'] ?? ''),
        'source_url'=> (string) (moop_page_sources()[$organism]['source_url'] ?? ''),
    ];
    return [(!$section['curations'] && !$section['aka']) ? null : $section, $accs];
}

function moop_v1_scope(array $organisms, string $assembly = '', string $gene_set = ''): array {
    $out = [];
    $one = count($organisms) === 1;
    foreach ($organisms as $org) {
        if (!moop_plain_name($org)) continue;
        $db = organism_db_path($org);
        if (!is_file($db)) continue;
        try {
            $sets = moop_kegg_visible_gene_sets($org, $db, $one ? $assembly : '');
        } catch (Throwable $e) {
            error_log("moop_v1_scope $org: " . $e->getMessage());
            continue;
        }
        foreach ($sets as $s) {
            if ($one && $gene_set !== '' && $s['gene_set'] !== $gene_set) continue;
            $out[] = ['organism' => $org, 'assembly' => $s['assembly'], 'gene_set' => $s['gene_set'],
                      'gene_set_id' => $s['gene_set_id'], 'db' => $db, 'dir' => $s['dir']];
        }
    }
    return $out;
}

