/** Normalise a KEGG pathway id: 04142, ko04142, hsa04142, map04142 -> map04142; modules (M00001) as they are. */

functions.code:
function moop_v1_pathway_id(string $id): string {
    $id = trim($id);
    if (preg_match('/^(?:[a-z]{2,4})?(\d{5})$/i', $id, $m)) return 'map' . $m[1];
    if (preg_match('/^M\d{5}$/i', $id)) return strtoupper($id);
    return $id;
}

function moop_annotation_type_genes(string $db_file, int $gene_set_id, string $type, array $accessions,
                                    bool $all, int $cap): array {
    $accessions = array_values(array_unique(array_filter(array_map('strval', $accessions), 'strlen')));
    if (!$accessions) return ['total' => 0, 'genes' => []];
    $dbh = getDbConnection($db_file);
    $st  = $dbh->prepare("SELECT COALESCE(f.parent_feature_id, f.feature_id) AS gene, f.feature_uniquename AS on_id,
                                 a.annotation_accession, a.annotation_description, s.annotation_source_name, fa.score
                            FROM json_each(?) j
                           CROSS JOIN annotation a          ON a.annotation_accession = j.value
                           CROSS JOIN annotation_source s   ON s.annotation_source_id = a.annotation_source_id
                           CROSS JOIN feature_annotation fa ON fa.annotation_id = a.annotation_id
                           CROSS JOIN feature f             ON f.feature_id = fa.feature_id
                           WHERE s.annotation_type = ? AND f.gene_set_id = ?");
    // CROSS JOIN pins the order, accession first: left to the planner it walked the whole gene set
    // (feature_gene_set_id_idx) -- 10.8 s for PF00085 across Smed's six gene sets, warm (2026-11-17).
    $st->execute([json_encode($accessions), $type, $gene_set_id]);
    $by_gene = [];
    while ($r = $st->fetch(PDO::FETCH_ASSOC)) {
        $k = $r['annotation_source_name'] . "\x1f" . $r['annotation_accession'];
        $h = &$by_gene[(int) $r['gene']][$k];
        $h ??= ['accession' => $r['annotation_accession'], 'name' => (string) $r['annotation_description'],
                'source' => $r['annotation_source_name'], 'score' => null, 'on' => []];
        if ($r['score'] !== null && ($h['score'] === null || (float) $r['score'] < $h['score'])) $h['score'] = (float) $r['score'];
        if (!in_array($r['on_id'], $h['on'], true)) $h['on'][] = $r['on_id'];
        unset($h);
    }
    if ($all) {
        $want = count($accessions);
        $by_gene = array_filter($by_gene, fn($hits) => count(array_unique(array_column($hits, 'accession'))) >= $want);
    }
    $total = count($by_gene);
    if (!$by_gene) return ['total' => 0, 'genes' => []];

    $st = $dbh->prepare("SELECT f.feature_id, f.feature_uniquename, " . moop_gene_name_sql('f') . " AS feature_name, f.feature_description
                           FROM feature f WHERE f.feature_id IN (SELECT value FROM json_each(?))");
    $st->execute([json_encode(array_keys($by_gene))]);
    $info = [];
    foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $f) $info[(int) $f['feature_id']] = $f;
    $genes = [];
    foreach ($by_gene as $gid => $hits) {
        $f = $info[$gid] ?? null;
        if (!$f) continue;
        $hits = array_values($hits);
        usort($hits, fn($a, $b) => [$a['accession'], $a['source']] <=> [$b['accession'], $b['source']]);
        $genes[] = ['gene' => $f['feature_uniquename'], 'name' => moop_gene_symbol($f['feature_name'], $f['feature_uniquename']),
                    'description' => (string) $f['feature_description'], 'hits' => $hits];
    }
    usort($genes, fn($a, $b) => strcmp($a['gene'], $b['gene']));
    return ['total' => $total, 'genes' => array_slice($genes, 0, $cap)];
}

function moop_annotation_type_search(string $db_file, string $type, string $text, int $cap): array {
    $text = trim($text);
    if ($text === '') return [];
    $dbh = getDbConnection($db_file);
    $st  = $dbh->prepare("SELECT a.annotation_accession, a.annotation_description, s.annotation_source_name
                            FROM annotation a JOIN annotation_source s ON s.annotation_source_id = a.annotation_source_id
                           WHERE s.annotation_type = ? AND (a.annotation_description LIKE ? ESCAPE '\\' OR a.annotation_accession = ?)
                           GROUP BY a.annotation_accession, s.annotation_source_name
                           ORDER BY a.annotation_accession LIMIT ?");
    $like = '%' . str_replace(['\\', '%', '_'], ['\\\\', '\\%', '\\_'], $text) . '%';
    $st->execute([$type, $like, $text, $cap]);
    return array_map(fn($r) => ['accession' => $r[0], 'name' => (string) $r[1], 'source' => $r[2]], $st->fetchAll(PDO::FETCH_NUM));
}

function moop_annotation_type_gene_counts(string $db_file, int $gene_set_id, string $type, array $accessions): array {
    $accessions = array_values(array_unique(array_filter(array_map('strval', $accessions), 'strlen')));
    if (!$accessions) return [];
    $dbh = getDbConnection($db_file);
    // Same join order as moop_annotation_type_genes(), for the same reason.
    $st  = $dbh->prepare("SELECT a.annotation_accession, COUNT(DISTINCT COALESCE(f.parent_feature_id, f.feature_id))
                            FROM json_each(?) j
                           CROSS JOIN annotation a          ON a.annotation_accession = j.value
                           CROSS JOIN annotation_source s   ON s.annotation_source_id = a.annotation_source_id
                           CROSS JOIN feature_annotation fa ON fa.annotation_id = a.annotation_id
                           CROSS JOIN feature f             ON f.feature_id = fa.feature_id
                           WHERE s.annotation_type = ? AND f.gene_set_id = ?
                           GROUP BY a.annotation_accession");
    $st->execute([json_encode($accessions), $type, $gene_set_id]);
    $out = [];
    foreach ($st->fetchAll(PDO::FETCH_NUM) as $r) $out[$r[0]] = (int) $r[1];
    return $out;
}

function moop_v1_annotation_name_matches(array $o, array $scope, string $name, string $format): void {
    $matches = [];
    $search  = [];
    foreach ($scope as $g) {
        $where = "{$g['organism']}/{$g['assembly']}/{$g['gene_set']}";
        try {
            $search[$g['db']] ??= moop_annotation_type_search($g['db'], $o['type'], $name, 200);
            foreach ($search[$g['db']] as $m) $matches[$m['accession']] ??= $m + ['total_genes' => 0, 'genes' => []];
            $counts = moop_annotation_type_gene_counts($g['db'], $g['gene_set_id'], $o['type'], array_column($search[$g['db']], 'accession'));
        } catch (Throwable $e) {
            error_log("api/v1 {$o['label']} name {$g['organism']}: " . $e->getMessage());
            $counts = [];
        }
        foreach ($counts as $acc => $n) {
            $matches[$acc]['genes'][$where] = $n;
            $matches[$acc]['total_genes'] += $n;
        }
    }
    $matches = array_values(array_filter($matches, fn($m) => $m['total_genes'] > 0));
    usort($matches, fn($a, $b) => [$b['total_genes'], $a['accession']] <=> [$a['total_genes'], $b['accession']]);
    $capped = count($matches) >= 200;
    $note = "These are the matching {$o['label_plural']}, not genes. Pick the accession(s) that mean what the person asked "
          . "and ask again with {$o['param']}=. A name catches broader and looser entries too.";
    if ($format === 'tsv') {
        header('Content-Type: text/tab-separated-values; charset=utf-8');
        $cell = fn($v) => str_replace(["\t", "\r", "\n"], ' ', (string) $v);
        echo "accession\tname\tsource\torganism/assembly/gene_set\tgenes\n";
        foreach ($matches as $m) foreach ($m['genes'] as $where => $n) echo implode("\t", array_map($cell, [$m['accession'], $m['name'], $m['source'], $where, $n])) . "\n";
        echo "# $note\n" . ($capped ? "# Only the first 200 matches were counted; use a more specific name.\n" : '');
        exit;
    }
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['api_version' => 1, 'type' => $o['type'], 'name' => $name, 'matches' => $matches,
                      'notes' => array_values(array_filter([$note, $capped ? 'Only the first 200 matches were counted; use a more specific name.' : null]))],
        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
    exit;
}

function moop_v1_annotation_genes_endpoint(array $o): void {
    $format = ($_GET['format'] ?? '') === 'tsv' ? 'tsv' : 'json';
    $split  = fn($v) => array_values(array_unique(preg_split('/[\s,;]+/', trim((string) $v), -1, PREG_SPLIT_NO_EMPTY)));
    $orgs   = array_slice($split($_GET['organism'] ?? ''), 0, 20);
    $accs   = array_slice($split($_GET[$o['param']] ?? ''), 0, $o['max_acc']);
    if ($o['normalise']) $accs = array_values(array_unique(array_map($o['normalise'], $accs)));
    $name   = $o['by_name'] ? trim((string) ($_GET['name'] ?? '')) : '';
    $all    = ($_GET['match'] ?? '') === 'all';
    $fail = function (int $code, string $msg) {
        http_response_code($code);
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['api_version' => 1, 'error' => $msg], JSON_UNESCAPED_SLASHES);
        exit;
    };
    if (!$orgs || (!$accs && $name === '')) {
        $fail(400, "organism and {$o['param']}" . ($o['by_name'] ? ' (or name)' : '') . ' are required.');
    }
    $scope = moop_v1_scope($orgs, (string) ($_GET['assembly'] ?? ''), (string) ($_GET['gene_set'] ?? ''));
    if (!$scope) $fail(404, 'No gene set that you can open for ' . implode(', ', $orgs) . '.');
    if ($name !== '' && !$accs) moop_v1_annotation_name_matches($o, $scope, $name, $format);

    $results = [];
    $matched = [];
    foreach ($scope as $g) {
        try {
            $these = $accs;
            if ($name !== '') {
                foreach (moop_annotation_type_search($g['db'], $o['type'], $name, 50) as $m) {
                    $these[] = $m['accession'];
                    $matched[$m['accession']] = $m;
                }
            }
            // name= with match=all would ask for every domain named "kinase" at once: name means any.
            $r = moop_annotation_type_genes($g['db'], $g['gene_set_id'], $o['type'], $these, $all && $name === '', $o['cap']);
        } catch (Throwable $e) {
            error_log("api/v1 {$o['label']} {$g['organism']}: " . $e->getMessage());
            $r = ['total' => 0, 'genes' => [], 'error' => 'could not be read'];
        }
        $results[] = ['organism' => $g['organism'], 'assembly' => $g['assembly'], 'gene_set' => $g['gene_set'],
                      'total' => $r['total'], 'shown' => count($r['genes'])] + (isset($r['error']) ? ['error' => $r['error']] : [])
                   + ['genes' => $r['genes']];
    }
    $capped = array_filter($results, fn($r) => $r['total'] > $r['shown']);
    $notes = array_values(array_filter([
        $capped ? "Each gene set lists at most {$o['cap']} genes; 'total' is the full count." : null,
        $name !== '' && count($matched) >= 50 ? 'name matched 50 or more accessions; only the first 50 per organism were used.' : null,
    ]));

    if ($format === 'tsv') {
        header('Content-Type: text/tab-separated-values; charset=utf-8');
        $cell = fn($v) => str_replace(["\t", "\r", "\n"], ' ', (string) $v);
        echo implode("\t", ['organism', 'assembly', 'gene_set', 'gene', 'gene_name', 'gene_description',
                            'accession', 'accession_name', 'source', 'score', 'on']) . "\n";
        foreach ($results as $r) {
            foreach ($r['genes'] as $gene) {
                foreach ($gene['hits'] as $h) {
                    echo implode("\t", array_map($cell, [$r['organism'], $r['assembly'], $r['gene_set'], $gene['gene'], $gene['name'],
                        $gene['description'], $h['accession'], $h['name'], $h['source'], $h['score'] ?? '', implode(' ', $h['on'])])) . "\n";
                }
            }
        }
        foreach ($notes as $n) echo "# $n\n";
        exit;
    }
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['api_version' => 1, 'type' => $o['type'], $o['param'] => $accs]
        + ($name !== '' ? ['name' => $name, 'name_matched' => array_values($matched)] : [])
        + ['match' => $all && $name === '' ? 'all' : 'any', 'results' => $results, 'notes' => $notes],
        JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
}

function moop_score_config_file(): string {
    $dir = null;
    if (class_exists('ConfigManager')) {
        try { $dir = ConfigManager::getInstance()->getPath('metadata_path'); } catch (\Throwable $e) { $dir = null; }
    }
    return ($dir ?: __DIR__ . '/../metadata') . '/annotation_scores.json';
}

function moop_score_config(): array {
    static $cfg = null;
    if ($cfg !== null) return $cfg;
    $file = moop_score_config_file();
    if (!is_file($file) && is_file($file . '.example')) {
        $file .= '.example';
    }
    if (!is_file($file)) {
        $file = __DIR__ . '/../metadata/annotation_scores.json.example';
    }
    $loaded = is_file($file) ? json_decode((string)file_get_contents($file), true) : null;
    $cfg = moop_score_config_normalize(is_array($loaded) ? $loaded : []);
    return $cfg;
}

functions.comment:
/**
* What an annotation's Score means, and how to show it.
*
* WHY THIS EXISTS
*
* feature_annotation.score holds many kinds of number under one column heading: E-values
* (lower is better), profile match scores (higher is better), a SignalP probability, a count
* of membrane segments, OMA's relationship as a CODE (1 = 1:1 ... 4 = many:many), the
* closest-gene TIER (1-7), the number of species sharing a duplication. Several kinds sit in
* the same table — the Orthologs table puts "4" (many:many) beside "2e-16" (EggNOG) — so no
* note above a table can explain its column: the meaning changes row by row.
*
* So the meaning travels with the cell. Each source maps to ONE kind; the table formats every
* score from it (words where the number is a code), puts one plain sentence on hover, and
* lists the kinds present in the table's (i) block.
*
* THE LOOKUP TABLE IS EDITABLE: metadata/annotation_scores.json, edited on Admin > Manage
* Annotations ("Score meanings"), so a new analysis needs no code change (user, 2026-10-06).
* The shipped default is metadata/annotation_scores.json.example; it is read until the admin
* first saves. What stays in code is only HOW each display style formats a number.
*
*   kinds: { id: { label, display, explanation, [unit, unit_plural], [words: {"1": "1:1"}] } }
*   rules: [ { [source], [type], kind } ]   `source` matches the START of the source name,
*          `type` the whole annotation type, both case-insensitive; a rule naming both needs both.
*          Two tiers: rules WITH a source are checked first, in file order, first match wins;
*          rules with only a type are FALLBACKS ("anything else in Domains is an E-value"),
*          checked only after every source rule. A fallback therefore can never shadow a
*          specific rule, wherever it sits in the file — when it was one ordered list, moving
*          "Domains -> E-value" above "ProSiteProfiles -> profile score" would have silently
*          made every ProSite score read as an E-value.
*
* Where each default kind comes from in the pipeline (config/build_and_load_db/analysis_parsers/):
*   E-values: DIAMOND, MMseqs2, EggNOG, InterProScan member databases; profile scores:
*   InterProScan ProSiteProfiles/Hamap (column 9); SignalP SP(Sec/SPI) probability; ProtNLM
*   prediction score; DeepTMHMM segment count; OMA relationship (OmaHogOrthologs.pm
*   %RELATIONSHIP_SCORE); OMA paralogs' species count; closest-gene tier/rank
*   (assign_gene_names_v2.pl header).
*
* A source no rule matches keeps the raw number — and is listed on the admin page, so a new
* analysis is noticed rather than silently shown as a bare number.
*/

/** The display styles a kind can use. Code, not data: each one is a formatting rule. */
const MOOP_SCORE_DISPLAYS = [
'evalue'  => 'E-value (short scientific: 2.7e-5)',
'number'  => 'Number (one decimal)',
'percent' => 'Percent (0–1 shown as 0–100%)',
'count'   => 'Count with a unit (7 segments)',
'words'   => 'Words for codes (1 → 1:1)',
'none'    => 'No score (—)',
];

/** The score lookup table: the admin's file, else the shipped default. */
function moop_score_config_file(): string {
$dir = null;
if (class_exists('ConfigManager')) {
try { $dir = ConfigManager::getInstance()->getPath('metadata_path'); } catch (\Throwable $e) { $dir = null; }
}
return ($dir ?: __DIR__ . '/../metadata') . '/annotation_scores.json';
}

function moop_score_config(): array {
static $cfg = null;
if ($cfg !== null) return $cfg;
$file = moop_score_config_file();
if (!is_file($file) && is_file($file . '.example')) {
$file .= '.example';
}
if (!is_file($file)) {
$file = __DIR__ . '/../metadata/annotation_scores.json.example';
}
$loaded = is_file($file) ? json_decode((string)file_get_contents($file), true) : null;
$cfg = moop_score_config_normalize(is_array($loaded) ? $loaded : []);
return $cfg;
}

/** Only well-formed entries; anything else is dropped rather than half-applied. */

functions.code:
function moop_score_config_normalize(array $c): array {
    $kinds = [];
    foreach ((array)($c['kinds'] ?? []) as $id => $k) {
        if (!is_array($k) || !isset(MOOP_SCORE_DISPLAYS[$k['display'] ?? ''])) continue;
        $kinds[(string)$id] = [
            'label'       => (string)($k['label'] ?? $id),
            'display'     => (string)$k['display'],
            'explanation' => (string)($k['explanation'] ?? ''),
            'unit'        => (string)($k['unit'] ?? ''),
            'unit_plural' => (string)($k['unit_plural'] ?? ($k['unit'] ?? '')),
            'words'       => array_map('strval', (array)($k['words'] ?? [])),
        ];
    }
    $rules = [];
    foreach ((array)($c['rules'] ?? []) as $r) {
        if (!is_array($r) || !isset($kinds[$r['kind'] ?? ''])) continue;
        $source = trim((string)($r['source'] ?? ''));
        $type   = trim((string)($r['type'] ?? ''));
        if ($source === '' && $type === '') continue;     // would match everything
        $rules[] = ['source' => $source, 'type' => $type, 'kind' => (string)$r['kind']];
    }
    return ['kinds' => $kinds, 'rules' => $rules];
}

