{
return [
'txt' => ['blast_results.txt', 'text/plain', 'pairwise'],
'tsv' => ['blast_results.tsv', 'text/tab-separated-values', 'tabular'],
'xml' => ['blast_results.xml', 'application/xml', 'output'],
