return bin2hex(random_bytes(8));
}

/** Is someone holding a lock on $path? Takes and drops it if not. */

functions.code:
function blast_queue_file_is_held(string $path): bool
{
    // 'r', not 'c': opening must never re-create a file its owner just removed.
    $fh = @fopen($path, 'r');
    if (!$fh) return false;
    $free = flock($fh, LOCK_EX | LOCK_NB);
    if ($free) flock($fh, LOCK_UN);
    fclose($fh);
    return !$free;
}

function blast_queue_waiters(string $dir): array
{
    $live = [];
    $names = @scandir("$dir/wait") ?: [];
    sort($names, SORT_STRING);
    foreach ($names as $name) {
        if ($name[0] === '.') continue;
        $path = "$dir/wait/$name";
        // A file younger than 2 s may belong to a request that has created it but not yet
        // locked it; leave it alone rather than delete a live waiter.
        if (blast_queue_file_is_held($path) || (time() - (int)@filemtime($path)) < 2) {
            $live[] = $name;
        } else {
            @unlink($path);
        }
    }
    return $live;
}

functions.comment:
/**
* The live waiters, oldest first, as basenames. Dead entries (file present, nobody holding it)
* are deleted on the way -- this sweep is the whole of the queue's self-repair.
*/
function blast_queue_waiters(string $dir): array
{
$live = [];
$names = @scandir("$dir/wait") ?: [];
sort($names, SORT_STRING);
foreach ($names as $name) {
if ($name[0] === '.') continue;
$path = "$dir/wait/$name";
// A file younger than 2 s may belong to a request that has created it but not yet
// locked it; leave it alone rather than delete a live waiter.
if (blast_queue_file_is_held($path) || (time() - (int)@filemtime($path)) < 2) {
$live[] = $name;
} else {
@unlink($path);
}
}
return $live;
}

/** Number of searches running now (held run/ files). Dead run files are swept. */

functions.code:
function blast_queue_running(string $dir): int
{
    $n = 0;
    foreach (@scandir("$dir/run") ?: [] as $name) {
        if ($name[0] === '.') continue;
        $path = "$dir/run/$name";
        if (blast_queue_file_is_held($path)) $n++;
        elseif ((time() - (int)@filemtime($path)) >= 2) @unlink($path);
    }
    return $n;
}

function blast_queue_status(string $ticket): array
{
    $dir = blast_queue_dir();
    if ($dir === '' || !preg_match('/^[a-f0-9]{16,32}$/', $ticket)) return ['state' => 'unknown'];

    if (is_file("$dir/run/$ticket") && blast_queue_file_is_held("$dir/run/$ticket")) {
        return ['state' => 'running', 'running' => blast_queue_running($dir)];
    }
    foreach (blast_queue_waiters($dir) as $i => $name) {
        if (substr($name, -strlen($ticket) - 1) === "-$ticket") {
            return ['state' => 'waiting', 'position' => $i + 1, 'running' => blast_queue_running($dir)];
        }
    }
    return ['state' => 'unknown'];
}

functions.comment:
/**
* Where a ticket stands, for the waiting page: ['state' => 'waiting'|'running'|'unknown',
* 'position' => 1-based place in line, 'ahead' => searches running].
*/
function blast_queue_status(string $ticket): array
{
$dir = blast_queue_dir();
if ($dir === '' || !preg_match('/^[a-f0-9]{16,32}$/', $ticket)) return ['state' => 'unknown'];

if (is_file("$dir/run/$ticket") && blast_queue_file_is_held("$dir/run/$ticket")) {
return ['state' => 'running', 'running' => blast_queue_running($dir)];
}
foreach (blast_queue_waiters($dir) as $i => $name) {
if (substr($name, -strlen($ticket) - 1) === "-$ticket") {
return ['state' => 'waiting', 'position' => $i + 1, 'running' => blast_queue_running($dir)];
}
}
return ['state' => 'unknown'];
}

/** Searches running and waiting right now, for the admin page. */

functions.code:
function blast_queue_snapshot(): array
{
    $dir = blast_queue_dir();
    if ($dir === '') return ['ok' => false, 'running' => 0, 'waiting' => 0];
    return ['ok' => true, 'running' => blast_queue_running($dir), 'waiting' => count(blast_queue_waiters($dir))];
}

function blast_queue_take_units(string $dir, int $total, int $need)
{
    $held = [];
    $broken = false;
    for ($i = 0; $i < $total && count($held) < $need; $i++) {
        $path = sprintf('%s/units/u%03d', $dir, $i);
        if (!is_file($path) && ($c = @fopen($path, 'c'))) {
            fclose($c);
            @chmod($path, 0664);
        }
        $fh = @fopen($path, 'r');
        if (!$fh) { $broken = true; break; }
        if (flock($fh, LOCK_EX | LOCK_NB)) $held[] = $fh;
        else fclose($fh);
    }
    if (!$broken && count($held) >= $need) return $held;
    foreach ($held as $fh) { flock($fh, LOCK_UN); fclose($fh); }
    return $broken ? false : null;
}

function blast_queue_run(callable $job, int $units, string $ticket): array
{
    $dir = blast_queue_dir();
    if ($dir === '') {
        error_log('MOOP: BLAST queue directory unusable under ' . moop_cache_root() . ' -- running UNQUEUED');
        return ['ran' => true, 'result' => $job(), 'waited' => 0];
    }

    $s     = blast_queue_settings();
    $units = min($units, $s['units']);   // bigger than the whole budget: it runs alone
    $start = microtime(true);

    // Join the line. The sequence prefix orders it; the ticket lets the status call find us.
    $wait_path = sprintf('%s/wait/%017.6f-%s', $dir, $start, $ticket);
    $wait_fh   = @fopen($wait_path, 'x');
    if (!$wait_fh || !flock($wait_fh, LOCK_EX)) {
        error_log("MOOP: BLAST queue could not create $wait_path -- running UNQUEUED");
        if ($wait_fh) fclose($wait_fh);
        return ['ran' => true, 'result' => $job(), 'waited' => 0];
    }
    $leave_line = function () use (&$wait_fh, $wait_path) {
        if ($wait_fh) { @unlink($wait_path); flock($wait_fh, LOCK_UN); fclose($wait_fh); $wait_fh = null; }
    };

    $held = null;
    while (true) {
        $line = blast_queue_waiters($dir);
        if (($line[0] ?? '') === basename($wait_path)
            && blast_queue_running($dir) < $s['max_concurrent']) {
            $held = blast_queue_take_units($dir, $s['units'], $units);
            if ($held === false) {
                error_log("MOOP: BLAST queue unit files under $dir/units cannot be opened -- running UNQUEUED");
                $leave_line();
                return ['ran' => true, 'result' => $job(), 'waited' => (int)round(microtime(true) - $start)];
            }
            if ($held !== null) break;
        }
        if (microtime(true) - $start > $s['max_wait']) {
            $leave_line();
            return ['ran' => false, 'error' =>
                'The server is busy with other BLAST searches and your search could not start within '
                . $s['max_wait'] . ' seconds. Nothing was run -- please try again in a minute or two.'];
        }
        usleep(400000);
    }

    // Our turn. Mark ourselves running BEFORE leaving the line, so a status call never sees
    // the ticket in neither place.
    $run_path = "$dir/run/$ticket";
    $run_fh   = @fopen($run_path, 'c');
    if ($run_fh) flock($run_fh, LOCK_EX);
    $leave_line();
    $waited = (int)round(microtime(true) - $start);

    try {
        $result = $job();
    } finally {
        if ($run_fh) { @unlink($run_path); flock($run_fh, LOCK_UN); fclose($run_fh); }
        foreach ($held as $fh) { flock($fh, LOCK_UN); fclose($fh); }
    }
    return ['ran' => true, 'result' => $result, 'waited' => $waited];
}

function blast_queue_wrap_command(string $cmd): string
{
    $timeout = moop_find_executable('timeout');
    if ($timeout === '') return $cmd;
    return escapeshellarg($timeout) . ' --kill-after=5 ' . blast_queue_settings()['max_runtime'] . ' ' . $cmd;
}

function blast_queue_timed_out(int $exit_code): bool
{
    return $exit_code === 124 || $exit_code === 137;
}

function blast_queue_timeout_message(): string
{
    return 'This search ran longer than the ' . blast_queue_settings()['max_runtime']
        . '-second limit and was stopped. Try a shorter query, a stricter E-value, or a smaller database.';
}

function parseBlastResults($blast_xml) {
    $all_queries = [];
    $search = [];

    // Parse XML
    try {
        $xml = simplexml_load_string($blast_xml);

        if ($xml === false) {
            return ['error' => t_plain('Failed to parse BLAST XML output'), 'queries' => []];
        }

        $search = moop_blast_search_summary($xml);

        // Parse each iteration (each query gets one iteration)
        $iterations = $xml->xpath('//Iteration');

        foreach ($iterations as $iteration) {
            $query_result = [
                'hits' => [],
                'query_length' => 0,
                'query_name' => '',
                'query_desc' => '',
                'total_hits' => 0,
                'error' => ''
            ];

            // Get query info using XPath to handle hyphens in element names
            $query_len = $iteration->xpath('./Iteration_query-len');
            if (!empty($query_len)) {
                $query_result['query_length'] = (int)$query_len[0];
            }

            $query_id = $iteration->xpath('./Iteration_query-ID');
            if (!empty($query_id)) {
                $query_result['query_name'] = (string)$query_id[0];
            }

            $query_def = $iteration->xpath('./Iteration_query-def');
            if (!empty($query_def)) {
                $query_result['query_desc'] = (string)$query_def[0];
            }

            // Parse each hit using XPath - maintain Hit/HSP hierarchy
            $hits = $iteration->xpath('.//Hit');
            foreach ($hits as $hit_node) {
                // Get hit info
                $hit_id = $hit_node->xpath('./Hit_id');
                $hit_def = $hit_node->xpath('./Hit_def');
                $hit_len = $hit_node->xpath('./Hit_len');

                $hit_id_str = !empty($hit_id) ? (string)$hit_id[0] : '';
                $hit_def_str = !empty($hit_def) ? (string)$hit_def[0] : '';
                if ($hit_def_str === '' || strcasecmp(trim($hit_def_str), 'No definition line') === 0) {
                    $hit_def_str = $hit_id_str;
                }
                $hit_len_int = !empty($hit_len) ? (int)$hit_len[0] : 0;

                // Get all HSPs (High-scoring Segment Pairs) for this hit
                $hsps = $hit_node->xpath('.//Hsp');
                if (!empty($hsps)) {
                    $hsps_array = [];
                    $best_evalue = PHP_FLOAT_MAX;
                    $cumulative_coverage = [];

                    // Process each HSP for this hit
                    foreach ($hsps as $hsp) {
                        // Use XPath for HSP elements with hyphens
                        $identities = $hsp->xpath('./Hsp_identity');
                        $align_len = $hsp->xpath('./Hsp_align-len');
                        $evalue = $hsp->xpath('./Hsp_evalue');
                        $bit_score = $hsp->xpath('./Hsp_bit-score');
                        $score = $hsp->xpath('./Hsp_score');
                        $query_from = $hsp->xpath('./Hsp_query-from');
                        $query_to = $hsp->xpath('./Hsp_query-to');
                        $hit_from = $hsp->xpath('./Hsp_hit-from');
                        $hit_to = $hsp->xpath('./Hsp_hit-to');
                        $qseq = $hsp->xpath('./Hsp_qseq');
                        $hseq = $hsp->xpath('./Hsp_hseq');
                        $midline = $hsp->xpath('./Hsp_midline');
                        // Frames drive the alignment coordinate DIRECTION (negative frame
                        // counts down). They were never extracted before, which left
                        // formatBlastAlignment() unreachable behind an isset() gate.
                        $query_frame = $hsp->xpath('./Hsp_query-frame');
                        $hit_frame = $hsp->xpath('./Hsp_hit-frame');

                        $identities_int = !empty($identities) ? (int)$identities[0] : 0;
                        $align_len_int = !empty($align_len) ? (int)$align_len[0] : 0;
                        $evalue_float = !empty($evalue) ? (float)$evalue[0] : 0;
                        $hit_from_int = !empty($hit_from) ? (int)$hit_from[0] : 0;
                        $hit_to_int = !empty($hit_to) ? (int)$hit_to[0] : 0;

                        // Track best (smallest) evalue
                        if ($evalue_float < $best_evalue) {
                            $best_evalue = $evalue_float;
                        }

                        // Track coverage regions for cumulative calculation
                        $cumulative_coverage[] = [
                            'from' => min($hit_from_int, $hit_to_int),
                            'to' => max($hit_from_int, $hit_to_int)
                        ];

                        // Count gaps and similarities with gap lengths
                        $query_seq = !empty($qseq) ? (string)$qseq[0] : '';
                        $hit_seq = !empty($hseq) ? (string)$hseq[0] : '';
                        $midline_str = !empty($midline) ? (string)$midline[0] : '';

                        // Count gaps and track individual gap lengths
                        $gap_count = 0;
                        $gap_lengths = [];

                        // Find gaps in query sequence
                        $in_gap = false;
                        $gap_len = 0;
                        for ($i = 0; $i < strlen($query_seq); $i++) {
                            if ($query_seq[$i] === '-') {
                                if (!$in_gap) {
                                    $in_gap = true;
                                    $gap_len = 1;
                                } else {
                                    $gap_len++;
                                }
                            } else {
                                if ($in_gap) {
                                    $gap_lengths[] = $gap_len;
                                    $gap_count += $gap_len;
                                    $in_gap = false;
                                }
                            }
                        }
                        if ($in_gap) {
                            $gap_lengths[] = $gap_len;
                            $gap_count += $gap_len;
                        }

                        // Find gaps in hit sequence
                        $in_gap = false;
                        $gap_len = 0;
                        for ($i = 0; $i < strlen($hit_seq); $i++) {
                            if ($hit_seq[$i] === '-') {
                                if (!$in_gap) {
                                    $in_gap = true;
                                    $gap_len = 1;
                                } else {
                                    $gap_len++;
                                }
                            } else {
                                if ($in_gap) {
                                    $gap_lengths[] = $gap_len;
                                    $gap_count += $gap_len;
                                    $in_gap = false;
                                }
                            }
                        }
                        if ($in_gap) {
                            $gap_lengths[] = $gap_len;
                            $gap_count += $gap_len;
                        }

                        $total_gap_length = $gap_count;
                        $gaps = count($gap_lengths);
                        $gap_lengths_str = implode(', ', $gap_lengths);

                        $similarities = strlen($midline_str) - $identities_int - substr_count($midline_str, ' ');

                        // Calculate HSP subject coverage percentage
                        $subject_coverage_percent = $hit_len_int > 0 ? round((abs($hit_to_int - $hit_from_int) + 1) / $hit_len_int * 100, 2) : 0;

                        $hsp_data = [
                            'identities' => $identities_int,
                            'alignment_length' => $align_len_int,
                            'evalue' => $evalue_float,
                            'bit_score' => !empty($bit_score) ? (float)$bit_score[0] : 0,
                            'score' => !empty($score) ? (int)$score[0] : 0,
                            'percent_identity' => $align_len_int > 0 ? round(($identities_int / $align_len_int) * 100, 2) : 0,
                            'query_from' => !empty($query_from) ? (int)$query_from[0] : 0,
                            'query_to' => !empty($query_to) ? (int)$query_to[0] : 0,
                            'query_frame' => !empty($query_frame) ? (int)$query_frame[0] : 0,
                            'hit_frame' => !empty($hit_frame) ? (int)$hit_frame[0] : 0,
                            'hit_from' => $hit_from_int,
                            'hit_to' => $hit_to_int,
                            'query_seq' => $query_seq,
                            'hit_seq' => $hit_seq,
                            'midline' => $midline_str,
                            'gaps' => $gaps,
                            'gap_lengths' => $gap_lengths,
                            'gap_lengths_str' => $gap_lengths_str,
                            'total_gap_length' => $total_gap_length,
                            'similarities' => $similarities,
                            'subject_coverage_percent' => $subject_coverage_percent
                        ];

                        $hsps_array[] = $hsp_data;
                    }

                    // Calculate cumulative coverage for this hit across all HSPs
                    // Track query coverage (not subject coverage)
                    $query_coverage = [];
                    foreach ($hsps_array as $hsp_data) {
                        $query_coverage[] = [
                            'from' => $hsp_data['query_from'],
                            'to' => $hsp_data['query_to']
                        ];
                    }

                    usort($query_coverage, function($a, $b) { return $a['from'] - $b['from']; });
                    $merged = [];
                    foreach ($query_coverage as $region) {
                        if (empty($merged) || $merged[count($merged)-1]['to'] < $region['from']) {
                            $merged[] = $region;
                        } else {
                            $merged[count($merged)-1]['to'] = max($merged[count($merged)-1]['to'], $region['to']);
                        }
                    }
                    $total_covered = 0;
                    foreach ($merged as $region) {
                        $total_covered += $region['to'] - $region['from'] + 1;
                    }
                    $query_coverage_percent = $query_result['query_length'] > 0 ? round(($total_covered / $query_result['query_length']) * 100, 2) : 0;

                    // Subject cumulative coverage, from THIS hit's HSPs. It used to search
                    // $query_result['hits'] for the hit -- which holds only the hits finished before
                    // this one, so it never found it and every hit header said "Subject Coverage: 0%"
                    // while each HSP below said 100% (found 2026-11-06).
                    $subject_cumulative_coverage = [];
                    foreach ($hsps_array as $hsp_test) {
                        $subject_cumulative_coverage[] = [
                            'from' => min($hsp_test['hit_from'], $hsp_test['hit_to']),
                            'to' => max($hsp_test['hit_from'], $hsp_test['hit_to'])
                        ];
                    }
                    usort($subject_cumulative_coverage, function($a, $b) { return $a['from'] - $b['from']; });
                    $merged_subject = [];
                    foreach ($subject_cumulative_coverage as $region) {
                        if (empty($merged_subject) || $merged_subject[count($merged_subject)-1]['to'] < $region['from']) {
                            $merged_subject[] = $region;
                        } else {
                            $merged_subject[count($merged_subject)-1]['to'] = max($merged_subject[count($merged_subject)-1]['to'], $region['to']);
                        }
                    }
                    $total_subject_covered = 0;
                    foreach ($merged_subject as $region) {
                        $total_subject_covered += $region['to'] - $region['from'] + 1;
                    }
                    $subject_cumulative_coverage_percent = $hit_len_int > 0 ? round(($total_subject_covered / $hit_len_int) * 100, 2) : 0;

                    // Create hit entry with all its HSPs
                    $hit = [
                        'id' => $hit_id_str,
                        'subject' => $hit_def_str,
                        'length' => $hit_len_int,
                        'hsps' => $hsps_array,
                        'best_evalue' => $best_evalue,
                        'num_hsps' => count($hsps_array),
                        'query_coverage_percent' => $query_coverage_percent,
                        'subject_cumulative_coverage_percent' => $subject_cumulative_coverage_percent
                    ];

                    $query_result['hits'][] = $hit;
                }
            }

            $query_result['total_hits'] = count($query_result['hits']);
            $all_queries[] = $query_result;
        }

    } catch (Exception $e) {
        return ['error' => 'XML parsing error: ' . $e->getMessage(), 'queries' => []];
    }

    return ['queries' => $all_queries, 'error' => '', 'search' => $search];
}

function moop_blast_search_summary(SimpleXMLElement $xml): array {
    $one = function (string $path) use ($xml): ?string {
        $n = $xml->xpath($path);
        return $n ? trim((string) $n[0]) : null;
    };
    $out = [
        'program'    => $one('/BlastOutput/BlastOutput_program'),
        'version'    => $one('/BlastOutput/BlastOutput_version'),
        'db'         => ($db = $one('/BlastOutput/BlastOutput_db')) !== null && $db !== '' ? basename($db) : null,
        'matrix'     => $one('/BlastOutput/BlastOutput_param/Parameters/Parameters_matrix'),
        'match'      => $one('/BlastOutput/BlastOutput_param/Parameters/Parameters_sc-match'),
        'mismatch'   => $one('/BlastOutput/BlastOutput_param/Parameters/Parameters_sc-mismatch'),
        'gap_open'   => $one('/BlastOutput/BlastOutput_param/Parameters/Parameters_gap-open'),
        'gap_extend' => $one('/BlastOutput/BlastOutput_param/Parameters/Parameters_gap-extend'),
        // Database size: the same on every query; the first iteration's statistics say it.
        'db_num'     => $one('(//Iteration_stat/Statistics/Statistics_db-num)[1]'),
        'db_len'     => $one('(//Iteration_stat/Statistics/Statistics_db-len)[1]'),
    ];
    return array_filter($out, fn($v) => $v !== null && $v !== '');
}

function generateHitsSummaryTable($results, $query_num = 1) {
    $html = '<div class="blast-hits-summary mb-4">';
    $html .= '<h6><i class="fa fa-table"></i> ' . ($results['total_hits'] == 1 ? t('Hits Summary (%d hit found)', 1)
                                                                           : t('Hits Summary (%d hits found)', $results['total_hits'])) . '</h6>';
    $html .= '<div style="overflow-x: auto;">';
    $html .= '<table class="table table-sm table-striped blast-hits-table">';
    $html .= '<thead class="table-light">';
    $html .= '<tr>';
    $html .= '<th style="width: 5%">#</th>';
    $html .= '<th style="width: 45%">' . t('Hit ID / Description') . '</th>';
    $html .= '<th style="width: 20%">' . gloss_first('coverage', 'Query Coverage') . ' %</th>';
    $html .= '<th style="width: 12%">' . gloss_first('e-value', 'E-value') . '</th>';
    $html .= '<th style="width: 18%">HSPs</th>';
    $html .= '</tr>';
    $html .= '</thead>';
    $html .= '<tbody>';

    foreach ($results['hits'] as $idx => $hit) {
        $hit_num = $idx + 1;
        $evalue_display = sprintf('%.2e', $hit['best_evalue']);
        $query_coverage = $hit['query_coverage_percent'];
        $coverage_bar_width = min(100, $query_coverage);

        // Color based on coverage percentage
        if ($query_coverage >= 80) {
            $coverage_color = '#28a745'; // Green - excellent coverage
        } elseif ($query_coverage >= 50) {
            $coverage_color = '#ffc107'; // Yellow - good coverage
        } elseif ($query_coverage >= 30) {
            $coverage_color = '#fd7e14'; // Orange - moderate coverage
        } else {
            $coverage_color = '#dc3545'; // Red - low coverage
        }

        $html .= '<tr style="cursor: pointer;" onclick="const elem = document.getElementById(\'query-' . $query_num . '-hit-' . $hit_num . '\'); elem.scrollIntoView({behavior: \'smooth\', block: \'start\'}); highlightHitElement(elem);">';
        $html .= '<td><strong>' . $hit_num . '</strong></td>';
        $clean_id = cleanBlastHitId($hit['id']);
        $html .= '<td>';
        $html .= '<small class="d-block fw-bold">' . htmlspecialchars($clean_id) . '</small>';
        $html .= '<small class="text-muted">' . htmlspecialchars(substr($hit['subject'], 0, 60)) . '</small>';
        $html .= '</td>';
        $html .= '<td>';
        $html .= '<div class="blast-coverage-bar" style="width: 100%; background: #e9ecef; border-radius: 4px; overflow: hidden;">';
        $html .= '<div style="width: ' . $coverage_bar_width . '%; background: ' . $coverage_color . '; height: 20px; display: flex; align-items: center; justify-content: center;">';
        $html .= '<small style="font-weight: bold; color: white;">' . $query_coverage . '%</small>';
        $html .= '</div>';
        $html .= '</div>';
        $html .= '</td>';
        $html .= '<td><small>' . $evalue_display . '</small></td>';
        $html .= '<td>' . $hit['num_hsps'] . '</td>';
        $html .= '</tr>';
    }

    $html .= '</tbody>';
    $html .= '</table>';
    $html .= '</div>';
    $html .= '</div>';

    return $html;
}

function generateAlignmentViewer($results, $blast_program = 'blastn', $query_num = 1, $context = []) {
    $html = '<div class="blast-alignment-viewer mt-4">';
    $html .= '<h6><i class="fa fa-align-justify"></i> Detailed Alignments (HSPs)</h6>';
    $html .= '<small class="text-muted d-block mb-3">' . t('Each Hit section contains one or more High-Scoring Segment Pairs (HSPs)') . '</small>';

    if (empty($results['hits'])) {
        $html .= '<div class="alert alert-info"><small>' . t('No alignments to display') . '</small></div>';
        return $html . '</div>';
    }

    // Extract context for per-HSP JBrowse buttons (genome BLAST only)
    $ctx_organism     = $context['organism']      ?? '';
    $ctx_assembly     = $context['assembly']      ?? '';
    $ctx_is_genome    = $context['is_genome_db']  ?? false;
    $ctx_has_jbrowse  = $context['has_jbrowse']   ?? false;
    $ctx_jb2_asm      = $ctx_organism . '_' . $ctx_assembly;
    $ctx_lc           = $context['linkout_config'] ?? [];
    $ctx_jb_enabled   = (bool)($ctx_lc['jbrowse'] ?? false);

    // Determine correct unit based on program
    $unit = 'bp';
    if (strpos($blast_program, 'blastp') !== false || strpos($blast_program, 'tblastn') !== false) {
        $unit = 'aa';
    }

    $html .= '<div style="background: #f8f9fa; border-radius: 4px; overflow-x: auto;">';

    foreach ($results['hits'] as $hit_idx => $hit) {
        $hit_num = $hit_idx + 1;
        $evalue_display = sprintf('%.2e', $hit['best_evalue']);

        // Hit header card
        $clean_hit_id = cleanBlastHitId($hit['id']);
        $html .= '<div id="query-' . $query_num . '-hit-' . $hit_num . '" style="padding: 15px; scroll-margin-top: 20px; background: #f0f7ff; margin-bottom: 15px;">';
        $html .= '<h5 style="margin-bottom: 4px; color: #007bff; font-family: monospace;">';
        $html .= '<strong>' . t('Hit %1$d: %2$s', $hit_num, $clean_hit_id) . '</strong>';
        $html .= '</h5>';
        $html .= '<div style="margin-bottom: 10px; color: #555; font-size: 0.9em;">' . htmlspecialchars($hit['subject']) . '</div>';
        $html .= '<small class="d-block" style="margin-bottom: 10px;">';
        $html .= '<strong>' . t('Length:') . '</strong> ' . $hit['length'] . ' ' . $unit . ' | ';
        $html .= '<strong>' . t('Best E-value:') . '</strong> ' . $evalue_display . ' | ';
        $html .= '<strong>HSPs:</strong> ' . $hit['num_hsps'] . ' | ';
        $html .= '<strong>' . t('Query Coverage:') . '</strong> ' . $hit['query_coverage_percent'] . '% | ';
        $html .= '<strong>' . t('Subject Coverage:') . '</strong> ' . $hit['subject_cumulative_coverage_percent'] . '%';
        $html .= '</small>';
        if (!empty($context)) {
            $linkout_html = buildBlastHitLinkouts($hit, $context);
            if ($linkout_html) {
                $html .= '<div style="margin-top:8px;">' . $linkout_html . '</div>';
            }
        }
        $html .= '</div>';

        // HSPs for this hit
        foreach ($hit['hsps'] as $hsp_idx => $hsp) {
            $hsp_num = $hsp_idx + 1;

            $html .= '<div style="padding: 15px; border-bottom: 1px solid #dee2e6; margin-left: 15px; background: #ffffff; margin-bottom: 10px; border-left: 4px solid #28a745;">';
            $html .= '<h6 style="margin-bottom: 10px;"><strong>HSP ' . $hsp_num . '</strong></h6>';
            $html .= '<small class="text-muted d-block" style="margin-bottom: 10px;">';
            $html .= gloss_first('e-value', 'E-value') . ': ' . sprintf('%.2e', $hsp['evalue']) . ' | ';
            $html .= t('Alignment length: %s', $hsp['alignment_length']) . ' | ';
            $html .= gloss_first('percent identity', 'Identity') . ': ' . $hsp['identities'] . '/' . $hsp['alignment_length'] . ' (' . $hsp['percent_identity'] . '%) | ';
            $html .= 'Similarities: ' . $hsp['similarities'] . ' | ';
            $html .= 'Gaps: ' . $hsp['gaps'];
            if ($hsp['gaps'] > 0) {
                $html .= ' (lengths: ' . $hsp['gap_lengths_str'] . ', total: ' . $hsp['total_gap_length'] . ')';
            }
            $html .= '</small>';

            // Query coverage information for this HSP
            $query_hsp_coverage = $results['query_length'] > 0 ? round((($hsp['query_to'] - $hsp['query_from'] + 1) / $results['query_length']) * 100, 2) : 0;
            $html .= '<small class="d-block" style="margin-bottom: 10px; background: #e7f3ff; padding: 8px; border-radius: 3px; border-left: 3px solid #007bff;">';
            $html .= '<strong>' . t('Query Coverage (This HSP):') . '</strong> ';
            $html .= $query_hsp_coverage . '% (' . ($hsp['query_to'] - $hsp['query_from'] + 1) . '/' . $results['query_length'] . ') | ';
            $html .= '<strong>' . t('Subject Coverage (This HSP):') . '</strong> ';
            $html .= $hsp['subject_coverage_percent'] . '% (' . (abs($hsp['hit_to'] - $hsp['hit_from']) + 1) . '/' . $results['hits'][$hit_idx]['length'] . ')';
            $html .= '</small>';

            // Per-HSP JBrowse button (genome BLAST only)
            if ($ctx_is_genome && $ctx_has_jbrowse && $ctx_jb_enabled) {
                $hsp_subject = cleanBlastHitId($hit['id'] ?? '');
                $s = min((int)$hsp['hit_from'], (int)$hsp['hit_to']) - 1;
                $e = max((int)$hsp['hit_from'], (int)$hsp['hit_to']);
                $hsp_track_id = 'blast_hsp_' . substr(md5($hit['id'] . '_' . $hsp_idx), 0, 10);
                $hsp_features = [[
                    'uniqueId' => $hsp_track_id . '_f',
                    'refName'  => $hsp_subject,
                    'start'    => $s,
                    'end'      => $e,
                    'name'     => 'HSP ' . $hsp_num . ' (evalue=' . ($hsp['evalue'] ?? '?') . ')',
                    'type'     => 'match_part',
                ]];
                $hsp_tracks = [[
                    'type'          => 'FeatureTrack',
                    'trackId'       => $hsp_track_id,
                    'name'          => 'BLAST HSP ' . $hsp_num . ': ' . $hsp_subject,
                    'assemblyNames' => [$ctx_jb2_asm],
                    'adapter'       => ['type' => 'FromConfigAdapter', 'features' => $hsp_features],
                ]];
                $hsp_loc = $hsp_subject . ':' . ($s + 1) . '-' . $e;
                $hsp_url = moop_url_base() . '/jbrowse2.php?organism=' . urlencode($ctx_organism)
                         . '&assembly='      . urlencode($ctx_assembly)
                         . '&loc='           . urlencode($hsp_loc)
                         . '&sessionTracks=' . urlencode(json_encode($hsp_tracks))
                         . '&sessionTrackId='. urlencode($hsp_track_id);
                $html .= '<div style="margin-bottom:8px;">'
                       . '<a href="' . htmlspecialchars($hsp_url) . '" target="_blank" '
                       . 'class="btn btn-sm btn-outline-success">'
                       . 'View HSP ' . $hsp_num . ' in Browser</a>'
                       . '</div>';
            }

            // Display the alignment in monospace, wrapped at the BLAST-conventional 60
            // columns. Unwrapped, a long HSP is a single 400-character line whose closing
            // coordinate sits off-screen behind a horizontal scrollbar.
            $html .= '<pre style="background: white; border: 1px solid #dee2e6; padding: 10px; border-radius: 3px; overflow-x: auto; font-size: 11px; margin: 0; font-family: \'Courier New\', monospace;">';
            $html .= htmlspecialchars(formatBlastAlignment($hsp, $blast_program));
            $html .= '</pre>';

            $html .= '</div>';
        }
    }

    $html .= '</div>';
    $html .= '</div>';

    return $html;
}

functions.comment:
/**
* Strip BLAST source prefixes (lcl|, gb|, ref|, etc.) from a hit ID.
*/

functions.code:
function cleanBlastHitId(string $id): string {
    // Strip leading source prefix: lcl|, gb|, ref|, dbj|, etc.
    $id = preg_replace('/^[a-z]{2,4}\|/', '', $id);
    // Handle remaining pipe-delimited formats like "AAB12345.1|"
    if (strpos($id, '|') !== false) {
        $parts = explode('|', $id);
        $id = $parts[0] !== '' ? $parts[0] : ($parts[1] ?? $id);
    }
    return $id;
}

function blastHitFeatureId(string $raw_id): string {
    $id = cleanBlastHitId(trim($raw_id));
    $id = preg_replace('/:[a-z]+$/', '', $id);
    // NCBI extracted CDS format: {chr}_cds_{ProteinAccession}_{index}
    if (preg_match('/_cds_([A-Z]{2}_?\d+\.\d+)_\d+$/', $id, $m)) {
        $id = $m[1];
    }
    return $id;
}

function buildBlastHitLinkouts($hit, $context) {
    if (empty($context)) return '';

    $site           = $context['site']           ?? '';
    $organism       = $context['organism']       ?? '';
    $assembly       = $context['assembly']       ?? '';
    $is_genome_db   = $context['is_genome_db']   ?? false;
    $has_sqlite     = $context['has_sqlite']     ?? false;
    $has_jbrowse    = $context['has_jbrowse']    ?? false;
    $coords         = $context['coords']         ?? [];
    $linkout_config = $context['linkout_config'] ?? [];
    $db_seq_type    = $context['db_seq_type']    ?? '';

    $hit_id = blastHitFeatureId($hit['id'] ?? '');

    $html = '';

    $gene_page_label  = htmlspecialchars($linkout_config['gene_page_label']       ?? 'Gene Page');
    $jbrowse_label    = htmlspecialchars($linkout_config['jbrowse_label']         ?? 'Genome Browser');
    $hsp_min_score    = (float)($linkout_config['jbrowse_hsp_min_score']          ?? 0);
    $hsp_max_span     = (int)($linkout_config['jbrowse_hsp_max_span']             ?? 500000);
    $hsp_max_link     = max(1, (int)($linkout_config['jbrowse_hsp_max_link']      ?? 10));
    $jb2_assembly_id  = $organism . '_' . $assembly; // JBrowse2 assembly name format

    if ($is_genome_db) {
        // Genome BLAST: hit subject is a chromosome/scaffold; HSP coords are genomic.
        // Build a sessionTracks payload so JBrowse2 shows each HSP as a colored block.
        // Connect HSPs only if total span <= hsp_max_span AND score >= hsp_min_score.
        if (($linkout_config['jbrowse'] ?? false) && $has_jbrowse && !empty($hit['hsps'])) {
            // For genome BLAST, refName is the sequence ID (Hit_id), not the description (Hit_def)
            $subject    = $hit_id;
            $total_hsps = count($hit['hsps']);

            // Sort by score descending, keep top $hsp_max_link
            $hsps_sorted = $hit['hsps'];
            usort($hsps_sorted, fn($a, $b) => ($b['bit_score'] ?? 0) <=> ($a['bit_score'] ?? 0));
            $hsps_to_use = array_slice($hsps_sorted, 0, $hsp_max_link);
            $dropped     = $total_hsps - count($hsps_to_use);

            $all_s = array_map(fn($h) => min((int)$h['hit_from'], (int)$h['hit_to']) - 1, $hsps_to_use);
            $all_e = array_map(fn($h) => max((int)$h['hit_from'], (int)$h['hit_to']), $hsps_to_use);
            $parent_start = min($all_s);
            $parent_end   = max($all_e);
            $connect      = (($parent_end - $parent_start) <= $hsp_max_span);

            $subfeats   = [];
            $standalone = [];
            foreach ($hsps_to_use as $i => $hsp) {
                $s     = min((int)$hsp['hit_from'], (int)$hsp['hit_to']) - 1;
                $e     = max((int)$hsp['hit_from'], (int)$hsp['hit_to']);
                $score = (float)($hsp['bit_score'] ?? 0);
                $feat  = [
                    'uniqueId' => $hit_id . '_hsp_' . $i,
                    'refName'  => $subject,
                    'start'    => $s,
                    'end'      => $e,
                    'score'    => (int)$score,
                    'name'     => 'HSP ' . ($i + 1) . ' (evalue=' . sprintf('%.2e', $hsp['evalue'] ?? 0) . ')',
                    'type'     => 'match_part',
                ];
                if ($connect && $score >= $hsp_min_score) {
                    $subfeats[] = $feat;
                } else {
                    if (!$connect) $feat['name'] .= ' — span too large';
                    elseif ($score < $hsp_min_score) $feat['name'] .= ' — below score threshold';
                    $standalone[] = $feat;
                }
            }

            $track_id   = 'blast_' . substr(md5($hit_id), 0, 10);
            $track_name = 'BLAST: ' . $hit_id;
            if ($dropped > 0) {
                $track_name .= ' (top ' . count($hsps_to_use) . '/' . $total_hsps . ' HSPs by score)';
            }

            $features = [];
            if (!empty($subfeats)) {
                $features[] = [
                    'uniqueId'    => $hit_id . '_match',
                    'refName'     => $subject,
                    'start'       => $parent_start,
                    'end'         => $parent_end,
                    'name'        => $hit_id,
                    'type'        => 'match',
                    'subfeatures' => $subfeats,
                ];
            }
            foreach ($standalone as $sf) {
                $features[] = $sf;
            }

            $session_tracks = [[
                'type'          => 'FeatureTrack',
                'trackId'       => $track_id,
                'name'          => $track_name,
                'assemblyNames' => [$jb2_assembly_id],
                'adapter'       => ['type' => 'FromConfigAdapter', 'features' => $features],
            ]];

            $loc = $subject . ':' . ($parent_start + 1) . '-' . $parent_end;
            $url = moop_url_base() . "/jbrowse2.php?organism=" . urlencode($organism)
                 . '&assembly='      . urlencode($assembly)
                 . '&loc='           . urlencode($loc)
                 . '&sessionTracks=' . urlencode(json_encode($session_tracks))
                 . '&sessionTrackId='. urlencode($track_id);

            $hsp_count = count($hsps_to_use);
            if ($dropped > 0) {
                $btn_label = t_plain('View hit with %1$d of %2$d HSPs in browser', $hsp_count, $total_hsps);
            } else {
                $btn_label = $hsp_count === 1 ? t_plain('View hit with %d HSP in browser', 1) : t_plain('View hit with %d HSPs in browser', $hsp_count);
            }
            $html .= '<a href="' . htmlspecialchars($url) . '" target="_blank" '
                   . 'class="btn btn-sm btn-outline-success me-1">'
                   . htmlspecialchars($btn_label) . '</a>';
        }
    } else {
        // Feature BLAST (mRNA / CDS / protein): hit ID is a feature uniquename
        $entry   = $coords[$hit_id] ?? null;
        $gene_id = $entry ? $entry['gene_id'] : $hit_id;

        if (($linkout_config['gene_page'] ?? false) && $has_sqlite) {
            $url  = moop_url_base() . "/tools/parent.php?uniquename=" . urlencode($gene_id)
                  . '&organism=' . urlencode($organism)
                  . '&assembly=' . urlencode($assembly)
                  . (($context['gene_set'] ?? '') !== '' ? '&gene_set=' . urlencode($context['gene_set']) : '');
            $html .= '<a href="' . htmlspecialchars($url) . '" target="_blank" '
                   . 'class="btn btn-sm btn-outline-primary me-1">'
                   . $gene_page_label . '</a>';
        }

        if (($linkout_config['jbrowse'] ?? false) && $has_jbrowse && $entry) {
            $loc  = $entry['chr'] . ':' . $entry['start'] . '-' . $entry['end'];
            $url  = moop_url_base() . "/jbrowse2.php?organism=" . urlencode($organism)
                  . '&assembly=' . urlencode($assembly)
                  . '&loc=' . urlencode($loc);
            $html .= '<a href="' . htmlspecialchars($url) . '" target="_blank" '
                   . 'class="btn btn-sm btn-outline-success me-1">'
                   . $jbrowse_label . '</a>';
        }
    }

    // Global external linkouts — apply to all DB types
    foreach (($linkout_config['external'] ?? []) as $ext) {
        $template = $ext['url_template'] ?? '';
        $label    = htmlspecialchars($ext['label'] ?? 'Link');
        if (empty($template)) continue;
        $url = str_replace(
            ['{fasta_id}', '{organism}', '{assembly}'],
            [urlencode($hit_id), urlencode($organism), urlencode($assembly)],
            $template
        );
        $html .= '<a href="' . htmlspecialchars($url) . '" target="_blank" '
               . 'class="btn btn-sm btn-outline-secondary me-1">'
               . '<i class="fa fa-external-link-alt"></i> ' . $label . '</a>';
    }

    // Per-DB external linkouts — only for the active organism|assembly|seq_type
    if ($db_seq_type !== '') {
        $per_db_key = $organism . '|' . $assembly . '|' . $db_seq_type;
        foreach (($linkout_config['per_db_external'][$per_db_key] ?? []) as $ext) {
            $template = $ext['url_template'] ?? '';
            $label    = htmlspecialchars($ext['label'] ?? 'Link');
            if (empty($template)) continue;
            $url = str_replace(
                ['{fasta_id}', '{organism}', '{assembly}'],
                [urlencode($hit_id), urlencode($organism), urlencode($assembly)],
                $template
            );
            $html .= '<a href="' . htmlspecialchars($url) . '" target="_blank" '
                   . 'class="btn btn-sm btn-outline-info me-1">'
                   . '<i class="fa fa-external-link-alt"></i> ' . $label . '</a>';
        }
    }

    return $html;
}

function generateCompleteBlastVisualization($blast_result, $query_seq, $blast_program, $blast_options = [], $context = []) {
    if (!$blast_result['success']) {
        return '<div class="alert alert-danger"><i class="fa fa-exclamation-circle"></i> No results to visualize</div>';
    }

    $parse_result = parseBlastResults($blast_result['output']);

    // Check for parsing errors
    if (!empty($parse_result['error'])) {
        return '<div class="alert alert-danger"><i class="fa fa-exclamation-circle"></i> ' . t('Error parsing results: %s', $parse_result['error']) . '</div>';
    }

    $queries = $parse_result['queries'] ?? [];
    if (empty($queries)) {
        return '<div class="alert alert-info"><i class="fa fa-info-circle"></i> ' . t('No queries found in results') . '</div>';
    }

    $html = '<div class="blast-visualization">';

    // Determine correct unit based on program
    $unit = 'bp';
    if (strpos($blast_program, 'blastp') !== false || strpos($blast_program, 'tblastn') !== false) {
        $unit = 'aa';
    }

    // Search Parameters Section (moved up, collapsible)
    $html .= '<div style="background: white; border: 1px solid #dee2e6; border-radius: 8px; margin-bottom: 20px;">';
    $html .= '<div style="padding: 15px; cursor: pointer; background: #f8f9fa; border-bottom: 1px solid #dee2e6; display: flex; justify-content: space-between; align-items: center;" onclick="document.getElementById(\'search-params\').style.display = document.getElementById(\'search-params\').style.display === \'none\' ? \'block\' : \'none\'; this.querySelector(\'i\').style.transform = document.getElementById(\'search-params\').style.display === \'none\' ? \'rotate(0deg)\' : \'rotate(180deg)\';">';
    $html .= '<h6 style="margin: 0; color: #333;"><i class="fa fa-cog"></i> ' . t('Search Parameters') . '</h6>';
    $html .= '<i class="fa fa-chevron-down" style="transition: transform 0.2s; transform: rotate(0deg);"></i>';
    $html .= '</div>';

    $html .= '<div id="search-params" style="display: none; padding: 15px;">';

    // What BLAST recorded about this search (moop_blast_search_summary(), read from its XML).
    // Was a block of placeholder values typed into the code, the same on every result.
    $sr = $parse_result['search'] ?? [];
    $cell = fn(string $label, string $value_html) => '<div><small style="color: #666; font-weight: bold;">' . t($label)
                                                    . '</small><br><small>' . $value_html . '</small></div>';
    $facts = [];
    $facts[] = $cell('Program', htmlspecialchars($sr['version'] ?? strtoupper($blast_program)));
    if (isset($sr['db'])) $facts[] = $cell('Database', htmlspecialchars($sr['db']));
    if (isset($sr['db_len'], $sr['db_num'])) {
        // A protein database (blastp, blastx) is counted in residues, a nucleotide one in letters.
        $facts[] = $cell('Database Size', in_array($blast_program, ['blastp', 'blastx'], true)
            ? t('%1$s residues | %2$s sequences', number_format((float) $sr['db_len']), number_format((float) $sr['db_num']))
            : t('%1$s letters | %2$s sequences', number_format((float) $sr['db_len']), number_format((float) $sr['db_num'])));
    }
    if (isset($sr['matrix'])) {
        $facts[] = $cell('Matrix', htmlspecialchars($sr['matrix']));
    } elseif (isset($sr['match'], $sr['mismatch'])) {
        $facts[] = $cell('Match / Mismatch Scores', htmlspecialchars($sr['match'] . ' / ' . $sr['mismatch']));
    }
    if (isset($sr['gap_open'], $sr['gap_extend'])) {
        // 0/0 is how BLAST reports megablast's linear (non-affine) gap costs, not "free gaps".
        $facts[] = $cell('Gap Penalties', ((int) $sr['gap_open'] === 0 && (int) $sr['gap_extend'] === 0)
            ? t('linear (megablast default)')
            : t('Existence: %1$s, Extension: %2$s', $sr['gap_open'], $sr['gap_extend']));
    }
    $html .= '<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 20px; margin-bottom: 20px;">'
           . implode('', $facts) . '</div>';

    // New search parameters from form - third grid
    $html .= '<hr style="margin: 15px 0;">';
    $html .= '<h6 style="color: #333; margin-bottom: 15px;"><i class="fa fa-sliders-h"></i> ' . t('Form Parameters') . '</h6>';
    $html .= '<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 20px;">';

    // Basic parameters
    $html .= '<div>';
    $html .= '<small style="color: #666; font-weight: bold;">' . t('E-value Threshold') . '</small><br>';
    $html .= '<small>' . htmlspecialchars($blast_options['evalue'] ?? '1e-3') . '</small>';
    $html .= '</div>';

    $html .= '<div>';
    $html .= '<small style="color: #666; font-weight: bold;">' . t('Maximum Hits') . '</small><br>';
    $html .= '<small>' . ($blast_options['max_hits'] ?? 10) . '</small>';
    $html .= '</div>';

    $html .= '<div>';
    $html .= '<small style="color: #666; font-weight: bold;">' . t('Scoring Matrix') . '</small><br>';
    $html .= '<small>' . htmlspecialchars($blast_options['matrix'] ?? 'BLOSUM62') . '</small>';
    $html .= '</div>';

    // Advanced parameters
    if (!empty($blast_options['word_size'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Word Size') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['word_size']) . '</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['gapopen'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Gap Open Penalty') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['gapopen']) . '</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['gapextend'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Gap Extend Penalty') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['gapextend']) . '</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['max_hsps'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Max HSPs') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['max_hsps']) . '</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['perc_identity'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Percent Identity') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['perc_identity']) . '%</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['culling_limit'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Culling Limit') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['culling_limit']) . '</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['threshold'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Threshold') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['threshold']) . '</small>';
        $html .= '</div>';
    }

    if (!empty($blast_options['strand'])) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Strand') . '</small><br>';
        $html .= '<small>' . htmlspecialchars($blast_options['strand']) . '</small>';
        $html .= '</div>';
    }

    if ($blast_options['soft_masking'] ?? false) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Soft Masking') . '</small><br>';
        $html .= '<small><i class="fa fa-check" style="color: green;"></i> Enabled</small>';
        $html .= '</div>';
    }

    if ($blast_options['filter'] ?? false) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Filter Low Complexity') . '</small><br>';
        $html .= '<small><i class="fa fa-check" style="color: green;"></i> Enabled</small>';
        $html .= '</div>';
    }

    if ($blast_options['ungapped'] ?? false) {
        $html .= '<div>';
        $html .= '<small style="color: #666; font-weight: bold;">' . t('Ungapped') . '</small><br>';
        $html .= '<small><i class="fa fa-check" style="color: green;"></i> Enabled</small>';
        $html .= '</div>';
    }

    $html .= '</div>';
    $html .= '</div>';
    $html .= '</div>';

    // Query Summary Table - all queries with links to their sections
    $html .= '<div style="background: white; border: 1px solid #dee2e6; border-radius: 8px; padding: 15px; margin-bottom: 20px;">';
    $html .= '<h6 style="margin-bottom: 15px;"><i class="fa fa-list"></i> Query Summary</h6>';
    $html .= '<div style="overflow-x: auto;">';
    $html .= '<table class="table table-sm table-striped">';
    $html .= '<thead class="table-light">';
    $html .= '<tr>';
    $html .= '<th style="width: 5%">#</th>';
    $html .= '<th style="width: 35%">' . t('Query Name') . '</th>';
    $html .= '<th style="width: 15%">' . t('Length') . '</th>';
    $html .= '<th style="width: 15%">' . t('Hits') . '</th>';
    $html .= '<th style="width: 30%">' . t('Best E-value') . '</th>';
    $html .= '</tr>';
    $html .= '</thead>';
    $html .= '<tbody>';

    foreach ($queries as $query_idx => $query) {
        $query_num = $query_idx + 1;
        $query_name = !empty($query['query_desc']) ? htmlspecialchars($query['query_desc']) : 'Query ' . $query_num;
        $best_evalue = $query['total_hits'] > 0 ? $query['hits'][0]['best_evalue'] : PHP_FLOAT_MAX;
        $best_evalue_display = $best_evalue < PHP_FLOAT_MAX ? sprintf('%.2e', $best_evalue) : 'N/A';

        $html .= '<tr style="cursor: pointer;" onclick="document.getElementById(\'query-' . $query_num . '\').scrollIntoView({behavior: \'smooth\', block: \'start\'});">';
        $html .= '<td><strong>' . $query_num . '</strong></td>';
        $html .= '<td><small>' . $query_name . '</small></td>';
        $html .= '<td>' . $query['query_length'] . ' ' . $unit . '</td>';
        $html .= '<td>' . $query['total_hits'] . '</td>';
        $html .= '<td><small>' . $best_evalue_display . '</small></td>';
        $html .= '</tr>';
    }

    $html .= '</tbody>';
    $html .= '</table>';
    $html .= '</div>';
    $html .= '</div>';

    // Individual Query Sections - each query with all its results
    foreach ($queries as $query_idx => $query) {
        $query_num = $query_idx + 1;
        $query_name = !empty($query['query_desc']) ? htmlspecialchars($query['query_desc']) : 'Query ' . $query_num;

        // Collapsible query section
        $html .= '<div id="query-' . $query_num . '" style="background: white; border: 1px solid #dee2e6; border-radius: 8px; margin-bottom: 20px; scroll-margin-top: 20px;">';

        // Query header (collapsible)
        $html .= '<div id="query-' . $query_num . '-header" style="padding: 15px; cursor: pointer; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; border-radius: 8px 8px 0 0; display: flex; justify-content: space-between; align-items: center;" onclick="toggleQuerySection(\'query-' . $query_num . '-content\', this);">';
        $html .= '<h5 style="margin: 0;"><i class="fa fa-dna"></i> Query ' . $query_num . ': ' . $query_name . '</h5>';
        $html .= '<i class="fa fa-chevron-down" style="transition: transform 0.2s; transform: rotate(0deg);"></i>';
        $html .= '</div>';

        // Query content (collapsible)
        $html .= '<div id="query-' . $query_num . '-content" style="padding: 15px;">';

        // Query info
        $html .= '<div style="background: #f8f9fa; border-left: 4px solid #667eea; padding: 12px; margin-bottom: 15px; border-radius: 4px;">';
        $html .= '<small>';
        if (!empty($query['query_desc'])) {
            $html .= '<strong>' . t('Description:') . '</strong> ' . htmlspecialchars($query['query_desc']) . '<br>';
        }
        $html .= '<strong>' . t('Length:') . '</strong> ' . $query['query_length'] . ' ' . $unit . ' | ';
        $html .= '<strong>' . t('Total Hits:') . '</strong> ' . $query['total_hits'];
        $html .= '</small>';
        $html .= '</div>';

        if ($query['total_hits'] === 0) {
            // A short DNA query lost to the defaults gets the reason and a one-click re-run
            // (js/modules/blast-short-nudge.js) -- a bare "no matches" reads as "not in this
            // genome", which for a primer is usually false.
            $short_reason = blast_short_query_reason((string)$blast_program, (int)$query['query_length'], $blast_options);
            if ($short_reason !== '') {
                $html .= '<div class="alert alert-warning blast-short-zero"><small>'
                       . '<strong>' . t('No matches kept.') . '</strong> ' . htmlspecialchars($short_reason)
                       . ' <button type="button" class="btn btn-sm btn-moop-teal text-white ms-1 blast-rerun-short">'
                       . '<i class="fa fa-redo me-1"></i>' . t('Re-run with BLASTn-short') . '</button> '
                       . help_modal_trigger('blast-short-help', '', 'Help: searching with primers and other short sequences')
                       . '</small></div>';
            } else {
                $html .= '<div class="alert alert-info"><small>' . t('No significant matches found for this query') . '</small></div>';
            }
        } else {
            // HSP visualization for this query
            $html .= generateHspVisualizationWithLines($query, $blast_program, $query_num);

            // Hits summary table for this query
            $html .= generateHitsSummaryTable($query, $query_num);

            // Alignment viewer for this query
            $html .= generateAlignmentViewer($query, $blast_program, $query_num, $context);
        }

        $html .= '</div>'; // End query content
        $html .= '</div>'; // End query section
    }

    $html .= '</div>';

    return $html;
}

function generateHspVisualizationWithLines($results, $blast_program = 'blastn', $query_num = 1) {
    if (empty($results['hits']) || $results['query_length'] <= 0) {
        return '';
    }

    // Determine unit based on program
    $unit = 'bp';
    if (strpos($blast_program, 'blastp') !== false || strpos($blast_program, 'tblastn') !== false) {
        $unit = 'aa';
    }

    $html = '<div class="blast-hsp-visualization" style="margin: 20px 0; background: white; border: 1px solid #ddd; border-radius: 8px; padding: 20px;">';
    $html .= '<h6 style="text-align: center;"><i class="fa fa-ruler-horizontal"></i> Query Length (' . $results['query_length'] . ' ' . $unit . ')</h6>';

    // Add CSS for HSP visualization
    $html .= '<style>';
    $html .= '.hsp-row { display: flex; align-items: center; margin-bottom: 12px; }';
    $html .= '.hsp-label { width: 150px; min-width: 150px; max-width: 150px; padding-right: 10px; font-size: 11px; font-weight: bold; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; cursor: default; }';
    $html .= '.hsp-segments { display: flex; align-items: center; width: 800px; position: relative; z-index: 5; }';
    $html .= '.hsp-segment { height: 16px; display: inline-block; margin-right: 0; cursor: pointer; border: 1px solid #333; transition: opacity 0.2s; }';
    $html .= '.hsp-segment:hover { opacity: 0.8; }';
    $html .= '.hsp-gap { height: 4px; background: #e0e0e0; display: inline-block; margin-top: 6px; }';
    $html .= '.hsp-connector { width: 1px; height: 6px; background: #000; display: inline-block; margin: 5px 0; }';
    $html .= '.color-black { background-color: #000000; }';
    $html .= '.color-blue { background-color: #0047c8; }';
    $html .= '.color-green { background-color: #77de75; }';
    $html .= '.color-purple { background-color: #e967f5; }';
    $html .= '.color-red { background-color: #e83a2d; }';
    $html .= '.hit-highlighted { background-color: #ffffcc !important; transition: background-color 0.3s ease-out; }';
    $html .= '.hsp-row:hover { background-color: rgba(100, 150, 255, 0.1); }';
    $html .= '</style>';

     // Add JavaScript for hit navigation and highlighting
     $html .= '<script>';
     $html .= 'function jumpToHit(hitIndex, queryNum) {';
     $html .= '  if (queryNum === undefined) queryNum = 1;';
     $html .= '  const hitId = "query-" + queryNum + "-hit-" + (hitIndex + 1);';
     $html .= '  const element = document.getElementById(hitId);';
     $html .= '  if (element) {';
     $html .= '    element.scrollIntoView({ behavior: "smooth", block: "start" });';
     $html .= '    highlightHitElement(element);';
     $html .= '  }';
     $html .= '}';
     $html .= 'function highlightHitElement(element) {';
     $html .= '  if (!element) return;';
     $html .= '  element.classList.remove("hit-highlighted");';
     $html .= '  void element.offsetWidth;';
     $html .= '  element.classList.add("hit-highlighted");';
     $html .= '  setTimeout(() => {';
     $html .= '    element.classList.remove("hit-highlighted");';
     $html .= '  }, 3500);';
     $html .= '}';
     $html .= 'function highlightHit(hitIndex, queryNum) {';
     $html .= '  if (queryNum === undefined) queryNum = 1;';
     $html .= '  jumpToHit(hitIndex, queryNum);';
     $html .= '}';
     $html .= '</script>';

    $html .= '<div style="margin-top: 15px; margin: 0 auto; width: 1000px; text-align: center;">';

    // Generate just the score legend (outside overflow:hidden)
    $html .= generateQueryScoreLegend($results['query_length'], $results['query_name']);

    // Pixel unit calculation based on query length (800px width)
    $px_unit = 800 / $results['query_length'];

    // Calculate total HSP rows
    $total_hsp_rows = 0;
    foreach ($results['hits'] as $hit) {
        $total_hsp_rows += count($hit['hsps']) + 1; // +1 for spacing between hits
    }

    // Calculate height needed for HSP rows (each row ~25px + spacing)
    $hsp_content_height = ($total_hsp_rows * 25) + 50;
    // Set max height before scrolling (e.g., 400px)
    $max_hsp_height = 400;
    $use_scroll = $hsp_content_height > $max_hsp_height;

    // Total container height: ticks (80px) + HSP area (either content height or max height)
    $hsp_display_height = min($hsp_content_height, $max_hsp_height);
    $total_container_height = 80 + $hsp_display_height;

    // Create a container for scale ticks and HSPs with relative positioning
    // This must be tall enough for all tick lines to extend down
    $html .= '<div style="position: relative; overflow: hidden; height: ' . $total_container_height . 'px;">';

    // Generate the query scale ruler with ticks (inside overflow:hidden to be clipped properly)
    $html .= generateQueryScaleTicks($results['query_length']);

    // Create a scrollable wrapper for HSP rows positioned below the ticks
    $scroll_style = $use_scroll ? 'overflow-y: scroll;' : 'overflow: hidden;';
    $html .= '<div style="position: absolute; top: 80px; left: 0; right: 0; height: ' . $hsp_display_height . 'px; ' . $scroll_style . '">';

    // Wrapper for HSP rows
    $html .= '<div style="padding-top: 0;">';

    foreach ($results['hits'] as $hit_idx => $hit) {
        $hit_num = $hit_idx + 1;

        // Organize HSPs by their query coordinates
        $hsp_positions = [];
        $hsp_scores = [];
        $hsp_details = [];

        foreach ($hit['hsps'] as $hsp_idx => $hsp) {
            $q_start = min($hsp['query_from'], $hsp['query_to']);
            $q_end = max($hsp['query_from'], $hsp['query_to']);

            $hsp_positions[] = [
                'start' => $q_start,
                'end' => $q_end,
                'index' => $hsp_idx
            ];

            $hsp_scores[$hsp_idx] = $hsp['bit_score'];
            $hsp_details[$hsp_idx] = $hsp;
        }

        // Sort by start position
        usort($hsp_positions, function($a, $b) {
            return $a['start'] - $b['start'];
        });

        // Build HTML row
        $hit_clean_id = cleanBlastHitId($hit['id']);
        $html .= '<div class="hsp-row" style="cursor: pointer;" onclick="jumpToHit(' . $hit_idx . ', ' . $query_num . '); highlightHit(' . $hit_idx . ', ' . $query_num . ');">';
        $html .= '<div class="hsp-label" title="' . htmlspecialchars($hit['subject']) . '">' . htmlspecialchars($hit_clean_id) . '</div>';
        $html .= '<div class="hsp-segments">';

        // First HSP
        if (!empty($hsp_positions)) {
            $first_hsp = $hsp_positions[0];
            $first_idx = $first_hsp['index'];
            $color = getHspColorClass($hsp_scores[$first_idx]);
            $segment_width = ($first_hsp['end'] - $first_hsp['start']) * $px_unit;

            // Add leading gap if needed
            if ($first_hsp['start'] > 1) {
                $gap_width = ($first_hsp['start'] - 1) * $px_unit;
                $html .= '<div class="hsp-gap" style="width: ' . $gap_width . 'px;"></div>';
            }

            $hsp = $hsp_details[$first_idx];
            $title = $hit_clean_id . ' - HSP ' . ($first_idx + 1) . ': ' . $hsp['percent_identity'] . '% identity | E-value: ' . sprintf('%.2e', $hsp['evalue']);
            $html .= '<div class="hsp-segment ' . $color . '" style="width: ' . $segment_width . 'px;" title="' . htmlspecialchars($title) . '"></div>';

            // Additional HSPs with connecting logic
            for ($k = 1; $k < count($hsp_positions); $k++) {
                $current = $hsp_positions[$k];
                $previous = $hsp_positions[$k - 1];
                $current_idx = $current['index'];

                $gap = $current['start'] - $previous['end'];

                if ($gap > 0) {
                    // Add connector lines for gaps
                    $html .= '<div class="hsp-connector"></div>';

                    // Add gap
                    $gap_width = $gap * $px_unit;
                    $html .= '<div class="hsp-gap" style="width: ' . $gap_width . 'px;"></div>';

                    // Add connector on other side
                    $html .= '<div class="hsp-connector"></div>';
                } else {
                    // Overlapping or adjacent HSPs - just connector line
                    $html .= '<div class="hsp-connector"></div>';
                }

                // Add current segment
                $color = getHspColorClass($hsp_scores[$current_idx]);
                $segment_width = ($current['end'] - $current['start']) * $px_unit;
                $hsp = $hsp_details[$current_idx];
                $title = $hit_clean_id . ' - HSP ' . ($current_idx + 1) . ': ' . $hsp['percent_identity'] . '% identity | E-value: ' . sprintf('%.2e', $hsp['evalue']);
                $html .= '<div class="hsp-segment ' . $color . '" style="width: ' . $segment_width . 'px;" title="' . htmlspecialchars($title) . '"></div>';
            }

            // Trailing gap
            $last_end = $hsp_positions[count($hsp_positions) - 1]['end'];
            if ($last_end < $results['query_length']) {
                $trailing_gap = ($results['query_length'] - $last_end) * $px_unit;
                $html .= '<div class="hsp-gap" style="width: ' . $trailing_gap . 'px;"></div>';
            }
        }

        $html .= '</div>';
        $html .= '</div>';
    }

    // Close the HSP rows wrapper
    $html .= '</div>';

    // Close the scrollable HSP container
    $html .= '</div>';

    // Close the main overflow:hidden container and outer div
    $html .= '</div>';
    $html .= '</div>';

    // Add description below the HSP visualization (outside the relative container so ticks don't overlap)
    $html .= '<small class="text-muted" style="display: block; margin-top: 15px; margin-bottom: 30px; text-align: center;">' . t_markup('Each color represents a different %s range.', gloss_first('bit score')) . ' ' . t('Lines connect adjacent HSPs on the query sequence.') . '</small>';

    return $html;
}

function getHspColorClass($score) {
    if ($score <= 40) {
        return 'color-black';
    } elseif ($score <= 50) {
        return 'color-blue';
    } elseif ($score <= 80) {
        return 'color-green';
    } elseif ($score <= 200) {
        return 'color-purple';
    } else {
        return 'color-red';
    }
}

function blastAlignmentResidueSteps($blast_program) {
    switch (strtolower(trim((string)$blast_program))) {
        case 'blastx':  return ['query' => 3, 'hit' => 1]; // translated nt query vs protein db
        case 'tblastn': return ['query' => 1, 'hit' => 3]; // protein query vs translated nt db
        case 'tblastx': return ['query' => 3, 'hit' => 3]; // both sides translated
        default:        return ['query' => 1, 'hit' => 1]; // blastn, blastp, *-short
    }
}

function blastAlignmentSide($label, $block, $start, $step, $descending, $coord_width) {
    $residues = strlen($block) - substr_count($block, '-');

    if ($residues === 0) {
        // An all-gap block consumes no coordinate; stay where we are.
        $end  = $start;
        $next = $start;
    } elseif ($descending) {
        $end  = $start - ($residues * $step) + 1;
        $next = $end - 1;
    } else {
        $end  = $start + ($residues * $step) - 1;
        $next = $end + 1;
    }

    $line = sprintf('%-5s %' . $coord_width . 'd  %s  %d', $label, $start, $block, $end);
    return [$line, $next];
}

function formatBlastAlignment(array $hsp, $blast_program = 'blastn', $width = 60) {
    $query_seq = (string)($hsp['query_seq'] ?? '');
    $hit_seq   = (string)($hsp['hit_seq'] ?? '');
    $midline   = (string)($hsp['midline'] ?? '');

    if ($query_seq === '' && $hit_seq === '') {
        return '';
    }

    $width = max(1, (int)$width);

    $query_from = (int)($hsp['query_from'] ?? 0);
    $query_to   = (int)($hsp['query_to'] ?? 0);
    $hit_from   = (int)($hsp['hit_from'] ?? 0);
    $hit_to     = (int)($hsp['hit_to'] ?? 0);

    // Frames are optional: absent for blastp, and absent from older parsed results.
    $query_frame = (int)($hsp['query_frame'] ?? 0);
    $hit_frame   = (int)($hsp['hit_frame'] ?? 0);

    $steps = blastAlignmentResidueSteps($blast_program);

    $query_descending = ($query_to < $query_from) || ($query_frame < 0);
    $hit_descending   = ($hit_to   < $hit_from)   || ($hit_frame   < 0);

    $coord_width = max(
        strlen((string)$query_from), strlen((string)$query_to),
        strlen((string)$hit_from),   strlen((string)$hit_to)
    );

    // 5 for the label, 1 space, the coordinate, then the two-space gutter.
    $indent  = str_repeat(' ', 5 + 1 + $coord_width + 2);
    $columns = max(strlen($query_seq), strlen($hit_seq));

    $query_pos = $query_from;
    $hit_pos   = $hit_from;
    $blocks    = [];

    for ($offset = 0; $offset < $columns; $offset += $width) {
        list($query_line, $query_pos) = blastAlignmentSide(
            'Query', substr($query_seq, $offset, $width),
            $query_pos, $steps['query'], $query_descending, $coord_width
        );
        list($hit_line, $hit_pos) = blastAlignmentSide(
            'Sbjct', substr($hit_seq, $offset, $width),
            $hit_pos, $steps['hit'], $hit_descending, $coord_width
        );

        $blocks[] = $query_line . "\n"
                  . $indent . substr($midline, $offset, $width) . "\n"
                  . $hit_line;
    }

    return implode("\n\n", $blocks) . "\n";
}

