/** Temp file + rename, 0640. False on any failure. */

functions.code:
function moop_feedback_write(string $f, array $all): bool {
    $tmp = $f . '.tmp' . getmypid();
    $json = json_encode(array_values($all), JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
    if ($json === false || @file_put_contents($tmp, $json . "\n") === false) { @unlink($tmp); return false; }
    @chmod($tmp, 0640);
    if (!@rename($tmp, $f)) { @unlink($tmp); return false; }
    return true;
}

function normalize_access_level($level) {
    return strtoupper(trim((string)($level ?? '')));
}

function access_level_hierarchy() {
    return [
        'ADMIN'        => 4,
        'IP_IN_RANGE'  => 3,
        'COLLABORATOR' => 2,
        'PUBLIC'       => 1,
    ];
}

function moop_jbrowse_track_access(array $track): string {
    if ((string)($track['metadata']['gene_set'] ?? '') !== '') return 'GENE_SET';
    $level = trim((string)($track['metadata']['access_level'] ?? ''));
    return $level === '' ? 'NOT_SET' : normalize_access_level($level);
}

function required_access_level_value($level) {
    return access_level_hierarchy()[normalize_access_level($level)] ?? 4;
}

function granted_access_level_value($level) {
    return access_level_hierarchy()[normalize_access_level($level)] ?? 0;
}

function genome_display_name($name, $accession = ''): string {
    $name = trim((string)$name);
    if ($name === '' || $name === trim((string)$accession)) return '';
    if (in_array(strtolower($name), ['na', 'n/a', 'none', 'null', '-', 'unknown'], true)) return '';
    return $name;
}

function assembly_label($name, $accession) {
    $accession = trim((string)$accession);
    $name = genome_display_name($name, $accession);
    if ($name === '') {
        return $accession;
    }
    if ($accession === '') {
        return $name;
    }
    return "$name ($accession)";
}

function gene_set_label(string $organism, $genome_name, string $accession, string $gene_set, bool $html = false): string {
    $species = str_replace('_', ' ', $organism);
    $rest = assembly_label($genome_name, $accession) . ($gene_set !== '' ? " \u{203A} $gene_set" : '');
    if (!$html) return "$species \u{00B7} $rest";
    return '<em class="sci-name">' . htmlspecialchars($species) . '</em>'
         . ' <span class="text-muted">&middot; ' . htmlspecialchars($rest) . '</span>';
}

function getAssemblyInfo($assembly, $db_path) {
    $genome_id = null;
    $genome_name = null;
    $genome_accession = $assembly;

    if (!file_exists($db_path)) {
        return [$genome_id, $genome_name, $genome_accession];
    }

    try {
        $query = "SELECT genome_id, genome_name, genome_accession FROM genome WHERE genome_accession = ? OR genome_name = ?";
        $results = fetchData($query, $db_path, [$assembly, $assembly]);
        if (!empty($results)) {
            $genome_id = $results[0]['genome_id'];
            $genome_name = $results[0]['genome_name'];
            $genome_accession = $results[0]['genome_accession'];
        }
    } catch (Exception $e) {
        // If query fails, return defaults
    }

    return [$genome_id, $genome_name, $genome_accession];
}

function getGeneSetInfo($assembly, $gene_set, $db_path) {
    if (!file_exists($db_path)) {
        return [null, null];
    }

    try {
        $query = "SELECT gs.gene_set_id, gs.genome_id
                  FROM gene_set gs
                  JOIN genome g ON gs.genome_id = g.genome_id
                  WHERE (g.genome_accession = ? OR g.genome_name = ?)
                  AND gs.gene_set_name = ?";
        $results = fetchData($query, $db_path, [$assembly, $assembly, $gene_set]);
        if (!empty($results)) {
            return [(int)$results[0]['gene_set_id'], (int)$results[0]['genome_id']];
        }
    } catch (Exception $e) {
        // return defaults
    }

    return [null, null];
}

function countAccessibleScope(array $organisms, ?string $assembly = null): array {
    if (empty($organisms)) return ['assemblies' => 0, 'gene_sets' => 0];

    $assemblies = [];
    $gene_sets  = [];
    foreach (getAccessibleGeneSets() as $org_data) {
        foreach ($org_data as $org => $sources) {
            if (!in_array($org, $organisms, true)) continue;
            foreach ($sources as $source) {
                $accession = $source['genome_accession'] ?? $source['assembly'];
                if ($assembly !== null && $accession !== $assembly) continue;
                $assemblies[$org . '|' . $accession] = true;
                $gene_sets[$org . '|' . $accession . '|' . ($source['gene_set'] ?? '')] = true;
            }
        }
    }
    return ['assemblies' => count($assemblies), 'gene_sets' => count($gene_sets)];
}

function getAccessibleGeneSets($specific_organism = null, $specific_assembly = null, $specific_gene_set = null, bool $include_blast_only = false) {
    $result = moop_accessible_gene_sets_all($specific_organism, $specific_assembly, $specific_gene_set);
    if ($include_blast_only) return $result;
    foreach ($result as $group => &$by_org) {
        foreach ($by_org as $org => $sources) {
            $kept = array_values(array_filter($sources, fn($s) => empty($s['blast_only'])));
            if ($kept) $by_org[$org] = $kept; else unset($by_org[$org]);
        }
        if (!$by_org) unset($result[$group]);
    }
    unset($by_org);
    return $result;
}

functions.comment:
/**
* The gene sets this viewer may see, by group then organism.
*
* $include_blast_only: also return BLAST-only genomes -- groups entries with gene_set 'blast_only'
* (MOOP_BLAST_ONLY) that stand for the assembly itself (moop_blast_only_genome()). They carry
* 'blast_only' => true, gene_set 'blast_only',
* and 'path' = the ASSEMBLY directory. OFF by default, because nearly every caller (search, MOOPmart,
* downloads, Primer tools, expression) assumes a gene set loaded in organism.sqlite; only BLAST and
* the genome browser's "may open this assembly" ask for them.
*/
function getAccessibleGeneSets($specific_organism = null, $specific_assembly = null, $specific_gene_set = null, bool $include_blast_only = false) {
$result = moop_accessible_gene_sets_all($specific_organism, $specific_assembly, $specific_gene_set);
if ($include_blast_only) return $result;
foreach ($result as $group => &$by_org) {
foreach ($by_org as $org => $sources) {
$kept = array_values(array_filter($sources, fn($s) => empty($s['blast_only'])));
if ($kept) $by_org[$org] = $kept; else unset($by_org[$org]);
}
if (!$by_org) unset($result[$group]);
}
unset($by_org);
return $result;
}

/** getAccessibleGeneSets() with BLAST-only genomes included; the session cache holds this form. */

functions.code:
function moop_accessible_gene_sets_all($specific_organism = null, $specific_assembly = null, $specific_gene_set = null) {
    $config = ConfigManager::getInstance();
    $organism_data = $config->getPath('organism_data');
    $metadata_path = $config->getPath('metadata_path');

    $groups_data = [];
    $groups_file = "$metadata_path/organism_assembly_groups.json";
    if (file_exists($groups_file)) {
        $groups_data = loadJsonFile($groups_file, []);
    }

    // Session-based caching for full (unfiltered) requests only
    $use_cache = ($specific_organism === null && $specific_assembly === null && $specific_gene_set === null
                  && session_status() === PHP_SESSION_ACTIVE);
    if ($use_cache) {
        $cache_key = 'accessible_assemblies_cache_v2';   // v2: includes BLAST-only genomes
        $groups_mtime = file_exists($groups_file) ? filemtime($groups_file) : 0;
        $access_level = get_access_level();
        // The cached list holds each gene set's DATABASE ids (gene_set_id, genome_id), and a
        // pipeline reload renumbers them. Keyed on groups + level alone, a session that began
        // before a reload kept the old ids and the ID search found nothing in that organism
        // (Smed, reloaded 2026-11-16: SMED30002742 "not found" for a logged-in admin, 11-17).
        // So the key also carries every organism.sqlite's mtime+size -- one stat each, cached
        // by the kernel; the per-organism identity file cache uses the same fingerprint.
        $dbs_fingerprint = '';
        foreach (array_unique(array_column($groups_data, 'organism')) as $__org) {
            $__st = @stat($config->getPath('organism_data') . "/$__org/organism.sqlite");
            $dbs_fingerprint .= $__org . ':' . ($__st ? $__st['mtime'] . '.' . $__st['size'] : '-') . ';';
        }
        $dbs_fingerprint = md5($dbs_fingerprint);

        if (isset($_SESSION[$cache_key]) &&
            $_SESSION[$cache_key]['groups_mtime'] === $groups_mtime &&
            ($_SESSION[$cache_key]['dbs_fingerprint'] ?? null) === $dbs_fingerprint &&
            $_SESSION[$cache_key]['access_level'] === $access_level) {
            return $_SESSION[$cache_key]['data'];
        }
    }

    $accessible_sources = [];

    // Filter entries to process
    $entries_to_process = $groups_data;

    if (!empty($specific_organism)) {
        $entries_to_process = array_filter($entries_to_process, function($entry) use ($specific_organism) {
            return $entry['organism'] === $specific_organism;
        });
    }
    if (!empty($specific_assembly)) {
        $entries_to_process = array_filter($entries_to_process, function($entry) use ($specific_assembly) {
            return $entry['assembly'] === $specific_assembly;
        });
    }
    if (!empty($specific_gene_set)) {
        $entries_to_process = array_filter($entries_to_process, function($entry) use ($specific_gene_set) {
            return ($entry['gene_set'] ?? '') === $specific_gene_set;
        });
    }

    // ── Pass 1: ACCESS ────────────────────────────────────────────────────────────
    // Decided entirely from organism_assembly_groups.json + users.json (via
    // has_gene_set_access) plus directory tests. No database is opened here. Measured
    // cold, this whole pass is 1.7 ms; the identity resolution below used to be ~240 ms.
    // Keeping the two separate is what lets the expensive half be cached and the cheap
    // half stay exact. See lib/gene_set_identity.php.
    $survivors = [];
    foreach ($entries_to_process as $entry) {
        $org      = $entry['organism'];
        $assembly = $entry['assembly'];
        $gene_set = $entry['gene_set'] ?? '';

        // Access check — use has_gene_set_access which handles all levels
        if (!has_gene_set_access($org, $assembly, $gene_set)) {
            continue;
        }

        $assembly_path  = "$organism_data/$org/$assembly";

        // gene_set 'blast_only' = the assembly itself, a BLAST-only genome: valid only with its
        // genome FASTA (or BLAST index) under an organism already on the site.
        // '' is not a gene set: its path would be the assembly directory and any *.fa in it
        // would pass the test below -- how a '' entry once slipped through by accident.
        if ($gene_set === '') continue;
        if ($gene_set === MOOP_BLAST_ONLY) {
            if (moop_blast_only_genome($org, $assembly) !== null) {
                $survivors[] = [$org, $assembly, MOOP_BLAST_ONLY, $entry['groups'] ?? []];
            }
            continue;
        }
        $gene_set_path  = "$assembly_path/$gene_set";

        if (!is_dir($assembly_path) || !is_dir($gene_set_path)) {
            continue;
        }

        // Gene_set directory must contain at least one sequence FASTA
        $has_fasta = false;
        foreach (['.fa', '.fasta', '.faa', '.nt.fa', '.aa.fa'] as $ext) {
            if (glob("$gene_set_path/*$ext")) {
                $has_fasta = true;
                break;
            }
        }
        if (!$has_fasta) {
            continue;
        }

        $survivors[] = [$org, $assembly, $gene_set, $entry['groups'] ?? []];
    }

    // ── Pass 2: IDENTITY ──────────────────────────────────────────────────────────
    // One batched, per-organism-fingerprinted lookup for the organisms that survived the
    // access pass, replacing a validateAssemblyDirectories() call per organism (which is
    // a health-check function — it builds mismatch and orphan reports this caller then
    // discarded) plus a getGeneSetInfo() query per entry.
    $identity = moop_gene_set_identity(array_column($survivors, 0), $organism_data);

    foreach ($survivors as [$org, $assembly, $gene_set, $entry_groups]) {
        $ids = moop_resolve_gene_set_identity(
            $identity[$org] ?? [], "$organism_data/$org", $assembly, $gene_set
        );
        $actual_assembly_dir = $ids['assembly_dir'];
        $blast_only = ($gene_set === MOOP_BLAST_ONLY);

        $accessible_sources[] = [
            'organism'         => $org,
            'assembly'         => $actual_assembly_dir,
            'gene_set'         => $gene_set,
            'genome_name'      => $ids['genome_name'],
            // A BLAST-only genome may have no genome row yet: its directory name is its identity.
            'genome_accession' => $ids['genome_accession'] ?? ($blast_only ? $actual_assembly_dir : null),
            'path'             => "$organism_data/$org/$actual_assembly_dir" . ($blast_only ? '' : "/$gene_set"),
            'groups'           => $entry_groups,
            'genome_id'        => $ids['genome_id'],
            'gene_set_id'      => $ids['gene_set_id'],
            'blast_only'       => $blast_only,
        ];
    }

    // Organize by group -> organism
    $organized = [];
    foreach ($accessible_sources as $source) {
        foreach ($source['groups'] as $group) {
            if (!isset($organized[$group])) {
                $organized[$group] = [];
            }
            $org = $source['organism'];
            if (!isset($organized[$group][$org])) {
                $organized[$group][$org] = [];
            }
            $organized[$group][$org][] = $source;
        }
    }

    // Sort groups (PUBLIC first, then alphabetically)
    uksort($organized, function($a, $b) {
        if ($a === 'PUBLIC') return -1;
        if ($b === 'PUBLIC') return 1;
        return strcasecmp($a, $b);
    });

    // Sort organisms within each group alphabetically
    foreach ($organized as &$group_data) {
        ksort($group_data);
    }

    if ($use_cache) {
        $_SESSION[$cache_key] = [
            'groups_mtime'    => $groups_mtime,
            'dbs_fingerprint' => $dbs_fingerprint,
            'access_level'    => $access_level,
            'data'         => $organized,
        ];
    }

    return $organized;
}

function moop_search_permitted_scope(string $organism): ?array {
    $permitted = [];
    foreach (getAccessibleGeneSets($organism) as $by_org) {
        foreach ($by_org[$organism] ?? [] as $s) {
            $acc = (string)($s['genome_accession'] ?? '');
            if ($acc === '') continue;
            $permitted[$acc . "\t" . $s['gene_set']] = ['assembly' => $acc, 'gene_set' => (string)$s['gene_set']];
        }
    }
    $identity = moop_gene_set_identity([$organism], ConfigManager::getInstance()->getPath('organism_data'))[$organism] ?? [];
    $acc_by_genome = array_column($identity['genomes'] ?? [], 'genome_accession', 'genome_id');
    foreach ($identity['gene_sets'] ?? [] as $gs) {
        if (!isset($permitted[($acc_by_genome[$gs['genome_id']] ?? '') . "\t" . $gs['gene_set_name']])) {
            return array_values($permitted);
        }
    }
    return null;
}

function moop_search_narrow_scope(?array $permitted, array $client_pairs, string $assembly = '', string $gene_set = ''): array {
    if ($permitted === null) return ['pairs' => $client_pairs, 'blocked' => false];
    if ($client_pairs) {
        $allowed = [];
        foreach ($permitted as $p) $allowed[$p['assembly'] . "\t" . $p['gene_set']] = true;
        $pairs = array_values(array_filter($client_pairs, fn($p) => isset($allowed[$p['assembly'] . "\t" . $p['gene_set']])));
    } else {
        $pairs = array_values(array_filter($permitted, fn($p) =>
            ($assembly === '' || $p['assembly'] === $assembly) && ($gene_set === '' || $p['gene_set'] === $gene_set)));
    }
    return ['pairs' => $pairs, 'blocked' => !$pairs];
}

function moop_assembly_dataset_units(string $organism_data_path, string $organism, string $assembly): array {
    $subdirs = glob("$organism_data_path/$organism/$assembly/*", GLOB_ONLYDIR) ?: [];
    if ($subdirs) return array_map('basename', $subdirs);
    return moop_blast_only_genome($organism, $assembly) !== null ? [MOOP_BLAST_ONLY] : [];
}

function getUnrepresentedGeneSetTuples(array $all_organisms, string $organism_data_path, array $groups_data): array {
    $represented = [];
    foreach ($groups_data as $entry) {
        if (!isset($entry['gene_set'])) continue;   // no such entry on any site (checked 2026-11-14)
        $represented[$entry['organism'] . '/' . $entry['assembly'] . '/' . $entry['gene_set']] = true;
    }

    $unrepresented = [];
    foreach ($all_organisms as $organism => $assemblies) {
        foreach ($assemblies as $assembly) {
            foreach (moop_assembly_dataset_units($organism_data_path, $organism, $assembly) as $gene_set) {
                $key = $organism . '/' . $assembly . '/' . $gene_set;
                if (!isset($represented[$key])) {
                    $unrepresented[] = ['organism' => $organism, 'assembly' => $assembly, 'gene_set' => $gene_set];
                }
            }
        }
    }
    return $unrepresented;
}

function getTaxonomyTreeUserAccess($group_data) {
    $taxonomy_user_access = [];
    foreach (moop_visible_group_entries($group_data) as $entry) {
        $taxonomy_user_access[$entry['organism']] = true;
    }
    return $taxonomy_user_access;
}

function pruneTaxonomyTreeForAccess(array $node, array $access): ?array {
    if (isset($node['organism'])) {
        return isset($access[$node['organism']]) ? $node : null;
    }
    $kept = [];
    foreach ($node['children'] ?? [] as $child) {
        if (!is_array($child)) continue;
        $pruned = pruneTaxonomyTreeForAccess($child, $access);
        if ($pruned !== null) $kept[] = $pruned;
    }
    if (!$kept) return null;
    $node['children'] = $kept;
    return $node;
}

function countOrganismsAtTaxonomyRank($tree_node, $rank_name, $user_access) {
    if (empty($tree_node) || empty($rank_name) || empty($user_access)) {
        return 0;
    }

    $count = 0;

    $traverse = function($node) use ($rank_name, $user_access, &$count, &$traverse) {
        // Check if this is the node we're looking for
        if ($node['name'] === $rank_name) {
            // Count all organisms under this rank
            $countOrganisms = function($n) use (&$countOrganisms, $user_access, &$count) {
                if (isset($n['organism']) && isset($user_access[$n['organism']])) {
                    $count++;
                }
                if (isset($n['children']) && is_array($n['children'])) {
                    foreach ($n['children'] as $child) {
                        $countOrganisms($child);
                    }
                }
            };
            $countOrganisms($node);
            return;
        }

        // Continue traversing down
        if (isset($node['children']) && is_array($node['children'])) {
            foreach ($node['children'] as $child) {
                $traverse($child);
            }
        }
    };

    $traverse($tree_node);
    return $count;
}

function getTaxonomyLineageWithCounts($lineage, $tree_node, $user_access) {
    if (empty($lineage) || empty($tree_node) || empty($user_access)) {
        return $lineage;
    }

    return array_map(function($item) use ($tree_node, $user_access) {
        $item['count'] = countOrganismsAtTaxonomyRank($tree_node, $item['name'], $user_access);
        return $item;
    }, $lineage);
}

function moop_user_agent(): string {
    static $ua = null;
    if ($ua !== null) return $ua;
    $contact = 'https://github.com/srobb1/moop';
    $email = class_exists('ConfigManager') ? ConfigManager::getInstance()->getString('admin_email') : '';
    if ($email !== '' && filter_var($email, FILTER_VALIDATE_EMAIL) && !preg_match('/@example\.(com|org)$/i', $email)) {
        $contact .= "; $email";
    }
    return $ua = "MOOP/1.0 ($contact) PHP-curl/" . (curl_version()['version'] ?? '');
}

function moop_curl_get(string $url, int $connect_timeout = 5, int $total_timeout = 10, &$http_code = null) {
    $ch = curl_init($url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_CONNECTTIMEOUT => $connect_timeout,
        CURLOPT_TIMEOUT        => $total_timeout,
        CURLOPT_USERAGENT      => moop_user_agent(),
    ]);
    $result    = curl_exec($ch);
    $err       = curl_errno($ch);
    $http_code = (int) curl_getinfo($ch, CURLINFO_RESPONSE_CODE);
    curl_close($ch);
    return ($result !== false && !$err) ? $result : false;
}

function getGroupData() {
    $config = ConfigManager::getInstance();
    $metadata_path = $config->getPath('metadata_path');
    $groups_file = "$metadata_path/organism_assembly_groups.json";
    $groups_data = [];
    if (file_exists($groups_file)) {
        $groups_data = loadJsonFile($groups_file, []);
    }
    return $groups_data;
}

function getAllGroupCards($group_data) {
    $cards = [];
    $group_organisms = [];
    foreach ($group_data as $data) {
        foreach ($data['groups'] as $group) {
            // Legacy access keyword, not a real display group — never card it.
            if (strtoupper(trim((string)$group)) === 'PUBLIC') continue;
            if (!isset($cards[$group])) {
                $cards[$group] = [
                    'title' => $group,
                    'text' => "Explore $group Data",
                    'link' => 'tools/groups.php?group=' . urlencode($group)
                ];
                $group_organisms[$group] = [];
            }
            $group_organisms[$group][$data['organism']] = true;
        }
    }
    foreach ($cards as $group => &$card) {
        $card['organism_count'] = count($group_organisms[$group]);
    }
    ksort($cards);
    return $cards;
}

function getAccessibleOrganismsInGroup($group_name, $group_data) {
    $accessible_organisms = [];

    // moop_visible_group_entries() applies has_gene_set_access()'s rule without
    // re-reading the groups file once per entry.
    foreach (moop_visible_group_entries($group_data) as $data) {
        if (!in_array($group_name, $data['groups'] ?? [], true)) {
            continue;
        }

        $organism = $data['organism'];
        $assembly = $data['assembly'];

        // One entry per assembly: several gene sets on one assembly must not
        // produce the same assembly several times.
        if (!isset($accessible_organisms[$organism])) {
            $accessible_organisms[$organism] = [];
        }
        if (!in_array($assembly, $accessible_organisms[$organism], true)) {
            $accessible_organisms[$organism][] = $assembly;
        }
    }

    foreach ($accessible_organisms as &$assemblies) {
        sort($assemblies);
    }
    unset($assemblies);

    ksort($accessible_organisms);

    return $accessible_organisms;
}

function moop_organism_groups_map(iterable $entries): array {
    $map = [];
    foreach ($entries as $e) {
        $org = (string)($e['organism'] ?? '');
        if ($org === '') continue;
        $map[$org] ??= [];
        foreach ($e['groups'] ?? [] as $g) {
            $g = (string)$g;
            if (strtoupper(trim($g)) === 'PUBLIC') continue;   // legacy keyword, not a real group
            if (!in_array($g, $map[$org], true)) $map[$org][] = $g;
        }
    }
    foreach ($map as &$groups) usort($groups, 'moop_group_name_order');
    return $map;
}

functions.comment:
/**
* Each organism's groups, for the group chips beside organism names: ONE list per organism, in
* one order, everywhere -- alphabetical, ignoring case (moop_group_name_order()).
*
* The home page, Search, the Data Exporter and the genome browser each built this map with their
* own copy of the same loop, keeping groups in whatever order the entries happened to list them --
* so Nematostella read "Cnidaria, Sea anemone" and Scolanthus "Sea anemone, Cnidaria" side by side
* (2026-10-22). The copies had drifted in other ways too: only the genome browser skipped the
* legacy PUBLIC keyword, and only in upper case.
*
* Which entries to read stays the caller's choice (visible gene sets, registered assemblies ...).
*
* @param iterable $entries rows with 'organism' and 'groups' (organism_assembly_groups.json rows,
*                          or flattenSourcesList() sources)
* @return array<string, list<string>> organism => its groups, sorted, without duplicates
*/
function moop_organism_groups_map(iterable $entries): array {
$map = [];
foreach ($entries as $e) {
$org = (string)($e['organism'] ?? '');
if ($org === '') continue;
$map[$org] ??= [];
foreach ($e['groups'] ?? [] as $g) {
$g = (string)$g;
if (strtoupper(trim($g)) === 'PUBLIC') continue;   // legacy keyword, not a real group
if (!in_array($g, $map[$org], true)) $map[$org][] = $g;
}
}
foreach ($map as &$groups) usort($groups, 'moop_group_name_order');
return $map;
}

/** The one order for group names on screen: alphabetical, case-insensitive, numbers natural. */

functions.code:
function moop_group_name_order(string $a, string $b): int {
    return strnatcasecmp($a, $b) ?: strcmp($a, $b);
}

function getGroupsForOrganism($organism_name, $group_data = null) {
    if ($group_data === null) {
        $group_data = getGroupData();
    }

    $organism_groups = [];

    // Find all groups containing this organism
    foreach ($group_data as $data) {
        if ($data['organism'] === $organism_name) {
            foreach ($data['groups'] as $group) {
                if (!isset($organism_groups[$group])) {
                    $organism_groups[$group] = [
                        'count' => 0,
                        'link' => 'tools/groups.php?group=' . urlencode($group)
                    ];
                }
            }
        }
    }

    // Count accessible organisms in each group
    foreach ($organism_groups as $group => &$info) {
        $accessible_organisms = getAccessibleOrganismsInGroup($group, $group_data);
        $info['count'] = count($accessible_organisms);
    }

    // Sort by group name -- the same order as every other group chip list (moop_group_name_order())
    uksort($organism_groups, 'moop_group_name_order');

    return $organism_groups;
}

function groupNameExists($group_name, $group_data, $group_descriptions = []) {
    if ($group_name === '') {
        return false;
    }
    foreach ($group_data as $entry) {
        if (in_array($group_name, $entry['groups'] ?? [], true)) {
            return true;
        }
    }
    foreach ($group_descriptions as $desc) {
        if (($desc['group_name'] ?? null) === $group_name && ($desc['in_use'] ?? false)) {
            return true;
        }
    }
    return false;
}

function taxonomyRankExists($rank_name, $tree_node) {
    if ($rank_name === '' || empty($tree_node)) {
        return false;
    }
    if (($tree_node['name'] ?? null) === $rank_name) {
        return true;
    }
    foreach ($tree_node['children'] ?? [] as $child) {
        if (taxonomyRankExists($rank_name, $child)) {
            return true;
        }
    }
    return false;
}

function getOrganismsAtTaxonomyLevel($rank_name, $tree_node, $group_data) {
    if (empty($rank_name) || empty($tree_node) || empty($group_data)) {
        return [];
    }

    $organisms_at_level = [];

    // Find the rank in the tree and collect all organisms under it
    $findOrganisms = function($node) use ($rank_name, &$organisms_at_level, &$findOrganisms) {
        // Check if this is the target rank
        if ($node['name'] === $rank_name) {
            // Collect all organisms under this rank
            $collectOrganisms = function($n) use (&$collectOrganisms, &$organisms_at_level) {
                if (isset($n['organism'])) {
                    $organisms_at_level[$n['organism']] = true;
                }
                if (isset($n['children']) && is_array($n['children'])) {
                    foreach ($n['children'] as $child) {
                        $collectOrganisms($child);
                    }
                }
            };
            $collectOrganisms($node);
            return;
        }

        // Continue traversing
        if (isset($node['children']) && is_array($node['children'])) {
            foreach ($node['children'] as $child) {
                $findOrganisms($child);
            }
        }
    };

    $findOrganisms($tree_node);

    // Now filter by user access and get assemblies
    $accessible_organisms = [];
    foreach ($organisms_at_level as $organism => $dummy) {
        // Find all assemblies for this organism
        $organism_assemblies = [];
        foreach ($group_data as $data) {
            if ($data['organism'] === $organism) {
                $organism_assemblies[] = $data['assembly'];
            }
        }

        // Check if user has access to at least one assembly
        $has_accessible_assembly = false;
        foreach ($organism_assemblies as $assembly) {
            if (has_assembly_access($organism, $assembly)) {
                $has_accessible_assembly = true;
                break;
            }
        }

        if ($has_accessible_assembly) {
            $accessible_organisms[$organism] = $organism_assemblies;
        }
    }

    // Sort organisms alphabetically
    ksort($accessible_organisms);

    return $accessible_organisms;
}

function getAssemblyFastaFiles($organism_name, $assembly_name) {
    $config = ConfigManager::getInstance();
    $organism_data = $config->getPath('organism_data');
    $sequence_types = $config->getSequenceTypes();
    $fasta_files = [];
    $assembly_dir = "$organism_data/$organism_name/$assembly_name";

    if (!is_dir($assembly_dir)) {
        return $fasta_files;
    }

    // The genome FASTA stays at assembly level (not in a gene_set subdir).
    // Identified by its config KEY, not by sniffing the filename for the word "genome":
    // this used to test strpos($seq_config['pattern'], 'genome') and then hardcode
    // "genome.fa" anyway, so renaming the pattern in Site Configuration dropped the
    // genome out of this list entirely.
    if (isset($sequence_types['genome'])) {
        $seq_config  = $sequence_types['genome'];
        $genome_file = genome_fasta_filename();
        if (file_exists("$assembly_dir/$genome_file")) {
            $fasta_files['genome'] = [
                'path'     => "$organism_name/$assembly_name/$genome_file",
                'label'    => $seq_config['label'],
                'color'    => $seq_config['color'],
                'gene_set' => '',
                'seq_type' => 'genome',
            ];
        }
    }

    // protein/transcript/cds live in gene_set subdirs
    $gene_set_dirs = glob("$assembly_dir/*", GLOB_ONLYDIR) ?: [];
    $multi_gs = count($gene_set_dirs) > 1;
    foreach ($gene_set_dirs as $gs_dir) {
        $gene_set = basename($gs_dir);
        foreach ($sequence_types as $type => $seq_config) {
            if (strpos($seq_config['pattern'], 'genome') !== false) continue;
            $matches = glob("$gs_dir/" . $seq_config['pattern']);
            if (!empty($matches)) {
                $key = $type . '.' . $gene_set;
                $label = $seq_config['label'];
                if ($multi_gs) {
                    $label .= ' (' . $gene_set . ')';
                }
                $fasta_files[$key] = [
                    'path'     => "$organism_name/$assembly_name/$gene_set/" . basename($matches[0]),
                    'label'    => $label,
                    'color'    => $seq_config['color'],
                    'gene_set' => $gene_set,
                    'seq_type' => $type,
                ];
            }
        }
    }

    return $fasta_files;
}

function buildHomeQuickSearch(array $visible_entries, array $organism_list, string $site): array {
    $items = [];
    $org_display_map = [];
    foreach ($organism_list as $org_entry) {
        $org_display_map[$org_entry['organism']] = $org_entry['display_name'];
        $search_parts = array_filter(array_merge(
            [$org_entry['display_name'], $org_entry['common_name']],
            $org_entry['groups'],
            $org_entry['taxon_chain']
        ));
        $items[] = [
            'type'      => 'organism',
            'label'     => $org_entry['display_name'],
            'secondary' => $org_entry['common_name'],
            'url'       => moop_url_base() . "/tools/organism.php?organism=" . urlencode($org_entry['organism']),
            'search'    => strtolower(implode(' ', $search_parts)),
        ];
    }

    $seen_groups = $seen_assemblies = $seen_genesets = [];
    foreach ($visible_entries as $entry) {
        $org      = $entry['organism'];
        $assembly = $entry['assembly'];   // the genome accession, e.g. GCA_004027475.1
        $gene_set = $entry['gene_set'] ?? '';
        $org_display = $org_display_map[$org] ?? str_replace('_', ' ', $org);

        foreach ($entry['groups'] ?? [] as $group) {
            if (strtoupper(trim((string)$group)) === 'PUBLIC') continue;   // legacy access keyword
            if (isset($seen_groups[$group])) continue;
            $seen_groups[$group] = true;
            $items[] = [
                'type'      => 'group',
                'label'     => $group,
                'secondary' => '',
                'url'       => moop_url_base() . "/tools/groups.php?group=" . urlencode($group),
                'search'    => strtolower($group),
            ];
        }

        $asm_key = $org . '|' . $assembly;
        if (!isset($seen_assemblies[$asm_key])) {
            $seen_assemblies[$asm_key] = true;
            $items[] = [
                'type'      => 'assembly',
                'label'     => $assembly,
                'secondary' => $org_display,
                'url'       => moop_url_base() . "/tools/assembly.php?organism=" . urlencode($org) . "&assembly=" . urlencode($assembly),
                'search'    => strtolower(implode(' ', array_filter([$assembly, $org_display, $org]))),
            ];
        }

        if ($gene_set !== '' && !isset($seen_genesets[$asm_key . '|' . $gene_set])) {
            $seen_genesets[$asm_key . '|' . $gene_set] = true;
            $items[] = [
                'type'      => 'geneset',
                'label'     => $gene_set,
                'secondary' => $org_display . ' › ' . $assembly,
                'url'       => moop_url_base() . "/tools/gene_set.php?organism=" . urlencode($org) . "&assembly=" . urlencode($assembly) . "&gene_set=" . urlencode($gene_set),
                'search'    => strtolower(implode(' ', array_filter([$gene_set, $org_display, $org, $assembly]))),
            ];
        }
    }

    return ['items' => $items, 'assembly_count' => count($seen_assemblies)];
}

function getIndexDisplayCards($group_data) {
    return getAllGroupCards(moop_visible_group_entries($group_data));
}

function loadAllOrganismsMetadata($organism_data_dir) {
    $organisms = [];

    if (!is_dir($organism_data_dir)) {
        return $organisms;
    }

    foreach (moop_organism_dirs($organism_data_dir) as $organism) {

        // Load organism.json using loadJsonFile (from functions_json.php)
        $organism_json_path = "$organism_data_dir/$organism/organism.json";
        $organism_info = loadJsonFile($organism_json_path);

        if (!$organism_info) {
            continue;
        }

        // Handle improperly wrapped JSON (extra outer braces)
        if (!isset($organism_info['genus']) && !isset($organism_info['common_name'])) {
            $keys = array_keys($organism_info);
            if (count($keys) > 0 && is_array($organism_info[$keys[0]]) && isset($organism_info[$keys[0]]['genus'])) {
                $organism_info = $organism_info[$keys[0]];
            }
        }

        // Store organism metadata keyed by organism name
        $organisms[$organism] = [
            'genus' => $organism_info['genus'] ?? '',
            'species' => $organism_info['species'] ?? '',
            'common_name' => $organism_info['common_name'] ?? '',
            'taxon_id' => $organism_info['taxon_id'] ?? '',
            'images' => $organism_info['images'] ?? [],
            'html_p' => $organism_info['html_p'] ?? []
        ];
    }

    return $organisms;
}

function getOrganismsWithAssemblies($organism_data_path) {
    if (!is_dir($organism_data_path)) {
        return [];
    }

    if (session_status() === PHP_SESSION_ACTIVE) {
        $cache_key = 'organisms_with_assemblies_cache';
        $dir_mtime = filemtime($organism_data_path);
        if (isset($_SESSION[$cache_key]) && $_SESSION[$cache_key]['mtime'] === $dir_mtime) {
            return $_SESSION[$cache_key]['data'];
        }
    }

    $orgs = [];
    foreach (moop_organism_dirs($organism_data_path) as $organism) {
        $assemblies = [];
        $assemblyPath = "$organism_data_path/$organism";
        foreach (scandir($assemblyPath) as $file) {
            if ($file[0] === '.' || !is_dir("$assemblyPath/$file")) {
                continue;
            }
            $assemblies[] = $file;
        }
        $orgs[$organism] = $assemblies;
    }

    if (session_status() === PHP_SESSION_ACTIVE) {
        $_SESSION[$cache_key] = ['mtime' => $dir_mtime, 'data' => $orgs];
    }

    return $orgs;
}

function getAllExistingGroups($groups_data) {
    $all_groups = [];
    foreach ($groups_data as $data) {
        if (!empty($data['groups'])) {
            foreach ($data['groups'] as $group) {
                $all_groups[$group] = true;
            }
        }
    }
    $group_list = array_keys($all_groups);
    sort($group_list);
    return $group_list;
}

function syncGroupDescriptions($existing_groups, $descriptions_data) {
    $desc_map = [];
    foreach ($descriptions_data as $desc) {
        $desc_map[$desc['group_name']] = $desc;
    }

    $updated_descriptions = [];

    // Update existing groups to in_use = true
    foreach ($existing_groups as $group) {
        if (isset($desc_map[$group])) {
            $desc_map[$group]['in_use'] = true;
            $updated_descriptions[] = $desc_map[$group];
        } else {
            // New group - add with default structure
            $updated_descriptions[] = [
                'group_name' => $group,
                'images' => [
                    [
                        'file' => '',
                        'caption' => ''
                    ]
                ],
                'html_p' => [
                    [
                        'text' => '',
                        'style' => '',
                        'class' => ''
                    ]
                ],
                'in_use' => true
            ];
        }
        unset($desc_map[$group]);
    }

    // Mark any remaining groups (not in existing groups) as in_use = false
    foreach ($desc_map as $group_name => $desc) {
        $desc['in_use'] = false;
        $updated_descriptions[] = $desc;
    }

    return $updated_descriptions;
}

function getAssemblyGroups($organism, $assembly, $groups_data) {
    $assembly_groups = [];

    foreach ($groups_data as $data) {
        if (!empty($data['groups'])) {
            foreach ($data['groups'] as $group) {
                // Check if this organism and assembly match
                if ($data['organism'] === $organism && $data['assembly'] === $assembly) {
                    $assembly_groups[] = $group;
                }
            }
        }
    }

    return $assembly_groups;
}

function isAssemblyInTaxonomyTree($organism, $assembly, $tree_file) {
    if (!file_exists($tree_file)) {
        return false;
    }

    $tree_content = file_get_contents($tree_file);
    if (!$tree_content) {
        return false;
    }

    // Simply search for the organism name in the tree file
    return strpos($tree_content, '"organism": "' . $organism . '"') !== false;
}

function getOrganismOverallStatus($organism, $data, $groups_data, $taxonomy_tree_file, $sequence_types) {
    $checks = array_fill_keys(array_keys(moop_organism_check_defs()), false);

    // 1. Does it have at least one assembly?
    $checks['has_assemblies'] = !empty($data['assemblies']);

    // 2. Is there at least one FASTA file in an assembly?
    if ($checks['has_assemblies'] && !empty($data['fasta_validation']['assemblies'])) {
        foreach ($data['fasta_validation']['assemblies'] as $asm_fasta) {
            if (!empty($asm_fasta['fasta_files'])) {
                foreach ($asm_fasta['fasta_files'] as $file_info) {
                    if ($file_info['found']) {
                        $checks['has_fasta'] = true;
                        break 2;
                    }
                }
            }
        }
    }

    // 2b. Does every assembly hold a gene set, and every gene set each gene-set FASTA type
    // (protein / mRNA / CDS)? Asked per gene set (assembly_fasta_gaps()), so one complete
    // sibling cannot hide a gene set that lacks its CDS. Not in moop_organism_severity()'s
    // critical list: the organism still serves the data it has, so a gap grades Incomplete.
    // genome.fa is not asked for -- a transcriptome-only assembly is a valid shape.
    if ($checks['has_assemblies']) {
        $complete = true;
        foreach ($data['assemblies'] as $assembly) {
            $gaps = $data['fasta_validation']['assemblies'][$assembly]['gaps']
                 ?? assembly_fasta_gaps($data['path'] . '/' . $assembly, $sequence_types);
            if (!empty($gaps['blast_only'])) continue;   // a BLAST-only genome: no gene set by design
            if (!$gaps['gene_sets'] || array_filter($gaps['gene_sets'])) { $complete = false; break; }
        }
        $checks['gene_sets_complete'] = $complete;
    }

    // 3. Are BLAST indexes present for ALL FASTA files?
    // This check fails if there are FASTA files but any are missing BLAST indexes
    if ($checks['has_fasta']) {
        $all_have_indexes = true;
        $has_any_fasta = false;

        foreach ($data['assemblies'] as $assembly) {
            // Use pre-computed blast validation if available (from cache)
            $blast_validation = $data['blast_validation'][$assembly] ?? null;
            if (!$blast_validation) {
                $blast_validation = moop_assembly_blast_validation($data['path'] . '/' . $assembly, $sequence_types);
            }

            if (!empty($blast_validation['databases'])) {
                foreach ($blast_validation['databases'] as $db) {
                    $has_any_fasta = true;
                    // If any FASTA file doesn't have indexes, fail the check
                    if (!$db['has_indexes']) {
                        $all_have_indexes = false;
                        break 2;
                    }
                }
            }
        }

        // Set to true only if we found FASTA files AND all have indexes
        $checks['has_blast_indexes'] = ($has_any_fasta && $all_have_indexes);
    }

    // 4. Does genome.fa have a .fai index for every assembly that has one?
    // Passes if no assembly has genome.fa (not applicable); fails if any genome.fa is missing .fai.
    if ($checks['has_assemblies']) {
        $any_genome_fa  = false;
        $all_have_fai   = true;
        foreach ($data['assemblies'] as $assembly) {
            $fai_info = $data['fai_validation'][$assembly] ?? null;
            if (!$fai_info) {
                $genome_fa = $data['path'] . '/' . $assembly . '/' . genome_fasta_filename();
                $fai_info  = [
                    'genome_fa_exists' => file_exists($genome_fa),
                    'fai_exists'       => file_exists($genome_fa . '.fai'),
                ];
            }
            if ($fai_info['genome_fa_exists']) {
                $any_genome_fa = true;
                if (!$fai_info['fai_exists']) {
                    $all_have_fai = false;
                    break;
                }
            }
        }
        $checks['has_fai_index'] = !$any_genome_fa || $all_have_fai;
    }

    // 4b. Do the gene sets name chromosomes the way their genome does? (organism cache,
    // seqname_validation -- only mismatches are recorded, so empty passes)
    $checks['seqnames_match_genome'] = empty($data['seqname_validation']);

    // 5. Is there a database file?
    $checks['has_database'] = $data['has_db'];

    // 6. Is the database valid? (readable, correct schema, all tables present, no data issues)
    if ($checks['has_database'] && !empty($data['db_validation'])) {
        $checks['database_valid'] = $data['db_validation']['valid'] ?? $data['db_validation']['readable'];
    }

    // 7. Do assembly and gene_set directories on disk match the DB records?
    if ($checks['has_database'] && !empty($data['assembly_validation'])) {
        $checks['directories_match_db'] = $data['assembly_validation']['valid'] ?? false;
    } elseif ($checks['has_database'] && !empty($data['db_file']) && !empty($data['path'])) {
        $live = validateAssemblyDirectories($data['db_file'], $data['path']);
        $checks['directories_match_db'] = $live['valid'];
    }

    // 8. Is each assembly a member of at least one group?
    if ($checks['has_assemblies']) {
        $all_in_groups = true;
        foreach ($data['assemblies'] as $assembly) {
            $assembly_groups = getAssemblyGroups($organism, $assembly, $groups_data);
            if (empty($assembly_groups)) {
                $all_in_groups = false;
                break;
            }
        }
        $checks['assemblies_in_groups'] = $all_in_groups;
    }

    // 9. Is the organism found in the tree? (use pre-computed value from cache if available)
    $checks['in_taxonomy_tree'] = $data['in_taxonomy_tree'] ?? isAssemblyInTaxonomyTree($organism, '', $taxonomy_tree_file);

    // 10. Is metadata complete?
    if (!empty($data['json_validation'])) {
        $json_val = $data['json_validation'];
        $checks['metadata_complete'] = ($json_val['exists'] && $json_val['readable'] && $json_val['valid_json'] && $json_val['has_required_fields'] && $json_val['writable']);
    }

    // Calculate overall status
    $all_pass = array_reduce($checks, function($carry, $item) {
        return $carry && $item;
    }, true);

    $pass_count = count(array_filter($checks));
    $total_count = count($checks);

    return [
        'checks' => $checks,
        'all_pass' => $all_pass,
        'pass_count' => $pass_count,
        'total_count' => $total_count,
        // Non-failing signal: does any assembly carry a reference genome (genome.fa)?
        // Transcriptome/proteome-only organisms legitimately have none — the UI shows this
        // as a neutral "Transcriptome only" tag, NOT a failed check. $any_genome_fa is set
        // in check #4 above; guard for the no-assemblies case.
        'has_genome' => $any_genome_fa ?? false,
    ];
}

function moop_organism_severity(array $overall_status): string {
    if (!empty($overall_status['all_pass'])) return 'complete';

    $checks = $overall_status['checks'] ?? [];
    foreach (['has_database', 'database_valid', 'has_assemblies', 'has_fasta'] as $critical) {
        // A check that is absent is not a failure -- only an explicit false is.
        if (array_key_exists($critical, $checks) && !$checks[$critical]) return 'critical';
    }
    return 'incomplete';
}

