functions.code:
function moop_severity_color(string $severity): string {
    return ['critical' => 'danger', 'incomplete' => 'warning', 'info' => 'secondary'][$severity] ?? 'secondary';
}

function getOrphanedGeneSetTuples(string $organism_data_path): array {
    $cache_file = moop_organism_cache_file();
    if (!file_exists($cache_file)) return [];

    $raw = loadJsonFile($cache_file, []);
    $tuples = [];
    foreach ($raw['data'] ?? [] as $organism => $org_data) {
        foreach ($org_data['assembly_validation']['mismatches'] ?? [] as $mm) {
            if (($mm['type'] ?? '') === 'orphaned_gene_set_directory') {
                $assembly = $mm['assembly_dir'] ?? '';
                $gene_set = $mm['gene_set_name'] ?? '';
                // Self-heal against a stale cache: the cache is rebuilt in the background,
                // not on delete, so it can still list a directory an admin just removed.
                // This mismatch asserts the dir exists on disk — if it's already gone it's
                // no longer an orphan, so drop it now instead of showing a phantom alert
                // until the next rescan. One stat() per already-flagged dir (rare); does
                // not defeat the cache, which exists to skip the expensive DB/BLAST checks.
                if (!is_dir("$organism_data_path/$organism/$assembly/$gene_set")) continue;
                $tuples[] = [
                    'organism' => $organism,
                    'assembly' => $assembly,
                    'gene_set' => $gene_set,
                ];
            }
        }
    }
    return $tuples;
}

function getOrphanedAssemblyTuples(string $organism_data_path): array {
    $cache_file = moop_organism_cache_file();
    if (!file_exists($cache_file)) return [];

    $raw = loadJsonFile($cache_file, []);
    $tuples = [];
    foreach ($raw['data'] ?? [] as $organism => $org_data) {
        foreach ($org_data['assembly_validation']['mismatches'] ?? [] as $mm) {
            if (($mm['type'] ?? '') === 'orphaned_assembly_directory') {
                $assembly = $mm['assembly_dir'] ?? '';
                // Self-heal against a cache that lags a manual delete — see the same
                // guard in getOrphanedGeneSetTuples(). If the dir is already gone, skip it.
                if (!is_dir("$organism_data_path/$organism/$assembly")) continue;
                $tuples[] = [
                    'organism' => $organism,
                    'assembly' => $assembly,
                ];
            }
        }
    }
    return $tuples;
}

function getNoDatabaseOrganisms(string $organism_data_path): array {
    $cache_file = moop_organism_cache_file();
    if (!file_exists($cache_file)) return [];

    $raw = loadJsonFile($cache_file, []);
    $names = [];
    foreach ($raw['data'] ?? [] as $organism => $org_data) {
        if (empty($org_data['has_db']) && !empty($org_data['assemblies'])) {
            // Self-heal against a stale cache (same reasoning as getOrphanedGeneSetTuples):
            // only report if the organism dir is still present and a database still hasn't
            // appeared — a load could have added organism.sqlite, or the whole dir could
            // have been removed, since the cache was built.
            $org_dir = "$organism_data_path/$organism";
            if (!is_dir($org_dir) || file_exists("$org_dir/organism.sqlite")) continue;
            $names[] = $organism;
        }
    }
    return $names;
}

function countJBrowseRegistrations(): int {
    $dir = ConfigManager::getInstance()->getPath('metadata_path') . '/jbrowse2-configs/assemblies';
    return is_dir($dir) ? count(glob("$dir/*.json") ?: []) : 0;
}

function isJBrowseAssemblyRegistered(string $organism, string $assembly): bool {
    foreach ([$organism, $assembly] as $name) {
        if ($name === '' || $name[0] === '.' || !preg_match('/^[A-Za-z0-9._-]+$/', $name)) {
            return false;
        }
    }
    $file = ConfigManager::getInstance()->getPath('metadata_path')
          . "/jbrowse2-configs/assemblies/{$organism}_{$assembly}.json";
    if (!is_file($file)) return false;
    $def = loadJsonFile($file, []);
    return ($def['organism'] ?? '') === $organism && ($def['assemblyId'] ?? '') === $assembly;
}

function jbrowseSheetConfigPath(string $organism, string $assembly): string {
    return ConfigManager::getInstance()->getPath('metadata_path')
         . "/jbrowse2-configs/sheets/$organism/$assembly/jbrowse_tracks_sheet.txt";
}

function writeJBrowseSheetConfig(string $organism, string $assembly, array $cfg): bool {
    $lines = '';
    foreach ($cfg as $key => $value) {
        $lines .= $key . '=' . str_replace(["\r", "\n"], '', (string)$value) . "\n";
    }
    return file_put_contents(jbrowseSheetConfigPath($organism, $assembly), $lines) !== false;
}

function getJBrowseSheetStatus(string $organism, string $assembly): array {
    $config = ConfigManager::getInstance();
    $file   = jbrowseSheetConfigPath($organism, $assembly);
    $cfg    = is_file($file) ? (parse_ini_file($file, false, INI_SCANNER_RAW) ?: []) : [];

    $tracks_dir = $config->getPath('metadata_path') . "/jbrowse2-configs/tracks/$organism/$assembly";
    $asm_dir    = $config->getPath('organism_data') . "/$organism/$assembly";
    $count = 0;
    foreach (glob("$tracks_dir/*/*.json") ?: [] as $track_file) {
        $name = basename($track_file, '.json');
        if (basename(dirname($track_file)) === 'gff' && substr($name, -6) === '_genes'
            && is_dir("$asm_dir/" . substr($name, 0, -6))) {
            continue;
        }
        $count++;
    }

    return [
        'sheet_id'    => $cfg['SHEET_ID'] ?? '',
        'gid'         => $cfg['GID'] ?? '',
        'registered'  => $cfg['REGISTERED_DATE'] ?? '',
        'last_sync'   => $cfg['LAST_SYNC'] ?? '',
        'track_count' => $count,
    ];
}

function getOrphanedJBrowseRegistrations(string $organism_data_path): array {
    $config        = ConfigManager::getInstance();
    $metadata_path = $config->getPath('metadata_path');
    $site_path     = $config->getPath('site_path');

    $assemblies_dir = "$metadata_path/jbrowse2-configs/assemblies";
    if (!is_dir($assemblies_dir)) return [];

    $orphans = [];
    foreach (glob("$assemblies_dir/*.json") ?: [] as $json_file) {
        $def = loadJsonFile($json_file, []);
        $org = $def['organism']   ?? '';
        $asm = $def['assemblyId'] ?? '';
        if ($org === '' || $asm === '') continue;   // malformed; not a source-data problem

        $source_dir = "$organism_data_path/$org/$asm";
        $reference  = "$site_path/data/genomes/$org/$asm/reference.fasta";

        if (!is_dir($source_dir)) {
            // Most common cause: the assembly directory was renamed after registration.
            // Show what the organism directory actually holds so the fix is obvious.
            $actual = array_map('basename', glob("$organism_data_path/$org/*", GLOB_ONLYDIR) ?: []);
            $orphans[] = [
                'organism' => $org,
                'assembly' => $asm,
                'reason'   => 'no_source_directory',
                'detail'   => $actual
                    ? 'organisms/' . $org . '/ now contains: ' . implode(', ', $actual)
                    : 'organisms/' . $org . '/ has no assembly directories',
            ];
        } elseif (!file_exists($reference)) {
            // Source directory is there but the genome link is dead — JBrowse 404s.
            $orphans[] = [
                'organism' => $org,
                'assembly' => $asm,
                'reason'   => 'broken_genome_link',
                'detail'   => 'data/genomes/' . $org . '/' . $asm . '/reference.fasta does not resolve',
            ];
        }
    }
    return $orphans;
}

function moop_organism_cache_staleness(array $raw_cache, string $organism_data,
                                       string $taxonomy_tree_file, string $groups_file): array {
    $out = ['stale' => false, 'format_outdated' => false, 'checks_changed' => false, 'config_changed' => false,
            'changed' => [], 'deleted' => [], 'current_fps' => [], 'reasons' => []];
    if (!$raw_cache) return $out;

    $has_fps = isset($raw_cache['org_fingerprints'], $raw_cache['config_fingerprint']);
    $out['format_outdated'] = !$has_fps || ($raw_cache['schema_version'] ?? 0) !== ORGANISM_CACHE_SCHEMA_VERSION;
    // The checks themselves changed (moop_organism_checks_version()): every stored result may be
    // out of date even though no organism's files did.
    $out['checks_changed']  = $has_fps && !$out['format_outdated']
        && ($raw_cache['checks_version'] ?? '') !== moop_organism_checks_version();
    $out['config_changed']  = $has_fps
        && $raw_cache['config_fingerprint'] !== buildConfigFingerprint($taxonomy_tree_file, $groups_file);

    $current_fps = buildPerOrganismFingerprints($organism_data);
    if ($has_fps) {
        // Without stored fingerprints every organism would read as changed; format_outdated
        // already says the whole cache needs rebuilding.
        $cached_fps = $raw_cache['org_fingerprints'];
        foreach ($current_fps as $org_name => $fp) {
            if (($cached_fps[$org_name] ?? null) !== $fp) $out['changed'][] = $org_name;
        }
        $out['deleted'] = array_values(array_diff(array_keys($cached_fps), array_keys($current_fps)));
    }
    $out['current_fps'] = $current_fps;

    if ($out['format_outdated']) $out['reasons'][] = 'it was built by an older version of MOOP';
    if ($out['checks_changed'])  $out['reasons'][] = 'the organism checks were updated since it was built';
    if ($out['config_changed'])  $out['reasons'][] = 'the groups or taxonomy config has changed since it was built';
    $out['stale'] = $out['format_outdated'] || $out['checks_changed'] || $out['config_changed'] || $out['changed'] || $out['deleted'];
    return $out;
}

function moop_organism_cache_stale_summary(array $raw_cache): array {
    $config        = ConfigManager::getInstance();
    $metadata_path = $config->getPath('metadata_path');
    $s = moop_organism_cache_staleness($raw_cache, $config->getPath('organism_data'),
        "$metadata_path/taxonomy_tree_config.json", "$metadata_path/organism_assembly_groups.json");
    $changed = array_merge($s['changed'], array_map(fn($o) => "$o (removed)", $s['deleted']));
    sort($changed);
    return ['cache_stale' => $s['stale'], 'cache_changed_orgs' => $changed, 'cache_stale_reasons' => $s['reasons']];
}

function getOrganismsNotInTree(array $cache_data): array {
    $out = [];
    foreach ($cache_data as $org_name => $org_data) {
        $checks = $org_data['overall_status']['checks'] ?? [];
        if (isset($checks['in_taxonomy_tree']) && !$checks['in_taxonomy_tree']) $out[] = $org_name;
    }
    sort($out);
    return $out;
}

function getUngroupedOrganisms(array $cache_data, array $groups_entries): array {
    $grouped_pairs = [];
    foreach ($groups_entries as $ge) {
        if (!empty($ge['groups'])) $grouped_pairs[($ge['organism'] ?? '') . '/' . ($ge['assembly'] ?? '')] = true;
    }
    $out = [];
    foreach ($cache_data as $org_name => $org_data) {
        foreach ($org_data['assemblies'] ?? [] as $asm) {
            if (!isset($grouped_pairs["$org_name/$asm"])) { $out[] = $org_name; break; }
        }
    }
    sort($out);
    return $out;
}

function getGeneSetFastaGaps(array $cache_data, array $sequence_types): array
{
    $expected = [];
    foreach ($sequence_types as $t => $cfg) if ($t !== 'genome') $expected[] = $cfg['label'] ?? $t;
    $out = ['gene_sets' => [], 'empty_assemblies' => [], 'expected' => $expected, 'unknown' => false];
    foreach ($cache_data as $org => $org_data) {
        foreach ($org_data['fasta_validation']['assemblies'] ?? [] as $asm => $asm_info) {
            $gaps = $asm_info['gaps'] ?? null;
            // A cache written before per-gene-set gaps existed (schema < 6) carries none;
            // say so rather than report "every gene set complete" from no data.
            if ($gaps === null) { $out['unknown'] = true; continue; }
            if (!empty($gaps['blast_only'])) continue;   // BLAST-only genome: no gene set by design
            if (empty($gaps['gene_sets'])) { $out['empty_assemblies'][] = "$org/$asm"; continue; }
            foreach ($gaps['gene_sets'] as $gs => $missing) {
                if (!$missing) continue;
                $out['gene_sets'][] = [
                    'path'    => "$org/$asm/$gs",
                    'missing' => array_map(fn($t) => $sequence_types[$t]['label'] ?? $t, $missing),
                ];
            }
        }
    }
    return $out;
}

function moop_group_entry_stale_reason(array $entry, string $organism_data_path, array $orphaned_assemblies): ?string {
    $gs = $entry['gene_set'] ?? '';
    // A BLAST-only genome is the assembly itself: no gene-set directory and, by design, no genome
    // row in the database -- its one rule is moop_blast_only_genome()
    if ($gs === MOOP_BLAST_ONLY) return moop_blast_only_genome($entry['organism'], $entry['assembly']) !== null ? null : 'gone';
    if ($gs === '' || !is_dir("$organism_data_path/{$entry['organism']}/{$entry['assembly']}/$gs")) return 'gone';
    if (isset($orphaned_assemblies[$entry['organism'] . '/' . $entry['assembly']])) return 'not_in_db';
    return null;
}

function moop_split_unrepresented_by_db(array $tuples, string $organism_data_path, ?array $orphan_asm = null, ?array $orphan_gs = null): array {
    // The orphan sets come from the organism cache; a caller (the smoke test) may pass its own
    $orphan_asm ??= moop_orphaned_assembly_set($organism_data_path);
    if ($orphan_gs === null) {
        $orphan_gs = [];
        foreach (getOrphanedGeneSetTuples($organism_data_path) as $t) $orphan_gs[$t['organism'] . '/' . $t['assembly'] . '/' . $t['gene_set']] = true;
    }
    $out = ['loaded' => [], 'not_loaded' => []];
    foreach ($tuples as $t) {
        // A BLAST-only genome is not loaded into the database by design; its rule checks organism.sqlite
        if ($t['gene_set'] === MOOP_BLAST_ONLY) {
            $out[moop_blast_only_genome($t['organism'], $t['assembly']) !== null ? 'loaded' : 'not_loaded'][] = $t;
            continue;
        }
        $loaded = is_file("$organism_data_path/{$t['organism']}/organism.sqlite")
               && !isset($orphan_asm[$t['organism'] . '/' . $t['assembly']])
               && !isset($orphan_gs[$t['organism'] . '/' . $t['assembly'] . '/' . $t['gene_set']]);
        $out[$loaded ? 'loaded' : 'not_loaded'][] = $t;
    }
    return $out;
}

