/**
* Gene-set directories with no groups entry, split into those that CAN be given groups (their
* organism, assembly and gene set are in the database) and those that cannot (no database, or an
* assembly / gene set the database does not have: rename or reload leftovers).
*
* Manage Groups' Bulk add offered every directory on disk. On 2026-10-27 it published six planarian
* leftovers this way: listed to users, every page failing. The dashboard's "new gene sets" and the
* Manage Groups list now count and offer only the loadable ones, and the add handlers refuse the rest.
*
* @param list<array{organism:string, assembly:string, gene_set:string}> $tuples getUnrepresentedGeneSetTuples()
* @return array{loaded: list, not_loaded: list}
*/
function moop_split_unrepresented_by_db(array $tuples, string $organism_data_path, ?array $orphan_asm = null, ?array $orphan_gs = null): array {
// The orphan sets come from the organism cache; a caller (the smoke test) may pass its own
$orphan_asm ??= moop_orphaned_assembly_set($organism_data_path);
if ($orphan_gs === null) {
$orphan_gs = [];
foreach (getOrphanedGeneSetTuples($organism_data_path) as $t) $orphan_gs[$t['organism'] . '/' . $t['assembly'] . '/' . $t['gene_set']] = true;
}
$out = ['loaded' => [], 'not_loaded' => []];
foreach ($tuples as $t) {
// A BLAST-only genome is not loaded into the database by design; its rule checks organism.sqlite
if ($t['gene_set'] === MOOP_BLAST_ONLY) {
$out[moop_blast_only_genome($t['organism'], $t['assembly']) !== null ? 'loaded' : 'not_loaded'][] = $t;
continue;
}
$loaded = is_file("$organism_data_path/{$t['organism']}/organism.sqlite")
&& !isset($orphan_asm[$t['organism'] . '/' . $t['assembly']])
&& !isset($orphan_gs[$t['organism'] . '/' . $t['assembly'] . '/' . $t['gene_set']]);
$out[$loaded ? 'loaded' : 'not_loaded'][] = $t;
}
return $out;
}

/** getOrphanedAssemblyTuples() as an "organism/assembly" => true set, for moop_group_entry_stale_reason(). */

functions.code:
function moop_orphaned_assembly_set(string $organism_data_path): array {
    $set = [];
    foreach (getOrphanedAssemblyTuples($organism_data_path) as $t) $set[$t['organism'] . '/' . $t['assembly']] = true;
    return $set;
}

function computeDataHealthAlerts(string $organism_data_path): array {
    $config        = ConfigManager::getInstance();
    $metadata_path = $config->getPath('metadata_path');
    $cache_file    = moop_organism_cache_file();
    $groups_file   = "$metadata_path/organism_assembly_groups.json";

    $health_alerts = moop_data_health_empty()['health_alerts'];

    // Cache-driven: taxonomy-tree membership + the list of assemblies per organism.
    $cache_data = [];
    if (file_exists($cache_file)) {
        $raw = loadJsonFile($cache_file, []);
        $cache_data = $raw['data'] ?? [];
    }
    //
    // Every OTHER check in this function asks a structural question: is the organism
    // grouped, in the tree, registered, does a database FILE exist. None of them opens a
    // database to ask whether it holds anything -- getNoDatabaseOrganisms() is a
    // file_exists() test -- so an organism that loaded nothing scored a clean bill of
    // health everywhere. Parastichopus_parvimensis sat at 0 features with 10 of 10 checks
    // passing, and Medicago_truncatula and Turritopsis_dohrnii returned 0 annotation
    // search results with HTTP 200, for weeks (found 2026-09-17).
    //
    // The counts were already there: validateDatabaseIntegrity() writes row_counts into
    // the organism cache. This reads the codes it now emits -- no database is opened here.
    $empty_db_codes = moop_db_content_issue_codes();
    $empty_database_organisms = [];
    $health_alerts['not_in_tree'] = count(getOrganismsNotInTree($cache_data));
    foreach ($cache_data as $org_name => $org_data) {
        // data_issues (prose) and data_issue_codes (machine) are built in lockstep, so the
        // index that matched a code selects that code's own message.
        $codes  = $org_data['db_validation']['data_issue_codes'] ?? [];
        $issues = $org_data['db_validation']['data_issues'] ?? [];
        $hits   = [];
        foreach ($codes as $i => $code) {
            if (in_array($code, $empty_db_codes, true)) $hits[] = $issues[$i] ?? $code;
        }
        if ($hits) {
            $empty_database_organisms[] = ['organism' => $org_name, 'issues' => $hits];
        }
    }
    $health_alerts['empty_database'] = count($empty_database_organisms);

    // Gene sets missing a Protein / mRNA / CDS FASTA -- the same list as the setup
    // checklist and Manage Organisms' "Missing gene-set files" filter. Empty assemblies are
    // not repeated here: they already appear as orphaned assembly directories below.
    $gene_set_file_gaps = getGeneSetFastaGaps($cache_data, $config->getSequenceTypes())['gene_sets'];
    $health_alerts['gene_set_files'] = count($gene_set_file_gaps);

    // Gene sets whose chromosome names are not the genome's -- every coordinate-based tool
    // finds nothing for their genes, and nothing else on the dashboard would say so.
    $gene_set_seqname_gaps = getGeneSetSeqnameGaps($cache_data);
    $health_alerts['seqname_mismatch'] = count($gene_set_seqname_gaps);

    // Gene-set dirs on disk with no matching DB row (dropped in a rebuild, not cleaned up).
    $orphaned_gene_set_tuples = getOrphanedGeneSetTuples($organism_data_path);
    $health_alerts['orphaned_gene_sets'] = count($orphaned_gene_set_tuples);

    // Whole assembly dirs on disk with no matching genome row (rename/reload leftovers).
    $orphaned_assembly_tuples = getOrphanedAssemblyTuples($organism_data_path);
    $health_alerts['orphaned_assemblies'] = count($orphaned_assembly_tuples);

    // JBrowse registrations whose source data was renamed/removed outside MOOP. Walks the
    // derived artifacts back to source — the one direction no other check here covers.
    $orphaned_jbrowse_registrations = getOrphanedJBrowseRegistrations($organism_data_path);
    $health_alerts['orphaned_jbrowse'] = count($orphaned_jbrowse_registrations);

    // If EVERY registration reports missing source data, the organisms tree itself is
    // unreachable — an unmounted share or a wrong organism_data path. That is one
    // infrastructure problem, not N broken assemblies, and listing them all as separate
    // failures buries the actual cause under a wall of red.
    $_jb_total = countJBrowseRegistrations();
    $orphaned_jbrowse_systemic = ($_jb_total > 1 && count($orphaned_jbrowse_registrations) === $_jb_total);

    // Organism dirs with assembly data on disk but no organism.sqlite (never loaded).
    $no_database_organisms = getNoDatabaseOrganisms($organism_data_path);
    $health_alerts['no_database'] = count($no_database_organisms);

    // LIVE groups file — keeps grouping checks accurate right after a group edit.
    $gd = loadJsonFile($groups_file, []);
    $health_alerts['ungrouped'] = count(getUngroupedOrganisms($cache_data, $gd));
    // Group entries that point at nothing users can open: directory gone, or no database row
    $_orphans = [];
    foreach ($orphaned_assembly_tuples as $t) $_orphans[$t['organism'] . '/' . $t['assembly']] = true;
    foreach ($gd as $ge) {
        if (moop_group_entry_stale_reason($ge, $organism_data_path, $_orphans) !== null) $health_alerts['stale_groups']++;
    }
    // Gene-set dirs on disk with no groups.json entry at all (checked per gene set).
    // Only those that can be given groups: a directory the database does not have is already
    // counted as an orphan above, and offering it here is how leftovers got published.
    $new_gene_set_tuples = moop_split_unrepresented_by_db(
        getUnrepresentedGeneSetTuples(getOrganismsWithAssemblies($organism_data_path), $organism_data_path, $gd),
        $organism_data_path)['loaded'];
    $health_alerts['new_gene_sets'] = count($new_gene_set_tuples);

    // Gene sets the taxonomy says probably belong to a curated group they are not in.
    // Suggestions, never auto-applied — see lib/group_taxonomy_check.php. Sub-millisecond
    // (two JSON files, no organism DB), so it runs live rather than through housekeeping.
    $gt = moop_gt_compute($gd, loadJsonFile("$metadata_path/taxonomy_tree_config.json", [])['tree'] ?? [], moop_gt_load_exceptions());
    $taxonomy_suggestions = $gt['suggestions'];
    $health_alerts['taxonomy_suggestions'] = count($taxonomy_suggestions);

    return [
        'health_alerts'            => $health_alerts,
        'orphaned_gene_set_tuples' => $orphaned_gene_set_tuples,
        'orphaned_assembly_tuples' => $orphaned_assembly_tuples,
        'orphaned_jbrowse_registrations' => $orphaned_jbrowse_registrations,
        'orphaned_jbrowse_systemic'      => $orphaned_jbrowse_systemic,
        'no_database_organisms'    => $no_database_organisms,
        'empty_database_organisms' => $empty_database_organisms,
        'gene_set_file_gaps'       => $gene_set_file_gaps,
        'gene_set_seqname_gaps'    => $gene_set_seqname_gaps,
        'new_gene_set_tuples'      => $new_gene_set_tuples,
        'taxonomy_suggestions'     => $taxonomy_suggestions,
    ];
}

function buildAutoDescription(string $scientific_name, array $lineage): string {
    if (empty($scientific_name) || empty($lineage)) return '';

    $ranks = [];
    foreach ($lineage as $entry) {
        $ranks[$entry['rank']] = $entry['name'];
    }

    // Class-level names (more specific than phylum)
    $class_map = [
        'Mammalia'       => 'mammal',
        'Aves'           => 'bird',
        'Reptilia'       => 'reptile',
        'Amphibia'       => 'amphibian',
        'Actinopterygii' => 'ray-finned fish',
        'Chondrichthyes' => 'cartilaginous fish',
        'Insecta'        => 'insect',
        'Arachnida'      => 'arachnid',
        'Malacostraca'   => 'crustacean',
        'Magnoliopsida'  => 'flowering plant',
        'Liliopsida'     => 'monocot plant',
        'Pinopsida'      => 'conifer',
    ];

    // Phylum-level fallbacks
    $phylum_map = [
        'Platyhelminthes' => 'flatworm',
        'Nematoda'        => 'nematode',
        'Annelida'        => 'annelid worm',
        'Arthropoda'      => 'arthropod',
        'Mollusca'        => 'mollusc',
        'Echinodermata'   => 'echinoderm',
        'Chordata'        => 'chordate',
        'Porifera'        => 'sponge',
        'Cnidaria'        => 'cnidarian',
        'Streptophyta'    => 'plant',
        'Ascomycota'      => 'fungus',
        'Basidiomycota'   => 'fungus',
        'Apicomplexa'     => 'apicomplexan parasite',
        'Euglenozoa'      => 'euglenozoan',
        'Amoebozoa'       => 'amoeba',
        'Ciliophora'      => 'ciliate',
        'Rhodophyta'      => 'red alga',
        'Chlorophyta'     => 'green alga',
        'Bacillariophyta' => 'diatom',
    ];

    $type = $class_map[$ranks['class'] ?? ''] ?? $phylum_map[$ranks['phylum'] ?? ''] ?? null;

    // Whole sentences through t_plain() (CLAUDE.md 7b), so a site in another language can
    // translate them -- the same English as when this was assembled from pieces.
    $tr = function_exists('t_plain') ? 't_plain' : fn($s, ...$a) => vsprintf($s, $a);
    $family = (string) ($ranks['family'] ?? '');
    $order  = (string) ($ranks['order'] ?? '');
    if ($type) {
        $type = $tr($type);
        if ($family !== '') return $tr('%1$s is a species of %2$s in the family %3$s.', $scientific_name, $type, $family);
        if ($order !== '')  return $tr('%1$s is a species of %2$s in the order %3$s.', $scientific_name, $type, $order);
        return $tr('%1$s is a species of %2$s.', $scientific_name, $type);
    }
    if ($family !== '') return $tr('%1$s is a species in the family %2$s.', $scientific_name, $family);
    if ($order !== '')  return $tr('%1$s is a species in the order %2$s.', $scientific_name, $order);
    return $tr('%1$s is a species.', $scientific_name);
}

function fetchOrganismInfoFromNCBI($genus, $species) {
    $result = [
        'taxon_id' => '',
        'common_name' => '',
        'scientific_name' => "$genus $species",
        'error' => ''
    ];

    if (empty($genus) || empty($species)) {
        $result['error'] = 'Genus and species are required';
        return $result;
    }

    // Search for the organism on NCBI
    $search_url = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?' . http_build_query([
        'db' => 'taxonomy',
        'term' => "$genus $species",
        'retmode' => 'json'
    ]);

    $response = moop_curl_get($search_url);

    if ($response === false) {
        $result['error'] = 'Failed to connect to NCBI';
        return $result;
    }

    $data = json_decode($response, true);

    if (empty($data['esearchresult']['idlist'])) {
        $result['error'] = 'Organism not found on NCBI';
        return $result;
    }

    $taxon_id = $data['esearchresult']['idlist'][0];
    $result['taxon_id'] = $taxon_id;

    // Fetch full details
    $fetch_url = 'https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?' . http_build_query([
        'db' => 'taxonomy',
        'id' => $taxon_id,
        'retmode' => 'json'
    ]);

    $response = moop_curl_get($fetch_url);

    if ($response === false) {
        return $result;
    }

    $data = json_decode($response, true);

    if (!empty($data['result'][$taxon_id]['commonname'])) {
        $result['common_name'] = $data['result'][$taxon_id]['commonname'];
    }

    return $result;
}

function organism_db_path(string $organism): string {
    return ConfigManager::getInstance()->getPath('organism_data') . '/' . $organism . '/organism.sqlite';
}

function validateDatabaseFile($dbFile) {
    if (!file_exists($dbFile)) {
        return ['valid' => false, 'error' => 'Database file not found'];
    }

    if (!is_readable($dbFile)) {
        return ['valid' => false, 'error' => 'Database file not readable (permission denied)'];
    }

    try {
        $db = getDbConnection($dbFile);
        $db = null;
        return ['valid' => true, 'error' => ''];
    } catch (Exception $e) {
        return ['valid' => false, 'error' => $e->getMessage()];
    }
}

