functions.code:
function handleFixFilePermissionsAjax() {
    if (empty($_POST['file_path'])) {
        return ['success' => false, 'message' => 'File path not provided'];
    }

    $file_path = $_POST['file_path'];
    $file_type = $_POST['file_type'] ?? 'file';

    // Basic security: prevent directory traversal
    $file_path = realpath($file_path);

    if (!$file_path || !file_exists($file_path)) {
        return ['success' => false, 'message' => 'File or directory not found'];
    }

    return fixFilePermissions($file_path, $file_type);
}

function handleAdminAjax($customHandler = null) {
    if (!isset($_POST['action'])) {
        return; // Not a POST request with action
    }

    $action = $_POST['action'];
    $isStandardAction = ($action === 'fix_file_permissions');
    $hasCustomHandler = ($customHandler && is_callable($customHandler));

    // Only process AJAX requests if we have a handler for them
    if (!$isStandardAction && !$hasCustomHandler) {
        return; // No handler for this action, let page process normally
    }

    // Only clear buffer for AJAX handlers
    while (ob_get_level()) {
        ob_end_clean();
    }
    header('Content-Type: application/json');

    // Handle standard fix_file_permissions action
    if ($isStandardAction) {
        echo json_encode(handleFixFilePermissionsAjax());
        exit;
    }

    // Pass to custom handler if provided
    if ($hasCustomHandler) {
        $handled = call_user_func($customHandler, $action);
        if ($handled) {
            exit;
        }
    }
}

function moop_find_executable(string $name): string {
    static $cache = [];
    if (isset($cache[$name])) {
        return $cache[$name];
    }
    if ($name === '') {
        return '';
    }
    if ($name[0] === '/') {
        return $cache[$name] = is_executable($name) ? $name : '';
    }
    if (strpos($name, '/') !== false) {
        return $cache[$name] = '';
    }
    $found = trim((string)@shell_exec('command -v ' . escapeshellarg($name) . ' 2>/dev/null'));
    if ($found !== '' && $found[0] === '/' && is_executable($found)) {
        return $cache[$name] = $found;
    }
    foreach (['/usr/local/bin/', '/usr/bin/'] as $dir) {
        if (is_executable($dir . $name)) {
            return $cache[$name] = $dir . $name;
        }
    }
    return $cache[$name] = '';
}

function moop_tool(string $name, string $config_group = ''): string {
    $configured = $name;
    if ($config_group !== '' && class_exists('ConfigManager')) {
        $configured = (string)(ConfigManager::getInstance()->getArray($config_group, [])[$name] ?? $name);
    }
    return moop_find_executable($configured !== '' ? $configured : $name);
}

function moop_find_jbrowse_cli(): ?string {
    static $cached = false;
    if ($cached !== false) {
        return $cached;
    }
    $root = dirname(__DIR__);
    // /usr/local/bin first: scripts/install_jbrowse_cli.sh puts it there, labelled bin_t. A copy
    // inside the document root is httpd_sys_content_t, which SELinux lets the web server read
    // but not run -- from php-fpm is_executable() is false there, so it is only a fallback for
    // shells and hosts without SELinux.
    $candidates = [
        '/usr/local/bin/jbrowse',
        "$root/tools/jbrowse-cli/jbrowse-run.sh",
        "$root/tools/jbrowse-cli/bin/jbrowse",
        (getenv('HOME') ?: '') . '/.npm-global/bin/jbrowse',
        '/root/.npm-global/bin/jbrowse',
        '/usr/local/lib/node_modules/.bin/jbrowse',
        '/usr/lib/node_modules/@jbrowse/cli/bin/run',
    ];
    foreach ($candidates as $path) {
        if ($path !== '' && $path[0] === '/' && is_executable($path)) {
            return $cached = $path;
        }
    }
    $found = moop_find_executable('jbrowse');
    return $cached = ($found !== '' ? $found : null);
}

function moop_cache_disk_problem(string $cache_dir, string $organism_dir): string {
    if (!is_dir($cache_dir) || !is_dir($organism_dir)) return '';
    $free_c = @disk_free_space($cache_dir);
    $free_o = @disk_free_space($organism_dir);
    if ($free_c === false) return '';
    $gb = fn($b) => sprintf('%.1f GB', $b / 1073741824);
    if ($free_c < 5 * 1073741824) {
        return "the cache folder's disk has only " . $gb($free_c) . ' free';
    }
    $same = @stat($cache_dir)['dev'] === @stat($organism_dir)['dev'];
    if (!$same && $free_o !== false && $free_c < $free_o / 10) {
        return "the cache folder is on a smaller disk than organisms/ (" . $gb($free_c) . ' free vs ' . $gb($free_o) . ')';
    }
    return '';
}

function getAvailableTools($context = []) {
    $config   = ConfigManager::getInstance();
    $all_tools = $config->getAllTools();
    $site     = $config->getString('site');
    $current_page = $context['page'] ?? null;

    // A site that saved its own toolbox (Admin -> Manage Tools, 'tools_layout.toolbox') gets
    // exactly those tools in that order, and its own labels; one that never did gets the
    // registry's order and 'toolbox' flags, as shipped.
    $saved_order = $config->toolboxOrder();
    if ($saved_order !== null) {
        $ordered = [];
        foreach ($saved_order as $id) {
            if (isset($all_tools[$id])) $ordered[$id] = ['toolbox' => true] + $all_tools[$id];
        }
        $all_tools = $ordered;
    }

    $tools = [];
    foreach ($all_tools as $tool_id => $tool) {
        if ($current_page && !_tool_visible_on_page($tool, $current_page)) {
            continue;
        }
        if ($tool_id === 'primer_maker' && !moop_primer_maker_as_shipped()) {
            $tool['description'] = PrimerPresets::GENERIC_DESCRIPTION;   // it names the shipped cards
        }
        $url = _build_tool_url($tool, $context, $site);
        if ($url !== null) {
            $tools[$tool_id] = array_merge($tool, ['url' => $url, 'name' => $config->toolLabel((string) $tool_id, 'toolbox')]);
        }
    }
    return $tools;
}

function _build_tool_url($tool, $context, $site) {
    if (!empty($tool['required_params'])) {
        foreach ($tool['required_params'] as $req) {
            if (empty($context[$req])) {
                return null;
            }
        }
    }

    $url      = moop_url_base() . $tool['url_path'];
    $params   = [];
    $organisms = [];

    foreach ($tool['context_params'] as $param) {
        if (!empty($context[$param])) {
            if ($param === 'organisms' && is_array($context[$param])) {
                $organisms = $context[$param];
            } else {
                $params[$param] = $context[$param];
            }
        }
    }

    if (empty($params) && empty($organisms)) {
        return $url;
    }

    $sep = '?';
    if (!empty($params)) {
        $url .= '?' . http_build_query($params);
        $sep  = '&';
    }
    foreach ($organisms as $org) {
        $url .= $sep . 'organisms[]=' . urlencode($org);
        $sep  = '&';
    }

    return $url;
}

