public function getJobStatus($jobId) {
        try {
            $status = $this->galaxy->getJobStatus($jobId);

            return [
                'state' => $status['state'],
                'status' => $status['status'],
                'created' => $status['create_time'],
                'updated' => $status['update_time']
            ];
        } catch (Exception $e) {
            return [
                'state' => 'error',
                'message' => $e->getMessage()
            ];
        }
