/** Access filter + attach accessions/terms + stable order (stage, then file). */

functions.code:
function moop_images_finish(PDO $db, string $organism, array $rows, int $limit): array {
    $rows = array_filter($rows, fn($r) => moop_dataset_visible($organism, $r['assembly'], $r['gene_set'], moop_image_analysis_key($organism, (string) $r['analysis'])));
    usort($rows, fn($a, $b) => [(string) $a['stage_id'], $a['file']] <=> [(string) $b['stage_id'], $b['file']]);
    $rows = array_slice($rows, 0, $limit);
    if (!$rows) return [];
    $ids = array_column($rows, 'id');
    $in  = implode(',', array_map('intval', $ids));
    $accs = $terms = [];
    foreach ($db->query("SELECT image_id, accession FROM image_accession WHERE image_id IN ($in)") as $r) $accs[$r['image_id']][] = $r['accession'];
    foreach ($db->query("SELECT image_id, term_id FROM image_term WHERE image_id IN ($in)") as $r) $terms[$r['image_id']][] = $r['term_id'];
    foreach ($rows as &$r) { $r['accessions'] = $accs[$r['id']] ?? []; $r['terms'] = $terms[$r['id']] ?? []; }
    return $rows;
}

function moop_images_by_analysis(string $organism, array $images): array {
    $db = moop_images_open($organism);
    $meta = [];
    if ($db) foreach ($db->query('SELECT * FROM analysis') as $r) $meta[$r['analysis']] = $r;
    $groups = [];
    foreach ($images as $im) {
        $k = (string) $im['analysis'];
        $groups[$k]['analysis'] = $meta[$k] ?? ['analysis' => $k, 'title' => $k, 'description' => null, 'pmid' => null, 'citation' => null, 'sort' => 2000, 'key_image' => null, 'key_caption' => null, 'link_url' => null, 'link_text' => null];
        $groups[$k]['images'][] = $im;
    }
    uasort($groups, fn($a, $b) => [$a['analysis']['sort'], $a['analysis']['title']] <=> [$b['analysis']['sort'], $b['analysis']['title']]);
    return array_values($groups);
}

function moop_image_thumbnail(string $organism, string $path): ?string {
    if (!extension_loaded('gd')) return null;
    $ext = strtolower(pathinfo($path, PATHINFO_EXTENSION));
    $open = ['png' => 'imagecreatefrompng', 'jpg' => 'imagecreatefromjpeg', 'jpeg' => 'imagecreatefromjpeg', 'gif' => 'imagecreatefromgif'][$ext] ?? null;
    if (!$open || !function_exists($open)) return null;
    require_once __DIR__ . '/cache_paths.php';
    $dir = moop_cache_root() . '/gene_image_thumbs/' . preg_replace('/[^A-Za-z0-9_.-]/', '', $organism);
    $out = $dir . '/' . sha1($path . '|' . filesize($path) . '|' . filemtime($path)) . ($ext === 'png' || $ext === 'gif' ? '.png' : '.jpg');
    if (is_file($out)) return $out;
    if (is_file("$out.orig")) return null;                    // decided before: the original is smaller
    if (filesize($path) < 40000) return null;                 // small already: a thumbnail cannot save much
    if (!moop_ensure_cache_dir($dir)) return null;
    $src = @$open($path);
    if (!$src) return null;
    [$w, $h] = [imagesx($src), imagesy($src)];
    $scale = min(1, 320 / $w, 240 / $h);
    if ($scale >= 1) { imagedestroy($src); return null; }   // already small: the original is the thumbnail
    [$tw, $th] = [max(1, (int) round($w * $scale)), max(1, (int) round($h * $scale))];
    $dst = imagecreatetruecolor($tw, $th);
    if (substr($out, -4) === '.png') { imagealphablending($dst, false); imagesavealpha($dst, true); }
    imagecopyresampled($dst, $src, 0, 0, 0, 0, $tw, $th, $w, $h);
    // 256 colours: plots and stained images lose nothing visible at thumbnail size, and the file
    // shrinks several-fold (a full-colour PNG thumbnail of a 96 KB plot was 64 KB).
    if (substr($out, -4) === '.png') imagetruecolortopalette($dst, true, 256);
    $tmp = $out . '.tmp-' . getmypid();
    $ok = substr($out, -4) === '.png' ? imagepng($dst, $tmp, 6) : imagejpeg($dst, $tmp, 85);
    imagedestroy($src); imagedestroy($dst);
    if ($ok && filesize($tmp) >= filesize($path)) {          // e.g. a palette PNG: resampled is bigger
        @unlink($tmp); @touch("$out.orig"); return null;
    }
    if (!$ok || !@rename($tmp, $out)) { @unlink($tmp); return null; }
    return $out;
}

function moop_image_key_path(string $organism, string $analysis): ?string {
    $db = moop_images_open($organism);
    if (!$db) return null;
    $st = $db->prepare('SELECT key_image FROM analysis WHERE analysis = ?');
    $st->execute([$analysis]);
    $key = (string) $st->fetchColumn();
    if ($key === '') return null;
    $st = $db->prepare('SELECT DISTINCT assembly, gene_set FROM image WHERE analysis = ?');
    $st->execute([$analysis]);
    foreach ($st as $r) {
        if (moop_dataset_visible($organism, $r['assembly'], $r['gene_set'], moop_image_analysis_key($organism, $analysis))) return moop_image_path($organism, $key);
    }
    return null;
}

function moop_images_for_analysis(string $organism, string $analysis, array $kinds = [], int $limit = 1000): array {
    $db = moop_images_open($organism);
    if (!$db || $analysis === '') return [];
    $sql = 'SELECT * FROM image WHERE analysis = ?';
    $args = [$analysis];
    if ($kinds) { $sql .= ' AND kind IN (' . implode(',', array_fill(0, count($kinds), '?')) . ')'; $args = array_merge($args, $kinds); }
    $st = $db->prepare($sql . ' LIMIT ' . (int) ($limit * 2));
    $st->execute($args);
    $rows = [];
    foreach ($st as $r) $rows[$r['id']] = $r;
    return moop_images_finish($db, $organism, $rows, $limit);
}

function moop_images_kind_counts(string $organism, string $analysis): array {
    $db = moop_images_open($organism);
    if (!$db || $analysis === '') return [];
    $st = $db->prepare('SELECT kind, assembly, gene_set, COUNT(*) AS n FROM image WHERE analysis = ? GROUP BY kind, assembly, gene_set');
    $st->execute([$analysis]);
    $key = moop_image_analysis_key($organism, $analysis);
    $counts = [];
    foreach ($st as $r) {
        if (!moop_dataset_visible($organism, $r['assembly'], $r['gene_set'], $key)) continue;
        $counts[$r['kind']] = ($counts[$r['kind']] ?? 0) + (int) $r['n'];
    }
    return array_intersect_key(array_replace(array_flip(MOOP_IMAGE_KINDS), $counts), $counts);
}

function moop_images_analyses(string $organism): array {
    $db = moop_images_open($organism);
    if (!$db) return [];
    $visible = [];
    foreach ($db->query('SELECT DISTINCT analysis, assembly, gene_set FROM image WHERE analysis IS NOT NULL') as $r) {
        if (!isset($visible[$r['analysis']]) && moop_dataset_visible($organism, $r['assembly'], $r['gene_set'], moop_image_analysis_key($organism, $r['analysis']))) {
            $visible[$r['analysis']] = true;
        }
    }
    $out = [];
    foreach ($db->query('SELECT * FROM analysis ORDER BY sort, title') as $r) {
        if (isset($visible[$r['analysis']])) $out[$r['analysis']] = $r;
    }
    return $out;
}

function moop_images_gene_names(string $organism, array $accessions): array {
    $accs = array_values(array_unique(array_filter(array_map('strval', $accessions), 'strlen')));
    if (!$accs) return [];
    require_once __DIR__ . '/crosswalk.php';
    $is_name = fn(string $n, string $id) => $n !== '' && strcasecmp($n, $id) !== 0 && stripos($n, $id) === false && stripos($id, $n) === false
                                            && !preg_match('/^(LOC\d+|[A-Za-z]{1,6}[_.]?\d{5,}[0-9._]*)$/', $n);
    $refs = [];   // accession_lc => first reference gene
    $hubs = array_keys(moop_crosswalk_sources()[$organism]['hubs'] ?? []);
    foreach (moop_crosswalk_genes($organism, $accs) as $acc_lc => $rows) {
        usort($rows, fn($a, $b) => array_search($a['hub'], $hubs) <=> array_search($b['hub'], $hubs));
        $refs[$acc_lc] = $rows[0]['ref_id'];
    }
    $f = rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/') . '/' . preg_replace('/[^A-Za-z0-9_.-]/', '', $organism) . '/organism.sqlite';
    $names = [];   // uniquename => name (the feature's gene's name)
    if (is_file($f)) {
        try {
            $db = new PDO('sqlite:' . $f, null, null, [PDO::SQLITE_ATTR_OPEN_FLAGS => PDO::SQLITE_OPEN_READONLY]);
            $want = array_values(array_unique(array_merge($accs, array_values($refs))));
            foreach (array_chunk($want, 400) as $chunk) {
                $st = $db->prepare('SELECT f.feature_uniquename u, f.feature_name n, p.feature_name pn FROM feature f
                                    LEFT JOIN feature p ON p.feature_id = f.parent_feature_id
                                    WHERE f.feature_uniquename IN (' . implode(',', array_fill(0, count($chunk), '?')) . ')');
                $st->execute($chunk);
                foreach ($st as $r) $names[$r['u']] = trim((string) ($r['n'] ?: $r['pn']));
            }
        } catch (Throwable $e) {
            error_log("MOOP: image gene names for $organism: " . $e->getMessage());
        }
    }
    $out = [];
    foreach ($accs as $a) {
        $ref = $refs[mb_strtolower($a)] ?? '';
        foreach ([$ref !== '' ? ($names[$ref] ?? '') : '', $names[$a] ?? ''] as $n) {
            if ($is_name($n, $a) && ($ref === '' || $is_name($n, $ref))) { $out[$a] = $n; break; }
        }
    }
    return $out;
}

function moop_gene_isoforms(string $organism, string $assembly, string $gene_set, string $gene_uniquename): array
{
    require_once __DIR__ . '/gff_gene_model.php';
    if ($gene_uniquename === '') return [];
    $model = moop_gene_model($organism, $assembly, $gene_set, $gene_uniquename, '');
    if ($model === null) return [];

    $transcripts = array_values(array_filter($model['children'], fn($c) => $c['id'] !== '' && moop_gff_is_transcript_type($c['type'])));
    $gene_set_path = ConfigManager::getInstance()->getPath('organism_data') . "/$organism/$assembly/$gene_set";
    $fai = $gene_set_path . '/transcript.nt.fa.fai';
    $wanted = [];
    foreach ($transcripts as $t) {
        $wanted[] = $t['id'];
        $wanted[] = preg_replace('/^(?:rna|cds|gene|id)-/', '', $t['id']);
    }
    require_once __DIR__ . '/fasta_index.php';
    $idx = is_readable($fai) ? moop_fai_lookup($fai, array_values(array_unique($wanted))) : [];

    $out = [];
    foreach ($transcripts as $t) {
        $bare = preg_replace('/^(?:rna|cds|gene|id)-/', '', $t['id']);
        $fasta_id = isset($idx[$t['id']]) ? $t['id'] : (isset($idx[$bare]) ? $bare : '');
        $out[] = $t + ['fasta_id' => $fasta_id, 'length' => $fasta_id !== '' ? $idx[$fasta_id]['len'] : null];
    }
    return $out;
}

function moop_primer_sequence_types(): array
{
    return ['transcript', 'cds'];
}

function moop_transcript_sequence(string $gene_set_path, string $id, string $seq_type = 'transcript'): string
{
    $types   = ConfigManager::getInstance()->getSequenceTypes();
    $pattern = $types[$seq_type]['pattern'] ?? null;
    if ($pattern === null || !in_array($seq_type, moop_primer_sequence_types(), true)) {
        return '';
    }

    $fa = $gene_set_path . '/' . $pattern;
    if ($id === '' || !is_readable($fa) || !is_readable($fa . '.fai')) {
        return '';
    }

    // The .fai reader the rest of the site uses (exact ids, uppercased like every other
    // sequence on the site), rather than a `samtools faidx` process per lookup.
    require_once __DIR__ . '/fasta_index.php';
    $got = moop_fasta_fetch_with_headers($fa, array_values(array_unique([$id, preg_replace('/^(?:rna|cds|gene|id)-/', '', $id)])));
    foreach ($got as $rec) {
        if ($rec['seq'] !== '') return $rec['seq'];
    }
    return '';
}

function moop_gene_lookup(string $organism, string $id, string $assembly = '', string $gene_set = ''): array {
    $organism_data = ConfigManager::getInstance()->getPath('organism_data');
    if (!preg_match('/^[A-Za-z0-9_.-]+$/', $organism) || str_contains($organism, '..')) return ['status' => 'no_organism'];
    $info = loadOrganismInfo($organism, $organism_data);
    if (!$info || (!is_public_organism($organism) && !has_access('COLLABORATOR', $organism))
        || !is_file("$organism_data/$organism/organism.sqlite")) {
        return ['status' => 'no_organism'];
    }
    $db    = "$organism_data/$organism/organism.sqlite";
    $label = trim(($info['genus'] ?? '') . ' ' . ($info['species'] ?? '')) ?: str_replace('_', ' ', $organism);

    // The gene sets this visitor may open, for permission-based DB filtering.
    $accessible_sources = flattenSourcesList(getAccessibleGeneSets($organism));
    $gene_set_ids = array_values(array_filter(array_column($accessible_sources, 'gene_set_id')));
    if (!$gene_set_ids) return ['status' => 'no_gene_sets', 'label' => $label];

    // Which gene set. A link may name one (assembly + gene_set: search results, BLAST, the home
    // page ID search); without it, an ID found in more than one gene set the viewer can open is
    // ASKED about, never guessed -- before 2026-10-20 the page silently took whichever row came
    // first and ignored the parameters the links already sent.
    if ($assembly !== '' || $gene_set !== '') {
        $scoped = array_filter($accessible_sources, fn($src) =>
            // the accession, or the assembly's directory name (they differ for a few assemblies)
            ($assembly === '' || in_array($assembly, [$src['genome_accession'] ?? null, $src['assembly'] ?? null], true))
            && ($gene_set === '' || ($src['gene_set'] ?? '') === $gene_set));
        $gene_set_ids = array_values(array_unique(array_filter(array_column($scoped, 'gene_set_id'))));
    }
    $holding = moop_feature_gene_set_ids($id, $db, $gene_set_ids);
    if (!$holding) {
        // Not in any gene set the viewer may open (or not in the one named): the same answer
        // either way, so a link cannot be used to learn what a restricted gene set holds.
        return ['status' => 'not_found', 'label' => $label];
    }
    if (count($holding) > 1) {
        $choices = [];
        foreach ($accessible_sources as $src) {
            if (!in_array((int)($src['gene_set_id'] ?? 0), $holding, true)) continue;
            $accession = $src['genome_accession'] ?? $src['assembly'];
            $choices["$accession/{$src['gene_set']}"] = [
                'assembly_label' => assembly_label($src['genome_name'] ?? '', $accession),
                'assembly'       => $accession,
                'gene_set'       => $src['gene_set'],
                'url'            => moop_url_base() . "/tools/parent.php?organism=" . urlencode($organism)
                                  . '&uniquename=' . urlencode($id)
                                  . '&assembly=' . urlencode($accession) . '&gene_set=' . urlencode($src['gene_set']),
            ];
        }
        return ['status' => 'choose', 'label' => $label, 'choices' => array_values($choices)];
    }
    $gene_set_ids = $holding;   // the one gene set; everything below reads only it

    // The gene: walk up from the ID to the highest ancestor whose type gets a page.
    $parents = !empty($info['feature_types']['parents']) ? $info['feature_types']['parents'] : ['gene', 'pseudogene'];
    $ancestors = getAncestors($id, $db, $gene_set_ids);
    $ancestor_id = '';
    $ancestor_uniquename = '';
    foreach ($ancestors as $ancestor) {
        $ancestor_id         = $ancestor['feature_id'];
        $ancestor_uniquename = $ancestor['feature_uniquename'];
        if (in_array($ancestor['feature_type'], $parents)) break;   // reached a page type
    }

    $row = getFeatureById($ancestor_id, $db, $gene_set_ids);
    if (empty($row)) return ['status' => 'not_found', 'label' => $label];

    return [
        'status'              => 'ok',
        'label'               => $label,
        'row'                 => $row,
        'gene_set_ids'        => $gene_set_ids,
        'accessible_sources'  => $accessible_sources,
        'ancestor_uniquename' => $ancestor_uniquename,
    ];
}

functions.comment:
/**
* Path to the identity cache, or '' if the cache directory cannot be created.
*/

functions.code:
function moop_gene_set_identity_file(): string
{
    $root = moop_cache_root();
    return moop_ensure_cache_dir($root) ? "$root/.gene_set_identity.json" : '';
}

function moop_gene_set_identity_fingerprint(string $db_path): string
{
    $st = @stat($db_path);
    if ($st === false) return 'missing';
    return $st['mtime'] . ':' . $st['size'];
}

function moop_gene_set_identity_read_db(string $db_path): array
{
    $entry = ['genomes' => [], 'gene_sets' => []];
    if (!is_file($db_path) || !is_readable($db_path)) return $entry;

    try {
        $dbh = getDbConnection($db_path);
        $entry['genomes'] = $dbh->query(
            "SELECT genome_id, genome_name, genome_accession FROM genome ORDER BY genome_name"
        )->fetchAll(PDO::FETCH_ASSOC);

        try {
            $entry['gene_sets'] = $dbh->query(
                "SELECT gene_set_id, genome_id, gene_set_name FROM gene_set ORDER BY gene_set_name"
            )->fetchAll(PDO::FETCH_ASSOC);
        } catch (PDOException $e) {
            // gene_set table may not exist in older DBs — treat as no gene sets
        }
    } catch (Exception $e) {
        error_log('MOOP gene-set identity: could not read ' . $db_path . ' — ' . $e->getMessage());
    }

    return $entry;
}

function moop_gene_set_identity(array $organisms, string $organism_data): array
{
    $organisms = array_values(array_unique($organisms));
    if (empty($organisms)) return [];

    $cache_file = moop_gene_set_identity_file();
    $stored     = [];
    if ($cache_file !== '' && is_file($cache_file)) {
        $raw = json_decode((string)@file_get_contents($cache_file), true);
        if (is_array($raw) && ($raw['schema_version'] ?? 0) === GENE_SET_IDENTITY_SCHEMA_VERSION) {
            $stored = is_array($raw['data'] ?? null) ? $raw['data'] : [];
        }
    }

    $out   = [];
    $dirty = false;
    foreach ($organisms as $org) {
        $fp = moop_gene_set_identity_fingerprint("$organism_data/$org/organism.sqlite");
        if (isset($stored[$org]) && ($stored[$org]['fp'] ?? null) === $fp) {
            $out[$org] = $stored[$org];
            continue;
        }
        $entry       = moop_gene_set_identity_read_db("$organism_data/$org/organism.sqlite");
        $entry['fp'] = $fp;
        $out[$org]   = $entry;
        $stored[$org] = $entry;
        $dirty = true;
    }

    if ($dirty && $cache_file !== '') {
        // Drop organisms that no longer exist on disk, so a long-lived deployment's cache
        // does not accumulate entries for removed organisms forever.
        foreach (array_keys($stored) as $org) {
            if (!is_dir("$organism_data/$org")) unset($stored[$org]);
        }
        organism_cache_write_atomic($cache_file, [
            'schema_version' => GENE_SET_IDENTITY_SCHEMA_VERSION,
            'generated'      => date('c'),
            'data'           => $stored,
        ]);
    }

    return $out;
}

function moop_resolve_gene_set_identity(array $identity, string $organism_dir, string $assembly, string $gene_set): array
{
    $found = [
        'genome_id'        => null,
        'genome_name'      => null,
        'genome_accession' => null,
        'assembly_dir'     => $assembly,
        'gene_set_id'      => null,
    ];

    $matching_genome_ids = [];
    foreach ($identity['genomes'] ?? [] as $genome) {
        $name = $genome['genome_name'] ?? null;
        $acc  = $genome['genome_accession'] ?? null;
        if ($name !== $assembly && $acc !== $assembly) continue;

        $matching_genome_ids[] = (string)($genome['genome_id'] ?? '');

        if ($found['genome_id'] === null) {
            $found['genome_id']        = $genome['genome_id'] ?? null;
            $found['genome_name']      = $name;
            $found['genome_accession'] = $acc;
            if     ((string)$name !== '' && is_dir("$organism_dir/$name")) $found['assembly_dir'] = $name;
            elseif ((string)$acc  !== '' && is_dir("$organism_dir/$acc"))  $found['assembly_dir'] = $acc;
        }
    }

    if (!empty($matching_genome_ids)) {
        foreach ($identity['gene_sets'] ?? [] as $gs) {
            if (($gs['gene_set_name'] ?? null) !== $gene_set) continue;
            if (!in_array((string)($gs['genome_id'] ?? ''), $matching_genome_ids, true)) continue;
            $found['gene_set_id'] = (int)$gs['gene_set_id'];
            break;
        }
    }

    return $found;
}

function moop_homology_types(array $db_types): array {
    $flags = moop_homology_flags();
    return array_values(array_filter($db_types, fn($t) => $flags[$t]
        ?? (bool)preg_match('/homolog|ortholog/i', (string)$t)));
}

functions.comment:
/**
* Which annotation types count as "this gene resembles a known gene" for the comparison's homology
* column (user, 2026-10-20). NOT "any annotation": DeepLoc predicts a location for every protein, so
* "any" was 100% for Congeria and meaningless. GO terms, domains and families are left out too --
* GO is derived from the others; the question is "does this gene have a known relative", which is
* what separates real genes from spurious predictions.
*
* GENERAL, because installations name their annotation types differently:
*   - annotation_config.json annotation_types.{type}.homology = true|false decides, when set;
*   - otherwise a type counts when its name contains "homolog" or "ortholog" (any case) --
*     here Homologs, Orthologs and RBBH Homolog; Paralogs and the rest do not.
*
* @param list<string> $db_types  the annotation types present in the database
* @return list<string>
*/
function moop_homology_types(array $db_types): array {
$flags = moop_homology_flags();
return array_values(array_filter($db_types, fn($t) => $flags[$t]
?? (bool)preg_match('/homolog|ortholog/i', (string)$t)));
}

/** The explicit homology flags from annotation_config.json: {type: bool}, only types that set one. */

functions.code:
function moop_homology_flags(): array {
    $cfg = loadJsonFile(ConfigManager::getInstance()->getPath('metadata_path') . '/annotation_config.json', []);
    $flags = [];
    foreach (($cfg['annotation_types'] ?? []) as $type => $settings) {
        if (is_array($settings) && array_key_exists('homology', $settings)) {
            $flags[(string)$type] = (bool)$settings['homology'];
        }
    }
    ksort($flags);
    return $flags;
}

function moop_gene_set_summary_file(string $organism): string {
    $dir = moop_cache_root() . '/' . $organism;
    return moop_ensure_cache_dir($dir) ? "$dir/gene_set_summary.json" : '';
}

functions.comment:
/**
* Is this organism's summary missing or older than anything it was built from?
*/

functions.code:
function moop_gene_set_summary_is_stale(string $organism_dir, string $file): bool {
    if ($file === '' || !is_file($file)) return true;
    $doc = json_decode((string)@file_get_contents($file), true);
    if (($doc['version'] ?? null) !== MOOP_GENE_SET_SUMMARY_VERSION) return true;
    // Built with different homology flags (an admin changed annotation_config.json): rebuild.
    if (($doc['homology_flags'] ?? null) !== moop_homology_flags()) return true;
    $built = filemtime($file);
    if (is_file("$organism_dir/organism.sqlite") && filemtime("$organism_dir/organism.sqlite") > $built) return true;
    foreach (glob("$organism_dir/*/" . genome_fasta_filename() . '.fai') ?: [] as $fai) {
        if (filemtime($fai) > $built) return true;
    }
    return false;
}

function moop_fai_stats(string $fai): ?array {
    if (!is_file($fai) || filesize($fai) === 0) return null;
    $total = 0; $count = 0;
    $fh = @fopen($fai, 'r');
    if (!$fh) return null;
    while (($line = fgets($fh)) !== false) {
        $parts = explode("\t", $line, 3);
        if (isset($parts[1]) && ctype_digit($parts[1])) {
            $total += (int)$parts[1];
            $count++;
        }
    }
    fclose($fh);
    if ($count === 0) return null;

    // Longest first; N50 is the length at which the running sum first reaches half the total.
    // sort's stderr is dropped: stopping at the N50 closes the pipe early, and sort then
    // reports "Broken pipe" -- expected, not an error.
    $cmd = 'cut -f2 ' . escapeshellarg($fai) . ' | LC_ALL=C sort -rn 2>/dev/null';
    $pipe = popen($cmd, 'r');
    if (!$pipe) return null;
    $n50 = 0; $l50 = 0; $running = 0;
    while (($len = fgets($pipe)) !== false) {
        $running += (int)$len;
        $l50++;
        if ($running * 2 >= $total) { $n50 = (int)$len; break; }
    }
    pclose($pipe);
    return ['sequences' => $count, 'total_length' => $total, 'n50' => $n50, 'l50' => $l50];
}

function moop_load_assembly_stats(string $assembly_dir): ?array {
    $file = rtrim($assembly_dir, '/') . '/assembly_stats.json';
    if (!is_file($file)) return null;
    $doc = json_decode((string)@file_get_contents($file), true);
    if (!is_array($doc)) {
        error_log("MOOP: unreadable assembly_stats.json at $file");
        return null;
    }
    $out = [];
    foreach (['sequences', 'total_length', 'n50', 'l50'] as $k) {
        if (!is_int($doc[$k] ?? null) || $doc[$k] <= 0) {
            error_log("MOOP: assembly_stats.json at $file lacks a valid $k");
            return null;
        }
        $out[$k] = $doc[$k];
    }
    foreach (['n90', 'l90', 'longest', 'contigs', 'contig_n50', 'contig_l50', 'gap_bases'] as $k) {
        if (is_int($doc[$k] ?? null) && $doc[$k] >= 0) $out[$k] = $doc[$k];
    }
    // Percentages arrive as JSON numbers, so 41.0 is written 41: accept int or float.
    foreach (['gap_pct', 'gc_pct'] as $k) {
        if (is_numeric($doc[$k] ?? null) && $doc[$k] >= 0 && $doc[$k] <= 100) $out[$k] = (float)$doc[$k];
    }
    // gap_pct is rounded to one decimal by the pipeline, so a typical 0.045% arrives as 0 and
    // would read as "no gaps". gap_bases is exact: derive the share from it when present.
    if (isset($out['gap_bases'])) $out['gap_pct'] = 100 * $out['gap_bases'] / $out['total_length'];
    $out['from_pipeline'] = true;
    return $out;
}

functions.comment:
/**
* Build one organism's summary. Seconds on a large organism: background run only.
*/

functions.code:
function moop_build_gene_set_summary(string $organism_dir): array {
    $out = ['version' => MOOP_GENE_SET_SUMMARY_VERSION, 'homology_flags' => moop_homology_flags(),
            'homology_types' => [], 'assemblies' => [], 'gene_sets' => []];
    foreach (glob("$organism_dir/*/" . genome_fasta_filename() . '.fai') ?: [] as $fai) {
        $stats = moop_fai_stats($fai);
        if ($stats) $out['assemblies'][basename(dirname($fai))] = $stats;
    }

    $db = "$organism_dir/organism.sqlite";
    if (!is_file($db)) return $out;
    $key = "g.genome_accession || '/' || gs.gene_set_name";
    foreach (fetchData("SELECT $key AS k,
                               COUNT(CASE WHEN f.feature_type = 'gene' THEN 1 END) AS genes,
                               COUNT(CASE WHEN " . moop_transcript_type_sql('f.feature_type') . " THEN 1 END) AS transcripts
                        FROM gene_set gs
                        JOIN genome g ON g.genome_id = gs.genome_id
                        LEFT JOIN feature f ON f.gene_set_id = gs.gene_set_id
                        GROUP BY gs.gene_set_id", $db, []) as $row) {
        $out['gene_sets'][$row['k']] = ['genes' => (int)$row['genes'], 'transcripts' => (int)$row['transcripts'],
                                        'homology_genes' => 0, 'homology_transcripts' => 0];
    }
    // A gene counts when it, or one of its transcripts, carries a homolog or ortholog.
    $homology = moop_homology_types(array_column(
        fetchData('SELECT DISTINCT annotation_type FROM annotation_source', $db, []), 'annotation_type'));
    $out['homology_types'] = $homology;   // recorded, so the page can say what was counted
    if (!$homology) {
        // Nothing homolog-like in this database: the figure is unknown, not zero.
        foreach ($out['gene_sets'] as &$gs_counts) {
            $gs_counts['homology_genes'] = $gs_counts['homology_transcripts'] = null;
        }
        unset($gs_counts);
        return $out;
    }
    $types = implode(',', array_fill(0, count($homology), '?'));
    foreach (fetchData("SELECT $key AS k,
                               COUNT(DISTINCT CASE WHEN f.feature_type = 'gene' THEN f.feature_id
                                                   WHEN p.feature_type = 'gene' THEN p.feature_id END) AS homology_genes,
                               COUNT(DISTINCT CASE WHEN " . moop_transcript_type_sql('f.feature_type') . " THEN f.feature_id END) AS homology_transcripts
                        FROM feature f
                        LEFT JOIN feature p ON p.feature_id = f.parent_feature_id
                        JOIN gene_set gs ON gs.gene_set_id = f.gene_set_id
                        JOIN genome g ON g.genome_id = gs.genome_id
                        WHERE f.feature_id IN (SELECT fa.feature_id FROM feature_annotation fa
                                               JOIN annotation a ON a.annotation_id = fa.annotation_id
                                               JOIN annotation_source ans ON ans.annotation_source_id = a.annotation_source_id
                                               WHERE ans.annotation_type IN ($types))
                        GROUP BY gs.gene_set_id", $db, $homology) as $row) {
        if (isset($out['gene_sets'][$row['k']])) {
            $out['gene_sets'][$row['k']]['homology_genes']       = (int)$row['homology_genes'];
            $out['gene_sets'][$row['k']]['homology_transcripts'] = (int)$row['homology_transcripts'];
        }
    }
    return $out;
}

function moop_gene_set_comparison_rows(string $organism, array $assemblies, string $organism_data): array {
    $org_dir = "$organism_data/$organism";
    $file    = moop_gene_set_summary_file($organism);
    $summary = null;
    if ($file !== '' && is_file($file) && !moop_gene_set_summary_is_stale($org_dir, $file)) {
        $summary = json_decode((string)@file_get_contents($file), true);
    }
    $db = "$org_dir/organism.sqlite";
    if (!is_file($db)) return [];

    $rows = [];
    foreach ($assemblies as $accession => $label) {
        foreach (getAssemblyGeneSetNames($accession, $db) as $gs) {
            if (!has_gene_set_access($organism, $accession, $gs['gene_set_name'])) continue;
            // The directory the files are actually in: the accession, else the genome name
            // (the same rule as the gene set and assembly pages).
            $asm_dir = is_dir("$org_dir/$accession") ? $accession
                     : (($gs['genome_name'] !== '' && is_dir("$org_dir/{$gs['genome_name']}")) ? $gs['genome_name'] : $accession);
            $gs_dir  = "$org_dir/$asm_dir/{$gs['gene_set_name']}";
            $meta    = loadJsonFile("$gs_dir/geneset.json", []);
            $busco   = moop_load_busco($gs_dir);

            $euk = null;
            foreach ($busco['runs'] ?? [] as $run) {
                if (strpos($run['lineage'], 'eukaryota') === 0) { $euk = $run; break; }
            }

            $counts   = $summary['gene_sets']["$accession/{$gs['gene_set_name']}"] ?? null;
            $asm_stat = moop_assembly_stats_or_fallback("$org_dir/$asm_dir", $summary);
            $warnings = $busco['warnings'] ?? [];
            if ($counts && $counts['transcripts'] > 0 && $counts['homology_transcripts'] === 0) {   // 0, not null
                $warnings[] = 'No gene in this gene set has a homolog or ortholog attached.';
            }

            $rows[] = [
                'assembly'       => $accession,
                // 'transcripts' = one assembled transcript per gene standing in for a genome:
                // its N50 is a transcript length and must not compete with real genomes.
                'genome_kind'    => moop_genome_kind("$org_dir/$asm_dir"),
                'assembly_label' => $label,
                'gene_set'       => $gs['gene_set_name'],
                'source'         => is_string($meta['source'] ?? null) ? $meta['source'] : '',
                'date_added'     => is_string($meta['date_added'] ?? null) ? $meta['date_added'] : '',
                'counts'         => $counts,
                'assembly_stats' => $asm_stat,
                'busco_euk'      => $euk,
                'warnings'       => $warnings,
            ];
        }
    }
    return $rows;
}

function getAssemblyGeneSetNames(string $assembly, string $db): array {
    return fetchData("SELECT gs.gene_set_name, g.genome_name
                      FROM gene_set gs JOIN genome g ON g.genome_id = gs.genome_id
                      WHERE g.genome_accession = ? ORDER BY gs.gene_set_name", $db, [$assembly]) ?: [];
}

function moop_assembly_stats_or_fallback(string $assembly_dir, ?array $summary = null): ?array {
    $from_file = moop_load_assembly_stats($assembly_dir);
    if ($from_file) return $from_file;
    if ($summary === null) {
        $organism_dir = dirname($assembly_dir);
        $file = moop_gene_set_summary_file(basename($organism_dir));
        if ($file !== '' && is_file($file) && !moop_gene_set_summary_is_stale($organism_dir, $file)) {
            $summary = json_decode((string)@file_get_contents($file), true);
        }
    }
    return $summary['assemblies'][basename($assembly_dir)] ?? null;
}

functions.comment:
/**
* An assembly's statistics, from the ONE place both pages ask: the pipeline's assembly_stats.json
* when there is one (contig N50, gaps, GC too); otherwise the scaffold figures the background run
* derived from the .fai into gene_set_summary.json. Never computed here -- a .fai can be 70 MB.
*
* @param array|null $summary  the organism's summary if the caller already has it; loaded if null
*/
function moop_assembly_stats_or_fallback(string $assembly_dir, ?array $summary = null): ?array {
$from_file = moop_load_assembly_stats($assembly_dir);
if ($from_file) return $from_file;
if ($summary === null) {
$organism_dir = dirname($assembly_dir);
$file = moop_gene_set_summary_file(basename($organism_dir));
if ($file !== '' && is_file($file) && !moop_gene_set_summary_is_stale($organism_dir, $file)) {
$summary = json_decode((string)@file_get_contents($file), true);
}
}
return $summary['assemblies'][basename($assembly_dir)] ?? null;
}

/** A share that may be tiny: "<0.01%" below that, two decimals below 0.1% ("0.05%"), else one. */

functions.code:
function moop_format_small_pct(float $pct): string {
    if ($pct > 0 && $pct < 0.01) return '<0.01%';
    return number_format($pct, ($pct > 0 && $pct < 0.1) ? 2 : 1) . '%';
}

functions.comment:
/**
* An assembly's statistics, from the ONE place both pages ask: the pipeline's assembly_stats.json
* when there is one (contig N50, gaps, GC too); otherwise the scaffold figures the background run
* derived from the .fai into gene_set_summary.json. Never computed here -- a .fai can be 70 MB.
*
* @param array|null $summary  the organism's summary if the caller already has it; loaded if null
*/
function moop_assembly_stats_or_fallback(string $assembly_dir, ?array $summary = null): ?array {
$from_file = moop_load_assembly_stats($assembly_dir);
if ($from_file) return $from_file;
if ($summary === null) {
$organism_dir = dirname($assembly_dir);
$file = moop_gene_set_summary_file(basename($organism_dir));
if ($file !== '' && is_file($file) && !moop_gene_set_summary_is_stale($organism_dir, $file)) {
$summary = json_decode((string)@file_get_contents($file), true);
}
}
return $summary['assemblies'][basename($assembly_dir)] ?? null;
}

/** A share that may be tiny: "<0.01%" below that, two decimals below 0.1% ("0.05%"), else one. */
function moop_format_small_pct(float $pct): string {
if ($pct > 0 && $pct < 0.01) return '<0.01%';
return number_format($pct, ($pct > 0 && $pct < 0.1) ? 2 : 1) . '%';
}

/** 1234567 -> "1.2 Mb"; for N50 and assembly size. */

functions.code:
function moop_format_bp(int $bp): string {
    if ($bp >= 1e9) return number_format($bp / 1e9, 2) . ' Gb';
    if ($bp >= 1e6) return number_format($bp / 1e6, 1) . ' Mb';
    if ($bp >= 1e3) return number_format($bp / 1e3, 1) . ' kb';
    return number_format($bp) . ' bp';
}

function moop_genome_declares_blast_only(string $assembly_dir): bool {
    $file = rtrim($assembly_dir, '/') . '/genome.json';
    if (!is_file($file)) return false;
    $json = json_decode((string)@file_get_contents($file), true);
    return is_array($json) && ($json['blast_only'] ?? false) === true;
}

function moop_feature_loci(string $gene_set_dir, array $ids): array {
    $want = array_flip($ids);
    $loci = [];
    if (!$want) return $loci;

    // Transcripts first: their own span, never their gene's.
    $fh = @fopen("$gene_set_dir/exon_coords.tsv", 'r');
    if ($fh) {
        while (($line = fgets($fh)) !== false) {
            $tab = strpos($line, "\t");
            if ($tab === false || !isset($want[substr($line, 0, $tab)])) continue;
            $p = explode("\t", rtrim($line, "\r\n"));
            if (count($p) < 4) continue;
            [$s, $e] = array_map('intval', explode(',', $p[3]) + [1 => 0]);
            if ($s < 1 || $e < $s) continue;
            $loci[$p[0]] = ['chr' => $p[1], 'start' => $s, 'end' => $e, 'strand' => $p[2], 'kind' => 'transcript'];
        }
        fclose($fh);
    }

    // Genes: column 2 of any row holds the gene, and every row carries the gene's span.
    $genes = array_keys(array_diff_key($want, $loci));
    foreach (moop_feature_coords_by_gene($gene_set_dir, $genes) as $gene => $locus) {
        $loci[$gene] = $locus + ['kind' => 'gene'];
    }
    return $loci;
}

function moop_genomic_region(array $locus, string $part, int $bp = 0, ?int $from = null, ?int $to = null): ?array {
    $minus = $locus['strand'] === '-';
    [$s, $e] = [$locus['start'], $locus['end']];

    if ($part === 'body') {
        if ($from !== null) {
            $len = $e - $s + 1;
            if ($from > $len) return null;
            $to = min($to ?? $len, $len);
            [$s, $e] = $minus ? [$locus['end'] - $to + 1, $locus['end'] - $from + 1]
                              : [$locus['start'] + $from - 1, $locus['start'] + $to - 1];
        }
    } elseif ($part === 'upstream' || $part === 'downstream') {
        if ($bp < 1) return null;
        $before = ($part === 'upstream') !== $minus;   // lower coordinates?
        [$s, $e] = $before ? [max(1, $locus['start'] - $bp), $locus['start'] - 1]
                           : [$locus['end'] + 1, $locus['end'] + $bp];
    } else {
        return null;
    }
    if ($e < $s) return null;
    return ['chr' => $locus['chr'], 'start' => $s, 'end' => $e, 'strand' => $minus ? '-' : '+'];
}

function moop_genome_open(string $assembly_dir, array $chrs): ?array {
    $fasta = "$assembly_dir/" . genome_fasta_filename();
    if (!is_file($fasta) || !is_file("$fasta.fai")) return null;
    $chrs = array_values(array_unique(array_filter(array_map('strval', $chrs), 'strlen')));
    $fh   = fopen($fasta, 'rb');
    if ($fh === false) return null;
    return ['fh' => $fh, 'fai' => $chrs ? moop_fai_lookup("$fasta.fai", $chrs) : []];
}

function moop_genome_close(?array $genome): void {
    if ($genome && is_resource($genome['fh'])) fclose($genome['fh']);
}

functions.comment:
/**
* Open an assembly's genome for a batch of cuts: the .fai entries for these sequence names,
* looked up in ONE pass, and the FASTA held open. Cutting each region through
* extractFastaRegion() re-read the .fai from the top every time -- 5.7 ms a region on
* Carollia's 1.9 M-line index, once per gene and once per EXON in the Data Exporter.
* (samtools faidx loads its index once too; this is the same idea.)
*
* @param list<string> $chrs every sequence name the batch will cut from
* @return array{fh: resource, fai: array<string, array{len: int, off: int, lb: int, lw: int}>}|null
*         null when the genome or its .fai is missing
*/
function moop_genome_open(string $assembly_dir, array $chrs): ?array {
$fasta = "$assembly_dir/" . genome_fasta_filename();
if (!is_file($fasta) || !is_file("$fasta.fai")) return null;
$chrs = array_values(array_unique(array_filter(array_map('strval', $chrs), 'strlen')));
$fh   = fopen($fasta, 'rb');
if ($fh === false) return null;
return ['fh' => $fh, 'fai' => $chrs ? moop_fai_lookup("$fasta.fai", $chrs) : []];
}

function moop_genome_close(?array $genome): void {
if ($genome && is_resource($genome['fh'])) fclose($genome['fh']);
}

/** Of these names, the ones the opened genome does not contain (see moop_genome_missing_seqnames()). */

functions.code:
function moop_genome_missing(array $genome, array $chrs): array {
    return array_values(array_unique(array_filter(array_map('strval', $chrs),
        fn($c) => $c !== '' && !isset($genome['fai'][$c]))));
}

function moop_genomic_sequence(array $genome, array $region): ?array {
    $entry = $genome['fai'][$region['chr']] ?? null;
    if (!$entry) return null;
    $seq = moop_fasta_read_at($genome['fh'], $entry, $region['start'], $region['end']);
    if ($seq === null || $seq === '') return null;
    $region['end'] = $region['start'] + strlen($seq) - 1;
    return ['seq' => $region['strand'] === '-' ? reverseComplement($seq) : $seq, 'region' => $region];
}

function moop_genome_missing_seqnames(string $assembly_dir, array $chrs): array {
    $chrs = array_values(array_unique(array_filter(array_map('strval', $chrs), 'strlen')));
    if (!$chrs) return [];
    $found = moop_fai_lookup("$assembly_dir/" . genome_fasta_filename() . '.fai', $chrs);
    return array_values(array_filter($chrs, fn($c) => !isset($found[$c])));
}

function moop_gene_set_seqname_gap(string $gene_set_dir, string $assembly_dir): ?array {
    $chrs = moop_feature_coords_seqnames($gene_set_dir);
    if ($chrs === null || !is_file("$assembly_dir/" . genome_fasta_filename() . '.fai')) return null;
    $missing = moop_genome_missing_seqnames($assembly_dir, $chrs);
    return ['missing' => count($missing), 'total' => count($chrs), 'examples' => array_slice($missing, 0, 3)];
}

function moop_genomic_skip_notes(array $skips): array {
    $eg    = fn(array $ids) => ' (e.g. ' . implode(', ', array_slice($ids, 0, 3)) . (count($ids) > 3 ? ', …' : '') . ')';
    $n     = fn(int $k, string $one) => number_format($k) . ' ' . $one . ($k === 1 ? '' : 's');
    $notes = [];
    if (!empty($skips['missing_chr'])) {
        $ids   = array_merge(...array_values($skips['missing_chr']));
        $names = array_keys($skips['missing_chr']);
        $one   = count($names) === 1;
        $notes[] = $n(count($ids), 'feature') . ' skipped: ' . ($one ? 'sequence' : 'sequences')
                 . " '" . implode("', '", array_slice($names, 0, 3)) . "'" . (count($names) > 3 ? ' and ' . (count($names) - 3) . ' more' : '')
                 . ($one ? ' is' : ' are') . " not in this assembly's genome -- the gene set and the genome name the chromosomes differently"
                 . $eg($ids) . '.';
    }
    if (!empty($skips['no_coords'])) {
        $notes[] = $n(count($skips['no_coords']), 'feature') . ' skipped: no genome coordinates in this gene set'
                 . $eg($skips['no_coords']) . '.';
    }
    if (!empty($skips['no_exons'])) {
        $notes[] = $n(count($skips['no_exons']), 'feature') . ' skipped: no exons found for them in the gene set\'s GFF'
                 . $eg($skips['no_exons']) . '.';
    }
    return $notes;
}

function moop_genomic_fasta_record(string $id, string $part, int $bp, array $region, string $seq, ?int $from = null, ?int $to = null, string $context = ''): string {
    $label = $part === 'body' ? 'genomic' : "{$part}_{$bp}bp";
    $name  = $id . ($from !== null ? ":$from-$to" : '');
    $ctx   = $context !== '' ? " $context" : '';
    return ">$name$ctx $label {$region['chr']}:{$region['start']}-{$region['end']}({$region['strand']})\n"
         . rtrim(chunk_split($seq, MOOP_FASTA_LINE_WIDTH, "\n")) . "\n";
}

function moop_genomic_anchors(array $ids, string $db_path, array $gene_set_ids = []): array {
    $walk = [];
    // In batches: SQLite caps the parameters one query may bind (32,766 here), and a whole
    // gene set's proteins (61k for Myotis myotis) is over it -- the query failed outright.
    foreach (array_chunk(array_values(array_unique($ids)), 5000) as $batch) {
        foreach (moop_hierarchy_walk($batch, $db_path, 'up', $gene_set_ids) as $row) {
            $walk[(string)$row['seed_name']][(int)$row['depth']] = $row;
        }
    }
    $out = [];
    foreach ($walk as $id => $chain) {
        ksort($chain);
        $out[$id] = moop_anchor_from_chain((string)$id, array_values($chain));
    }
    $ids_named = moop_names_that_are_ids(array_column($out, 'gene_name'), $db_path, $gene_set_ids);
    foreach ($out as &$a) if ($a['gene_name'] !== null && isset($ids_named[$a['gene_name']])) $a['gene_name'] = null;
    unset($a);
    return $out;
}

function moop_names_that_are_ids(array $names, string $db_path, array $gene_set_ids = []): array {
    $names = array_values(array_unique(array_filter($names, fn($n) => $n !== null && $n !== '')));
    $hit   = [];
    if (!$names || !is_file($db_path)) return $hit;
    $gs = $gene_set_ids ? ' AND gene_set_id IN (' . implode(',', array_fill(0, count($gene_set_ids), '?')) . ')' : '';
    foreach (array_chunk($names, 5000) as $chunk) {
        $sql = 'SELECT DISTINCT feature_uniquename FROM feature WHERE feature_uniquename IN ('
             . implode(',', array_fill(0, count($chunk), '?')) . ')' . $gs;
        foreach (fetchData($sql, $db_path, array_merge($chunk, array_values($gene_set_ids))) as $row) $hit[$row['feature_uniquename']] = true;
    }
    return $hit;
}

function moop_anchor_from_chain(string $id, array $chain): array {
    static $sub = ['cds' => 1, 'protein' => 1, 'polypeptide' => 1, 'exon' => 1];
    $top   = end($chain);
    $gene  = (string)$top['feature_uniquename'];
    $locus = $gene;
    foreach ($chain as $row) {
        if (!isset($sub[strtolower((string)$row['feature_type'])])) { $locus = (string)$row['feature_uniquename']; break; }
    }
    // A RefSeq gene's uniquename is a bare GeneID (118665088); its name (PIGG) is what a
    // reader recognises. Only a real name: one word, and not just another of its IDs.
    $name = trim((string)($top['feature_name'] ?? ''));
    if ($name === '' || preg_match('/\s/', $name) || $name === $gene || $name === $locus || $name === $id) $name = null;
    return ['locus' => $locus, 'gene' => $gene, 'gene_name' => $name, 'transcript' => $locus !== $gene ? $locus : null];
}

function moop_anchors_from_family(array $ids, array $family): array {
    $by_name = [];
    foreach ($family as $fid => $row) $by_name[(string)$row['feature_uniquename']] = $fid;
    $out = [];
    foreach ($ids as $id) {
        $fid = $by_name[(string)$id] ?? null;
        if ($fid === null) continue;
        $chain = [];
        $seen  = [];
        while ($fid !== null && isset($family[$fid]) && !isset($seen[$fid]) && count($chain) <= MOOP_HIERARCHY_MAX_DEPTH) {
            $seen[$fid] = true;   // cycle guard, as the SQL walks have
            $chain[] = $family[$fid];
            $fid = $family[$fid]['parent_feature_id'] ?? null;
        }
        $a = moop_anchor_from_chain((string)$id, $chain);
        // A "name" that is a family member's ID (NV2 names genes after a transcript) is not one
        if ($a['gene_name'] !== null && isset($by_name[$a['gene_name']])) $a['gene_name'] = null;
        $out[(string)$id] = $a;
    }
    return $out;
}

function moop_header_context(string $id, ?array $anchor): string {
    if (!$anchor) return '';
    if ($anchor['gene'] === $id) return ($anchor['gene_name'] ?? null) !== null ? 'gene_name=' . $anchor['gene_name'] : '';
    return 'gene=' . $anchor['gene']
         . (($anchor['gene_name'] ?? null) !== null ? ' gene_name=' . $anchor['gene_name'] : '')
         . ($anchor['transcript'] !== null && $anchor['transcript'] !== $id ? ' transcript=' . $anchor['transcript'] : '');
}

function moop_fasta_with_context(string $fasta, array $anchors): string {
    if (!$anchors || $fasta === '') return $fasta;
    // Jump from header to header ("\n>"), never looking at sequence lines: a regex anchored at
    // every line start spent ~0.5 s per 240 MB on lines it then left alone.
    $parts = [];
    $done  = 0;
    $at    = $fasta[0] === '>' ? 0 : strpos($fasta, "\n>");
    if ($at !== false && $at > 0) $at++;
    while ($at !== false) {
        $len     = strcspn($fasta, " \t\n\r\f\v", $at + 1);   // the ID: the header's first word
        $word    = substr($fasta, $at + 1, $len);
        $id      = strpos($word, '-') !== false ? preg_replace('/:\d+-\d+$/', '', $word) : $word;
        $context = moop_header_context($id, $anchors[$id] ?? null);
        if ($context !== '') {
            $end     = $at + 1 + $len;
            $parts[] = substr($fasta, $done, $end - $done) . ' ' . $context;
            $done    = $end;
        }
        $next = strpos($fasta, "\n>", $at + 1);
        $at   = $next === false ? false : $next + 1;
    }
    if (!$parts) return $fasta;
    $parts[] = substr($fasta, $done);
    return implode('', $parts);
}

function moop_genome_kind(string $assembly_dir): string {
    static $memo = [];
    if (isset($memo[$assembly_dir])) return $memo[$assembly_dir];
    if (!is_file("$assembly_dir/" . genome_fasta_filename() . '.fai')) return $memo[$assembly_dir] = 'none';

    $json = @json_decode((string)@file_get_contents("$assembly_dir/genome.json"), true);
    $said = is_array($json) ? strtolower(trim((string)($json['genome_kind'] ?? ''))) : '';
    if (in_array($said, ['genome', 'transcripts'], true)) return $memo[$assembly_dir] = $said;

    $seen = $own = 0;
    foreach (glob("$assembly_dir/*/feature_coords.tsv") ?: [] as $file) {
        $fh = @fopen($file, 'r');
        if (!$fh) continue;
        while ($seen < 200 && ($line = fgets($fh)) !== false) {
            $p = explode("\t", rtrim($line, "\r\n"));
            if (count($p) < 5 || !ctype_digit($p[3])) continue;
            [$gene, $chr, $start] = [$p[1], $p[2], (int)$p[3]];
            $seen++;
            if ($start <= 10 && ($chr === $gene || strpos($chr, $gene) === 0 || strpos($gene, $chr) === 0)) $own++;
        }
        fclose($fh);
        if ($seen >= 200) break;
    }
    return $memo[$assembly_dir] = ($seen >= 20 && $own >= 0.9 * $seen) ? 'transcripts' : 'genome';
}

function moop_site_is_transcriptomes(): bool {
    static $memo = null;
    if ($memo !== null) return $memo;
    $root = rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/');
    $any = false;
    foreach (glob("$root/*/*/" . genome_fasta_filename() . '.fai') ?: [] as $fai) {
        $kind = moop_genome_kind(dirname($fai));
        if ($kind === 'genome') return $memo = false;
        if ($kind === 'transcripts') $any = true;
    }
    return $memo = $any;
}

function moop_retrieve_genomic(array $requests, string $gene_set_dir, string $assembly_dir, int $upstream = 0, int $downstream = 0, array $anchors = [], ?callable $emit = null, bool $dry_run = false): array {
    $out = ['fasta' => '', 'notes' => []];
    if (!$requests) return $out;
    if (!is_file("$gene_set_dir/feature_coords.tsv") || !is_file("$assembly_dir/" . genome_fasta_filename() . '.fai')) {
        $out['notes'][] = 'Genomic sequence is not available for this gene set: it has no genome coordinates.';
        return $out;
    }

    $anchor_of = fn(string $id) => $anchors[$id]['locus'] ?? $id;
    $loci    = moop_feature_loci($gene_set_dir, array_values(array_unique(array_map($anchor_of, array_column($requests, 'id')))));
    $genome  = moop_genome_open($assembly_dir, array_column($loci, 'chr'));
    if (!$genome) {
        $out['notes'][] = 'Genomic sequence is not available: this assembly has no readable genome.';
        return $out;
    }
    $missing  = array_flip(moop_genome_missing($genome, array_column($loci, 'chr')));
    $skips    = [];
    $done     = [];
    $toobig   = [];
    $no_range = [];
    foreach ($requests as $r) {
        $id     = $r['id'];
        $anchor = $anchors[$id] ?? null;
        $locus  = $loci[$anchor_of($id)] ?? null;
        if (!$locus) {
            // Not in the database: already shown red in the ID box, nothing to add. In it but
            // not on the genome: say so -- this used to give nothing, silently.
            if (($anchor || !$anchors) && !in_array($id, $skips['no_coords'] ?? [], true)) $skips['no_coords'][] = $id;
            continue;
        }
        if (isset($missing[$locus['chr']])) {
            if (!in_array($id, $skips['missing_chr'][$locus['chr']] ?? [], true)) $skips['missing_chr'][$locus['chr']][] = $id;
            continue;
        }
        $context = moop_header_context($id, $anchor);
        $parts = [];
        if ($r['start'] !== null && $anchor_of($id) !== $id) {
            $no_range[] = $id;
        } else {
            $parts[] = ['body', 0, $r['start'], $r['end']];
        }
        // Flanks belong to the feature, not to a range of it: added once per ID.
        if (!isset($done[$id])) {
            if ($upstream > 0)   $parts[] = ['upstream', $upstream, null, null];
            if ($downstream > 0) $parts[] = ['downstream', $downstream, null, null];
            $done[$id] = true;
        }
        foreach ($parts as [$part, $bp, $from, $to]) {
            $region = moop_genomic_region($locus, $part, $bp, $from, $to);
            if (!$region) continue;
            if ($region['end'] - $region['start'] + 1 > MOOP_MAX_REGION_BP) { $toobig[] = $id; continue; }
            if ($dry_run) continue;
            $got = moop_genomic_sequence($genome, $region);
            if (!$got) continue;
            $shown_to = $from !== null ? $from + strlen($got['seq']) - 1 : null;
            $record = moop_genomic_fasta_record($id, $part, $bp, $got['region'], $got['seq'], $from, $shown_to, $context);
            if ($emit) $emit($record); else $out['fasta'] .= $record;
        }
    }
    moop_genome_close($genome);
    array_push($out['notes'], ...moop_genomic_skip_notes($skips));
    // At most 10 IDs named, like the skip notes' examples: a long list (all 20,154 Myotis genes)
    // made one of these 1,800 characters naming 154 IDs.
    $named = function (array $ids): string {
        $ids = array_values(array_unique($ids));
        return implode(', ', array_slice($ids, 0, 10)) . (count($ids) > 10 ? ' and ' . number_format(count($ids) - 10) . ' more' : '');
    };
    if ($no_range) {
        $out['notes'][] = 'A range on a protein or CDS ID counts amino acids or coding bases, not genome positions, so no genomic region was cut for: '
                        . $named($no_range) . '. Its flanks are given; for a genomic range, use the transcript ID.';
    }
    if ($toobig) {
        $out['notes'][] = 'Genomic sequence longer than ' . number_format(MOOP_MAX_REGION_BP) . ' bp is left out: '
                        . $named($toobig) . '. The Data Exporter has no such limit.';
    }
    return $out;
}

function moop_geoip_dir(): string {
    return moop_cache_root() . '/geoip';
}

function moop_geoip_db_file(): string {
    return moop_geoip_dir() . '/dbip-region.sqlite';
}

functions.comment:
/**
* Where an address is: country and state/region, from a LOCAL copy of DB-IP's free
* "IP to City Lite" database (CC BY 4.0 -- pages that show its results must say
* "IP geolocation by DB-IP" with a link; moop_geoip_attribution()).
*
* Why local: looking an address up with an online service would send every visitor's address to
* a third party. Here nothing leaves the server; the database is downloaded once a month
* (housekeeping task geoip_update, or scripts/update_geoip.php by hand).
*
* Only country + state/region are kept (the city column is dropped and neighbouring ranges in
* the same region merged), which is all the System Monitor shows and keeps the file small.
* Accuracy: country is reliable; region is usually right for home and university connections,
* often wrong for mobile networks and VPNs, and meaningless for cloud providers (a crawler in an
* Azure data centre shows the data centre's region).
*
* File: {cache}/geoip/dbip-region.sqlite
*   v4(start INTEGER PRIMARY KEY, end INTEGER, cc TEXT, region TEXT)
*   v6(start TEXT PRIMARY KEY, end TEXT, cc TEXT, region TEXT)  -- 32 lowercase hex digits
*   meta(k TEXT PRIMARY KEY, v TEXT)                              -- source, built_at
*/

require_once __DIR__ . '/cache_paths.php';

const MOOP_GEOIP_URL      = 'https://download.db-ip.com/free/dbip-city-lite-%s.csv.gz';
const MOOP_GEOIP_MAX_AGE  = 35 * 86400;   // DB-IP publishes monthly

function moop_geoip_dir(): string {
return moop_cache_root() . '/geoip';
}

function moop_geoip_db_file(): string {
return moop_geoip_dir() . '/dbip-region.sqlite';
}

/** HTML for the required attribution line. */

functions.code:
function moop_geoip_attribution(): string {
    return '<a href="https://db-ip.com" target="_blank" rel="noopener">IP geolocation by DB-IP</a>';
}

