function moop_geoip_next(string $table, $k) {
    if ($table === 'v4') return $k + 1;
    $bin = hex2bin($k);
    for ($i = 15; $i >= 0; $i--) {
        $c = ord($bin[$i]);
        if ($c < 255) { $bin[$i] = chr($c + 1); break; }
        $bin[$i] = "\0";
    }
    return bin2hex($bin);
}

