function moop_gt_index_tree(array $tree): array {
    $ranks     = [];   // rank name => [organism => true]
    $depth     = [];   // rank name => depth from root
    $organisms = [];   // organism => true

    $walk = function (array $node, array $path) use (&$walk, &$ranks, &$depth, &$organisms) {
        $name = $node['name'] ?? null;

        // A node carrying an 'organism' key is a leaf for our purposes: it is a species,
        // not a rank you could file other organisms under.
        if (!empty($node['organism'])) {
            $org = $node['organism'];
            $organisms[$org] = true;
            foreach ($path as $ancestor) {
                $ranks[$ancestor][$org] = true;
            }
            return;
        }

        if ($name !== null && $name !== '') {
            if (!isset($depth[$name])) {
                $depth[$name] = count($path);
            }
            if (!isset($ranks[$name])) {
                $ranks[$name] = [];
            }
            $path[] = $name;
        }

        foreach ($node['children'] ?? [] as $child) {
            if (is_array($child)) {
                $walk($child, $path);
            }
        }
    };

    $walk($tree, []);

    return ['ranks' => $ranks, 'depth' => $depth, 'organisms' => $organisms];
}

function moop_gt_cover_rank(array $members, array $index, array $known_orgs): ?array {
    $n = count($members);
    if ($n < MOOP_GT_COVER_MIN_MEMBERS) {
        return null;
    }

    $best = null;
    foreach ($index['ranks'] as $rank => $rank_orgs) {
        // Only organisms we actually hold count toward the comparison; a rank listing
        // organisms absent from the groups file should not be penalised for them.
        $held = array_intersect_key($rank_orgs, $known_orgs);
        if (count($held) < $n) {
            continue;                       // too small to contain every member
        }
        foreach ($members as $org => $_) {
            if (!isset($held[$org])) {
                continue 2;                 // does not contain them all
            }
        }
        $size  = count($held);
        $depth = $index['depth'][$rank] ?? 0;
        // Smallest containing rank wins; ties go to the DEEPEST (most specific) node.
        if ($best === null || $size < $best['size'] || ($size === $best['size'] && $depth > $best['depth'])) {
            $best = ['rank' => $rank, 'size' => $size, 'depth' => $depth, 'held' => $held];
        }
    }

    if ($best === null) {
        return null;                        // polyphyletic: no single rank contains them
    }

    $extras = array_keys(array_diff_key($best['held'], $members));
    $allowed = max(MOOP_GT_COVER_MIN_EXTRAS, (int) ceil(MOOP_GT_COVER_EXTRA_RATIO * $n));
    if (count($extras) > $allowed) {
        return null;                        // rank is far bigger than the group
    }

    sort($extras);
    return ['rank' => $best['rank'], 'extras' => $extras];
}

function moop_gt_compute(array $group_data, array $tree, array $exceptions = []): array {
    $index = moop_gt_index_tree($tree);

    // group => [organism => true]; organism => list of rows
    $group_members = [];
    $known_orgs    = [];
    $rows          = [];
    foreach ($group_data as $entry) {
        $org = $entry['organism'] ?? null;
        if ($org === null || $org === '') {
            continue;
        }
        $known_orgs[$org] = true;
        $groups = $entry['groups'] ?? [];
        if (!is_array($groups)) {
            $groups = [];
        }
        $rows[] = [
            'organism' => $org,
            'assembly' => $entry['assembly'] ?? '',
            'gene_set' => $entry['gene_set'] ?? '',
            'groups'   => array_flip($groups),
        ];
        foreach ($groups as $g) {
            $group_members[$g][$org] = true;
        }
    }

    // Which rank, if any, each curated group corresponds to.
    $group_rank = [];
    foreach ($group_members as $group => $members) {
        // Organisms absent from the taxonomy tree cannot inform a cover; they are already
        // reported separately as the 'not_in_tree' health alert.
        $in_tree = array_intersect_key($members, $index['organisms']);

        if (isset($index['ranks'][$group])) {
            $held = array_intersect_key($index['ranks'][$group], $known_orgs);
            $group_rank[$group] = [
                'rank'      => $group,
                'basis'     => 'name',
                'members'   => count($members),
                'rank_size' => count($held),
                'rank_orgs' => $held,
            ];
            continue;
        }

        if (empty($in_tree)) {
            continue;
        }
        $cover = moop_gt_cover_rank($in_tree, $index, $known_orgs);
        if ($cover === null) {
            continue;
        }
        $held = array_intersect_key($index['ranks'][$cover['rank']], $known_orgs);
        $group_rank[$group] = [
            'rank'      => $cover['rank'],
            'basis'     => 'cover',
            'members'   => count($members),
            'rank_size' => count($held),
            'rank_orgs' => $held,
        ];
    }

    // Index dismissals by organism + group (the editorial unit: "this organism does not
    // belong in that group", independent of how many gene sets it has).
    $dismissed_key = [];
    foreach ($exceptions as $ex) {
        $k = ($ex['organism'] ?? '') . "\0" . ($ex['group'] ?? '');
        $dismissed_key[$k] = $ex;
    }

    $suggestions = [];
    $dismissed   = [];
    foreach ($rows as $row) {
        foreach ($group_rank as $group => $info) {
            if (isset($row['groups'][$group])) {
                continue;                                   // already a member
            }
            if (!isset($info['rank_orgs'][$row['organism']])) {
                continue;                                   // not under that rank
            }
            $item = [
                'organism'   => $row['organism'],
                'assembly'   => $row['assembly'],
                'gene_set'   => $row['gene_set'],
                'group'      => $group,
                'rank'       => $info['rank'],
                'basis'      => $info['basis'],
                'group_size' => $info['members'],
                'rank_size'  => $info['rank_size'],
            ];
            $k = $row['organism'] . "\0" . $group;
            if (isset($dismissed_key[$k])) {
                $item['reason']       = $dismissed_key[$k]['reason'] ?? '';
                $item['dismissed_by'] = $dismissed_key[$k]['by'] ?? '';
                $item['dismissed_at'] = $dismissed_key[$k]['at'] ?? '';
                $dismissed[] = $item;
            } else {
                $suggestions[] = $item;
            }
        }
    }

    usort($suggestions, function ($a, $b) {
        return [$a['group'], $a['organism'], $a['gene_set']] <=> [$b['group'], $b['organism'], $b['gene_set']];
    });

    $checked = [];
    foreach ($group_rank as $group => $info) {
        unset($info['rank_orgs']);
        $checked[$group] = $info;
    }

    return [
        'suggestions'    => $suggestions,
        'dismissed'      => $dismissed,
        'groups_checked' => $checked,
        'row_count'      => count($rows),
    ];
}

function moop_gt_exceptions_file(): string {
    return ConfigManager::getInstance()->getPath('metadata_path') . '/group_taxon_exceptions.json';
}

function moop_gt_load_exceptions(): array {
    $data = loadJsonFile(moop_gt_exceptions_file(), []);
    return is_array($data) ? $data : [];
}

function moop_gt_set_exception(string $organism, string $group, string $reason, string $by, bool $remove = false): array {
    $file = moop_gt_exceptions_file();
    $list = moop_gt_load_exceptions();

    $kept = [];
    foreach ($list as $ex) {
        if (($ex['organism'] ?? '') === $organism && ($ex['group'] ?? '') === $group) {
            continue;                        // drop any existing entry; re-added below
        }
        $kept[] = $ex;
    }

    if (!$remove) {
        $kept[] = [
            'organism' => $organism,
            'group'    => $group,
            'reason'   => $reason,
            'by'       => $by,
            'at'       => date('c'),
        ];
    }

    usort($kept, function ($a, $b) {
        return [$a['organism'] ?? '', $a['group'] ?? ''] <=> [$b['organism'] ?? '', $b['group'] ?? ''];
    });

    // A write the web server cannot do, unchecked and reported as success, is THE
    // recurring failure shape in this codebase. Check the return value.
    $bytes = saveJsonFile($file, $kept);
    if ($bytes === false) {
        $dir = dirname($file);
        $hint = !is_dir($dir)
            ? "metadata directory $dir does not exist"
            : (file_exists($file)
                ? "cannot write $file — check owner/mode and the SELinux label (httpd_sys_rw_content_t)"
                : "cannot create files in $dir — check owner/mode and the SELinux label");
        return ['ok' => false, 'error' => $hint];
    }

    return ['ok' => true, 'error' => ''];
}

function moop_gt_suggestions(): array {
    $metadata_path = ConfigManager::getInstance()->getPath('metadata_path');
    $group_data    = loadJsonFile("$metadata_path/organism_assembly_groups.json", []);
    $tree_config   = loadJsonFile("$metadata_path/taxonomy_tree_config.json", []);
    $tree          = $tree_config['tree'] ?? [];

    if (!is_array($group_data) || empty($tree)) {
        return ['suggestions' => [], 'dismissed' => [], 'groups_checked' => [], 'row_count' => 0];
    }

    return moop_gt_compute($group_data, $tree, moop_gt_load_exceptions());
}

function field_help(string $text, string $title = '', bool $lines = false): string {
    $text = trim($text);
    if ($text === '') {
        return '';
    }
    // In the visitor's language (t_plain(), includes/config_init.php): translated here, once, so
    // no (i) on any page has to be wrapped. English on a one-language site, unchanged.
    $text  = t_plain($text);
    $title = $title !== '' ? t_plain($title) : '';

    // aria-label describes the control's purpose; the popover carries the content.
    // Without this a screen reader announces an icon button with no accessible name.
    $aria = $title !== '' ? t_plain('Help: %s', $title) : t_plain('More information');

    $html  = '<button type="button" class="field-help"';
    $html .= ' data-bs-toggle="popover" data-bs-trigger="manual" data-bs-placement="top"';
    // $lines: keep the text's line breaks in the popover (css/moop.css .field-help-lines), for a
    // short list such as a method's rules. Off by default, so every existing (i) is unchanged.
    if ($lines) $html .= ' data-bs-custom-class="field-help-lines"';
    if ($title !== '') {
        $html .= ' data-bs-title="' . htmlspecialchars($title, ENT_QUOTES) . '"';
    }
    $html .= ' data-bs-content="' . htmlspecialchars($text, ENT_QUOTES) . '"';
    // No-JS fallback; removed by field-help.js on successful init.
    $html .= ' title="' . htmlspecialchars($text, ENT_QUOTES) . '"';
    $html .= ' aria-label="' . htmlspecialchars($aria, ENT_QUOTES) . '">';
    $html .= '<i class="fa fa-info-circle" aria-hidden="true"></i>';
    $html .= '</button>';

    return $html;
}

function help_modal_trigger(string $modal_id, string $label = '', string $aria = 'Help'): string {
    $label = $label !== '' ? t_plain($label) : '';
    $aria  = t_plain($aria);
    $html  = '<button type="button" class="field-help"';
    $html .= ' data-bs-toggle="modal" data-bs-target="#' . htmlspecialchars($modal_id, ENT_QUOTES) . '"';
    $html .= ' aria-label="' . htmlspecialchars($aria, ENT_QUOTES) . '">';
    $html .= '<i class="fa fa-info-circle" aria-hidden="true"></i>';
    if ($label !== '') {
        $html .= ' <span class="field-help-label">' . htmlspecialchars($label) . '</span>';
    }
    $html .= '</button>';
    return $html;
}

function help_modal(string $modal_id, string $title, array $sections, array $opts = []): string {
    $id    = htmlspecialchars($modal_id, ENT_QUOTES);
    $size  = $opts['size'] ?? 'modal-lg';
    $intro = trim((string)($opts['intro'] ?? ''));
    // Every piece of text in the visitor's language -- title, intro, headings, notes, labels and
    // plain card text (t_plain()). Card text with 'html' => true is left as written: it carries
    // markup, and a translation from the spreadsheet is not trusted to carry markup.
    $intro = $intro !== '' ? t_plain($intro) : '';
    $title = t_plain($title);
    // 'lead': a sentence about THIS page's data (a count), built by the caller with t_plain() and
    // sprintf -- already in the visitor's language, so it is escaped here but not translated again.
    $lead  = trim((string)($opts['lead'] ?? ''));

    $h  = '<div class="modal fade help-modal" id="' . $id . '" tabindex="-1"';
    $h .= ' aria-labelledby="' . $id . '-label" aria-hidden="true">';
    $h .= '<div class="modal-dialog ' . htmlspecialchars($size, ENT_QUOTES) . ' modal-dialog-scrollable">';
    $h .= '<div class="modal-content">';

    $h .= '<div class="modal-header py-2">';
    $h .= '<h5 class="modal-title fw-bold" id="' . $id . '-label">' . htmlspecialchars($title) . '</h5>';
    $h .= '<button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="' . htmlspecialchars(t_plain('Close'), ENT_QUOTES) . '"></button>';
    $h .= '</div>';

    $h .= '<div class="modal-body">';
    if ($lead !== '') {
        $h .= '<p class="fw-semibold mb-2">' . htmlspecialchars($lead) . '</p>';
    }
    if ($intro !== '') {
        $h .= '<p class="text-muted small mb-4">' . htmlspecialchars($intro) . '</p>';
    }

    foreach ($sections as $section) {
        $cards = $section['cards'] ?? [];
        if (!$cards) {
            continue;   // an empty section is a data gap, not a heading to render
        }

        // Each section is wrapped so its sticky heading is scoped to its OWN section.
        // Without the wrapper every heading shares .modal-body as its containing block,
        // so each one sticks for the entire remaining scroll: they pile up at the top
        // and cover the cards. Measured — three headings pinned at once, with card
        // titles half-hidden behind them.
        $h .= '<div class="help-modal-sec">';

        $heading = trim((string)($section['heading'] ?? ''));
        if ($heading !== '') $heading = t_plain($heading);
        if ($heading !== '') {
            $h .= '<h6 class="help-modal-section">' . htmlspecialchars($heading) . '</h6>';
        }

        // Optional one-line note under the heading — a caveat or scope statement that
        // applies to the whole section rather than any one card.
        $note = trim((string)($section['note'] ?? ''));
        if ($note !== '') $note = t_plain($note);
        if ($note !== '') {
            $h .= '<p class="text-muted small mb-3">' . htmlspecialchars($note) . '</p>';
        }

        $h .= '<div class="row g-3">';
        foreach ($cards as $card) {
            $label = trim((string)($card['label'] ?? ''));
            $text  = (string)($card['text'] ?? '');
            if ($label === '' && $text === '') {
                continue;
            }
            if ($label !== '') $label = t_plain($label);
            if ($text !== '' && empty($card['html'])) $text = t_plain($text);
            $body = !empty($card['html']) ? $text : htmlspecialchars($text);

            // An 'accent' card is set apart from its siblings — a worked example, a caveat —
            // with a slightly different wash and border. Quiet on purpose: it should read as
            // "this one is different in kind", not as an alert.
            $card_cls = 'card h-100 help-card' . (!empty($card['accent']) ? ' help-card-accent' : '');
            $h .= '<div class="col-md-6"><div class="' . $card_cls . '"><div class="card-body">';
            if ($label !== '') {
                // Optional step number, rendered as the SAME .step-badge circle the page
                // uses for its numbered steps (css/display.css). Passing 'num' makes a help
                // card a visual echo of the step it describes, so the reader maps the help
                // onto the workflow in front of them. 'num' and 'color' are mutually
                // exclusive — a card is either a step or a badge, not both.
                $num = isset($card['num']) ? trim((string)$card['num']) : '';
                if ($num !== '') {
                    $h .= '<h6 class="card-title mb-2 d-flex align-items-center gap-2">'
                        . '<span class="step-badge">' . htmlspecialchars($num) . '</span>'
                        . '<span>' . htmlspecialchars($label) . '</span></h6>';
                } elseif (!empty($card['color'])) {
                    // Badge form — for when the page itself shows this same badge, so the
                    // eye can match the help to the thing it just looked at.
                    $h .= '<h6 class="card-title mb-2"><span class="badge bg-'
                        . htmlspecialchars((string)$card['color'], ENT_QUOTES) . '">'
                        . htmlspecialchars($label) . '</span></h6>';
                } else {
                    $h .= '<h6 class="card-title mb-2">' . htmlspecialchars($label) . '</h6>';
                }
            }
            $h .= '<p class="card-text small text-muted mb-0">' . $body . '</p>';
            $h .= '</div></div></div>';
        }
        $h .= '</div>';   // .row
        $h .= '</div>';   // .help-modal-sec
    }

    $h .= '</div></div></div></div>';
    return $h;
}

function page_purpose(string $text, string $extra = '', bool $html = false, bool $visible = true): string {
    if (!$html) $text = t_plain($text);   // a sentence with markup is left as written (see help_modal())
    $body = $html ? $text : htmlspecialchars($text);

    // $visible = false: declared for extraction, but NOT shown.
    //
    // Some pages already carry a good visible line of their own — index.php's
    // "Browse genes, genomes, and annotations across N organisms and M assemblies" is the
    // site's tagline and shows live counts. Adding a second sentence beneath it says the
    // same thing twice, which is the redundancy this whole help effort is trying to remove.
    // The page still needs to DECLARE its purpose for the router, so the declaration stays
    // and the rendering stops.
    //
    // `hidden` rather than a visually-hidden class: this is a duplicate of what the page
    // already communicates visually, so announcing it to screen-reader users only would be
    // an inconsistency, not an improvement. `hidden` keeps it out of the accessibility tree
    // while leaving it in the DOM for scripts/extract_page_purposes.php.
    if (!$visible) {
        // Tags stripped: a gloss() term renders its own <span>, and the router's extractor
        // reads to the first </span> -- MOOPmart's purpose came out as "Export annotation".
        // Nothing hidden needs a tooltip.
        if ($html) $body = htmlspecialchars(strip_tags($text));
        return '<span hidden data-page-purpose>' . $body . '</span>';
    }

    $cls = trim('page-purpose text-muted small mb-0 ' . $extra);
    // $html is for a sentence carrying gloss() terms — MOOPmart's names two. Extraction
    // strips tags, so markup inside is harmless; it is opt-in rather than the default so an
    // ordinary sentence cannot inject markup by accident.
    return '<p class="' . htmlspecialchars($cls, ENT_QUOTES) . '" data-page-purpose>'
         . $body . '</p>';
}

function page_purpose_info(string $text): string {
    return page_purpose($text, '', false, false) . field_help($text, 'About this page');
}

function tool_page_blurb(string $tool_id, ?string $instead = null): string {
    $config = ConfigManager::getInstance();
    if (!$config->toolsMenuBlurbs()) return '';
    $line = $instead ?? (string) ($config->getAllTools(true)[$tool_id]['menu_blurb'] ?? '');
    if ($line === '') return '';
    return '<div class="tool-page-blurb">' . htmlspecialchars(t_plain($line)) . '</div>';
}

