function housekeeping_check_jbrowse_version() {
    $config    = ConfigManager::getInstance();
    $site_path = $config->getPath('site_path');
    $version_file = $site_path . '/jbrowse2/version.txt';

    // No JBrowse installed → nothing to report. Not an error; JBrowse is optional.
    if (!file_exists($version_file)) {
        $_SESSION['jbrowse_version'] = null;
        housekeeping_persist_status('jbrowse_version', null);
        return;
    }

    $current = trim((string)@file_get_contents($version_file));
    if ($current === '') return;

    // Reuse whatever the last successful check found; only the local version is refreshed.
    $prev   = $_SESSION['jbrowse_version'] ?? [];
    $latest = $prev['latest']     ?? null;
    $when   = $prev['checked_at'] ?? null;

    $due = !$when || (time() - (int)strtotime($when)) > (7 * 86400);

    if ($due && function_exists('curl_init')) {
        $ch = curl_init('https://api.github.com/repos/GMOD/jbrowse-components/releases/latest');
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_TIMEOUT        => 8,
            CURLOPT_CONNECTTIMEOUT => 4,
            CURLOPT_USERAGENT      => 'MOOP-version-check',
            CURLOPT_HTTPHEADER     => ['Accept: application/vnd.github+json'],
        ]);
        $body = curl_exec($ch);
        $code = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($code === 200 && $body) {
            $data = json_decode($body, true);
            $tag  = is_array($data) ? ($data['tag_name'] ?? '') : '';
            // Releases are tagged "v4.3.0"; version.txt holds "4.3.0".
            if (preg_match('/^v?(\d+\.\d+\.\d+)$/', trim($tag), $m)) {
                $latest = $m[1];
                $when   = date('c');
            }
        }
        // Any other outcome: keep the previous $latest/$when. Silence is deliberate.
    }

    $result = [
        'current'    => $current,
        'latest'     => $latest,
        'checked_at' => $when,
        // version_compare handles 4.1.15 > 4.1.3 correctly; a string compare does not.
        'outdated'   => ($latest !== null) && version_compare($current, $latest, '<'),
    ];

    $_SESSION['jbrowse_version'] = $result;
    housekeeping_persist_status('jbrowse_version', $result);
}

function moop_human_check_config(): ?array {
    $ts = ConfigManager::getInstance()->getArray('turnstile', []);
    if (empty($ts['enabled']) || empty($ts['site_key']) || empty($ts['secret_key'])) {
        return null;
    }
    return $ts;
}

function moop_human_verified(): bool {
    return (int) ($_SESSION['human_verified_until'] ?? 0) > time();
}

function moop_human_check_decision(bool $enabled, bool $logged_in, bool $verified, string $script,
                                   string $method, string $uri, array $headers): ?string {
    if (!$enabled || $logged_in || $verified) return null;
    // The challenge page itself, and the way in for people who have an account (login.php has
    // its own brute-force protection).
    if (in_array($script, ['verify-human.php', 'login.php', 'logout.php'], true)) return null;
    // The Not found page: nginx serves it (error_page 404) for EVERY unknown address -- typically a
    // first visit from an old link in a paper. A redirect cannot happen inside an error page, so
    // gating it showed those visitors a blank 404 (2026-11-23). It shows a sentence and a Home button.
    if ($script === 'not_found.php') return null;
    // The assistants' guide (llms.txt -> llms.php): the first thing an assistant reads, before it uses
    // api/v1/. Gated, Claude's own fetcher got a 403 and Claude in Chrome a challenge it will not solve
    // (both in the request log 2026-11-20), so the open API behind it was unreachable. Static text, cheap.
    if ($script === 'llms.php') return null;

    $path   = parse_url($uri, PHP_URL_PATH) ?? '';
    // The agent API (api/v1/, advertised in llms.txt) is for assistants fetching on one person's
    // behalf -- they cannot pass a browser challenge. Its expensive endpoints are in the nginx
    // 'heavy' rate-limit group (rate_limit_heavy); the cheap lookups get the api limit. Restricted
    // data still needs a login. Gating it here broke the API when Turnstile went on (2026-11-19).
    if (preg_match('#/api/v1/#', $path)) return null;
    $xhr    = strcasecmp($headers['X-Requested-With'] ?? '', 'XMLHttpRequest') === 0;
    $accept = $headers['Accept'] ?? '';
    $is_api = (bool) preg_match('#/(api|admin/api)/#', $path);
    $page   = $method === 'GET' && !$xhr && !$is_api && ($accept === '' || stripos($accept, 'text/html') !== false);
    return $page ? 'redirect' : 'deny';
}

function moop_human_check_safe_return(string $raw, string $site): string {
    $home = '/' . trim($site, '/') . '/';
    if ($raw === '' || $raw[0] !== '/' || strlen($raw) > 2000) return $home;
    if (isset($raw[1]) && ($raw[1] === '/' || $raw[1] === '\\')) return $home;
    if (strpos($raw, '\\') !== false || preg_match('/[\x00-\x1f\x7f]/', $raw)) return $home;
    $p = parse_url($raw);
    if ($p === false || isset($p['scheme']) || isset($p['host'])) return $home;
    return $raw;
}

