/**
* Check an uploaded sheet against the catalog -- nothing is saved here. Returns:
*   'changes'  [english => new entry]            new or changed translations / statuses / notes
*   'refused'  [[english, why], ...]             placeholders that do not match, unknown status...
*   'unknown'  [english, ...]                    English the site does not have (edited, or old)
*   'kept'     n                                 blank in the sheet, already translated: kept
*   'same'     n                                 unchanged
* or ['error' => message].
*/
function moop_i18n_check_upload(string $lang, array $rows, array $known): array {
if (!$rows) return ['error' => 'The file is empty.'];
$hdr = array_map(fn($h) => strtolower(trim((string) $h)), $rows[0]);
$col = fn(string $name) => array_search(strtolower($name), $hdr, true);
$ci = ['en' => $col('English'), 'tr' => $col('Translation'), 'st' => $col('Status'), 'no' => $col('Notes')];
if ($ci['tr'] === false) $ci['tr'] = $col('Spanish');
if ($ci['en'] === false || $ci['tr'] === false) {
return ['error' => 'The first row must name the columns, including "English" and "Translation". Use the spreadsheet this page exports.'];
}
$catalog = moop_i18n_catalog($lang);
$res = ['changes' => [], 'refused' => [], 'unknown' => [], 'kept' => 0, 'same' => 0];
foreach (array_slice($rows, 1) as $r) {
$en = (string) ($r[$ci['en']] ?? '');
if (trim($en) === '') continue;
if (!isset($known[$en])) { $res['unknown'][] = $en; continue; }
$tr     = trim((string) ($r[$ci['tr']] ?? ''));
$status = strtolower(trim((string) ($ci['st'] !== false ? ($r[$ci['st']] ?? '') : '')));
$notes  = trim((string) ($ci['no'] !== false ? ($r[$ci['no']] ?? '') : ''));
$old    = $catalog[$en] ?? [];

if ($status !== '' && !in_array($status, MOOP_I18N_STATUSES, true)) {
$res['refused'][] = [$en, 'Status "' . $status . '" is not one of: ' . implode(', ', MOOP_I18N_STATUSES) . '.'];
continue;
}
if ($tr === '') {
// A blank cell never erases a translation: say so, change nothing else.
if (trim((string) ($old['text'] ?? '')) !== '') { $res['kept']++; continue; }
if ($notes === (string) ($old['notes'] ?? '')) { $res['same']++; continue; }
$res['changes'][$en] = ['text' => '', 'status' => 'needs translation', 'notes' => $notes];
continue;
}
if (!moop_i18n_placeholders_match($en, $tr)) {
$want = implode(' ', moop_i18n_placeholders($en)) ?: 'none';
$res['refused'][] = [$en, 'The codes do not match. The English has: ' . $want . '; the translation has: '
. (implode(' ', moop_i18n_placeholders($tr)) ?: 'none') . '.'];
continue;
}
if ($status === '' || $status === 'needs translation') $status = 'machine draft';
$new = ['text' => $tr, 'status' => $status, 'notes' => $notes];
if ($new['text'] === (string) ($old['text'] ?? '') && $new['status'] === (string) ($old['status'] ?? '')
&& $new['notes'] === (string) ($old['notes'] ?? '')) { $res['same']++; continue; }
$res['changes'][$en] = $new;
}
return $res;
}

/** Apply checked changes to a language's catalog. Atomic write. Returns ['success', 'message']. */

functions.code:
function moop_i18n_save(string $lang, array $changes, string $who): array {
    if (!preg_match(ConfigManager::LANGUAGE_CODE, $lang) || $lang === 'en') return ['success' => false, 'message' => 'Not a language this page translates into.'];
    $dir = moop_i18n_dir();
    if (!is_dir($dir) && !@mkdir($dir, 02775, true)) {
        return ['success' => false, 'message' => "Could not create $dir -- the web server cannot write there (see Manage Filesystem Permissions)."];
    }
    @chmod($dir, 02775);
    $strings = moop_i18n_catalog($lang, true);
    $when = date('c');
    foreach ($changes as $en => $c) {
        $strings[$en] = ['text' => (string) $c['text'], 'status' => (string) $c['status'], 'notes' => (string) $c['notes'],
                         'updated_at' => $when, 'updated_by' => $who];
    }
    uksort($strings, 'strnatcasecmp');
    $json = json_encode(['language' => $lang, 'strings' => $strings], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    $file = "$dir/$lang.json";
    $tmp  = "$dir/.$lang." . getmypid() . '.tmp';
    if ($json === false || @file_put_contents($tmp, $json . "\n") === false || !@rename($tmp, $file)) {
        @unlink($tmp);
        return ['success' => false, 'message' => "Could not write $file -- the web server cannot write there (see Manage Filesystem Permissions)."];
    }
    @chmod($file, 0664);
    moop_i18n_catalog($lang, true);
    return ['success' => true, 'message' => count($changes) . ' line' . (count($changes) === 1 ? '' : 's') . ' saved.'];
}

public static function getScheme($name)
    {
        // Handle exact color: exact=ColorName
        if (strpos($name, 'exact=') === 0) {
            $color = substr($name, 6); // Remove "exact="
            return [$color]; // Return as single-element array
        }

        // Handle specific index: blues3 (0-indexed)
        if (preg_match('/^([a-z]+)(\d+)$/', $name, $matches)) {
            $schemeName = $matches[1];
            $index = intval($matches[2]);

            if (isset(self::$schemes[$schemeName])) {
                $scheme = self::$schemes[$schemeName];
                if ($index < count($scheme)) {
                    return [$scheme[$index]]; // Return single color as array
                }
            }
            return null; // Invalid scheme or index
        }

        // Regular scheme name
        return self::$schemes[$name] ?? null;
    }

public static function listSchemes()
    {
        // Build sorted list
        $groups = [];
        foreach (self::$schemes as $name => $colors) {
            $info = self::$info[$name] ?? ['type' => 'unknown', 'best_for' => 'general use'];
            $groups[] = [
                'name' => $name,
                'count' => count($colors),
                'type' => $info['type'],
                'best_for' => $info['best_for']
            ];
        }

        // Sort by count (descending), then name
        usort($groups, function($a, $b) {
            if ($b['count'] != $a['count']) {
                return $b['count'] - $a['count'];
            }
            return strcmp($a['name'], $b['name']);
        });

        // Display formatted table
        echo str_repeat('=', 80) . "\n";
        echo "AVAILABLE COLOR GROUPS\n";
        echo str_repeat('=', 80) . "\n\n";

        printf("%-15s %-8s %-12s %s\n", "Group", "Colors", "Type", "Best For");
        echo str_repeat('-', 80) . "\n";

        foreach ($groups as $group) {
            printf("%-15s %-8d %-12s %s\n", 
                $group['name'], 
                $group['count'], 
                $group['type'], 
                $group['best_for']
            );
        }

        echo "\n" . str_repeat('=', 80) . "\n";
        echo "USAGE EXAMPLES:\n";
        echo str_repeat('-', 80) . "\n";
        echo "  ## blues: Sample Group          # Use blues color group\n";
        echo "  ## exact=OrangeRed: Group       # Use specific color\n";
        echo "  ## reds3: Group                 # Use 4th color from reds (0-indexed)\n";
        echo str_repeat('=', 80) . "\n";
    }

public static function suggestSchemes($numFiles, $maxSuggestions = 5)
    {
        $suitable = [];

        foreach (self::$schemes as $name => $colors) {
            if (count($colors) >= $numFiles) {
                $info = self::$info[$name] ?? ['type' => 'unknown', 'best_for' => 'general use'];
                $suitable[] = [
                    'name' => $name,
                    'count' => count($colors),
                    'type' => $info['type'],
                    'best_for' => $info['best_for']
                ];
            }
        }

        // Sort by: closest to needed count, then by name
        usort($suitable, function($a, $b) use ($numFiles) {
            $diffA = abs($a['count'] - $numFiles);
            $diffB = abs($b['count'] - $numFiles);
            if ($diffA != $diffB) {
                return $diffA - $diffB;
            }
            return strcmp($a['name'], $b['name']);
        });

        return array_slice($suitable, 0, $maxSuggestions);
    }

public static function displaySuggestions($numFiles)
    {
        $suggestions = self::suggestSchemes($numFiles, 5);

        if (empty($suggestions)) {
            echo "No color schemes have $numFiles or more colors.\n";
            echo "Largest available: " . max(array_map('count', self::$schemes)) . " colors\n";
            return;
        }

        echo str_repeat('=', 80) . "\n";
        echo "COLOR GROUP SUGGESTIONS FOR $numFiles FILES\n";
        echo str_repeat('=', 80) . "\n\n";

        printf("%-15s %-8s %-12s %s\n", "Group", "Colors", "Type", "Best For");
        echo str_repeat('-', 80) . "\n";

        foreach ($suggestions as $group) {
            printf("%-15s %-8d %-12s %s\n", 
                $group['name'], 
                $group['count'], 
                $group['type'], 
                $group['best_for']
            );
        }

        echo "\nRECOMMENDED:\n";
        echo "  ## {$suggestions[0]['name']}: Your Group Name\n\n";
        echo str_repeat('=', 80) . "\n";
    }

public static function sheetMetadata(array $data): array
    {
        $out = [];
        if (isset($data['sheet_metadata']) && is_array($data['sheet_metadata'])) {
            foreach ($data['sheet_metadata'] as $key => $value) {
                $value = is_scalar($value) ? trim((string)$value) : '';
                if ($value !== '') $out[$key] = $value;
            }
            return $out;
        }
        foreach (self::METADATA_FIELDS as $key) {
            $value = isset($data[$key]) && is_scalar($data[$key]) ? trim((string)$data[$key]) : '';
            if ($value !== '') $out[$key] = $value;
        }
        return $out;
    }

public static function categoryPath($category, string $default = 'Uncategorized'): array
    {
        $parts = is_array($category) ? $category : explode('/', (string)$category);
        $parts = array_map(fn($p) => trim(preg_replace('/\s+/u', ' ', (string)$p)), $parts);
        $parts = array_values(array_filter($parts, fn($p) => $p !== ''));
        return $parts ?: [$default];
    }

public static function normalizeColumnName($name)
    {
        return preg_replace('/[\s-]+/', '_', strtolower(trim((string) $name)));
    }

public function download($sheetId, $gid)
    {
        $url = "https://docs.google.com/spreadsheets/d/$sheetId/export?format=tsv&gid=$gid";

        // Use file_get_contents with error handling
        $content = @file_get_contents($url);

        if ($content === false) {
            throw new RuntimeException(
                "Failed to download Google Sheet. Check sheet ID and GID are correct and sheet is publicly accessible.\n" .
                "URL: $url"
            );
        }

        if (empty($content)) {
            throw new RuntimeException("Downloaded sheet is empty");
        }

        return $content;
    }

public function parseTracks($content, $organism, $assembly)
    {
        $lines = explode("\n", $content);

        if (empty($lines)) {
            return ['regular' => [], 'combo' => []];
        }

        // Parse header
        $header = str_getcsv(trim($lines[0]), "\t");
        $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', $header[0]); // Remove BOM

        // Normalize column names (lowercase; hyphens and spaces become underscores)
        $header = array_map([self::class, 'normalizeColumnName'], $header);

        // Filter out columns starting with #
        $validColumns = [];
        $validIndices = [];
        foreach ($header as $index => $col) {
            if (!preg_match('/^#/', $col)) {
                $validColumns[] = $col;
                $validIndices[] = $index;
            }
        }

        // Parse all rows
        //
        // A track is DEFINED once: by the first row with its TRACK_ID that has a NAME and a
        // TRACK_PATH. Combo groups hold references to tracks, not copies -- a member row may be
        // just the TRACK_ID (every other cell blank), and the definition fills it in. A later
        // full copy still works, but the definition wins and a copy that disagrees is reported.
        // Until 2026-10-20 every member row had to repeat the whole track (425 of Nematostella's
        // 1,166 tracks appear more than once), an edit to one copy did not reach the others, and
        // which copy won depended on processing order.
        $definitions = [];     // track_id => track (first full row)
        $definedOnLine = [];   // track_id => sheet line of that row
        $warnings = [];
        $comboTracks = [];

        $inCombo = false;
        $comboName = null;
        $comboGroup = null;
        $comboColor = null;
        $currentCombo = null;

        for ($i = 1; $i < count($lines); $i++) {
            $line = trim($lines[$i]);

            if (empty($line)) {
                continue;
            }

            // Check for combo track markers
            if (preg_match('/^###/', $line)) {
                // End of combo track
                if ($currentCombo && !empty($currentCombo['groups'])) {
                    $comboTracks[] = $currentCombo;
                }
                $inCombo = false;
                $comboName = null;
                $comboGroup = null;
                $currentCombo = null;
                continue;

            } elseif (preg_match('/^# ([^#].*)/', $line, $matches)) {
                // Start of combo track: # SIMR:Four_Adult_Tissues_MOLNG-2707
                // Only a block that had colour groups -- "# BAM FILES" and the like are section
                // labels, not combos, and are left unclosed on purpose.
                if ($currentCombo && !empty($currentCombo['groups'])) {
                    $warnings[] = 'line ' . ($i + 1) . ': combo "' . $currentCombo['name'] . '" was not closed with "### end" before "'
                                . trim($matches[1]) . '" -- it is ignored';
                }
                $comboName = trim($matches[1]);
                $comboGroup = null;   // rows before this combo's first "##" line belong to no group
                $inCombo = true;
                $currentCombo = [
                    // The id is also the JSON file name: '/' or '\\' would make it a path. 23
                    // Nematostella combos ("Circadian dark/light overlay ...") were never written
                    // because of it (found 2026-10-20). Other characters are left as they were so
                    // existing ids (e.g. gonads_male+female) do not change.
                    'track_id' => strtolower(str_replace([' ', ',', ':', '/', '\\'], ['_', '', '_', '_', '_'], $comboName)),
                    'name' => $comboName,
                    'organism' => $organism,
                    'assembly' => $assembly,
                    'groups' => [],
                    'line' => $i + 1
                ];
                continue;

            } elseif (preg_match('/^## (\S+):\s*(.+)/', $line, $matches)) {
                // Color group: ## greens: body_wall +
                $comboColor = trim($matches[1]);
                $comboGroup = trim($matches[2]);

                if ($currentCombo) {
                    $currentCombo['groups'][$comboGroup] = [
                        'color' => $comboColor,
                        'tracks' => []
                    ];
                }
                continue;
            }

            // Parse data row
            $values = str_getcsv($line, "\t");

            // Filter to valid columns
            $filteredValues = [];
            foreach ($validIndices as $index) {
                $filteredValues[] = $values[$index] ?? '';
            }

            // Create associative array
            $row = [];
            foreach ($validColumns as $index => $columnName) {
                $row[$columnName] = $filteredValues[$index] ?? '';
            }

            $rowTrackId = trim((string)($row['track_id'] ?? ''));
            $inGroup = $inCombo && $currentCombo && $comboGroup !== null;

            // A reference: a member row inside a combo group with only its TRACK_ID filled in.
            if ($inGroup && $rowTrackId !== ''
                    && trim((string)($row['name'] ?? '')) === '' && trim((string)($row['track_path'] ?? '')) === '') {
                $currentCombo['groups'][$comboGroup]['tracks'][] = ['ref' => $rowTrackId, 'line' => $i + 1];
                continue;
            }

            // Skip if missing required fields
            if (empty($row['track_id']) || empty($row['name']) || empty($row['track_path'])) {
                continue;
            }

            // Add organism and assembly
            $row['organism'] = $organism;
            $row['assembly'] = $assembly;

            // Generate browser track ID from file path (for JBrowse2 config)
            $row['browser_track_id'] = $this->generateBrowserTrackId($row['track_path']);

            // Clean track data
            $track = $this->cleanTrackData($row);

            // The first full row defines the track; a later full copy is checked against it.
            $id = $track['track_id'];
            if (!isset($definitions[$id])) {
                $definitions[$id] = $track;
                $definedOnLine[$id] = $i + 1;
            } else {
                $differ = [];
                foreach ($track as $key => $value) {
                    if (in_array($key, ['browser_track_id', 'organism', 'assembly'], true)) continue;
                    $other = $definitions[$id][$key] ?? '';
                    $same  = is_array($value) || is_array($other) ? $value == $other : (string)$value === (string)$other;
                    if (!$same) $differ[] = $key;
                }
                if ($differ) {
                    $warnings[] = 'line ' . ($i + 1) . ': ' . $id . ' repeats line ' . $definedOnLine[$id]
                                . ' with a different ' . implode(', ', $differ) . ' -- line ' . $definedOnLine[$id]
                                . "'s values are used (leave only the TRACK_ID on this row to avoid copies)";
                }
            }

            // In a combo group, the member is a reference to the definition, resolved below.
            // !== null, not truthiness: a group named "0" (Woods Hole "## oranges: 0", the 0 hpf
            // strand) is falsy in PHP, so its rows were dropped and the 4 time-series combos failed.
            if ($inGroup) {
                $currentCombo['groups'][$comboGroup]['tracks'][] = ['ref' => $id, 'line' => $i + 1];
            }
        }

        // Add final combo track if we're still in one
        if ($currentCombo && !empty($currentCombo['groups'])) {
            $comboTracks[] = $currentCombo;
        }

        // Resolve members to their definitions; report what cannot be built.
        $seenComboIds = [];
        $resolvedCombos = [];
        foreach ($comboTracks as $combo) {
            if (isset($seenComboIds[$combo['track_id']])) {
                $warnings[] = 'line ' . $combo['line'] . ': combo "' . $combo['name'] . '" has the same name as line '
                            . $seenComboIds[$combo['track_id']] . ' -- ignored; give it its own name';
                continue;
            }
            $seenComboIds[$combo['track_id']] = $combo['line'];
            foreach ($combo['groups'] as $groupName => $group) {
                $members = [];
                foreach ($group['tracks'] as $member) {
                    if (isset($definitions[$member['ref']])) {
                        $members[] = $definitions[$member['ref']];
                    } else {
                        $warnings[] = 'line ' . $member['line'] . ': combo "' . $combo['name'] . '" refers to TRACK_ID '
                                    . $member['ref'] . ', which no row defines (a row with its NAME and TRACK_PATH)';
                    }
                }
                if (!$members) {
                    $warnings[] = 'line ' . $combo['line'] . ': combo "' . $combo['name'] . '", group "' . $groupName
                                . '" has no tracks -- the combo will not be built';
                }
                $combo['groups'][$groupName]['tracks'] = $members;
            }
            // A combo track shows its members' data, so it takes the STRICTEST member level; a member
            // with no level makes the combo not set. The `#` lines that define it have no Access cell.
            $combo['access_level'] = self::strictestAccessLevel($combo);
            $resolvedCombos[] = $combo;
        }
        $comboTracks = $resolvedCombos;

        return [
            'regular'  => array_values($definitions),   // each track once
            'combo'    => $comboTracks,
            'warnings' => $warnings,
        ];
    }

public function parseTSV($content)
    {
        $lines = explode("\n", $content);

        if (empty($lines)) {
            return [];
        }

        // First line is header
        $header = str_getcsv(trim($lines[0]), "\t");

        // Remove BOM if present
        $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', $header[0]);

        // Normalize column names (lowercase; hyphens and spaces become underscores)
        $header = array_map([self::class, 'normalizeColumnName'], $header);

        $rows = [];

        // Parse data rows
        for ($i = 1; $i < count($lines); $i++) {
            $line = trim($lines[$i]);

            // Skip empty lines
            if (empty($line)) {
                continue;
            }

            $values = str_getcsv($line, "\t");

            // Create associative array
            $row = [];
            foreach ($header as $index => $columnName) {
                $row[$columnName] = $values[$index] ?? '';
            }

            $rows[] = $row;
        }

        return $rows;
    }

public static function strictestAccessLevel(array $combo): string
    {
        $rank = ['PUBLIC' => 1, 'COLLABORATOR' => 2, 'IP_IN_RANGE' => 3, 'ADMIN' => 4];
        $best = null;
        $bestRank = 0;
        foreach ($combo['groups'] ?? [] as $group) {
            foreach ($group['tracks'] ?? [] as $member) {
                $level = strtoupper(trim((string)($member['access_level'] ?? '')));
                if ($level === '') return '';
                $memberRank = $rank[$level] ?? 4;
                if ($memberRank > $bestRank) { $bestRank = $memberRank; $best = $level; }
            }
        }
        return $best ?? '';
    }

private function normalizeTrackPath(string $path): string
    {
        // Collapse accidental double (or more) slashes in the path portion of a URL
        // without touching the :// in the scheme (https://, http://)
        if (preg_match('/^https?:\/\//i', $path)) {
            // Split on :// so we only normalize the part after the scheme
            [$scheme, $rest] = explode('://', $path, 2);
            $rest = preg_replace('#/{2,}#', '/', $rest);
            return $scheme . '://' . $rest;
        }
        return $path;
    }

private function cleanTrackData($row)
    {
        // Map ACCESS column to access_level
        // A blank Access cell is NOT public: it stays '' = not set, which JBrowse shows to admins
        // only. Until 2026-10-20 a blank became PUBLIC -- 2,541 of 2,636 sheet rows were blank.
        $accessLevel = trim($row['access'] ?? $row['access_level'] ?? '');

        $track = [
            'track_id' => trim($row['track_id']),
            'browser_track_id' => trim($row['browser_track_id'] ?? ''),
            'name' => trim($row['name']),
            'TRACK_PATH' => $this->normalizeTrackPath(trim($row['track_path'])),
            'category' => trim($row['category'] ?? 'Uncategorized'),
            'access_level' => $accessLevel,
            'color' => trim($row['color'] ?? ''),
            'description' => trim($row['description'] ?? ''),
            'organism' => $row['organism'],
            'assembly' => $row['assembly'],
        ];

        // Every other column is description: kept by name, empty cells dropped (sheetMetadata()).
        // The flat copies under METADATA_FIELDS stay for code that still reads them by name.
        $sheet = [];
        foreach ($row as $column => $value) {
            if (in_array($column, self::CONTROL_COLUMNS, true)
                || in_array($column, ['organism', 'assembly', 'browser_track_id'], true)
                || $column === '') continue;
            $value = trim((string)$value);
            if ($value !== '') $sheet[$column] = $value;
        }
        $track['sheet_metadata'] = $sheet;
        foreach (self::METADATA_FIELDS as $field) {
            $track[$field] = $sheet[$field] ?? '';
        }

        return $track;
    }

public function validateColumns($parsed)
    {
        if (empty($parsed)) {
            return [
                'valid' => false,
                'missing' => ['Sheet is empty']
            ];
        }

        $firstRow = $parsed[0];
        $actualColumns = array_keys($firstRow);

        $missing = [];
        foreach ($this->requiredColumns as $required) {
            if (!in_array($required, $actualColumns)) {
                $missing[] = $required;
            }
        }

        return [
            'valid' => empty($missing),
            'missing' => $missing
        ];
    }

public function generateBrowserTrackId($filePath)
    {
        if (empty($filePath)) {
            return '';
        }

        // Create MD5 hash of the file path
        $hash = md5($filePath);

        // Take first 10 characters for a compact ID
        return "track_" . substr($hash, 0, 10);
    }

public function __construct($config)
    {
        $this->config = $config;
        $this->tracksServerConfig = $config->get('tracks_server', []);
    }

public function toWebUri($filesystemPath)
    {
        if (empty($filesystemPath)) {
            throw new InvalidArgumentException("Filesystem path cannot be empty");
        }

        // If already a URL, return as-is — don't strip the host
        if ($this->isRemote($filesystemPath)) {
            return $filesystemPath;
        }

        // Check if this is a reference genome (always local)
        $isReferenceGenome = strpos($filesystemPath, '/data/genomes/') !== false || 
                            strpos($filesystemPath, '/genomes/') !== false;

        // Get site configuration
        $sitePath = $this->config->getPath('site_path');
        $site = $this->config->getString('site');

        // Local filesystem paths always serve locally — if you want remote serving,
        // register the file with its remote https:// URL directly in the sheet.
        if (false) {
            // (remote routing block disabled — kept for reference)
        } else {
            // Local server
            // Extract the path after the site directory name
            // Works for any deployment:
            //   /data/moop/data/tracks/... -> /moop/data/tracks/...
            //   /var/www/html/moop/data/tracks/... -> /moop/data/tracks/...
            //   /opt/simrbase/data/tracks/... -> /simrbase/data/tracks/...

            // Find the site directory in the path
            $parts = explode('/', $filesystemPath);
            $siteIndex = array_search($site, $parts);

            if ($siteIndex === false) {
                throw new InvalidArgumentException(
                    "Cannot determine web URI: site directory '$site' not found in path '$filesystemPath'"
                );
            }

            // Build URI from site directory onward
            $uriParts = array_slice($parts, $siteIndex);
            return '/' . implode('/', $uriParts);
        }
    }

public function toFilesystemPath($webUri)
    {
        if (empty($webUri)) {
            throw new InvalidArgumentException("Web URI cannot be empty");
        }

        // If it's a full URL (http:// or https://), return as-is
        if ($this->isRemote($webUri)) {
            return $webUri;
        }

        // Local URI - convert to filesystem path
        $sitePath = $this->config->getPath('site_path');
        $site = $this->config->getString('site');

        // Remove leading slash and site name from URI
        $webUri = ltrim($webUri, '/');
        if (strpos($webUri, $site . '/') === 0) {
            $webUri = substr($webUri, strlen($site) + 1);
        }

        // Build filesystem path
        return $sitePath . '/' . $webUri;
    }

public function isRemote($path)
    {
        return preg_match('#^https?://#i', $path) === 1;
    }

public function fileExists($path)
    {
        // Can't check remote URLs
        if ($this->isRemote($path)) {
            return true; // Assume remote URLs are valid
        }

        return file_exists($path);
    }

private function ensureDirectoryExists($path)
    {
        if (!is_dir($path)) {
            if (!mkdir($path, 0775, true)) {
                throw new RuntimeException(
                    "Failed to create directory: $path"
                );
            }
        }
    }

function loadJBrowse2Plugins() {
    $pluginFile = __DIR__ . '/../../config/jbrowse2_plugins.json';

    if (!file_exists($pluginFile)) {
        error_log("JBrowse2 plugin config not found: $pluginFile");
        return [];
    }

    $plugins = loadJsonFile($pluginFile, []);

    if (!is_array($plugins)) {
        error_log("Invalid JBrowse2 plugin config format");
        return [];
    }

    // Filter to only enabled plugins and return in JBrowse2 format.
    // A url without a scheme or leading slash is a file this site serves itself
    // (js/vendor/, pinned in scripts/vendor_assets.txt) and resolves under the site prefix.
    // Self-hosted on purpose: the Content-Security-Policy allows scripts from 'self' only,
    // and an unversioned third-party URL changes under us without notice.
    // Links start with moop_url() (CLAUDE.md 3b), never "/$site": the folder name is not the link
    // prefix once a site has its own address. ?v= = the file's mtime, so an edited plugin reaches
    // browsers that cached the old copy.
    $enabledPlugins = [];
    foreach ($plugins as $plugin) {
        if (isset($plugin['enabled']) && $plugin['enabled'] === true) {
            $url = (string) $plugin['url'];
            if (!preg_match('#^(https?:)?//|^/#', $url)) {
                $file = __DIR__ . '/../../' . $url;
                $url  = moop_url($url) . (is_file($file) ? '?v=' . filemtime($file) : '');
            }
            $enabledPlugins[] = [
                'name' => $plugin['name'],
                'url' => $url
            ];
        }
    }

    return $enabledPlugins;
}

function getJBrowse2PluginConfiguration() {
    return loadJBrowse2Plugins();
}

public function __construct($config)
    {
        $this->config = $config;
        $this->pathResolver = new PathResolver($config);
        $this->sheetsParser = new GoogleSheetsParser();

        // Register track type handlers
        $this->registerTrackTypes();
    }

private function registerTrackTypes()
    {
        // Map track type identifier to class name
        // NOTE: PAF, PIF, and MCScan are dual-assembly synteny tracks
        // and should be generated using generate_synteny_tracks_from_sheet.php
        $trackTypeClasses = [
            'bigwig' => 'BigWigTrack',
            'bam' => 'BamTrack',
            'combo' => 'ComboTrack',
            'auto' => 'AutoTrack',
            'vcf' => 'VCFTrack',
            'bed' => 'BEDTrack',
            'gtf' => 'GTFTrack',
            'gff' => 'GFFTrack',
            'cram' => 'CRAMTrack',
            'maf' => 'MAFTrack',  // Multiple alignment format (single-assembly)
            // Optional: 'bigbed' => 'BigBedTrack',  // For BigMaf conversion
            // Dual-assembly synteny tracks (NOT registered here):
            // - paf, pif, mcscan
            // Use: generate_synteny_tracks_from_sheet.php
        ];

        // Load and instantiate each track type
        foreach ($trackTypeClasses as $type => $className) {
            $classFile = __DIR__ . "/TrackTypes/$className.php";

            if (file_exists($classFile)) {
                require_once $classFile;

                if (class_exists($className)) {
                    $this->trackTypes[$type] = new $className($this->pathResolver, $this->config);
                } else {
                    error_log("TrackGenerator: Class $className not found in $classFile");
                }
            } else {
                error_log("TrackGenerator: Track type file not found: $classFile");
            }
        }
    }

public function getTrackTypeHandler($type)
    {
        return $this->trackTypes[$type] ?? null;
    }

public function determineTrackType($path)
    {
        // Check for AUTO keyword - reference sequences and annotations
        // These are handled by assembly setup, not as separate tracks
        if (strtoupper(trim($path)) === 'AUTO') {
            return 'auto';
        }

        // Check against each registered track type
        foreach ($this->trackTypes as $type => $handler) {
            foreach ($handler->getValidExtensions() as $ext) {
                if (preg_match('/' . preg_quote($ext, '/') . '$/i', $path)) {
                    return $type;
                }
            }
        }

        return null;
    }

public function loadFromSheet($sheetId, $gid, $organism, $assembly)
    {
        // Download sheet content
        $content = $this->sheetsParser->download($sheetId, $gid);

        // Parse tracks
        $tracks = $this->sheetsParser->parseTracks($content, $organism, $assembly);

        // Validate columns
        $parsed = $this->sheetsParser->parseTSV($content);
        $validation = $this->sheetsParser->validateColumns($parsed);

        if (!$validation['valid']) {
            throw new RuntimeException(
                "Sheet missing required columns: " . implode(', ', $validation['missing'])
            );
        }

        return $tracks;
    }

public function generateTracks($tracks, $options = [])
    {
        $results = [
            'success' => [],
            'failed' => [],
            'skipped' => [],
            'stats' => [
                'total' => 0,
                'created' => 0,
                'failed' => 0,
                'skipped' => 0
            ]
        ];

        // Get force list (empty array means force all)
        $forceIds = $options['force'] ?? null;
        $dryRun = !empty($options['dry_run']);

        // Process regular tracks
        foreach ($tracks['regular'] as $track) {
            $results['stats']['total']++;

            // Determine if we should force regenerate this track
            $shouldForce = false;
            if ($forceIds !== null) {
                if (empty($forceIds)) {
                    // Empty array = force all
                    $shouldForce = true;
                } elseif (in_array($track['track_id'], $forceIds)) {
                    // Specific track ID in force list
                    $shouldForce = true;
                }
            }

            // Check if track exists
            $trackExists = $this->trackExists($track['track_id'], $track['organism'], $track['assembly']);

            if ($trackExists && !$shouldForce) {
                // Existing tracks are not regenerated -- but their ACCESS still follows the sheet.
                // Before 2026-10-20 a changed Access cell never reached a track that already had a
                // JSON file, so the sheet could say COLLABORATOR while the site served it PUBLIC.
                $trackFile = $this->findTrackFile($track['track_id'], $track['organism'], $track['assembly']);
                if ($this->syncExistingAccessLevel($trackFile, (string)($track['access_level'] ?? ''), $dryRun)) {
                    $results['access_updated'][] = $track['track_id'];
                    echo "  ⚿ Access updated: " . $track['track_id'] . " -> " . ($track['access_level'] ?: 'not set') . "\n";
                }
                // ...and so does what the sheet SAYS about it: name, category, description and the
                // descriptive columns. See syncExistingDescription().
                $changed = $this->syncExistingDescription($trackFile, $track, $dryRun);
                if ($changed) {
                    $results['description_updated'][] = $track['track_id'];
                    echo "  ✎ Updated: " . $track['track_id'] . " (" . implode(', ', $changed) . ")\n";
                }
                $results['skipped'][] = $track['track_id'];
                $results['stats']['skipped']++;
                continue;
            }

            // Output what we're doing
            if ($shouldForce && $trackExists) {
                echo "  ♻ Regenerating: " . $track['track_id'] . " (" . $track['name'] . ")\n";
            }

            // Generate track
            $result = $this->generateSingleTrack($track, ['force' => $shouldForce, 'dry_run' => $dryRun]);

            if ($result === 'skipped') {
                // Track generation was skipped (e.g., assembly already exists)
                $results['skipped'][] = $track['track_id'];
                $results['stats']['skipped']++;
                echo "  ⊘ Skipped: " . $track['track_id'] . " (already exists)\n";
            } elseif ($result === true) {
                $results['success'][] = [
                    'track_id' => $track['track_id'],
                    'name' => $track['name'],
                    'regenerated' => ($shouldForce && $trackExists)
                ];
                $results['stats']['created']++;

                // Show what was created/regenerated
                if ($shouldForce && $trackExists) {
                    echo "    ✓ Regenerated successfully\n";
                } else {
                    echo "  ✓ Created: " . $track['track_id'] . " (" . $track['name'] . ")\n";
                }
            } else {
                // Check why it failed
                $trackType = $this->determineTrackType($track['TRACK_PATH']);
                $errorMsg = 'Generation failed';

                if (!$trackType) {
                    $errorMsg = 'Unknown track type: ' . basename($track['TRACK_PATH']);
                }

                $results['failed'][] = [
                    'track_id' => $track['track_id'],
                    'name' => $track['name'],
                    'error' => $errorMsg
                ];
                $results['stats']['failed']++;
                echo "  ✗ Failed: " . $track['track_id'] . " (" . $errorMsg . ")\n";
            }
        }

        // Process combo tracks
        if (!empty($tracks['combo'])) {
            echo "\nProcessing combo tracks...\n";
            echo str_repeat('-', 60) . "\n";

            foreach ($tracks['combo'] as $combo) {
                // Determine if we should force regenerate this track
                $shouldForce = false;
                if ($forceIds !== null) {
                    if (empty($forceIds)) {
                        // Empty array = force all
                        $shouldForce = true;
                    } elseif (in_array($combo['track_id'], $forceIds)) {
                        // Specific track ID in force list
                        $shouldForce = true;
                    }
                }

                // Check if track exists and should skip
                $trackFile = $this->config->getPath('site_path') . '/metadata/jbrowse2-configs/tracks/' . 
                            $combo['organism'] . '/' . $combo['assembly'] . '/combo/' . 
                            strtolower($combo['track_id']) . '.json';

                if (!$shouldForce && file_exists($trackFile)) {
                    // Access still follows the sheet (strictest member), as for regular tracks.
                    if ($this->syncExistingAccessLevel($trackFile, (string)($combo['access_level'] ?? ''), $dryRun)) {
                        $results['access_updated'][] = $combo['track_id'];
                        echo "  ⚿ Access updated: " . $combo['track_id'] . " -> " . ($combo['access_level'] ?: 'not set') . "\n";
                    }
                    // ...and so do its folder and shared description, worked out from its members
                    // (ComboTrack::describe()), through the same refresh as a single track.
                    if (isset($this->trackTypes['combo'])) {
                        $d = ComboTrack::describe($combo);
                        $changed = $this->syncExistingDescription($trackFile, [
                            'name'           => $combo['name'],
                            'category'       => implode(' / ', $d['category']),
                            'sheet_metadata' => $d['sheet'],
                        ], $dryRun);
                        if ($changed) {
                            $results['description_updated'][] = $combo['track_id'];
                            echo "  ✎ Updated: " . $combo['track_id'] . " (" . implode(', ', $changed) . ")\n";
                        }
                    }
                    echo "  ⊘ Skipping " . $combo['track_id'] . " (already exists, use --force to regenerate)\n";
                    $results['skipped'][] = $combo['track_id'];
                    $results['stats']['skipped']++;
                    continue;
                }

                $results['stats']['total']++;

                // Generate combo track
                if (isset($this->trackTypes['combo'])) {
                    $success = $this->trackTypes['combo']->generate(
                        $combo,
                        $combo['organism'],
                        $combo['assembly'],
                        ['dry_run' => $dryRun]
                    );

                    if ($success) {
                        $results['success'][] = $combo['track_id'];
                        $results['stats']['created']++;
                    } else {
                        $results['failed'][] = [
                            'track_id' => $combo['track_id'],
                            'name' => $combo['name'],
                            'error' => 'Combo track generation failed'
                        ];
                        $results['stats']['failed']++;
                    }
                } else {
                    echo "    ✗ Combo track type not registered\n";
                    $results['failed'][] = [
                        'track_id' => $combo['track_id'],
                        'name' => $combo['name'],
                        'error' => 'Combo track type not available'
                    ];
                    $results['stats']['failed']++;
                }
            }
        }

        return $results;
    }

private function generateSingleTrack($trackData, $options = [])
    {
        // Determine track type
        $trackType = $this->determineTrackType($trackData['TRACK_PATH']);

        if (!$trackType) {
            // Don't output error here - let the calling function handle it
            return false;
        }

        // Get track handler
        $handler = $this->getTrackTypeHandler($trackType);

        if (!$handler) {
            // Don't output error here - let the calling function handle it
            return false;
        }

        // Validate track
        $validation = $handler->validate($trackData);
        if (!$validation['valid']) {
            // Don't output error here - let the calling function handle it
            return false;
        }

        // Generate track
        return $handler->generate(
            $trackData,
            $trackData['organism'],
            $trackData['assembly'],
            $options
        );
    }

