/**
* The JSON file of an existing track (same search as trackExists()), or null.
*/

functions.code:
public function findTrackFile($trackId, $organism, $assembly): ?string
    {
        $baseDir = $this->config->getPath('metadata_path') . "/jbrowse2-configs/tracks/$organism/$assembly";
        foreach (['bigwig', 'bam', 'vcf', 'gff', 'gtf', 'bed', 'cram', 'paf', 'maf', 'combo', 'auto'] as $typeDir) {
            $trackFile = "$baseDir/$typeDir/$trackId.json";
            if (file_exists($trackFile)) return $trackFile;
        }
        return null;
    }

public function syncExistingAccessLevel(?string $trackFile, string $level, bool $dryRun = false): bool
    {
        if ($trackFile === null || !is_file($trackFile)) return false;
        $def = json_decode((string)file_get_contents($trackFile), true);
        if (!is_array($def) || (string)($def['metadata']['gene_set'] ?? '') !== '') return false;
        $current = trim((string)($def['metadata']['access_level'] ?? ''));
        $level   = trim($level);
        if (array_key_exists('access_level', $def['metadata'] ?? []) && strcasecmp($current, $level) === 0) return false;
        if ($dryRun) return true;
        $def['metadata']['access_level'] = $level;
        if (file_put_contents($trackFile, json_encode($def, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) === false) {
            error_log("TrackGenerator: could not update access_level in $trackFile");
            return false;
        }
        return true;
    }

public function syncExistingDescription(?string $trackFile, array $track, bool $dryRun = false): array
    {
        if ($trackFile === null || !is_file($trackFile)) return [];
        $def = json_decode((string)file_get_contents($trackFile), true);
        if (!is_array($def) || (string)($def['metadata']['gene_set'] ?? '') !== '') return [];

        $changed = [];
        $name = trim((string)($track['name'] ?? ''));
        if ($name !== '' && ($def['name'] ?? null) !== $name) {
            $def['name'] = $name; $changed[] = 'name';
        }
        $category = trim((string)($track['category'] ?? ''));
        if ($category !== '' && ($def['category'] ?? null) !== GoogleSheetsParser::categoryPath($category)) {
            $def['category'] = GoogleSheetsParser::categoryPath($category); $changed[] = 'category';
        }
        $description = trim((string)($track['description'] ?? ''));
        if (($def['metadata']['description'] ?? '') !== $description) {
            $def['metadata']['description'] = $description; $changed[] = 'description';
        }
        // The key's presence is what marks a sheet track for clean (isSheetOriginTrack()), so a
        // track that has it keeps it even when its row's descriptive cells are now all empty.
        $sheet = GoogleSheetsParser::sheetMetadata($track);
        $had = array_key_exists('google_sheets_metadata', $def['metadata'] ?? []);
        if (($sheet || $had) && ($def['metadata']['google_sheets_metadata'] ?? null) !== $sheet) {
            $def['metadata']['google_sheets_metadata'] = $sheet; $changed[] = 'metadata';
        }

        if (!$changed || $dryRun) return $changed;
        if (file_put_contents($trackFile, json_encode($def, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) === false) {
            error_log("TrackGenerator: could not update the description in $trackFile");
            return [];
        }
        return $changed;
    }

public function trackExists($trackId, $organism, $assembly)
    {
        // Check all track type directories
        $metadataDir = $this->config->getPath('metadata_path');
        $baseDir = "$metadataDir/jbrowse2-configs/tracks/$organism/$assembly";

        if (!is_dir($baseDir)) {
            return false;
        }

        // Check each track type directory
        $trackTypeDirs = ['bigwig', 'bam', 'vcf', 'gff', 'gtf', 'bed', 'cram', 'paf', 'maf', 'combo', 'auto'];

        foreach ($trackTypeDirs as $typeDir) {
            $trackFile = "$baseDir/$typeDir/$trackId.json";
            if (file_exists($trackFile)) {
                return true;
            }
        }

        return false;
    }

public function getTrackStatus($organism, $assembly)
    {
        $tracks = [];

        $metadataDir = $this->config->getPath('metadata_path');
        $baseDir = "$metadataDir/jbrowse2-configs/tracks/$organism/$assembly";

        if (!is_dir($baseDir)) {
            return $tracks;
        }

        // Scan each track type directory
        $trackTypeDirs = ['bigwig', 'bam', 'vcf', 'bed', 'gtf', 'gff', 'cram', 'paf', 'maf', 'combo'];

        foreach ($trackTypeDirs as $typeDir) {
            $fullPath = "$baseDir/$typeDir";
            if (!is_dir($fullPath)) {
                continue;
            }

            $files = glob("$fullPath/*.json");
            foreach ($files as $file) {
                $trackId = basename($file, '.json');
                $metadata = loadJsonFile($file, []);

                $tracks[] = [
                    'track_id' => $trackId,
                    'type' => $typeDir,
                    'name' => $metadata['name'] ?? $trackId,
                    'category' => $metadata['category'] ?? 'Unknown',
                    'file' => $file,
                    'sheet_origin' => self::isSheetOriginTrack($typeDir, $metadata)
                ];
            }
        }

        return $tracks;
    }

public static function isSheetOriginTrack($typeDir, $trackJson)
    {
        if ($typeDir === 'combo') {
            return true;
        }
        $metadata = $trackJson['metadata'] ?? [];
        return is_array($metadata) && array_key_exists('google_sheets_metadata', $metadata);
    }

public static function selectOrphanedTracks($existingTracks, $sheetTrackIds)
    {
        $inSheet = array_flip(array_map('strtolower', $sheetTrackIds));
        $orphans = [];
        foreach ($existingTracks as $track) {
            if (empty($track['sheet_origin'])) {
                continue;
            }
            if (!isset($inSheet[strtolower($track['track_id'])])) {
                $orphans[] = $track;
            }
        }
        return $orphans;
    }

public function cleanOrphanedTracks($sheetTrackIds, $organism, $assembly, $dryRun = false)
    {
        $orphans = self::selectOrphanedTracks($this->getTrackStatus($organism, $assembly), $sheetTrackIds);
        $removed = [];

        foreach ($orphans as $track) {
            if ($dryRun || unlink($track['file'])) {
                $removed[] = $track['track_id'];
            }
        }

        return $removed;
    }

public function __construct($pathResolver)
    {
        $this->pathResolver = $pathResolver;
        $this->config = ConfigManager::getInstance();
    }

