        if (!$isRemote && empty($errors) && $this->tool('samtools') !== '') {
            $output = [];
            $returnCode = 0;
            exec(escapeshellarg($this->tool('samtools')) . " quickcheck " . escapeshellarg($filePath) . " 2>&1", $output, $returnCode);
            if ($returnCode !== 0) {
                $errors[] = "Invalid CRAM file format";
            }
        }

        return [
            'valid' => empty($errors),
            'errors' => $errors
        ];
    }

