private function findTbiIndex(string $gtfPath): ?string
    {
        $tbiPath = $gtfPath . '.tbi';
        if (file_exists($tbiPath)) {
            return $tbiPath;
        }

        $tbiPath = preg_replace('/\.gtf(\.gz)?$/i', '.tbi', $gtfPath);
        if (file_exists($tbiPath)) {
            return $tbiPath;
        }

        return null;
    }

