public function buildMetadata(string $filePath, array $options): array
    {
        $organism = $options['organism'];
        $assembly1 = $options['assembly1'];
        $assembly2 = $options['assembly2'];
        $bed1Path = $options['bed1_path'];
        $bed2Path = $options['bed2_path'];
        $trackId = $options['track_id'] ?? $this->generateTrackId($filePath, $organism, $assembly1);
        $browserTrackId = $options['browser_track_id'] ?? $trackId;
        $trackName = $options['name'] ?? $this->generateTrackName($filePath);
        $category = GoogleSheetsParser::categoryPath($options['category'] ?? '', 'Synteny');
        $description = $options['description'] ?? '';
        $accessLevel = isset($options['access_level']) && !empty($options['access_level'])
            ? $options['access_level']
            : '';   // not set = admins only; never a default PUBLIC

        // Determine if remote or local
        $isRemote = preg_match('/^https?:\/\//i', $filePath);

        // Get URIs for web access
        if ($isRemote) {
            $anchorsUri = $filePath;
            $bed1Uri = $bed1Path;
            $bed2Uri = $bed2Path;
        } else {
            // Convert absolute paths to web URIs
            $anchorsUri = $this->pathResolver->toWebUri($filePath);
            $bed1Uri = $this->pathResolver->toWebUri($bed1Path);
            $bed2Uri = $this->pathResolver->toWebUri($bed2Path);
        }

        // Build metadata structure
        $metadata = [
            'trackId' => $browserTrackId,
            'name' => $trackName,
            'organism' => $organism,
            'assembly1' => $assembly1,
            'assembly2' => $assembly2,
            'category' => $category,
            'description' => $description,
            'metadata' => [
                'management_track_id' => $trackId,
                'access_level' => $accessLevel,
                'track_type' => 'mcscan',
                'file_path' => $filePath,
                'bed1_path' => $bed1Path,
                'bed2_path' => $bed2Path,
                'is_remote' => $isRemote,
                'date_created' => date('Y-m-d H:i:s'),
            ]
        ];

        // Sheet fields go under google_sheets_metadata, as for every other track type. These
        // three used to put them loose in metadata, where the browser's faceted selector (which
        // reads google_sheets_metadata, see moop_jbrowse_browser_metadata()) and the sheet-origin
        // check (TrackGenerator) both missed them.
        $sheetsMetadata = GoogleSheetsParser::sheetMetadata($options);
        if (!empty($sheetsMetadata)) {
            $metadata['metadata']['google_sheets_metadata'] = $sheetsMetadata;
        }

        // Build JBrowse2 track configuration
        $metadata['config'] = [
            'type' => 'SyntenyTrack',
            'trackId' => $trackId,
            'name' => $trackName,
            'category' => $category,
            'assemblyNames' => [$assembly1, $assembly2],
            'adapter' => [
                'type' => 'MCScanAnchorsAdapter',
                'mcscanAnchorsLocation' => [
                    'uri' => $anchorsUri,
                    'locationType' => 'UriLocation'
                ],
                'bed1Location' => [
                    'uri' => $bed1Uri,
                    'locationType' => 'UriLocation'
                ],
                'bed2Location' => [
                    'uri' => $bed2Uri,
                    'locationType' => 'UriLocation'
                ],
                'assemblyNames' => [$assembly1, $assembly2]
            ],
            'metadata' => [
                'management_track_id' => $trackId,
                'access_level' => $accessLevel,
            ]
        ];

        // Add optional metadata to config
        foreach ($optionalFields as $field) {
            if (isset($options[$field]) && !empty($options[$field])) {
                $metadata['config']['metadata'][$field] = $options[$field];
            }
        }

        return $metadata;
    }

