function moop_jbrowse_trix_location(string $organism, string $assembly, string $gene_set = ''): array {
    $config = ConfigManager::getInstance();
    $rel = "data/genomes/$organism/$assembly" . ($gene_set !== '' ? "/$gene_set" : '');
