}

function prepareGeneSetForJBrowse(
    string $organism,
    string $assembly,
    string $gene_set,
    ConfigManager $config,
    array &$log,
    bool $force = false
): bool {
    $organisms_dir = $config->getPath('organism_data');
    $site_path     = $config->getPath('site_path');
    $site          = $config->getString('site', 'moop');
    $metadata_path = $config->getPath('metadata_path');

    $source_gff    = "$organisms_dir/$organism/$assembly/$gene_set/" . genes_gff_filename();
    $genomes_dir   = "$site_path/data/genomes/$organism/$assembly/$gene_set";
    $target_gff    = "$genomes_dir/annotations.gff3";
    $gz_file       = "$genomes_dir/annotations.gff3.gz";
    $tbi_file      = "$gz_file.tbi";
    $csi_file      = "$gz_file.csi";
    $index_type    = 'TBI';   // may be updated to 'CSI' below
    $assembly_name = "{$organism}_{$assembly}";
    $track_id      = "{$assembly_name}_{$gene_set}_genes";
    $track_name    = "Genes ($gene_set)";
    $tracks_dir    = "$metadata_path/jbrowse2-configs/tracks/$organism/$assembly/gff";
    $track_file    = "$tracks_dir/{$gene_set}_genes.json";
    $assembly_json = "$metadata_path/jbrowse2-configs/assemblies/{$organism}_{$assembly}.json";
    $uri_base      = "/$site/data/genomes/$organism/$assembly/$gene_set";

    if (!file_exists($source_gff)) {
        $log[] = "$gene_set: no " . genes_gff_filename() . " found — skipped";
        return false;
    }
    if (filesize($source_gff) === 0) {
        $log[] = "$gene_set: " . genes_gff_filename() . " is empty — skipped";
        return false;
    }
    $log[] = "$gene_set: source GFF found (" . number_format(filesize($source_gff)) . " bytes)";

    // ── Create gene_set directory ────────────────────────────────────────────
    if (!is_dir($genomes_dir) && !mkdir($genomes_dir, 0755, true)) {
        $log[] = "$gene_set: ERROR — could not create $genomes_dir";
        return false;
    }

    // ── Symlink annotations.gff3 ─────────────────────────────────────────────
    // Self-healing: recreate if missing, dangling, or pointing at the wrong
    // source (e.g. after the source GFF is renamed). is_link() alone is true
    // for a *broken* link, so we must compare readlink() to the current source.
    if (is_link($target_gff)) {
        if (readlink($target_gff) === $source_gff) {
            $log[] = "$gene_set: annotations.gff3 symlink OK";
        } else {
            unlink($target_gff);
            symlink($source_gff, $target_gff);
            $log[] = "$gene_set: repointed annotations.gff3 symlink";
        }
    } elseif (!file_exists($target_gff)) {
        symlink($source_gff, $target_gff);
        $log[] = "$gene_set: symlinked annotations.gff3";
    } else {
        // A real (non-symlink) file is present — leave it as-is.
        $log[] = "$gene_set: annotations.gff3 present (regular file)";
    }

    // ── bgzip + tabix ────────────────────────────────────────────────────────
    // FRESHNESS and SOUNDNESS, not existence -- gene_track_index_problem() is the one rule.
    //
    // These tests used to be `!file_exists($gz_file)`, so once a .gz had ever been built
    // it was never rebuilt unless someone passed $force by hand. But a gene-set reload
    // rewrites the source GFF underneath it, and annotations.gff3 is a SYMLINK into
    // organisms/ -- so the uncompressed file silently follows every reload while the
    // compressed copy JBrowse actually reads stays frozen. Measured 2026-07-29: 41 of 69
    // gene tracks were serving indexes older than their own GFF.
    //
    // The mtime-only version then had the opposite blind spot: on 2026-10-13 a rebuild with
    // bgzip missing from PATH left six 0-byte .gz files, NEWER than their GFF, which every
    // check read as fine. Soundness (non-empty, complete BGZF) is now part of the rule, and
    // the build never touches the live files until a verified replacement exists.
    $index_ok = true;
    $problem  = gene_track_index_problem($target_gff);
    if ($force || $problem !== null) {
        if ($problem !== null) {
            $log[] = "$gene_set: index needs rebuilding — {$problem['why']}";
        }
        $index_ok = gene_track_build_index($target_gff, $gene_set, $log);
    } else {
        $log[] = "$gene_set: compressed GFF and tabix index are current";
    }
    // gene_track_build_index() leaves exactly one index type; TBI wins if both somehow exist.
    if (!file_exists($tbi_file) && file_exists($csi_file)) {
        $index_type = 'CSI';
    }

    // ── Gene track JSON ──────────────────────────────────────────────────────
    if (!is_dir($tracks_dir)) mkdir($tracks_dir, 0755, true);

    if (($force || !file_exists($track_file)) && file_exists($gz_file)) {
        $track = [
            'trackId'       => $track_id,
            'name'          => $track_name,
            'assemblyNames' => [$assembly_name],
            'category'      => ['Gene Models'],
            'type'          => 'FeatureTrack',
            'adapter'       => [
                'type'          => 'Gff3TabixAdapter',
                'gffGzLocation' => [
                    'uri'          => "$uri_base/annotations.gff3.gz",
                    'locationType' => 'UriLocation',
                ],
                'index'         => ($index_type === 'CSI')
                    ? [
                        'indexType' => 'CSI',
                        'location'  => [
                            'uri'          => "$uri_base/annotations.gff3.gz.csi",
                            'locationType' => 'UriLocation',
                        ],
                    ]
                    : [
                        'location' => [
                            'uri'          => "$uri_base/annotations.gff3.gz.tbi",
                            'locationType' => 'UriLocation',
                        ],
                    ],
            ],
            'displays' => [
                [
                    // Must be a display type the deployed JBrowse2 build actually
                    // registers. An unknown type (or unknown property) makes
                    // mobx-state-tree reject the ENTIRE config — every track and the
                    // assembly — with "No matching type for union". (audit #12)
                    'type'      => 'LinearBasicDisplay',
                    'displayId' => "$track_id-LinearBasicDisplay",
                ],
            ],
            'metadata' => [
                'management_track_id'   => $track_id,
                'gene_set'              => $gene_set,
                'description'           => "Gene models ($gene_set)",
                'is_primary_gene_track' => true,
                'is_remote'             => false,
                'file_path'             => "$genomes_dir/annotations.gff3.gz",
                'added_date'            => date('c'),
            ],
        ];
        if (file_put_contents($track_file, json_encode($track, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) !== false) {
            $log[] = "$gene_set: created gene track JSON ($track_id)";
        } else {
            $log[] = "$gene_set: WARNING — could not write track JSON";
        }
    } else {
        $log[] = "$gene_set: gene track JSON already exists";
    }

    // ── Update assembly JSON primaryGeneTracks ───────────────────────────────
    if (file_exists($assembly_json)) {
        $asm_data = loadJsonFile($assembly_json, []);
        $primary  = $asm_data['primaryGeneTracks'] ?? [];
        if (!in_array($track_id, $primary, true)) {
            $primary[] = $track_id;
            $asm_data['primaryGeneTracks'] = $primary;
            file_put_contents($assembly_json, json_encode($asm_data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
            $log[] = "$gene_set: added $track_id to assembly primaryGeneTracks";
        }
    }

    // ── Feature coords index (for BLAST linkouts + MOOPmart) ─────────────────
    $gene_set_path = "$organisms_dir/$organism/$assembly/$gene_set";
    $tsv_path      = "$gene_set_path/feature_coords.tsv";
    $gff_mtime     = filemtime("$gene_set_path/" . genes_gff_filename()) ?: 0;
    $tsv_mtime     = file_exists($tsv_path) ? filemtime($tsv_path) : 0;
    if ($tsv_mtime >= $gff_mtime && $tsv_mtime > 0) {
        $log[] = "$gene_set: feature_coords.tsv is up to date — skipped";
    } else {
        $log[] = moop_log_index_build(
            $gene_set, 'feature_coords.tsv', $tsv_path,
            generateFeatureCoordsIndex($gene_set_path),
            'BLAST linkouts on feature databases will not work'
        );
    }

    // ── Exon coords index (maps transcript hits back to genomic blocks) ──────
    $exon_path  = "$gene_set_path/exon_coords.tsv";
    $exon_mtime = file_exists($exon_path) ? filemtime($exon_path) : 0;
    if ($exon_mtime >= $gff_mtime && $exon_mtime > 0) {
        $log[] = "$gene_set: exon_coords.tsv is up to date — skipped";
    } else {
        $log[] = moop_log_index_build(
            $gene_set, 'exon_coords.tsv', $exon_path,
            generateExonCoordsIndex($gene_set_path),
            'Primer BLAST cannot place cDNA products on the genome, so junction-spanning '
            . 'primers get no browser link'
        );
    }

    return $index_ok;
}

function moop_log_index_build(string $gene_set, string $name, string $path, bool $ok, string $consequence): string {
    if (!$ok) {
        return "$gene_set: WARNING — could not generate $name. Check that " . genes_gff_filename()
             . " is readable and the gene set directory is writable by the web server. $consequence.";
    }

    // filesize() is cached per path, and the file may have existed before this
    // build, so a stale stat here would hide exactly the case being checked.
    clearstatcache(true, $path);

    if (!file_exists($path) || filesize($path) === 0) {
        return "$gene_set: WARNING — $name is empty; no matching features found in "
             . genes_gff_filename() . ". $consequence.";
    }

    // KB below a megabyte: "0.0 MB" on a real 40 KB index reads like nothing
    // was written, which is the very state the line above is reporting is fine.
    $bytes = filesize($path);
    $size  = $bytes >= 1048576
        ? number_format($bytes / 1048576, 1) . ' MB'
        : number_format($bytes / 1024, 1) . ' KB';

    return "$gene_set: generated $name ($size)";
}

function unregisterAssembly(string $organism, string $assembly, ConfigManager $config): array {
    $site_path     = $config->getPath('site_path');
    $metadata_path = $config->getPath('metadata_path');

    $assembly_json = "$metadata_path/jbrowse2-configs/assemblies/{$organism}_{$assembly}.json";
    if (!file_exists($assembly_json)) {
        return ['success' => false, 'error' => "Not registered: {$organism}_{$assembly}"];
    }

    $removed = [];
    $kept    = [];

    // 1. The registry entry — this is what puts the assembly in the served JBrowse config,
    //    so remove it first: after this the browser stops offering the broken assembly.
    if (@unlink($assembly_json)) {
        $removed[] = "assembly registration ({$organism}_{$assembly}.json)";
    } else {
        return ['success' => false, 'error' => "Could not remove $assembly_json"];
    }

    // 2. The derived genome directory: the reference.fasta symlink and its .fai index.
    //    rrmdir() unlinks symlinks rather than following them, so the organisms/ genome
    //    this points at is never at risk.
    $genomes_dir = "$site_path/data/genomes/$organism/$assembly";
    if (is_dir($genomes_dir)) {
        if (rrmdir($genomes_dir)) {
            $removed[] = "data/genomes/$organism/$assembly/";
        } else {
            $kept[] = "data/genomes/$organism/$assembly/ (could not remove — check permissions)";
        }
        @rmdir(dirname($genomes_dir));   // organism dir, only if now empty
    }

    // 3. Track JSONs are curation work — keep them if there are any, and only tidy up the
    //    empty directory skeleton that registration/gene-set prep leaves behind.
    $tracks_dir = "$metadata_path/jbrowse2-configs/tracks/$organism/$assembly";
    if (is_dir($tracks_dir)) {
        $track_files = glob("$tracks_dir/*/*.json") ?: [];
        if ($track_files) {
            $kept[] = count($track_files) . " track JSON(s) under jbrowse2-configs/tracks/$organism/$assembly/";
        } elseif (rrmdir($tracks_dir)) {
            $removed[] = "empty track directory (tracks/$organism/$assembly/)";
            @rmdir(dirname($tracks_dir));
        }
    }

    // 4. (Trix search indexes live under data/genomes/$organism/$assembly/, removed in step 2.)

    // 5. A registered Google Sheet track source for this assembly is no longer reachable.
    $sheet_dir = "$metadata_path/jbrowse2-configs/sheets/$organism/$assembly";
    if (is_dir($sheet_dir) && rrmdir($sheet_dir)) {
        $removed[] = "registered Google Sheet source (sheets/$organism/$assembly/)";
        @rmdir(dirname($sheet_dir));
    }

    return ['success' => true, 'removed' => $removed, 'kept' => $kept];
}

function buildGeneSetTextIndex(
    string $organism,
    string $assembly,
    string $gene_set,
    string $attributes,
    ConfigManager $config
): array {
    $site_path     = $config->getPath('site_path');
    $site          = $config->getString('site', 'moop');
    $metadata_path = $config->getPath('metadata_path');

    $jbrowse = moop_find_jbrowse_cli();
    if (!$jbrowse) {
        return [
            'success' => false,
            'error'   => 'jbrowse CLI not found — install Node.js then: npm install -g @jbrowse/cli',
            'no_cli'  => true,
        ];
    }

    $gz_file     = "$site_path/data/genomes/$organism/$assembly/$gene_set/annotations.gff3.gz";
    // Beside the gene track it indexes, never in jbrowse2/ (read-only app code; see
    // moop_jbrowse_trix_location()).
    [$trix_parent, $trix_url] = moop_jbrowse_trix_location($organism, $assembly, $gene_set);
    $trix_dir    = "$trix_parent/trix";

    if (!file_exists($gz_file)) {
        return ['success' => false, 'error' => "GFF not prepped: $gz_file — register the gene set first"];
    }

    if (!is_dir($trix_parent) && !mkdir($trix_parent, 0755, true)) {
        return ['success' => false, 'error' => "Could not create trix directory: $trix_parent"];
    }

    // Find the gene set's track JSON
    $tracks_dir = "$metadata_path/jbrowse2-configs/tracks/$organism/$assembly/gff";
    $track_file = "$tracks_dir/{$gene_set}_genes.json";
    if (!file_exists($track_file)) {
        return ['success' => false, 'error' => "Gene track JSON not found: $track_file — register the gene set first"];
    }
    $track_def = loadJsonFile($track_file, []);
    if (!$track_def) {
        return ['success' => false, 'error' => "Could not parse gene track JSON"];
    }
    $track_id = $track_def['trackId'] ?? null;
    if (!$track_id) {
        return ['success' => false, 'error' => "Gene track JSON has no trackId"];
    }

    $cmd = escapeshellarg($jbrowse) . ' text-index'
         . ' --file '       . escapeshellarg($gz_file)
         . ' --fileId '     . escapeshellarg($track_id)
         . ' --out '        . escapeshellarg($trix_parent)
         . ' --attributes ' . escapeshellarg($attributes)
         . ' --force 2>&1';

    $out = []; exec($cmd, $out, $rc);

    if ($rc !== 0) {
        return ['success' => false, 'error' => "exit $rc: " . implode(' ', $out)];
    }

    $gz_basename = basename($gz_file);
    $ix_file     = "$trix_dir/{$gz_basename}.ix";
    if (!file_exists($ix_file)) {
        return ['success' => false, 'error' => 'text-index ran but .ix file was not created'];
    }

    $asm_name = $track_def['assemblyNames'][0] ?? "{$organism}_{$assembly}";
    $base     = "$trix_url/trix/$gz_basename";
    $track_def['textSearching'] = [
        'textSearchAdapter' => [
            'type'                => 'TrixTextSearchAdapter',
            'textSearchAdapterId' => "$track_id-index",
            'ixFilePath'          => ['uri' => "$base.ix",        'locationType' => 'UriLocation'],
            'ixxFilePath'         => ['uri' => "$base.ixx",       'locationType' => 'UriLocation'],
            'metaFilePath'        => ['uri' => "{$base}_meta.json", 'locationType' => 'UriLocation'],
            'assemblyNames'       => [$asm_name],
        ],
    ];
    $track_def['metadata']['text_index_attributes'] = $attributes;
    $track_def['metadata']['text_index_date']       = gmdate('Y-m-d\TH:i:s\Z');
    file_put_contents($track_file, json_encode($track_def, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));

    return ['success' => true];
}

function generateExonCoordsIndex(string $gene_set_path): bool {
    $gff_file = $gene_set_path . '/' . genes_gff_filename();
    $tsv_file = $gene_set_path . '/exon_coords.tsv';

    if (!file_exists($gff_file) || filesize($gff_file) === 0) {
        return false;
    }

    $fh = fopen($gff_file, 'r');
    if (!$fh) return false;
    $out = fopen($tsv_file, 'w');
    if (!$out) { fclose($fh); return false; }

    $features = [];   // id => [chr, strand, start, end]   within the current gene family
    $exons    = [];   // parent id => [[start, end], ...]

    $flush = function () use ($out, &$features, &$exons): void {
        foreach ($exons as $parent => $blocks) {
            if (!isset($features[$parent])) {
                continue;   // exons whose parent never appeared: nothing to anchor them to
            }
            [$chr, $strand, $start, $end] = $features[$parent];

            usort($blocks, function ($a, $b) { return $a[0] <=> $b[0]; });
            $spans = [];
            foreach ($blocks as [$s, $e]) {
                $spans[] = $s . ',' . $e;
            }
            $row = "\t" . $chr . "\t" . $strand . "\t" . $start . ',' . $end
                 . "\t" . implode(';', $spans) . "\n";

            fwrite($out, $parent . $row);
            $bare = moop_gff_bare_id($parent);   // the database's form of the ID
            if ($bare !== $parent) {
                fwrite($out, $bare . $row);
            }
        }
        $features = [];
        $exons    = [];
    };

    while (($line = fgets($fh)) !== false) {
        if ($line[0] === '#') continue;
        $parts = explode("\t", rtrim($line), 9);
        if (count($parts) < 9) continue;

        $id = $parent = null;
        foreach (explode(';', $parts[8]) as $attr) {
            $kv = explode('=', $attr, 2);
            if (count($kv) !== 2) continue;
            $k = trim($kv[0]);
            if ($k === 'ID')     $id     = trim($kv[1]);
            if ($k === 'Parent') $parent = trim($kv[1]);
        }

        if (strtolower($parts[2]) === 'exon') {
            if ($parent) {
                $exons[$parent][] = [(int)$parts[3], (int)$parts[4]];
            }
            continue;
        }

        if (!$id) continue;

        // A root feature starts a new family; everything buffered belongs to the last one.
        if (!$parent) {
            $flush();
        }
        $features[$id] = [$parts[0], $parts[6], (int)$parts[3], (int)$parts[4]];
    }
    $flush();

    fclose($fh);
    fclose($out);

    // Group-writable ON PURPOSE. This file is written both from the web (as
    // apache, at registration) and from the CLI (as the deploying user, when
    // backfilling), and the default 0640 leaves whichever of the two did NOT
    // create it unable to overwrite it -- so "Regenerate" fails on exactly the
    // files a backfill produced. Group is apache via the setgid on organisms/.
    @chmod($tsv_file, 0660);

    return true;
}

function generateFeatureCoordsIndex(string $assembly_path): bool {
    $gff_file = $assembly_path . '/' . genes_gff_filename();
    $tsv_file = $assembly_path . '/feature_coords.tsv';

    if (!file_exists($gff_file) || filesize($gff_file) === 0) {
        return false;
    }

    $skip_types = ['region', 'chromosome', 'contig', 'scaffold', 'supercontig', 'biological_region'];

    $fh = fopen($gff_file, 'r');
    if (!$fh) return false;
    $out = fopen($tsv_file, 'w');
    if (!$out) { fclose($fh); return false; }

    $gene    = null;   // current root: ['id','chr','start','end','strand']
    $pending = [];     // feature rows for current gene family
    $seen    = [];     // dedup within current gene family

    $flush = function() use ($out, &$gene, &$pending, &$seen): void {
        if (!$gene) return;
        $suffix = "\t{$gene['id']}\t{$gene['chr']}\t{$gene['start']}\t{$gene['end']}\t{$gene['strand']}\n";
        foreach ($pending as [$id, $type, $name]) {
            if (!isset($seen[$id])) {
                fwrite($out, $id . $suffix);
                $seen[$id] = true;
            }
            $bare = preg_replace('/^(?:rna|cds|gene|id)-/', '', $id);
            if ($bare !== $id && !isset($seen[$bare])) {
                fwrite($out, $bare . $suffix);
                $seen[$bare] = true;
            }
            if ($type === 'cds' && $name !== null && $name !== $id && $name !== $bare && !isset($seen[$name])) {
                fwrite($out, $name . $suffix);
                $seen[$name] = true;
            }
        }
        $pending = [];
        $seen    = [];
    };

    while (($line = fgets($fh)) !== false) {
        if ($line[0] === '#') continue;
        $parts = explode("\t", rtrim($line), 9);
        if (count($parts) < 9) continue;
        $type = strtolower($parts[2]);
        if (in_array($type, $skip_types)) continue;

        $id = $parent = $name = null;
        foreach (explode(';', $parts[8]) as $attr) {
            $kv = explode('=', $attr, 2);
            if (count($kv) !== 2) continue;
            switch (trim($kv[0])) {
                case 'ID':     $id     = trim($kv[1]); break;
                case 'Parent': $parent = trim($kv[1]); break;
                case 'Name':   $name   = trim($kv[1]); break;
            }
        }
        if (!$id) continue;

        if (!$parent) {
            $flush();
            $gene = ['id' => $id, 'chr' => $parts[0], 'start' => $parts[3], 'end' => $parts[4], 'strand' => $parts[6]];
        }
        $pending[] = [$id, $type, $name];
    }
    $flush();

    fclose($fh);
    fclose($out);
    return true;
}

function moop_bgzf_is_complete(string $path): bool {
    clearstatcache(true, $path);
    if (!is_file($path) || filesize($path) <= strlen(MOOP_BGZF_EOF)) {
        return false;
    }
    $fh = @fopen($path, 'rb');
    if ($fh === false) {
        return false;
    }
    $head = fread($fh, 4);
    $tail = fseek($fh, -strlen(MOOP_BGZF_EOF), SEEK_END) === 0 ? fread($fh, strlen(MOOP_BGZF_EOF)) : '';
    fclose($fh);
    return $head === "\x1f\x8b\x08\x04" && $tail === MOOP_BGZF_EOF;
}

function gene_track_index_problem(string $gff): ?array {
    $gz  = "$gff.gz";
    clearstatcache();
    if (!file_exists($gz)) {
        return ['kind' => 'missing', 'why' => 'no compressed GFF'];
    }
    if (!moop_bgzf_is_complete($gz)) {
        return ['kind' => 'broken', 'why' => 'compressed GFF is empty, truncated or unreadable'];
    }
    // filemtime() follows the symlink, so this compares against the real GFF.
    if (file_exists($gff) && filemtime($gz) < filemtime($gff)) {
        return ['kind' => 'stale', 'why' => 'compressed GFF older than source'];
    }
    $index = file_exists("$gz.tbi") ? "$gz.tbi" : (file_exists("$gz.csi") ? "$gz.csi" : null);
    if ($index === null) {
        return ['kind' => 'missing', 'why' => 'no tabix index'];
    }
    if (!moop_bgzf_is_complete($index)) {
        return ['kind' => 'broken', 'why' => 'tabix index is empty, truncated or unreadable'];
    }
    // An index older than the .gz it describes points at the wrong offsets.
    if (filemtime($index) < filemtime($gz)) {
        return ['kind' => 'stale', 'why' => 'tabix index older than compressed GFF'];
    }
    return null;
}

function gene_set_jbrowse_problems(string $gff, string $track_json = ''): array {
    $out = [];
    if ($p = gene_track_index_problem($gff)) {
        $out[] = ['part' => 'track'] + $p;
    }

    $src = realpath($gff);   // the gene set's own genes.gff in organisms/
    if ($src !== false) {
        $gff_mtime = filemtime($src);
        foreach (['feature_coords.tsv', 'exon_coords.tsv'] as $name) {
            $f = dirname($src) . "/$name";
            if (!is_file($f)) {
                $out[] = ['part' => 'coords', 'kind' => 'missing', 'why' => "no $name"];
            } elseif (filemtime($f) < $gff_mtime) {
                $out[] = ['part' => 'coords', 'kind' => 'stale', 'why' => "$name older than genes.gff"];
            }
        }
    }

    $gz = "$gff.gz";
    $ix = dirname($gff) . '/trix/' . basename($gz) . '.ix';
    $track = $track_json !== '' && is_file($track_json) ? (json_decode((string)file_get_contents($track_json), true) ?: []) : null;
    $want  = defined('MOOP_JBROWSE_TEXT_INDEX_ATTRIBUTES') ? MOOP_JBROWSE_TEXT_INDEX_ATTRIBUTES : null;
    if (!is_file($ix)) {
        $out[] = ['part' => 'search', 'kind' => 'missing', 'why' => 'no search index'];
    } elseif (is_file($gz) && filemtime($ix) < filemtime($gz)) {
        $out[] = ['part' => 'search', 'kind' => 'stale', 'why' => 'search index older than the gene track'];
    } elseif ($track !== null && empty($track['textSearching']['textSearchAdapter'])) {
        $out[] = ['part' => 'search', 'kind' => 'missing', 'why' => 'search index not linked from the gene track'];
    } elseif ($track !== null && $want !== null && ($track['metadata']['text_index_attributes'] ?? '') !== $want) {
        $out[] = ['part' => 'search', 'kind' => 'stale',
                  'why' => 'search index built from ' . ($track['metadata']['text_index_attributes'] ?? 'unknown attributes') . ", not $want"];
    }
    return $out;
}

function gene_track_build_index(string $gff, string $label, array &$log): bool {
    $gz    = "$gff.gz";
    $bgzip = moop_find_executable('bgzip');
    $tabix = moop_find_executable('tabix');
    if ($bgzip === '' || $tabix === '') {
        $missing = implode(' and ', array_keys(array_filter(['bgzip' => $bgzip === '', 'tabix' => $tabix === ''])));
        $log[] = "$label: ERROR — $missing not found (looked on PATH, /usr/local/bin, /usr/bin). "
               . 'Nothing was changed; install htslib or fix PATH and re-run.';
        return false;
    }

    // Temp files sit BESIDE the target so the final rename() is on one filesystem (atomic).
    // tabix names its index after the file it indexes: $tmp.tbi / $tmp.csi.
    $tmp     = "$gz.tmp-" . getmypid();
    $cleanup = function () use ($tmp) {
        foreach ([$tmp, "$tmp.tbi", "$tmp.csi"] as $f) {
            if (file_exists($f)) @unlink($f);
        }
    };
    $cleanup();

    // sort spills to $TMPDIR (default /tmp) -- a 4 GB volume on this host, and php-fpm's private
    // /tmp lives on it. A 1.2 GB GFF (Danio_rerio RS_2025_04, 2026-11-18) failed with "No space
    // left on device". Spill beside the target instead: same disk as the output, which we already
    // write to. TMPDIR also reaches the sort that `jbrowse sort-gff` runs underneath.
    $env = 'export TMPDIR=' . escapeshellarg(dirname($gff)) . '; set -o pipefail; ';

    // Headers first, then features sorted by seqid and start -- what tabix requires.
    $sorted = '(grep "^#" ' . escapeshellarg($gff)
            . '; grep -v "^#" ' . escapeshellarg($gff)
            . ' | sort -t"$(printf \'\\t\')" -k1,1 -k4,4n)';
    $out = []; $rc = 1;
    exec('/bin/bash -c ' . escapeshellarg($env . $sorted . ' | ' . escapeshellarg($bgzip)
         . ' > ' . escapeshellarg($tmp)) . ' 2>&1', $out, $rc);

    if ($rc !== 0 || !moop_bgzf_is_complete($tmp)) {
        // GFFs whose parents follow their children need jbrowse's own sort.
        $jb = moop_find_jbrowse_cli();
        if ($jb) {
            $out = []; $rc = 1;
            exec('/bin/bash -c ' . escapeshellarg($env . escapeshellarg($jb) . ' sort-gff '
                 . escapeshellarg($gff) . ' | ' . escapeshellarg($bgzip) . ' > ' . escapeshellarg($tmp))
                 . ' 2>&1', $out, $rc);
            $log[] = $rc === 0 ? "$label: sorted with jbrowse sort-gff" : "$label: jbrowse sort-gff also failed";
        }
    }
    if ($rc !== 0 || !moop_bgzf_is_complete($tmp)) {
        $log[] = "$label: ERROR — bgzip failed; existing index left untouched. " . implode(' ', array_slice($out, -3));
        $cleanup();
        return false;
    }

    $type = 'tbi';
    $out = []; $rc = 1;
    exec(escapeshellarg($tabix) . ' -p gff ' . escapeshellarg($tmp) . ' 2>&1', $out, $rc);
    if ($rc !== 0) {
        $err = implode(' ', $out);
        // TBI cannot address chromosomes over 512 Mb; CSI can.
        if (stripos($err, 'coordinate') !== false || stripos($err, 'CSI') !== false) {
            $out = []; $rc = 1;
            exec(escapeshellarg($tabix) . ' -C -p gff ' . escapeshellarg($tmp) . ' 2>&1', $out, $rc);
            $type = 'csi';
        }
    }
    if ($rc !== 0 || !moop_bgzf_is_complete("$tmp.$type")) {
        $log[] = "$label: ERROR — tabix failed; existing index left untouched. " . implode(' ', array_slice($out, -3));
        $cleanup();
        return false;
    }

    // Swap in: the .gz first, then its index. The index was written after the .gz, and
    // rename() keeps mtimes, so the pair passes the freshness rule. If the second rename
    // fails, the old index is older than the new .gz and the next check rebuilds it.
    $other = $type === 'tbi' ? "$gz.csi" : "$gz.tbi";
    if (!@rename($tmp, $gz) || !@rename("$tmp.$type", "$gz.$type")) {
        $log[] = "$label: ERROR — could not move the rebuilt index into place (is the directory writable by the web server?)";
        $cleanup();
        return false;
    }
    if (file_exists($other)) {
        @unlink($other);   // never leave a stale index of the other type for a reader to pick
    }

    clearstatcache();
    $log[] = "$label: bgzip OK (" . number_format(filesize($gz)) . ' bytes), tabix ' . strtoupper($type)
           . ' OK (' . number_format(filesize("$gz.$type")) . ' bytes)'
           . ($type === 'csi' ? ' — chromosomes exceed the TBI limit' : '');
    return true;
}

function moop_jwt_key_paths(): array {
    $dir = dirname(__DIR__, 2) . '/certs';
    return [
        'dir'     => $dir,
        'private' => $dir . '/jwt_private_key.pem',
        'public'  => $dir . '/jwt_public_key.pem',
    ];
}

functions.comment:
/**
* Where the JWT key pair lives: <moop>/certs/. Every reader goes through here -- signing and
* verifying below, the permissions check, housekeeping, setup and setup-check, the tracks
* server admin page -- so a check can never inspect a different file from the one in use.
*
* Fixed, not configured, on purpose: this file also runs on the tracks server, which has no
* MOOP config to read a path from. Until 2026-10-23 site_config.php carried six settings
* (certs_directory, jwt_private_key, jwt_public_key, twice over) that LOOKED like they moved
* the keys; the signing code never read any of them, so changing one would only have pointed
* the health checks at the wrong file.
*
* The directory is inside the web root. nginx refuses it outright (location ^~ /moop/certs/
* in docs/nginx/moop-security.conf); the 2750 directory mode is the second line, not the only one.
*
* @return array{dir: string, private: string, public: string}
*/
function moop_jwt_key_paths(): array {
$dir = dirname(__DIR__, 2) . '/certs';
return [
'dir'     => $dir,
'private' => $dir . '/jwt_private_key.pem',
'public'  => $dir . '/jwt_public_key.pem',
];
}

/** Load firebase/php-jwt (Composer) on first use. */

functions.code:
function moop_jwt_library(): void {
    require_once __DIR__ . '/../../vendor/autoload.php';
}

function generateTrackToken($organism, $assembly, $file = '') {
    $private_key_path = moop_jwt_key_paths()['private'];

    if (!file_exists($private_key_path)) {
        throw new Exception("JWT private key not found at: $private_key_path");
    }

    $private_key = file_get_contents($private_key_path);

    $token_data = [
        'organism' => $organism,
        'assembly' => $assembly,
        'file'     => $file,
        'iat' => time(),
        'exp' => time() + 3600  // 1 hour expiry
    ];

    moop_jwt_library();
    try {
        $jwt = JWT::encode($token_data, $private_key, 'RS256');
        return $jwt;
    } catch (Exception $e) {
        throw new Exception("Failed to generate JWT: " . $e->getMessage());
    }
}

function verifyTrackToken($token) {
    $public_key_path = moop_jwt_key_paths()['public'];

    if (!file_exists($public_key_path)) {
        error_log("JWT verification failed: public key not found at $public_key_path");
        return false;
    }

    $public_key = file_get_contents($public_key_path);
    if ($public_key === false) {
        error_log("JWT verification failed: public key at $public_key_path is not readable");
        return false;
    }

    // The signing host (MOOP) and this verifying host may be seconds apart, and
    // php-jwt defaults to zero tolerance: a token whose `iat` is one second in
    // the verifier's future is rejected outright. Tokens live an hour, so a
    // minute of slack costs nothing.
    moop_jwt_library();
    JWT::$leeway = 60;

    try {
        $decoded = JWT::decode($token, new Key($public_key, 'RS256'));
        return $decoded;
    } catch (Exception $e) {
        error_log("JWT verification failed: " . $e->getMessage());
        return false;
    }
}

function moop_kegg_genes_url(array $scope, string $pathway): string {
    return moop_url('tools/moopmart.php?' . http_build_query($scope + [
        'annotation' => $pathway, 'annotation_source' => MOOP_KEGG_PATHWAY_SOURCE,
        'annotation_column_sources' => MOOP_KEGG_GENE_COLUMNS]));
}

function moop_kegg_genes_download_html(array $scope, string $pathway): string {
    static $by_scope = [];                     // a pathway table calls this once per row
    $sk = json_encode($scope);
    if (!isset($by_scope[$sk])) {
        $by_scope[$sk] = [];
        foreach (getAccessibleGeneSets($scope['organism'] ?? null, $scope['assembly'] ?? null, $scope['gene_set'] ?? null) as $by_org) {
            foreach ($by_org as $org => $rows) foreach ($rows as $r) $by_scope[$sk][$org . '|' . $r['assembly'] . '|' . $r['gene_set']] = true;
        }
    }
    $keys = $by_scope[$sk];
    if (!$keys) return '';
    $fields = ['output_format' => 'tsv', 'ann_format' => 'wide', 'sources[]' => array_keys($keys),
               'ann_criteria_type[]' => '', 'ann_criteria_src[]' => MOOP_KEGG_PATHWAY_SOURCE, 'ann_criteria_acc[]' => $pathway,
               'ann_criteria_kw[]' => '', 'ann_criteria_sub[]' => '0', 'annotation_columns[]' => MOOP_KEGG_GENE_COLUMNS];
    $h = '<form method="post" action="' . htmlspecialchars(moop_url('api/moopmart_export.php')) . '" class="d-inline">' . csrf_input_field();
    foreach ($fields as $k => $v) {
        foreach ((array) $v as $one) $h .= '<input type="hidden" name="' . htmlspecialchars($k) . '" value="' . htmlspecialchars((string) $one) . '">';
    }
    $title = t('Download these genes with their KEGG Orthology, pathways and modules (TSV)');
    return $h . '<button type="submit" class="btn btn-sm btn-link p-0 ms-1 align-baseline" title="' . $title . '" aria-label="' . $title . '">'
              . '<i class="fa fa-download" aria-hidden="true"></i></button></form>';
}

function moop_kegg_ordered(array $ko_colours): array {
    $rank = array_flip(['other_set', 'in_assembly', 'in_organism', 'this_set', 'this_gene']);
    uksort($ko_colours, fn($a, $b) => [$rank[$ko_colours[$a]] ?? -1, $a] <=> [$rank[$ko_colours[$b]] ?? -1, $b]);
    return $ko_colours;
}

functions.comment:
/**
* The order KOs are SENT in, least important first. KEGG draws one box for several KOs (CTSB/L/S on map04612)
* and the LAST colour sent for any of them wins (checked in a browser 2026-11-14) -- sorted by KO number,
* cathepsin B's green hid the gene's own cathepsin L. So "this gene" goes last.
*/
function moop_kegg_ordered(array $ko_colours): array {
$rank = array_flip(['other_set', 'in_assembly', 'in_organism', 'this_set', 'this_gene']);
uksort($ko_colours, fn($a, $b) => [$rank[$ko_colours[$a]] ?? -1, $a] <=> [$rank[$ko_colours[$b]] ?? -1, $b]);
return $ko_colours;
}

/** What each colour means, for the legend (each a literal, so the translation scan lists it). */

functions.code:
function moop_kegg_colour_labels(): array {
    return [
        'this_gene'   => t('this gene'),
        'this_set'    => t('in this gene set'),
        'other_set'   => t('only in another gene set of this species'),
        'in_organism' => t('found in this organism'),
        'in_assembly' => t('found in this assembly'),
    ];
}

function moop_kegg_split_pathway_name(string $description): array {
    if (preg_match('/^(.*\S)\s*\(([^();]+);\s*([^()]+)\)$/', trim($description), $m)) {
        return [$m[1], trim($m[2]), trim($m[3])];
    }
    return [trim($description), '', ''];
}

function moop_kegg_sort_classes(array $by_class): array {
    uksort($by_class, function ($a, $b) {
        $ia = array_search($a, MOOP_KEGG_CLASS_ORDER, true);
        $ib = array_search($b, MOOP_KEGG_CLASS_ORDER, true);
        return [$ia === false ? 99 : $ia, $a] <=> [$ib === false ? 99 : $ib, $b];
    });
    return $by_class;
}

functions.comment:
/**
* "TNF signaling pathway (Environmental Information Processing; Signal transduction)" ->
* ['TNF signaling pathway', 'Environmental Information Processing', 'Signal transduction'].
* The pipeline writes every pathway description this way (all 428 in Nematostella, 2026-11-14); a name
* that does not fit comes back whole with an empty class, never cut.
*
* @return array{0:string,1:string,2:string}
*/
function moop_kegg_split_pathway_name(string $description): array {
if (preg_match('/^(.*\S)\s*\(([^();]+);\s*([^()]+)\)$/', trim($description), $m)) {
return [$m[1], trim($m[2]), trim($m[3])];
}
return [trim($description), '', ''];
}

/** KEGG's own order of its top pathway classes (br08901); anything else sorts after, by name. */
const MOOP_KEGG_CLASS_ORDER = ['Metabolism', 'Genetic Information Processing', 'Environmental Information Processing',
'Cellular Processes', 'Organismal Systems', 'Human Diseases', 'Drug Development'];

function moop_kegg_sort_classes(array $by_class): array {
uksort($by_class, function ($a, $b) {
$ia = array_search($a, MOOP_KEGG_CLASS_ORDER, true);
$ib = array_search($b, MOOP_KEGG_CLASS_ORDER, true);
return [$ia === false ? 99 : $ia, $a] <=> [$ib === false ? 99 : $ib, $b];
});
return $by_class;
}

/** A KEGG reference pathway id as the pipeline loads them ("map04668"). */

functions.code:
function moop_kegg_valid_pathway(string $id): bool {
    return preg_match('/^map\d{5}\z/', $id) === 1;
}

function moop_kegg_gene_set_pathway_kos(string $db_file, int $gene_set_id, string $pathway): array {
    $sql = "SELECT ak.annotation_accession AS ko,
                   COUNT(DISTINCT fk.feature_id) AS genes
              FROM annotation ap
              JOIN annotation_source sp ON sp.annotation_source_id = ap.annotation_source_id
              JOIN feature_annotation fp ON fp.annotation_id = ap.annotation_id
              JOIN feature f            ON f.feature_id = fp.feature_id
              JOIN feature_annotation fk ON fk.feature_id = fp.feature_id
              JOIN annotation ak        ON ak.annotation_id = fk.annotation_id
              JOIN annotation_source sk ON sk.annotation_source_id = ak.annotation_source_id
             WHERE sp.annotation_source_name = ? AND ap.annotation_accession = ?
               AND sk.annotation_source_name = ? AND f.gene_set_id = ?
             GROUP BY ak.annotation_accession";
    $dbh = getDbConnection($db_file);
    $st  = $dbh->prepare($sql);
    $st->execute([MOOP_KEGG_PATHWAY_SOURCE, $pathway, MOOP_KEGG_KO_SOURCE, $gene_set_id]);
    $out = [];
    foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
        $out[$r['ko']] = ['genes' => (int)$r['genes']];
    }
    return $out;
}

functions.comment:
/**
* The KOs a gene set has in one pathway: [KO => ['genes' => n]].
*
* A feature with KOs A and B whose pathway came through A also brings B; KEGG simply does not draw a KO
* that is not on the map, so the link is unaffected. (With organisms/.kegg/ko_pathway.tsv on the site
* this could filter first; not needed for colouring.)
*
* @throws PDOException when the database cannot be read (the caller decides what that means)
*/
function moop_kegg_gene_set_pathway_kos(string $db_file, int $gene_set_id, string $pathway): array {
$sql = "SELECT ak.annotation_accession AS ko,
COUNT(DISTINCT fk.feature_id) AS genes
FROM annotation ap
JOIN annotation_source sp ON sp.annotation_source_id = ap.annotation_source_id
JOIN feature_annotation fp ON fp.annotation_id = ap.annotation_id
JOIN feature f            ON f.feature_id = fp.feature_id
JOIN feature_annotation fk ON fk.feature_id = fp.feature_id
JOIN annotation ak        ON ak.annotation_id = fk.annotation_id
JOIN annotation_source sk ON sk.annotation_source_id = ak.annotation_source_id
WHERE sp.annotation_source_name = ? AND ap.annotation_accession = ?
AND sk.annotation_source_name = ? AND f.gene_set_id = ?
GROUP BY ak.annotation_accession";
$dbh = getDbConnection($db_file);
$st  = $dbh->prepare($sql);
$st->execute([MOOP_KEGG_PATHWAY_SOURCE, $pathway, MOOP_KEGG_KO_SOURCE, $gene_set_id]);
$out = [];
foreach ($st->fetchAll(PDO::FETCH_ASSOC) as $r) {
$out[$r['ko']] = ['genes' => (int)$r['genes']];
}
return $out;
}

/** The KOs of one feature (a gene page's transcript): [KO, ...]. */

functions.code:
function moop_kegg_feature_kos(string $db_file, int $gene_set_id, string $uniquename): array {
    $dbh = getDbConnection($db_file);
    $st  = $dbh->prepare("SELECT DISTINCT a.annotation_accession
                            FROM feature f
                            JOIN feature_annotation fa ON fa.feature_id = f.feature_id
                            JOIN annotation a          ON a.annotation_id = fa.annotation_id
                            JOIN annotation_source s   ON s.annotation_source_id = a.annotation_source_id
                           WHERE f.gene_set_id = ? AND f.feature_uniquename = ? AND s.annotation_source_name = ?");
    $st->execute([$gene_set_id, $uniquename, MOOP_KEGG_KO_SOURCE]);
    return $st->fetchAll(PDO::FETCH_COLUMN);
}

function moop_kegg_ko_colours(array $kos, array $this_gene = [], array $other_kos = []): array {
    $out = [];
    foreach ($other_kos as $ko) $out[$ko] = 'other_set';
    foreach (array_keys($kos) as $ko) $out[$ko] = 'this_set';
    foreach ($this_gene as $ko) $out[$ko] = 'this_gene';
    ksort($out);
    return $out;
}

function moop_kegg_map_url(string $pathway, array $ko_colours): string {
    $lines = [];
    foreach (moop_kegg_ordered($ko_colours) as $ko => $key) {
        if (!preg_match('/^K\d{5}\z/', $ko) || !isset(MOOP_KEGG_COLOURS[$key])) continue;
        $lines[] = $ko . '+' . rawurlencode(MOOP_KEGG_COLOURS[$key]) . ',black';
    }
    return 'https://www.kegg.jp/kegg-bin/show_pathway?map=' . rawurlencode($pathway)
         . '&multi_query=' . implode('%0d%0a', $lines);
}

function moop_kegg_map_post(string $pathway, array $ko_colours): array {
    $lines = [];
    foreach (moop_kegg_ordered($ko_colours) as $ko => $key) {
        if (!preg_match('/^K\d{5}\z/', $ko) || !isset(MOOP_KEGG_COLOURS[$key])) continue;
        $lines[] = $ko . ' ' . MOOP_KEGG_COLOURS[$key] . ',black';
    }
    return ['action' => 'https://www.kegg.jp/kegg-bin/show_pathway',
            'fields' => ['map' => $pathway, 'multi_query' => implode("\r\n", $lines)]];
}

function moop_kegg_map_legend_html(array $keys): string {
    $labels = moop_kegg_colour_labels();
    $html = '<span class="kegg-legend">';
    foreach ($keys as $key) {
        if (!isset($labels[$key], MOOP_KEGG_COLOURS[$key])) continue;
        $html .= '<span class="kegg-legend-item"><span class="kegg-swatch" style="background:' . MOOP_KEGG_COLOURS[$key] . '"></span>'
               . $labels[$key] . '</span>';
    }
    $html .= '<span class="kegg-legend-item"><span class="kegg-swatch" style="background:' . MOOP_KEGG_NOT_FOUND . '"></span>'
           . t('not found') . '</span>';
    $html .= field_help(
        'Each box on a KEGG pathway map is a KO (KEGG Orthology, e.g. K01365): a gene function, the group of '
        . 'orthologous genes that do the same job. eggNOG-mapper gives each gene a KO, and a KO can sit on many '
        . 'pathway maps (e.g. map04612), so one gene can be in many pathways. The map colours each box by where '
        . 'that KO is found. Some genes were given more than one possible KO; each of them is coloured.',
        'Colours on the KEGG map'
    );
    return $html . '</span>';
}

function moop_kegg_gene_pathways_html(array $rows, string $uniquename, array $link_ctx): string {
    $by_class = [];
    $n = 0;
    foreach ($rows as $r) {
        if (($r['annotation_source_name'] ?? '') !== MOOP_KEGG_PATHWAY_SOURCE) continue;
        $id = (string)($r['annotation_accession'] ?? '');
        if (!moop_kegg_valid_pathway($id)) continue;
        [$name, $top, $sub] = moop_kegg_split_pathway_name((string)($r['annotation_description'] ?? ''));
        $by_class[$top !== '' ? $top : 'Other'][$sub][$id] = ['name' => $name, 'kos' => (int)($r['score'] ?? 1)];
        $n++;
    }
    if ($n === 0) return '';
    $by_class = moop_kegg_sort_classes($by_class);

    $ctx = array_filter(['organism' => $link_ctx['organism'] ?? '', 'assembly' => $link_ctx['assembly'] ?? '',
                         'gene_set' => $link_ctx['gene_set'] ?? ''], 'strlen');
    $can_link = count($ctx) === 3;
    // "Genes in this organism" too, when the visitor can see more than this one gene set of the species
    $org_link = false;
    if ($can_link) {
        try {
            $org_link = count(moop_kegg_visible_gene_sets($ctx['organism'], organism_db_path($ctx['organism']))) > 1;
        } catch (PDOException $e) {
            error_log('KEGG gene page, gene sets of ' . $ctx['organism'] . ': ' . $e->getMessage());
        }
    }
    // Classes start closed (one Nematostella gene has 126 pathways); the counts say what is inside.

    $html = '<div class="kegg-pathways mb-2">';
    $html .= '<div class="small text-muted mb-1">'
           . t('KEGG pathways by class. "View on KEGG" opens KEGG\'s map with the boxes coloured:')
           . ' ' . moop_kegg_map_legend_html(['this_gene', 'this_set', 'other_set']) . '</div>';
    foreach ($by_class as $top => $subs) {
        $count = array_sum(array_map('count', $subs));
        $html .= '<details class="kegg-class"><summary><i class="fas fa-chevron-right kegg-chev" aria-hidden="true"></i><strong>' . htmlspecialchars($top)
               . '</strong> <span class="badge bg-light text-dark">' . $count . '</span></summary><ul class="kegg-pathway-list">';
        ksort($subs);
        foreach ($subs as $sub => $paths) {
            if ($sub !== '') $html .= '<li class="kegg-sub">' . htmlspecialchars($sub) . '</li>';
            uasort($paths, fn($a, $b) => strcasecmp($a['name'], $b['name']));
            foreach ($paths as $id => $p) {
                $html .= '<li class="kegg-pathway">' . htmlspecialchars($p['name']) . ' <span class="text-muted small">' . htmlspecialchars($id) . '</span>';
                if ($p['kos'] > 1) {
                    $html .= ' <span class="small text-muted" title="' . t('eggNOG could not settle on one KO for this gene; this pathway comes from one of them.') . '">'
                           . t('(from one of %d possible KOs)', $p['kos']) . '</span>';
                }
                if ($can_link) {
                    $map = moop_url('api/kegg_map.php?' . http_build_query($ctx + ['pathway' => $id, 'gene' => $uniquename]));
                    // MOOPmart: the genes of this gene set in this pathway, each with its KO
                    $genes = moop_kegg_genes_url($ctx, $id);
                    $html .= ' <a class="kegg-map-link" href="' . htmlspecialchars($map) . '" target="_blank" rel="noopener nofollow">' . t('View on KEGG')
                           . ' <i class="fa fa-external-link-alt link-icon"></i></a>'
                           . ' · <a href="' . htmlspecialchars($genes) . '">' . t('Genes in this gene set') . '</a>'
                           . moop_kegg_genes_download_html($ctx, $id);
                    if ($org_link) {
                        $org_genes = moop_kegg_genes_url(['organism' => $ctx['organism']], $id);
                        $html .= ' · <a href="' . htmlspecialchars($org_genes) . '">' . t('Genes in this organism') . '</a>'
                               . moop_kegg_genes_download_html(['organism' => $ctx['organism']], $id);
                    }
                }
                $html .= '</li>';
            }
        }
        $html .= '</ul></details>';
    }
    return $html . '</div>';
}

function moop_kegg_reference(): ?array {
    static $ref = false;
    if ($ref !== false) return $ref;
    $dir = rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/') . '/.kegg';
    $ref = null;
    if (!is_readable("$dir/pathway.tsv") || !is_readable("$dir/ko_pathway.tsv")) return null;

    $names = [];
    foreach (file("$dir/pathway.tsv", FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) {
        [$id, $name] = array_pad(explode("\t", $line, 2), 2, '');
        if (moop_kegg_valid_pathway($id)) $names[$id] = trim($name);
    }
    $kos = [];
    foreach (file("$dir/ko_pathway.tsv", FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES) ?: [] as $line) {
        // "ko:K00001<TAB>path:map00010" -- each pair is listed for map… and ko…; keep map…
        if (preg_match('/^ko:(K\d{5})\tpath:(map\d{5})$/', $line, $m)) $kos[$m[2]][$m[1]] = true;
    }
    $classes = [];
    $tree = is_readable("$dir/pathway_classes.json") ? json_decode((string)file_get_contents("$dir/pathway_classes.json"), true) : null;
    foreach ((array)($tree['children'] ?? []) as $top) {
        foreach ((array)($top['children'] ?? []) as $sub) {
            foreach ((array)($sub['children'] ?? []) as $leaf) {
                if (preg_match('/^(\d{5})\s/', (string)($leaf['name'] ?? ''), $m)) {
                    $classes['map' . $m[1]] = [(string)$top['name'], (string)$sub['name']];
                }
            }
        }
    }
    $date = '';
    if (is_readable("$dir/info.txt") && preg_match('/^\s*pathway\s+\d+\s+(\S+)/m', (string)file_get_contents("$dir/info.txt"), $m)) {
        $date = str_replace('/', '-', $m[1]);
    }
    $mtime = max(array_map(fn($f) => (int)@filemtime("$dir/$f"), ['pathway.tsv', 'ko_pathway.tsv', 'pathway_classes.json']));
    $ref = ['date' => $date, 'names' => $names, 'classes' => $classes, 'kos' => $kos, 'mtime' => $mtime];
    return $ref;
}

function moop_kegg_gene_set_rows(PDO $dbh, int $gene_set_id, string $source): array {
    $st = $dbh->prepare("SELECT COALESCE(f.parent_feature_id, f.feature_id) AS gene, a.annotation_accession AS acc, fa.score
                           FROM annotation_source s
                          CROSS JOIN annotation a          ON a.annotation_source_id = s.annotation_source_id
                          CROSS JOIN feature_annotation fa ON fa.annotation_id = a.annotation_id
                          CROSS JOIN feature f             ON f.feature_id = fa.feature_id
                          WHERE s.annotation_source_name = ? AND f.gene_set_id = ?");
    $st->execute([$source, $gene_set_id]);
    $out = [];
    while ($r = $st->fetch(PDO::FETCH_NUM)) {
        $out[(int)$r[0]][$r[1]] = (float)($r[2] ?? 1);
    }
    return $out;
}

function moop_kegg_pathway_table(array $gene_pathways, array $gene_kos, array $descriptions, ?array $ref): array {
    $by_path = [];
    foreach ($gene_pathways as $gene => $paths) {
        foreach ($paths as $p => $score) $by_path[$p][$gene] = $score > 1;
    }
    $rows = [];
    foreach ($by_path as $p => $genes) {
        [$dname, $dtop, $dsub] = moop_kegg_split_pathway_name((string)($descriptions[$p] ?? $p));
        $in_ref = $ref['kos'][$p] ?? null;
        $found = [];
        foreach (array_keys($genes) as $g) {
            foreach (array_keys($gene_kos[$g] ?? []) as $ko) {
                if ($in_ref === null || isset($in_ref[$ko])) $found[$ko] = true;
            }
        }
        ksort($found);
        $rows[] = [
            'pathway'         => $p,
            'name'            => $ref['names'][$p] ?? $dname,
            'class'           => $ref['classes'][$p][0] ?? $dtop,
            'sub'             => $ref['classes'][$p][1] ?? $dsub,
            'genes'           => count($genes),
            'ambiguous_genes' => count(array_filter($genes)),
            'kos_found'       => array_keys($found),
            'kos_total'       => $in_ref !== null ? count($in_ref) : null,
        ];
    }
    usort($rows, fn($a, $b) => [$b['genes'], $a['pathway']] <=> [$a['genes'], $b['pathway']]);
    return $rows;
}

function moop_kegg_gene_set_pathways(string $db_path, int $gene_set_id, string $gene_set_dir): array {
    $ref   = moop_kegg_reference();
    $cdir  = moop_cache_dir_for($gene_set_dir);
    $cfile = $cdir !== '' ? "$cdir/kegg_pathways.json" : '';
    $stamp = (int)@filemtime($db_path) . ':' . ($ref['mtime'] ?? 0) . ':v1';
    if ($cfile !== '' && is_readable($cfile)) {
        $c = json_decode((string)file_get_contents($cfile), true);
        if (is_array($c) && ($c['stamp'] ?? '') === $stamp) return $c['data'];
    }

    $dbh = getDbConnection($db_path);
    $paths = moop_kegg_gene_set_rows($dbh, $gene_set_id, MOOP_KEGG_PATHWAY_SOURCE);
    $data = ['rows' => [], 'reference_date' => (string)($ref['date'] ?? ''), 'has_reference' => $ref !== null];
    if ($paths) {
        $kos = moop_kegg_gene_set_rows($dbh, $gene_set_id, MOOP_KEGG_KO_SOURCE);
        $st = $dbh->prepare("SELECT a.annotation_accession, a.annotation_description FROM annotation a
                               JOIN annotation_source s ON s.annotation_source_id = a.annotation_source_id
                              WHERE s.annotation_source_name = ?");
        $st->execute([MOOP_KEGG_PATHWAY_SOURCE]);
        $data['rows'] = moop_kegg_pathway_table($paths, $kos, $st->fetchAll(PDO::FETCH_KEY_PAIR), $ref);
    }
    if ($cfile !== '' && moop_ensure_cache_dir($cdir)) {
        $tmp = "$cfile." . getmypid() . '.tmp';
        if (@file_put_contents($tmp, json_encode(['stamp' => $stamp, 'data' => $data])) !== false) @rename($tmp, $cfile);
        else @unlink($tmp);
    }
    return $data;
}

function moop_kegg_visible_gene_sets(string $organism, string $db_path, string $assembly = ''): array {
    $org_dir = rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/') . "/$organism";
    $dbh = getDbConnection($db_path);
    $out = [];
    $rows = $dbh->query('SELECT gs.gene_set_id, gs.gene_set_name, g.genome_accession, g.genome_name
                           FROM gene_set gs JOIN genome g ON g.genome_id = gs.genome_id
                          ORDER BY g.genome_accession, gs.gene_set_name')->fetchAll(PDO::FETCH_ASSOC);
    foreach ($rows as $r) {
        $asm = (string)$r['genome_accession'];
        $gs  = (string)$r['gene_set_name'];
        if ($assembly !== '' && $asm !== $assembly) continue;   // the assembly page: its own gene sets only
        if (!moop_plain_name($asm) || !moop_plain_name($gs) || !has_gene_set_access($organism, $asm, $gs)) continue;
        $asm_dir = is_dir("$org_dir/$asm") ? $asm
                 : (($r['genome_name'] ?? '') !== '' && is_dir("$org_dir/{$r['genome_name']}") ? $r['genome_name'] : $asm);
        if (!is_dir("$org_dir/$asm_dir/$gs")) continue;   // retired / not on this site
        $out[] = ['assembly' => $asm, 'gene_set' => $gs, 'gene_set_id' => (int)$r['gene_set_id'], 'dir' => "$org_dir/$asm_dir/$gs"];
    }
    return $out;
}

function moop_kegg_merge_gene_sets(array $tables): array {
    $tables = array_filter($tables);
    $n_sets = count($tables);
    $by = [];
    foreach ($tables as $key => $rows) {
        foreach ($rows as $r) {
            $p = $r['pathway'];
            $by[$p] ??= ['pathway' => $p, 'name' => $r['name'], 'class' => $r['class'], 'sub' => $r['sub'],
                         'genes' => [], 'ko_sets' => [], 'kos_total' => $r['kos_total']];
            $by[$p]['genes'][$key] = $r['genes'];
            foreach ($r['kos_found'] as $ko) $by[$p]['ko_sets'][$ko][$key] = true;
        }
    }
    $out = [];
    foreach ($by as $p => $row) {
        ksort($row['ko_sets']);
        $row['kos_found']  = array_keys($row['ko_sets']);
        $row['kos_in_all'] = array_keys(array_filter($row['ko_sets'], fn($sets) => count($sets) === $n_sets));
        unset($row['ko_sets']);
        $out[] = $row;
    }
    usort($out, fn($a, $b) => [count($b['kos_found']), $a['pathway']] <=> [count($a['kos_found']), $b['pathway']]);
    return $out;
}

function moop_kegg_organism_pathways(string $organism, string $db_path, string $assembly = ''): array {
    $tables = [];
    $ref_date = ''; $has_ref = false;
    foreach (moop_kegg_visible_gene_sets($organism, $db_path, $assembly) as $g) {
        $t = moop_kegg_gene_set_pathways($db_path, $g['gene_set_id'], $g['dir']);
        $tables["{$g['assembly']}/{$g['gene_set']}"] = $t['rows'];
        $has_ref = $t['has_reference']; $ref_date = $t['reference_date'];
    }
    $tables = array_filter($tables);
    return ['rows' => moop_kegg_merge_gene_sets($tables), 'gene_sets' => array_keys($tables),
            'has_reference' => $has_ref, 'reference_date' => $ref_date];
}

function moop_vendor_asset_rows(?string $file = null): array {
    $file = $file ?? dirname(__DIR__) . '/scripts/vendor_assets.txt';
    $rows = [];
    foreach (@file($file, FILE_IGNORE_NEW_LINES) ?: [] as $line) {
        if ($line === '' || $line[0] === '#') continue;
        $f = explode('|', $line);
        if (count($f) >= 5) $rows[] = array_map('trim', array_slice($f, 0, 5));
    }
    return $rows;
}

function moop_library_inventory(string $root, ?array $rows = null): array {
    $rows = $rows ?? moop_vendor_asset_rows("$root/scripts/vendor_assets.txt");
    $pkgs = [];
    foreach ($rows as [$path, $url, $sha, , $spec]) {
        if (!preg_match('/^(\w+):(.+)@([^@]+)$/', $spec, $m)) {
            $pkgs["?$path"] = ['ecosystem' => '', 'name' => $path, 'version' => '', 'files' => [$path],
                               'problems' => ["no package@version recorded for $path"]];
            continue;
        }
        [, $eco, $name, $ver] = $m;
        $key = "$eco:$name@$ver";
        $pkgs[$key] = $pkgs[$key] ?? ['ecosystem' => $eco === 'npm' ? 'npm' : $eco, 'name' => $name,
                                     'version' => $ver, 'files' => [], 'problems' => []];
        $pkgs[$key]['files'][] = $path;
        // The URL names the version it was downloaded as; a bump that changed one column and
        // not the other would make OSV check the wrong release.
        if (strpos($url, $ver) === false) {
            $pkgs[$key]['problems'][] = "$path: the URL does not mention version $ver";
        }
        $file = "$root/$path";
        if (!is_file($file)) {
            $pkgs[$key]['problems'][] = "$path is missing";
        } elseif (hash_file('sha256', $file) !== $sha) {
            $pkgs[$key]['problems'][] = "$path no longer matches its pinned checksum, so its version is unverified";
        }
    }
    // Composer: runtime packages only. Dev tools (require-dev) never ship to the site.
    $installed = json_decode((string)@file_get_contents("$root/vendor/composer/installed.json"), true);
    $dev = array_flip($installed['dev-package-names'] ?? []);
    foreach (($installed['packages'] ?? (is_array($installed) ? $installed : [])) as $p) {
        if (!isset($p['name'], $p['version']) || isset($dev[$p['name']])) continue;
        $ver = ltrim((string)$p['version'], 'v');
        $pkgs["Packagist:{$p['name']}@$ver"] = ['ecosystem' => 'Packagist', 'name' => $p['name'], 'version' => $ver,
                                                'files' => ['vendor/' . $p['name']], 'problems' => []];
    }
    return array_values($pkgs);
}

function moop_osv_check(array $pkgs): ?array {
    $queries = [];
    $index = [];
    foreach ($pkgs as $i => $p) {
        if ($p['ecosystem'] === '' || $p['version'] === '') continue;
        $queries[] = ['package' => ['name' => $p['name'], 'ecosystem' => $p['ecosystem']], 'version' => $p['version']];
        $index[] = $i;
    }
    if (!$queries) return [];
    $batch = moop_osv_request('https://api.osv.dev/v1/querybatch', json_encode(['queries' => $queries]));
    if (!isset($batch['results']) || count($batch['results']) !== count($queries)) return null;

    $out = [];
    foreach ($batch['results'] as $n => $res) {
        foreach ($res['vulns'] ?? [] as $v) {
            $d = moop_osv_request('https://api.osv.dev/v1/vulns/' . rawurlencode($v['id'])) ?? [];
            $fixed = [];
            foreach ($d['affected'] ?? [] as $a) {
                if (($a['package']['name'] ?? '') !== $pkgs[$index[$n]]['name']) continue;
                foreach ($a['ranges'] ?? [] as $r) {
                    foreach ($r['events'] ?? [] as $e) if (isset($e['fixed'])) $fixed[] = $e['fixed'];
                }
            }
            $out[$index[$n]][] = [
                'id'       => $v['id'],
                'summary'  => (string)($d['summary'] ?? ''),
                'severity' => ucfirst(strtolower((string)($d['database_specific']['severity'] ?? 'unknown'))),
                'fixed'    => array_values(array_unique($fixed)),
                'url'      => 'https://osv.dev/vulnerability/' . rawurlencode($v['id']),
            ];
        }
    }
    return $out;
}

