functions.code:
function moop_menu_without_page(array $menu, string $slug): array {
    $out = [];
    foreach ($menu as $item) {
        if (($item['type'] ?? '') === 'link' && ($item['to']['page'] ?? null) === $slug) continue;
        if (($item['type'] ?? '') === 'dropdown') {
            $item['items'] = array_values(array_filter((array) ($item['items'] ?? []),
                fn($c) => ($c['to']['page'] ?? null) !== $slug));
        }
        $out[] = $item;
    }
    return $out;
}

function moop_menu_set_page(array $menu, string $slug, string $where, array $titles, ?array $old_titles = null): array {
    $label = array_filter(array_map('strval', $titles), fn($t) => trim($t) !== '');
    $relabel = function ($now) use ($label, $old_titles): array {
        if ($old_titles === null || !is_array($now)) return $label;
        $out = $label;
        foreach ($now as $lang => $text) {
            $text = (string) $text;
            if (trim($text) !== '' && $text !== (string) ($old_titles[$lang] ?? '')) $out[$lang] = $text;   // hand-written
        }
        return $out;
    };
    $here  = moop_menu_page_place($menu, $slug);
    if ($where === $here && $where !== 'none') {
        // Same place: refresh the label only.
        foreach ($menu as &$item) {
            if (($item['type'] ?? '') === 'link' && ($item['to']['page'] ?? null) === $slug) $item['label'] = $relabel($item['label'] ?? null);
            if (($item['type'] ?? '') === 'dropdown') {
                foreach ($item['items'] as &$child) {
                    if (($child['to']['page'] ?? null) === $slug) $child['label'] = $relabel($child['label'] ?? null);
                }
                unset($child);
            }
        }
        unset($item);
        return $menu;
    }
    $menu = moop_menu_without_page($menu, $slug);
    $link = ['type' => 'link', 'label' => $label, 'to' => ['page' => $slug]];
    if ($where === 'top') {
        $menu[] = $link;
    } elseif (strpos($where, 'dd:') === 0) {
        $key = substr($where, 3);
        foreach ($menu as &$item) {
            if (($item['type'] ?? '') === 'dropdown' && ($item['key'] ?? '') === $key) { $item['items'][] = $link; break; }
        }
        unset($item);
    }
    return $menu;
}

function moop_menu_save(array $menu): array {
    $config = ConfigManager::getInstance();
    // An emptied label (a Spanish box typed in, then cleared) is no label: drop it, so the menu
    // compares equal to the default when it is the default.
    $tidy = function (array $item) {
        if (isset($item['label']) && is_array($item['label'])) {
            $item['label'] = array_filter($item['label'], fn($t) => trim((string) $t) !== '');
        }
        return $item;
    };
    $menu = array_map(function ($item) use ($tidy) {
        $item = $tidy($item);
        if (($item['type'] ?? '') === 'dropdown') $item['items'] = array_map($tidy, (array) ($item['items'] ?? []));
        return $item;
    }, $menu);
    $value  = $menu == ConfigManager::defaultMainMenu() ? [] : array_values($menu);
    $dir    = $config->getPath('root_path') . '/' . $config->getString('site') . '/config';
    return $config->saveEditableConfig(['main_menu' => $value], $dir);
}

function moop_site_has_restricted_data(): bool {
    static $memo = null;
    if ($memo !== null) return $memo;
    $config = ConfigManager::getInstance();
    $root   = rtrim($config->getPath('organism_data'), '/');
    foreach (glob("$root/*/*", GLOB_ONLYDIR) ?: [] as $dir) {
        $organism = basename(dirname($dir));
        $assembly = basename($dir);
        if ($organism[0] === '.' || $assembly[0] === '.') continue;          // .retired, .cache
        if (!is_file("$dir/genome.json") && !glob("$dir/*/", GLOB_ONLYDIR)) continue;  // not an assembly
        if (!is_public_assembly($organism, $assembly)) return $memo = true;
    }
    return $memo = false;
}

function moopmartResolveInputIds(array $input_ids, string $db_path, array $gene_set_ids, &$unresolved = null): array
{
    if (empty($input_ids) || empty($gene_set_ids)) return [];

    // Version-tolerant ID resolution FIRST, then the climb.
    //
    // Ambiguity is kept, not resolved: if a stem matches .1 and .2 both are seeded, both
    // export, and the reason string says so (user decision, 2026-08-05 -- "list both, export
    // both, report it"). Silently picking one would make an export depend on a tie-break
    // nobody can see.
    $resolved = moop_resolve_input_ids($input_ids, $db_path, $gene_set_ids, $unresolved);
    if (empty($resolved)) return [];

    // uniquename -> the id the USER typed, for the reason label.
    $typed_as = [];
    $seeds    = [];
    foreach ($resolved as $typed => $names) {
        foreach ($names as $n) { $seeds[] = $n; $typed_as[$n] = (string)$typed; }
    }

    // The shared walker carries the cycle guards. Note what it does NOT do, deliberately: a
    // self-parented feature terminates at the guard and never satisfies "no parent" below, so
    // it resolves to nothing. The cure is reloading the data, not teaching this to accept a
    // broken hierarchy as a root.
    $rows = moop_hierarchy_walk($seeds, $db_path, 'up', $gene_set_ids);
    if (empty($rows)) return [];

    // The seed's OWN type, for the reason label. Depth 0 is the seed itself.
    $seed_type = [];
    foreach ($rows as $r) {
        if ((int)$r['depth'] === 0) $seed_type[(string)$r['seed_name']] = (string)$r['feature_type'];
    }

    $by_gene = [];
    foreach ($rows as $r) {
        // The root is the node with no parent -- the same test the CTE used to make.
        $pid = $r['parent_feature_id'];
        if ($pid !== null && $pid !== '' && $pid !== 'NULL') continue;

        $input = (string)$r['seed_name'];
        $gene  = (string)$r['feature_uniquename'];
        $typed = $typed_as[$input] ?? $input;

        // Say what MATCHED when it differs from what was typed, so a row that came back
        // under a version the user did not enter is explained rather than surprising.
        $shown = ($typed === $input) ? $input : "{$input} (matched {$typed})";
        $reason = ($input === $gene && $typed === $input)
            ? "Gene ID: {$input}"
            : moopmartFeatureTypeLabel($seed_type[$input] ?? '') . ": {$shown}";
        $by_gene[$gene][] = $reason;
    }

    $result = [];
    foreach ($by_gene as $gene => $reasons) {
        $result[$gene] = implode('; ', array_unique($reasons));
    }
    return $result;
}

