function moop_ontology_normalise_id(string $v): string {
    $v = trim($v);
    if (preg_match('#^https?://purl\.obolibrary\.org/obo/([A-Za-z][A-Za-z0-9]*)_([A-Za-z0-9_.-]+)$#', $v, $m)) {
        $v = $m[1] . ':' . $m[2];
    }
    return preg_match(MOOP_ONTOLOGY_ID_RE, $v) ? $v : '';
}

