/**
* Build fingerprint for config files (tree, groups)
*/

functions.code:
function buildConfigFingerprint($taxonomy_tree_file, $groups_file) {
    $parts = [];
    // Note: taxonomy_tree_config.json is intentionally excluded — it is an output
    // of the organism scan, so including its mtime would create a circular invalidation.
    if (file_exists($groups_file)) {
        // mtime + size — a re-synced groups file can preserve its mtime, so size makes
        // an actual content change detectable (same reasoning as buildPerOrganismFingerprints).
        $parts[] = 'groups:' . filemtime($groups_file) . ':' . filesize($groups_file);
    }
    return md5(implode('|', $parts));
}

function buildPerOrganismFingerprints($organism_data_path) {
    $fingerprints = [];

    if (!is_dir($organism_data_path)) {
        return $fingerprints;
    }

    foreach (moop_organism_dirs($organism_data_path) as $organism) {

        $org_path = "$organism_data_path/$organism";
        $parts = [];

        // SQLite file: mtime + size. Size catches timestamp-preserving replacements
        // (rsync -a, cp -p, tar extract, restore-from-backup all keep the old mtime) —
        // a rebuilt or re-synced DB is virtually always a different byte size.
        $sqlite_file = "$org_path/organism.sqlite";
        if (file_exists($sqlite_file)) {
            $parts[] = 'db:' . filemtime($sqlite_file) . ':' . filesize($sqlite_file);
        }

        // organism.json: mtime + size (same timestamp-lies reasoning as the DB above)
        $json_file = "$org_path/organism.json";
        if (file_exists($json_file)) {
            $parts[] = 'json:' . filemtime($json_file) . ':' . filesize($json_file);
        }

        // Assembly directories — include each dir's mtime so that adding/removing
        // files inside an assembly (FASTA, FAI, BLAST indexes) triggers a rescan.
        $assemblies = array_filter(scandir($org_path), function($f) use ($org_path) {
            return $f[0] !== '.' && is_dir("$org_path/$f");
        });
        $parts[] = 'asm:' . count($assemblies);
        foreach ($assemblies as $asm) {
            $parts[] = 'asm_mtime:' . filemtime("$org_path/$asm");
            // genome.json declares a BLAST-only genome; an edit in place does not touch the
            // directory's mtime, so without this a new "blast_only" waited for an unrelated change.
            if (is_file("$org_path/$asm/genome.json")) {
                $parts[] = 'genome_json:' . filemtime("$org_path/$asm/genome.json") . ':' . filesize("$org_path/$asm/genome.json");
            }
            // Gene_set subdirs sit one level below the assembly dir. On Linux, only direct
            // children affect a directory's mtime, so files changed inside a gene_set subdir
            // (e.g. BLAST indexes rebuilt) must be tracked here explicitly.
            foreach (glob("$org_path/$asm/*", GLOB_ONLYDIR) ?: [] as $gs_dir) {
                $parts[] = 'gs_mtime:' . basename($gs_dir) . ':' . filemtime($gs_dir);
            }
        }

        $fingerprints[$organism] = md5(implode('|', $parts));
    }

    return $fingerprints;
}

function organism_checklist_checks(string $organism_data, array $sequence_types, string $metadata_path): array
{
    $organisms_in_system = organism_checklist_organisms($organism_data);

    $raw_cache  = loadJsonFile(moop_organism_cache_file(), []);
    $cache_data = is_array($raw_cache) ? ($raw_cache['data'] ?? []) : [];
    $staleness  = moop_organism_cache_staleness(is_array($raw_cache) ? $raw_cache : [], $organism_data,
                      "$metadata_path/taxonomy_tree_config.json", "$metadata_path/organism_assembly_groups.json");
    $health     = computeDataHealthAlerts($organism_data);

    $missing_json = [];
    foreach ($organisms_in_system as $org) {
        if (!file_exists("$organism_data/$org/organism.json")) $missing_json[] = $org;
    }

    $groups_entries  = loadJsonFile("$metadata_path/organism_assembly_groups.json", []);
    $web_server_info = getWebServerUser();

    return [
        'organisms_in_system'      => $organisms_in_system,
        'cache_generated'          => is_array($raw_cache) ? ($raw_cache['generated'] ?? null) : null,
        'cache_stale_organisms'    => $staleness['changed'],
        'cache_stale_reasons'      => $staleness['reasons'],   // config change, older format
        'no_database_organisms'    => $health['no_database_organisms'],
        'empty_database_organisms' => $health['empty_database_organisms'],
        'missing_json'             => $missing_json,
        'blast_issues'             => organism_checklist_blast_issues($cache_data),
        'fai_issues'               => organism_checklist_fai_issues($cache_data),
        'expected_group'           => $web_server_info['group'],
        'permission_issues'        => organism_checklist_permission_issues($organism_data, $organisms_in_system, $web_server_info['group']),
        'permission_expectation'   => moop_permission_expectation('data', 'directory', false, true),
        'exec_files_fix_command'   => moop_permission_fix_exec_files_command($organism_data),
        'gene_sets_missing_gff'    => organism_checklist_gene_sets_missing_gff($organism_data, $organisms_in_system, $sequence_types),
        'fasta_gaps'               => getGeneSetFastaGaps($cache_data, $sequence_types),
        'seqname_gaps'             => getGeneSetSeqnameGaps($cache_data),
        'organisms_not_in_tree'    => getOrganismsNotInTree($cache_data),
        'unassigned_organisms'     => getUngroupedOrganisms($cache_data, is_array($groups_entries) ? $groups_entries : []),
    ];
}

