function moop_hierarchy_walk(array $seeds, $dbFile, $direction = 'up', array $gene_set_ids = []) {
    $seeds = array_values(array_unique(array_filter($seeds, static fn($s) => $s !== '' && $s !== null)));
    if (empty($seeds) || !file_exists($dbFile)) return [];

    $ph_seed = implode(',', array_fill(0, count($seeds), '?'));
    $params  = $seeds;

    $gs_seed = $gs_step = '';
    if (!empty($gene_set_ids)) {
        $ph_gs   = implode(',', array_fill(0, count($gene_set_ids), '?'));
        $gs_seed = "AND f.gene_set_id IN ($ph_gs)";
        $gs_step = "AND f.gene_set_id IN ($ph_gs)";
    }

    // The ONLY difference between the two directions is which way the JOIN points.
    $step_join = ($direction === 'down')
        ? 'f.parent_feature_id = w.feature_id'   // descend: my parent is the current node
        : 'f.feature_id = w.parent_feature_id';  // ascend:  the current node's parent is me

    $sql = "WITH RECURSIVE walk AS (
                SELECT f.feature_uniquename AS seed_name, f.feature_id, f.feature_uniquename,
                       f.feature_name, f.feature_description, f.feature_type,
                       f.parent_feature_id, 0 AS depth
                FROM   feature f
                WHERE  f.feature_uniquename IN ($ph_seed) $gs_seed
                UNION ALL
                SELECT w.seed_name, f.feature_id, f.feature_uniquename,
                       f.feature_name, f.feature_description, f.feature_type,
                       f.parent_feature_id, w.depth + 1
                FROM   feature f
                JOIN   walk w ON $step_join
                WHERE  w.depth < " . MOOP_HIERARCHY_MAX_DEPTH . "
                  AND  f.feature_id <> w.feature_id
                  $gs_step
            )
            SELECT seed_name, feature_id, feature_uniquename, feature_name,
                   feature_description, feature_type, parent_feature_id, depth
            FROM   walk";

    if (!empty($gene_set_ids)) {
        array_push($params, ...$gene_set_ids);   // seed clause
        array_push($params, ...$gene_set_ids);   // step clause
    }
    return fetchData($sql, $dbFile, $params);
}

function moop_hierarchy_nearest_of_type(array $seeds, $dbFile, array $types, array $gene_set_ids = []) {
    if (empty($types)) return [];
    $want = array_flip(array_map('strtolower', $types));

    $best = [];
    foreach (moop_hierarchy_walk($seeds, $dbFile, 'up', $gene_set_ids) as $row) {
        if (!isset($want[strtolower((string)$row['feature_type'])])) continue;
        $seed = (string)$row['seed_name'];
        $d    = (int)$row['depth'];
        if (!isset($best[$seed]) || $d < $best[$seed]['d']) {
            $best[$seed] = ['d' => $d, 'name' => (string)$row['feature_uniquename']];
        }
    }
    return array_map(static fn($b) => $b['name'], $best);
}

function moop_feature_gene_set_ids(string $feature_uniquename, string $dbFile, array $gene_set_ids): array {
    if (!$gene_set_ids) return [];
    $in   = implode(',', array_fill(0, count($gene_set_ids), '?'));
    $rows = fetchData("SELECT DISTINCT gene_set_id FROM feature
                        WHERE feature_uniquename = ? AND gene_set_id IN ($in) ORDER BY gene_set_id",
                      $dbFile, array_merge([$feature_uniquename], array_map('intval', $gene_set_ids)));
    return array_map('intval', array_column($rows, 'gene_set_id'));
}

function getAncestors($feature_uniquename, $dbFile, $gene_set_ids = []) {
    // Delegates to the shared walker (moop_hierarchy_walk). Was its own recursive CTE;
    // the cycle guards now live in one place instead of four. Column set and order are
    // unchanged -- callers still get [self, parent, grandparent, ...] with the same six
    // fields -- so this is a pure extraction.
    $rows = moop_hierarchy_walk([$feature_uniquename], $dbFile, 'up', $gene_set_ids);

    usort($rows, static fn($a, $b) => (int)$a['depth'] <=> (int)$b['depth']);

    $out = [];
    foreach ($rows as $r) {
        $out[] = [
            'feature_id'          => $r['feature_id'],
            'feature_uniquename'  => $r['feature_uniquename'],
            'feature_name'        => $r['feature_name'],
            'feature_description' => $r['feature_description'],
            'feature_type'        => $r['feature_type'],
            'parent_feature_id'   => $r['parent_feature_id'],
        ];
    }
    return $out;
}

function getChildren($feature_id, $dbFile, $gene_set_ids = []) {
    $params = [$feature_id];

    $gs_clause = '';
    if (!empty($gene_set_ids)) {
        $ph        = implode(',', array_fill(0, count($gene_set_ids), '?'));
        $gs_clause = "AND f.gene_set_id IN ($ph)";
        array_push($params, ...$gene_set_ids);
    }

    // Cycle-guarded, same reasoning as getAncestors() -- walking DOWN loops just as
    // readily as walking up. The seed also excludes a self-parented row, which
    // would otherwise be returned as its own child: a feature that is its own
    // parent is not a child of anything.
    $query = "WITH RECURSIVE descendants AS (
        SELECT f.feature_id, f.feature_uniquename, f.feature_name,
               f.feature_description, f.feature_type, f.parent_feature_id,
               0 AS depth
        FROM   feature f
        WHERE  f.parent_feature_id = ? $gs_clause
          AND  f.feature_id <> f.parent_feature_id
        UNION ALL
        SELECT f.feature_id, f.feature_uniquename, f.feature_name,
               f.feature_description, f.feature_type, f.parent_feature_id,
               d.depth + 1
        FROM   feature f
        JOIN   descendants d ON f.parent_feature_id = d.feature_id
        WHERE  d.depth < " . MOOP_HIERARCHY_MAX_DEPTH . "
          AND  f.feature_id <> d.feature_id
    )
    SELECT feature_id, feature_uniquename, feature_name,
           feature_description, feature_type, parent_feature_id
    FROM   descendants";

    return fetchData($query, $dbFile, $params);
}

function getChildrenHierarchical($feature_id, $dbFile, $gene_set_ids = []) {
    return childTreeFromRows($feature_id, getChildren($feature_id, $dbFile, $gene_set_ids));
}

function childTreeFromRows($feature_id, array $flat) {
    if (empty($flat)) return [];

    // Group all nodes by their parent_feature_id for O(1) child lookup
    $by_parent = [];
    foreach ($flat as $row) {
        $by_parent[$row['parent_feature_id']][] = $row;
    }

    // Recursively attach grandchildren starting from direct children of $feature_id
    return _buildChildTree($feature_id, $by_parent);
}

function _buildChildTree($parent_id, array &$by_parent, array $seen = []) {
    // getChildren()'s CTE rejects a row that is its own parent, and caps depth, but a
    // longer loop (A parents B, B parents A) still arrives here as two rows that point
    // at each other -- and this walk would then recurse until PHP ran out of memory.
    // Cheap insurance, and the loaders are known to have produced cyclic parentage.
    if (isset($seen[$parent_id])) {
        return [];
    }
    $seen[$parent_id] = true;

    $children = $by_parent[$parent_id] ?? [];
    foreach ($children as &$child) {
        $child['grandchildren'] = _buildChildTree($child['feature_id'], $by_parent, $seen);
    }
    unset($child);
    return $children;
}

function moop_annotation_card_anchor(string $uniquename): string {
    return 'annot_card_' . preg_replace('/[^a-zA-Z0-9_]/', '_', $uniquename);
}

function moop_type_word(?string $type): string {
    $type = trim((string) $type);
    if ($type === '') return '';
    if ($type === strtoupper($type))        return $type;   // CDS
    if (preg_match('/[A-Z]/', substr($type, 1))) return $type;   // mRNA, ncRNA
    return strtolower($type);
}

function moop_same_organism_hit_url(array $ctx, string $accession): ?string {
    if (($ctx['site'] ?? '') === '' || ($ctx['organism'] ?? '') === '' || trim($accession) === '') return null;
    // moop_url(), not '/' . site: the site setting is the folder name, not the start of a link (CLAUDE.md §3b)
    return moop_url('tools/parent.php?' . http_build_query(array_filter([
        'organism'   => $ctx['organism'],
        'assembly'   => $ctx['assembly'] ?? '',
        'gene_set'   => $ctx['gene_set'] ?? '',
        'uniquename' => trim($accession),
    ], 'strlen')));
}

function generateAnnotationTableHTML($results, $uniquename, $type, $count, $annotation_type, $desc, $color = 'warning', $organism = '', $annotation_type_key = '', array $link_ctx = []) {
    if (empty($results)) {
        return '';
    }

    $table_id = "annotTable_$count";
    $result_count = count($results);

    // What this table's Score column means, per source present (lib/annotation_scores.php).
    // Joined to the type's description in the (i) block; it alone is reason enough to show it.
    $score_help = moop_score_help_html($results);
    if ($score_help !== '') {
        $desc = ($desc ? $desc : '') . $score_help;
    }
    $desc_id = "annotDesc_$count";

    // Determine text color based on background color
    $text_color = in_array($color, ['warning', 'info', 'secondary']) ? 'text-dark' : 'text-white';

    // Border color matches badge color
    $border_class = "border-$color";

    // Create unique ID for this annotation section
    // Use annotation_type_key if provided, otherwise fall back to annotation_type
    $key_for_anchor = $annotation_type_key ?: $annotation_type;
    $section_id = "annot_section_" . preg_replace('/[^a-zA-Z0-9_]/', '_', $uniquename . '_' . $key_for_anchor);

    // data-annot-count is the ONE source of this number. The section nav (parent-nav.js)
    // reads the attribute rather than scraping the badge text, so the sidebar count and
    // the heading count cannot drift, and rewording the badge cannot silently break the nav.
    $html = '<div class="annotation-section mb-3 ' . htmlspecialchars($border_class) . '"'
          . ' id="' . htmlspecialchars($section_id) . '"'
          . ' data-annot-count="' . (int)$result_count . '">';
    $html .= '<div class="d-flex justify-content-between align-items-center mb-2">';
    // The count rides the CORNER of the type badge, the same treatment as the scope-filter
    // button in css/search-controls.css. It replaces a second full-size "N results" pill:
    // the word "results" is identical on every one of these headings down the page, so it
    // is pure repetition after the first two, and the number is what is actually scanned.
    // The wrapper must be position:relative for the absolute badge to hang off it.
    $html .= "<h5 class=\"mb-0\"><span class=\"annot-type-badge badge bg-" . htmlspecialchars($color) . " $text_color badge-lg\">"
           . htmlspecialchars($annotation_type)
           . "<span class=\"badge annot-count-badge\" title=\"" . htmlspecialchars($result_count)
           . " result" . ($result_count > 1 ? 's' : '') . "\">" . htmlspecialchars($result_count) . "</span>"
           . "</span>";

    if ($desc) {
        // NAME THE BUTTON. This is icon-only, so without an accessible name a screen
        // reader announces bare "button" and a mouse user gets no tooltip -- on a page
        // that renders seven of them, one per annotation section, all identical. The
        // label carries the annotation type so the seven are distinguishable rather than
        // seven copies of "More information".
        //
        // aria-controls pairs with the aria-expanded Bootstrap already toggles, so the
        // control is properly associated with the region it opens.
        $info_label = 'About ' . $annotation_type . ' annotations';
        $html .= "&nbsp;<button class=\"btn btn-sm btn-link p-0 annotation-info-btn\" type=\"button\""
               . " data-bs-toggle=\"collapse\" data-bs-target=\"#" . htmlspecialchars($desc_id) . "\""
               . " aria-controls=\"" . htmlspecialchars($desc_id) . "\" aria-expanded=\"false\""
               . " aria-label=\"" . htmlspecialchars($info_label) . "\""
               . " title=\"" . htmlspecialchars($info_label) . "\">";
        $html .= "<i class=\"fas fa-info-circle\" aria-hidden=\"true\"></i>";
        $html .= "</button>";
    }

    $html .= "</h5>";
    $html .= '<div class="d-flex gap-2 align-items-center">';
    $html .= '<div id="' . htmlspecialchars($table_id) . '_filter" class="dataTables_filter"></div>';
    $html .= '</div>';
    $html .= '</div>';

    if ($desc) {
        $html .= '<div class="collapse mb-3" id="' . htmlspecialchars($desc_id) . '">';
        $html .= '<div class="alert alert-info mb-0 font-size-xsmall">';
        $html .= $desc;
        $html .= '</div>';
        $html .= '</div>';
    }

    // KEGG pathways: grouped by class with links to KEGG's coloured map, above the full table (lib/kegg.php)
    $html .= moop_kegg_gene_pathways_html($results, (string)$uniquename, $link_ctx);

    // Table with DataTables
    $html .= "<div class=\"table-responsive\">";
    $html .= "<table id=\"" . htmlspecialchars($table_id) . "\" class=\"table table-sm table-striped table-hover substring-search\" style=\"width:100%;\">";
    $html .= "<thead><tr>";
    $html .= "<th class=\"export-only\">Organism</th>";
    $html .= "<th class=\"export-only\">Feature ID</th>";
    $html .= "<th class=\"export-only\">Feature Type</th>";
    $html .= "<th class=\"export-only\">Annotation Type</th>";
    $html .= "<th>Annotation ID</th>";
    $html .= "<th>Description</th>";
    $html .= "<th title=\"What the score means depends on the source. Hover a value, or open the (i) above.\">Score</th>";
    $html .= "<th>Source</th>";
    $html .= "</tr></thead>";
    $html .= "<tbody>";

    foreach ($results as $row) {
        $hit_id = htmlspecialchars(trim($row['annotation_accession']));
        $hit_description = htmlspecialchars($row['annotation_description']);
        // feature_annotation.score is REAL and NULLABLE since the 2026-07-24 schema change
        // (df088cb). It used to be TEXT NOT NULL, where annotation types carrying no score
        // stored the literal string "-" -- 43% of rows in the sampled organism. Those load
        // as NULL now, so without this the column renders as a blank cell where it used to
        // read "-", and the reader cannot tell "no score" from "we failed to show it".
        // Also keeps NULL out of htmlspecialchars(), which is deprecated in PHP 8.1+.
        //
        // Formatted by what the number IS for this source (lib/annotation_scores.php): an OMA
        // "4" reads "many:many", a closest-gene "1" reads "OMA ortholog", an E-value is
        // shortened. data-order keeps sorting on the stored number; data-export gives a
        // download the full number, or the words where the number is only a code.
        $score_cell = moop_format_score($row['score'],
            moop_score_kind((string)$row['annotation_type'], (string)$row['annotation_source_name']));
        $hit_score = $score_cell['display'];
        // gloss() rather than htmlspecialchars(): a source name like PANTHER, RBBH, EggNOG,
        // InterPro or ProtNLM is an opaque acronym that nothing else on the site explains.
        // The annotation TYPE has a description (annotation_config.json, opened by the (i)
        // beside each section); the source that produced the call did not.
        //
        // Safe as a drop-in. gloss() falls back to the escaped plain word when the term is
        // not in the glossary, so every other source renders exactly as before, and it
        // escapes internally — this is not a lost htmlspecialchars().
        //
        // Export is unaffected: DataTableExportConfig's format.body strips tags with
        // /<[^>]+>/, so the cell exports as "PANTHER", and the definition — escaped into a
        // data- attribute — goes with the tag.
        //
        // gloss_terms_in(), not gloss(): source names are compounds. Only 2 of the 46 on
        // this deployment are a bare term; 25 are "InterProScan (member)" and 17 are
        // "Ensembl species". Glossing the whole string would match almost none of them.
        $annotation_source = gloss_terms_in($row['annotation_source_name']);
        // NULL when the source has no per-accession page to link to (SignalP,
        // DeepTMHMM -- see load_annotations_sqlite.pl). Render plain text
        // instead of a broken relative link, and guard against NULL the same
        // way $hit_score does above (trim()/htmlspecialchars() on null is
        // deprecated in PHP 8.1+).
        $raw_accession_url = $row['annotation_accession_url'];
        $has_link = $raw_accession_url !== null && trim($raw_accession_url) !== '';
        $hit_id_cell = $hit_id;
        $same_org_url = (!$has_link && in_array($row['annotation_type'] ?? '', MOOP_SAME_ORGANISM_ANNOTATION_TYPES, true))
            ? moop_same_organism_hit_url($link_ctx, (string)$row['annotation_accession']) : null;
        if ($same_org_url !== null) {
            // Same site, so the same tab — unlike the outside links below.
            $hit_id_cell = '<a href="' . htmlspecialchars($same_org_url) . '" title="Open this gene\'s page">' . $hit_id . '</a>';
        } elseif ($has_link) {
            $annotation_accession_url = htmlspecialchars(trim($raw_accession_url));
            $hit_id_link = $annotation_accession_url . urlencode(trim($row['annotation_accession']));
            $hit_id_cell = "<a href=\"" . htmlspecialchars($hit_id_link) . "\" target=\"_blank\">" . $hit_id . "</a>";
            // A GO term: the ID opens OUR term page (its genes in this site's organisms, where it sits in GO),
            // the stored outside page (AmiGO) moves to a small icon. Only when GO is built on this site.
            $acc = trim((string) $row['annotation_accession']);
            if (preg_match('/^GO:\d{7}$/', $acc) && moop_go_term_page_available()) {
                // Narrowed to this gene's organism (Sofia, 2026-11-25); the term page offers the way out to all.
                // open_*: this gene's own gene set, whose gene list the term page opens; the organism's
                // other assemblies / gene sets stay listed in its table.
                $term_org = (string) ($link_ctx['organism'] ?? $organism);
                $term_url = moop_url('tools/ontology_term.php') . '?' . http_build_query(['o' => 'GO', 'id' => $acc]
                          + ($term_org !== '' ? ['organism' => $term_org] : [])
                          + (($link_ctx['assembly'] ?? '') !== '' && ($link_ctx['gene_set'] ?? '') !== ''
                             ? ['open_assembly' => $link_ctx['assembly'], 'open_gene_set' => $link_ctx['gene_set']] : []));
                $hit_id_cell = '<a href="' . htmlspecialchars($term_url) . '" title="' . t('Open this GO term on this site') . '">' . $hit_id . '</a>'
                             . ' <a href="' . htmlspecialchars($hit_id_link) . '" target="_blank" rel="noopener" class="text-muted"'
                             . ' title="' . t('Open this GO term in AmiGO') . '" aria-label="' . t('Open this GO term in AmiGO') . '">'
                             . '<i class="fa fa-external-link-alt link-icon" aria-hidden="true"></i></a>';
            }
        }

        $html .= "<tr>";
        $html .= "<td class=\"export-only\">" . htmlspecialchars($organism) . "</td>";
        $html .= "<td class=\"export-only\">" . htmlspecialchars($uniquename) . "</td>";
        $html .= "<td class=\"export-only\">" . htmlspecialchars($type) . "</td>";
        $html .= "<td class=\"export-only\">" . htmlspecialchars($annotation_type) . "</td>";
        $html .= "<td>" . $hit_id_cell . "</td>";
        $html .= "<td>" . $hit_description . "</td>";
        $html .= '<td data-order="' . htmlspecialchars($score_cell['order']) . '"'
               . ' data-export="' . htmlspecialchars($score_cell['export']) . '"'
               . ($score_cell['title'] !== '' ? ' title="' . htmlspecialchars($score_cell['title']) . '"' : '')
               . '>' . $hit_score . '</td>';
        $html .= "<td>" . $annotation_source . "</td>";
        $html .= "</tr>";
    }

    $html .= "</tbody></table>";
    $html .= "</div>";
    $html .= "</div>";

    return $html;
}

function getAllAnnotationsForFeatures($feature_ids, $dbFile, $gene_set_ids = []) {
    if (empty($feature_ids)) {
        return [];
    }

    $placeholders = implode(',', array_fill(0, count($feature_ids), '?'));

    // Build WHERE clause with optional genome filtering
    $where_clause = "f.feature_id IN ($placeholders)";
    $params = $feature_ids;

    if (!empty($gene_set_ids)) {
        $gene_set_placeholders = implode(',', array_fill(0, count($gene_set_ids), '?'));
        $where_clause .= " AND f.gene_set_id IN ($gene_set_placeholders)";
        $params = array_merge($params, $gene_set_ids);
    }

    $query = "SELECT f.feature_id, f.feature_uniquename, f.feature_type,
              a.annotation_accession, a.annotation_description,
              fa.score, " . moop_annotation_date_expr($dbFile) . " AS date,
              ans.annotation_source_name, ans.annotation_accession_url, ans.annotation_type
        FROM annotation a, feature f, feature_annotation fa, annotation_source ans, gene_set gs, genome g, organism o
        WHERE f.organism_id = o.organism_id
          AND f.gene_set_id = gs.gene_set_id
          AND gs.genome_id = g.genome_id
          AND ans.annotation_source_id = a.annotation_source_id
          AND f.feature_id = fa.feature_id
          AND fa.annotation_id = a.annotation_id
          AND $where_clause
        ORDER BY f.feature_id, ans.annotation_type";

    $results = fetchData($query, $dbFile, $params);

    // Organize by feature_id and annotation_type
    $organized = [];
    foreach ($results as $row) {
        $feature_id = $row['feature_id'];
        $annotation_type = $row['annotation_type'];

        if (!isset($organized[$feature_id])) {
            $organized[$feature_id] = [];
        }
        if (!isset($organized[$feature_id][$annotation_type])) {
            $organized[$feature_id][$annotation_type] = [];
        }

        $organized[$feature_id][$annotation_type][] = $row;
    }

    return $organized;
}

function getGeneNaming($feature_id, $dbFile): array {
    $empty = ['statements' => [], 'data_version' => null];
    try {
        $dbh = getDbConnection($dbFile);
        $has = $dbh->query("SELECT COUNT(*) FROM sqlite_master
                            WHERE type = 'table' AND name IN ('gene_naming', 'gene_naming_link')")
                   ->fetchColumn();
        if ((int)$has < 2) {
            return $empty;
        }
        $stmt = $dbh->prepare(
            "SELECT n.kind, n.link_kind, n.sort_order, n.naming_text, n.accession, l.accession_url
             FROM gene_naming n
             LEFT JOIN gene_naming_link l ON l.link_kind = n.link_kind
             WHERE n.feature_id = ? AND n.kind <> 'name_source'
             ORDER BY n.sort_order, n.kind");
        $stmt->execute([$feature_id]);
        $statements = [];
        foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $r) {
            $r['url'] = ($r['accession'] !== null && $r['accession'] !== '' && !empty($r['accession_url']))
                // ':' kept literal: HGNC's own links read ".../hgnc_id/HGNC:21625", and a
                // colon is legal there. Everything else is still encoded.
                ? $r['accession_url'] . str_replace('%3A', ':', rawurlencode($r['accession']))
                : null;
            $statements[] = $r;
        }
        if (empty($statements)) {
            return $empty;
        }

        $version = null;
        $run = $dbh->query("SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = 'gene_naming_run'")
                   ->fetchColumn();
        if ((int)$run > 0) {
            $v = $dbh->prepare("SELECT r.data_version FROM gene_naming_run r
                                JOIN feature f ON f.gene_set_id = r.gene_set_id
                                WHERE f.feature_id = ?");
            $v->execute([$feature_id]);
            $version = $v->fetchColumn() ?: null;
        }
        return ['statements' => $statements, 'data_version' => $version];
    } catch (PDOException $e) {
        error_log('getGeneNaming: ' . $e->getMessage());
        return $empty;
    }
}

function moop_resolve_naming_protein(string $accession, array $children, $gene_id): ?array {
    if ($accession === '' || empty($children)) return null;
    $by_id = [];
    $by_name = [];
    foreach ($children as $c) {
        $by_id[$c['feature_id']] = $c;
        $by_name[$c['feature_uniquename']] = $c;
    }
    $bare = preg_replace('/:pep$/', '', $accession);
    $hit = null;
    foreach ([$accession, $bare . ':pep', $bare] as $candidate) {
        if (isset($by_name[$candidate])) { $hit = $by_name[$candidate]; break; }
    }
    if ($hit === null) return null;

    // Up to the transcript that hangs directly off the gene (protein -> cds -> mRNA).
    $protein = _fasta_key_for_type((string)$hit['feature_type']) === 'protein' ? $hit['feature_uniquename'] : null;
    $node = $hit;
    for ($guard = 0; $guard < 10 && (string)$node['parent_feature_id'] !== (string)$gene_id; $guard++) {
        if (!isset($by_id[$node['parent_feature_id']])) return null;
        $node = $by_id[$node['parent_feature_id']];
    }
    if ((string)$node['parent_feature_id'] !== (string)$gene_id) return null;

    // Given an mRNA id, the protein is the one beneath it.
    if ($protein === null) {
        foreach ($children as $c) {
            if (_fasta_key_for_type((string)$c['feature_type']) !== 'protein') continue;
            for ($n = $c, $g = 0; $g < 10 && isset($by_id[$n['parent_feature_id']]); $g++) {
                $n = $by_id[$n['parent_feature_id']];
                if ($n['feature_id'] === $node['feature_id']) { $protein = $c['feature_uniquename']; break 2; }
            }
        }
    }
    return ['protein' => $protein, 'mrna' => $node['feature_uniquename']];
}

function moop_gene_naming_label(string $kind): string {
    static $labels = [
        'support'       => 'Support',
        // "Isoform", not "Protein": the overview already has a Protein line (the length of
        // the longest), and two lines both called Protein would read as a contradiction
        // whenever the naming protein is not the longest.
        'protein'       => 'Isoform',
        'copies'        => 'Copies',
        'identical'     => 'Identical proteins',
        'alignment'     => 'Alignment',
        'domains'       => 'Domains',
        'tree'          => 'Tree',
        'cautions'      => 'Cautions',
        'features'      => 'Features',
        'expression'    => 'Expression',
        'pipeline_name' => 'MOOP name',
    ];
    return $labels[$kind] ?? ucfirst(str_replace('_', ' ', $kind));
}

function generateTreeHTML(array $children, $all_annotations = [], $analysis_order = [], $depth = 0,
                          array $protein_lengths = [], string $longest_protein = '',
                          string $naming_protein = '') {
    if ($depth >= MOOP_HIERARCHY_MAX_DEPTH || empty($children)) {
        return '';
    }

    $results = array_values($children);

    $html = "<ul>";
    $total = count($results);

    foreach ($results as $index => $row) {
        $is_last_child = ($index === $total - 1);

        $feature_type = htmlspecialchars($row['feature_type']);
        $feature_name = htmlspecialchars($row['feature_uniquename']);
        $child_feature_id = $row['feature_id'];

        // Color code badges by feature type
        $badge_class = 'bg-secondary';
        $text_color = 'text-white';

        if ($feature_type == 'mRNA') {
            $badge_class = 'bg-feature-mrna';
            $text_color = 'text-white';
        } elseif ($feature_type == 'CDS') {
            $badge_class = 'bg-info';
            $text_color = 'text-white';
        } elseif ($feature_type == 'exon') {
            $badge_class = 'bg-warning';
            $text_color = 'text-dark';
        } elseif ($feature_type == 'gene') {
            $badge_class = 'bg-feature-gene';
            $text_color = 'text-white';
        } elseif ($feature_type == 'protein' || $feature_type == 'polypeptide') {
            $badge_class = 'bg-feature-protein';
            $text_color = 'text-white';
        }

        // Calculate annotation count for this child
        $child_annot_count = 0;
        if (isset($all_annotations[$child_feature_id])) {
            foreach ($all_annotations[$child_feature_id] as $annotation_type => $annots) {
                $child_annot_count += count($annots);
            }
        }

        // Link to the child's CARD — but ONLY if that card is actually rendered.
        //
        // Cards exist for children that carry annotations; cds and protein rows do not get
        // one, because there is no annotation section for them anywhere on the page. They
        // were still linked, so 7 of the 10 hierarchy links on a 3-isoform gene went
        // nowhere: a link that looks live, does nothing, and gives no reason why.
        //
        // Previously ALL of them were dead (they targeted "$analysis_order[0]", which only
        // exists if the child happens to have that annotation type), so this was invisible
        // — the mRNA rows started working first, which is what made the cds/protein rows
        // stand out as broken rather than as uniformly inert.
        $child_annot_anchor = moop_annotation_card_anchor($row['feature_uniquename']);
        $child_has_card     = $child_annot_count > 0;

        // Tree character - └── for last child, ├── for others
        $tree_char = $is_last_child ? '└── ' : '├── ';

        $html .= "<li>";
        $html .= "<span class=\"tree-char\">$tree_char</span>";
        if ($child_has_card) {
            $html .= "<a href=\"#$child_annot_anchor\" class=\"link-light-bordered text-decoration-none\"><span class=\"text-dark\">$feature_name</span></a> ";
        } else {
            // Plain text: nothing to jump to, so do not dress it as a link.
            $html .= "<span class=\"text-dark\">$feature_name</span> ";
        }
        $html .= "<span class=\"badge $badge_class $text_color\">$feature_type</span>";

        // Add annotation count badge if there are annotations
        if ($child_annot_count > 0) {
            $html .= " <span class=\"badge bg-success text-white badge-sm\">$child_annot_count annotation" . ($child_annot_count > 1 ? 's' : '') . "</span>";
        }

        // Nested children were fetched with the parent, in the same CTE.
        // Protein length; "longest" only when there is more than one to choose between —
        // that is the protein the overview's length and the naming Features describe.
        if (isset($protein_lengths[$row['feature_uniquename']])) {
            $html .= ' <span class="tree-length">' . number_format($protein_lengths[$row['feature_uniquename']]) . ' aa';
            if (count($protein_lengths) > 1 && $row['feature_uniquename'] === $longest_protein) {
                $html .= ' · longest';
            }
            if ($row['feature_uniquename'] === $naming_protein) {
                $html .= ' · used for naming';
            }
            $html .= '</span>';
        }

        $html .= generateTreeHTML($row['grandchildren'] ?? [], $all_annotations, $analysis_order, $depth + 1,
                                  $protein_lengths, $longest_protein, $naming_protein);
        $html .= "</li>";
    }
    $html .= "</ul>";

    return $html;
}

function generateChildAnnotationCards($child, $all_annotations, $analysis_order, $annotation_colors, $annotation_labels, $analysis_desc, $organism_name, &$count, $is_grandchild = false, $annotated_child_types = [], array $link_ctx = []) {
    $child_feature_id = $child['feature_id'];
    $child_uniquename = $child['feature_uniquename'];
    $child_type = $child['feature_type'];

    // Skip feature types that never carry annotations in this gene set
    if (!empty($annotated_child_types) && !in_array($child_type, $annotated_child_types)) {
        return '';
    }

    // Count annotations for this child
    $child_annotation_count = 0;
    foreach ($analysis_order as $annotation_type) {
        $annot_results = $all_annotations[$child_feature_id][$annotation_type] ?? [];
        if (!empty($annot_results)) {
            $child_annotation_count += count($annot_results);
        }
    }

    // Determine header styling based on feature type and nesting level
    $header_class = 'child-feature-header';
    $badge_class = 'bg-feature-mrna';

    if ($is_grandchild) {
        $header_class = 'child-feature-header grandchild-feature-header';
        if ($child_type == 'protein' || $child_type == 'polypeptide') {
            $badge_class = 'bg-feature-protein';
        } else {
            $badge_class = 'bg-secondary';
        }
    }

    // data-annot-total feeds the same count into the section nav for the CHILD row, so a
    // reader can see how much sits under an mRNA without expanding it.
    $html = '<div class="card annotation-card border-info"'
          . ' id="' . htmlspecialchars(moop_annotation_card_anchor($child_uniquename)) . '"'
          . ' style="scroll-margin-top:20px;"'
          . ' data-annot-total="' . (int)$child_annotation_count . '">';
    $html .= "  <div class=\"card-header d-flex align-items-center $header_class\">";
    $html .= "    <span class=\"collapse-section\" data-bs-toggle=\"collapse\" data-bs-target=\"#child_$child_feature_id\" aria-expanded=\"true\" role=\"button\">";
    $html .= "      <i class=\"fas fa-minus toggle-icon text-info\"></i>";
    $html .= "    </span>";
    $html .= "    <span class=\"ms-2 text-white px-2 py-1 rounded child-feature-badge $badge_class badge-md\">$child_uniquename ($child_type)</span>";

    // Annotation-type navigation now lives in the section sidebar (parent-nav.js),
    // so per-type chips are no longer shown next to the child name.
    //
    // The TOTAL earns its place when the card is COLLAPSED: folded shut, the header is all
    // a reader has, and "which of these 17 transcripts is worth opening" is exactly what
    // the count answers. Zero is stated in words rather than as "0", because a transcript
    // with nothing on it is a different thing from one you have not opened yet.
    if ($child_annotation_count === 0) {
        $html .= " <span class=\"badge bg-secondary ms-2 child-annot-count\">No annotations</span>";
    } else {
        // The NUMBER alone. "12 annotations" repeated down seventeen headers is the same
        // word seventeen times; the count is the only part that varies, and it matches the
        // pills already used on the type badges and in the section nav. The full phrasing
        // stays in the tooltip for anyone who needs it spelled out.
        $n = number_format($child_annotation_count);
        $html .= " <span class=\"badge rounded-pill ms-2 child-annot-count\" title=\"$n annotation"
               . ($child_annotation_count === 1 ? '' : 's') . " across all types\">" . $n . "</span>";
    }

    $html .= '  </div>';
    $html .= "  <div id=\"child_$child_feature_id\" class=\"collapse show\">";
    $html .= '    <div class="card-body">';

    $child_has_annotations = false;
    foreach ($analysis_order as $annotation_type) {
        $count++;
        $annot_results = $all_annotations[$child_feature_id][$annotation_type] ?? [];
        if (!empty($annot_results)) {
            $child_has_annotations = true;
            $color = $annotation_colors[$annotation_type] ?? 'warning';
            $display_label = $annotation_labels[$annotation_type] ?? $annotation_type;
            $html .= generateAnnotationTableHTML($annot_results, $child_uniquename, $child_type, $count, $display_label, $analysis_desc[$annotation_type] ?? '', $color, $organism_name, $annotation_type, $link_ctx);
        }
    }

    if (!$child_has_annotations) {
        $type_label = ($child_type === 'mRNA') ? 'transcript' : strtolower($child_type);
        $html .= "<p class=\"text-muted\"><i class=\"fas fa-info-circle\"></i> No annotations loaded for this $type_label.</p>";
    }

    // Render grandchildren (recursively)
    if (!empty($child['grandchildren'])) {
        foreach ($child['grandchildren'] as $grandchild) {
            $html .= generateChildAnnotationCards($grandchild, $all_annotations, $analysis_order, $annotation_colors, $annotation_labels, $analysis_desc, $organism_name, $count, true, $annotated_child_types, $link_ctx);
        }
    }

    $html .= '    </div>';
    $html .= '  </div>';
    $html .= '</div>';

    return $html;
}

