function moop_permission_item_mode(array $item): string {
    return (string)($item['check_mode'] ?? moop_permission_check_mode((string)$item['name']));
}

function moop_permission_check_mode(string $name): string {
    // 'secret' — private key material.
    if ($name === 'JWT Key Files' || $name === 'JWT Certificates Directory') return 'secret';

    // 'writable' — the ONLY paths the web server (apache/httpd_t) legitimately writes,
    // straight from the table in docs/SELINUX_AND_HARDENING.md §55. Everything else is
    // read-only served content.
    //
    // NOTE on organisms/: the tree IS writable to apache by design (§73 — the web builds
    // BLAST/.fai indexes in place), but its entries stay 'data' here deliberately. The
    // *directories* need apache write (makeblastdb creates new files); the FASTA/SQLite
    // *files* do not, and should stay unwritable. performPermissionCheck's 'data' branch
    // therefore checks writability for data-tree DIRECTORIES only.
    //
    // (An earlier version of this comment claimed 'data' mode "already reports a softened
    // not-writable for data trees". It did not — the check did not exist, and 22 assembly
    // dirs at 2755 were invisible to the dashboard because of it. Do not trust a comment
    // that says a check exists; grep for the check.)
    static $writable = [
        'Logs Directory'                  => 1,  // error.log, login_attempts.json
        'Site Configuration Files'        => 1,  // config/config_editable.json (admin UI)
        'Metadata Configuration Files'    => 1,  // metadata/*.json
        'Site Data Backup Directory'      => 1,  // site_data_path — housekeeping writes here
        'Site Data Backup Files'          => 1,  // the snapshot rewrites these in place
        'Taxonomy Lineage Cache'          => 1,  // metadata/taxonomy_lineage_cache.json
        'Metadata Directory'              => 1,
        'Content Pages Directory'         => 1,  // metadata/pages — Admin -> Manage Pages writes here
        'Translations Directory'          => 1,  // metadata/translations — Admin -> Manage Translations
        'Metadata Backups Directory'      => 1,
        'Change Log Directory'            => 1,
        'JBrowse2 Track Config Directory' => 1,  // metadata/jbrowse2-configs
        'Genome Data Directory'           => 1,  // data/genomes — gff.gz + tabix
        'Cache Directory'                 => 1,  // cache_path
        'Temp Directory'                  => 1,  // lib/temp_dir.php: BLAST, primer, MAFFT temp files
        'Organism Cache File'             => 1,  // under cache_path
        'Gene Set Identity Cache'         => 1,  // under cache_path — lib/gene_set_identity.php
        'Images Directory'                => 1,  // images/ — organism images upload HERE, flat
                                                //   (handle_image_upload.php -> absolute_images_path)
        'Documentation Directory'         => 1,  // docs/ — the admin "Generate registry" button
                                                //   rewrites function_registry.json here
        'Function Registry Files'         => 1,  // docs/*function_registry.json — rewritten in
                                                //   place, so the FILE must be group-writable
        'NCBI Taxonomy Images Cache'      => 1,  // images/ncbi_taxonomy (php downloads)
        'Wikimedia Images Cache'          => 1,  // images/wikimedia (php downloads)
        'Banner Images Directory'         => 1,  // images/banners — admin UI uploads/deletes
        'Organism Metadata Files'         => 1,  // organisms/*/organism.json — admin UI edits in place
    ];
    if (isset($writable[$name])) return 'writable';

    // Default: read-only served content (FASTA/genome/SQLite, the organism tree,
    // top-level images/, docs, data/tracks, jbrowse2/ app dir).
    return 'data';
}

function moop_permission_expectation(string $mode, string $type, bool $sensitive = false, bool $build_dir = false): string {
    $is_dir = ($type === 'directory');
    // Sensitivity is a separate axis from the check_mode — a path can be web-writable AND
    // hold credentials — so it is appended rather than switched on.
    $suffix = $sensitive ? '; holds credentials, so must not be readable by other users on the host' : '';
    switch ($mode) {
        case 'secret':
            return 'Readable by the web server; not accessible to any other user on the host';
        case 'writable':
            return ($is_dir
                ? 'Writable by the web server; SGID so new files inherit the group; not world-writable'
                : 'Writable by the web server; not world-writable; not executable') . $suffix;
        default:
            if ($is_dir && $build_dir) {
                // moop_permission_needs_build_write(): data the web server also builds into.
                return 'Writable by the web server (in-app builds create files here); SGID and the web '
                     . 'server group so new files inherit it; not world-writable' . $suffix;
            }
            return ($is_dir
                ? 'Readable and traversable by the web server; not world-writable'
                : 'Readable by the web server; not world-writable; not executable') . $suffix;
    }
}

function moop_permission_sensitive_paths($config, array $ctx): array {
    $paths = [];
    foreach (moop_build_permission_items($config, $ctx) as $item) {
        if (empty($item['sensitive'])) continue;
        foreach (($item['paths'] ?? []) as $p) {
            $p = rtrim((string)$p, '/');
            if ($p !== '') $paths[$p] = true;
        }
    }
    return $paths;
}

function moop_permission_dir_mode(string $dir, array $sensitive_paths): string {
    $dir = rtrim($dir, '/');
    if ($dir === '') return '2775';
    if (isset($sensitive_paths[$dir])) return '2770';
    foreach (array_keys($sensitive_paths) as $p) {
        if (strpos($p, $dir . '/') === 0) return '2770';
    }
    return '2775';
}

function moop_permission_fix_commands(array $check, string $moop_owner): array {
    $path = (string)($check['path'] ?? '');
    if ($path === '') return [];

    $mode   = (string)($check['check_mode'] ?? 'data');
    $is_dir = (($check['type'] ?? 'file') === 'directory');
    $q      = escapeshellarg($path);
    $R      = $is_dir ? '-R ' : '';
    $bits   = octdec((string)($check['current_perms'] ?? '0'));
    $group  = (string)($check['required_group'] ?? '');
    $sensitive = !empty($check['sensitive']);
    $cmds   = [];

    // A wrong SELinux label cannot be fixed with chmod — say so first, it is the real gate.
    foreach (($check['issues'] ?? []) as $issue) {
        if (strpos((string)$issue, 'SELinux label') !== false) {
            $cmds[] = 'sudo scripts/fix_moop_selinux.sh   # label is the real gate — chmod will not help';
            break;
        }
    }

    if (empty($check['exists'])) {
        // A missing FILE has no group or mode to change: chgrp/chmod on it just fails.
        if (!$is_dir) return $cmds;
        $cmds[] = "sudo mkdir -p $q";
    }
    if ($mode === 'writable') {
        if ($group !== '' && (string)($check['current_group'] ?? '') !== $group) {
            $cmds[] = 'sudo chgrp ' . $R . escapeshellarg($group) . " $q";
        }
        if (empty($check['is_writable'])) {
            $cmds[] = $is_dir ? "sudo chmod -R g+rwX $q && sudo chmod g+s $q" : "sudo chmod g+rw $q";
        }
    } elseif ($mode === 'secret') {
        if (empty($check['is_readable'])) {
            $cmds[] = $is_dir ? "sudo chmod 2770 $q" : "sudo chmod 640 $q";
        }
    } else {
        if (empty($check['is_readable'])) $cmds[] = "sudo chmod {$R}g+rX $q";

        // Data directories the web server builds into (performPermissionCheck's
        // needs_build_write branch). DIRECTORIES only: `chmod -R 2775` would also mark
        // every genome, database and index file executable -- which is how 234 such
        // files got that way here.
        if ($is_dir && moop_permission_needs_build_write((string)($check['name'] ?? ''))) {
            if ($group !== '' && (string)($check['current_group'] ?? '') !== $group) {
                $cmds[] = 'sudo chgrp -R ' . escapeshellarg($group) . " $q";
            }
            if (empty($check['is_writable']) || ($bits & 02000) === 0) {
                $cmds[] = "sudo find $q -type d -exec chmod g+rwxs {} +";
            }
        }
    }

    // A path holding credentials that is open to `other`. Independent of check_mode: the
    // site-data backup is written by housekeeping AND holds users.json/secrets.php.
    //
    // 2770 for a directory, NOT 640 — which is what this used to print for every 'secret'
    // path regardless of type. `chmod 640 certs/` strips the traverse bit and locks the web
    // server out of the very keys it exists to read, so the advice broke the thing it was
    // fixing. 2770 keeps owner+group (the web server) working and drops world entirely.
    if (($sensitive || $mode === 'secret') && ($bits & 0007) !== 0) {
        $cmds[] = $is_dir ? "sudo chmod 2770 $q" : "sudo chmod 640 $q";
    }
    if (($bits & 0002) === 0002) $cmds[] = "sudo chmod {$R}o-w $q";
    if (!$is_dir && ($bits & 0111) !== 0) $cmds[] = "sudo chmod a-x $q";

    return $cmds;
}

function moop_permission_fix_exec_files_command(string $organism_data): string {
    return 'sudo find ' . escapeshellarg($organism_data) . ' -type f -exec chmod a-x {} +';
}

function moop_permission_consolidate(array $checks, string $organism_data = ''): array {
    $root   = rtrim($organism_data, '/') . '/';
    $groups = [];
    foreach ($checks as $c) {
        if (empty($c['issues'])) continue;
        $issues = array_map(fn($i) => preg_replace('/ \(\d{3,4}\)/', '', (string)$i), $c['issues']);
        $key    = implode("\n", $issues);
        $path   = (string)($c['path'] ?? '');
        $org    = '';
        if ($organism_data !== '' && strpos($path, $root) === 0) {
            $org = explode('/', substr($path, strlen($root)), 2)[0];
        }
        if (!isset($groups[$key])) {
            $groups[$key] = ['issues' => $issues, 'count' => 0, 'perms' => [], 'by_organism' => [], 'first' => $c, 'checks' => []];
        }
        $g = &$groups[$key];
        $g['count']++;
        $perm = (string)($c['current_perms'] ?? '');
        if ($perm !== '') $g['perms'][$perm] = ($g['perms'][$perm] ?? 0) + 1;
        $g['by_organism'][$org][] = $path;
        $g['checks'][] = $c;
        unset($g);
    }
    $groups = array_values($groups);
    usort($groups, fn($a, $b) => $b['count'] <=> $a['count']);
    return $groups;
}

function moop_permission_merged_fix_commands(array $checks, string $moop_owner): array {
    $merged = [];   // prefix => [quoted paths]
    $order  = [];   // first-seen order across merged and verbatim commands
    foreach ($checks as $c) {
        $q = escapeshellarg((string)($c['path'] ?? ''));
        foreach (moop_permission_fix_commands($c, $moop_owner) as $cmd) {
            $tail = ' ' . $q;
            if (substr($cmd, -strlen($tail)) === $tail && substr_count($cmd, $q) === 1) {
                $prefix = substr($cmd, 0, -strlen($tail));
                if (!isset($merged[$prefix])) { $merged[$prefix] = []; $order[] = ['m', $prefix]; }
                $merged[$prefix][$q] = true;
            } elseif (!in_array(['v', $cmd], $order, true)) {
                $order[] = ['v', $cmd];
            }
        }
    }
    $out = [];
    foreach ($order as [$kind, $val]) {
        $out[] = $kind === 'v' ? $val : $val . ' ' . implode(' ', array_keys($merged[$val]));
    }
    return $out;
}

function moop_selinux_enforcing(): bool {
    static $enf = null;
    if ($enf !== null) return $enf;
    // Read the kernel state directly — PATH-independent. php-fpm runs with a restricted
    // PATH (often no /usr/sbin, where getenforce lives), so shell_exec('getenforce') would
    // return empty under the web server and silently disable the label check.
    $f = @file_get_contents('/sys/fs/selinux/enforce');
    if ($f !== false && $f !== '') return $enf = (trim($f) === '1');
    // Fallback: getenforce by absolute path.
    foreach (['/usr/sbin/getenforce', '/sbin/getenforce'] as $bin) {
        if (is_executable($bin)) {
            $out = @trim((string) shell_exec(escapeshellarg($bin) . ' 2>/dev/null'));
            return $enf = (strcasecmp($out, 'Enforcing') === 0);
        }
    }
    return $enf = false;
}

function moop_selinux_type(string $path): ?string {
    $out = [];
    @exec('ls -dZ ' . escapeshellarg($path) . ' 2>/dev/null', $out);
    if (empty($out[0])) return null;
    // context: user_u:object_r:<type>:s0
    return preg_match('/:([a-z0-9_]+_t):/', $out[0], $m) ? $m[1] : null;
}

function moop_permission_category(string $name): string {
    if (str_starts_with($name, 'FASTA File:'))            return 'Sequence files (FASTA)';
    if (str_starts_with($name, 'Assembly Subdirectory:')) return 'Assembly directories';
    if (str_starts_with($name, 'Gene Set Subdirectory:')) return 'Gene-set directories';
    if ($name === 'Organism Directory')                   return 'Organism directories';
    return $name;
}

function moop_permission_is_data_tree(string $name): bool {
    if (str_starts_with($name, 'Assembly Subdirectory:')) return true;
    if (str_starts_with($name, 'Gene Set Subdirectory:')) return true;
    return in_array($name, [
        'Organism Data Directories', 'Organism Directory', 'Genome Data Directory',
        'Track Data Directory',
    ], true);
}

function moop_permission_needs_build_write(string $name): bool {
    if (str_starts_with($name, 'Assembly Subdirectory:')) return true;
    if (str_starts_with($name, 'Gene Set Subdirectory:')) return true;
    return in_array($name, ['Organism Data Directories', 'Organism Directory'], true);
}

function moop_permission_organism_dir_rule(string $web_group): array {
    return [
        'name' => 'Organism Directory',
        'type' => 'directory',
        'required_perms' => '2775',
        'required_group' => $web_group,
        'reason' => 'SGID required for assembly rename operations',
        'why_write' => 'Web server needs to rename/move assembly subdirectories',
    ];
}

function moop_web_owned_evidence(string $dir, string $web_user, array $prune_paths = [], int $limit = 3): array {
    if ($web_user === '' || !is_dir($dir)) return [];

    $dir = rtrim($dir, '/');
    $cmd = 'find ' . escapeshellarg($dir) . ' -xdev';
    foreach ($prune_paths as $p) {
        $p = rtrim((string) $p, '/');
        // Only prune things actually inside $dir; a sibling rule is irrelevant here.
        if ($p === '' || strpos($p, $dir . '/') !== 0) continue;
        $cmd .= ' -path ' . escapeshellarg($p) . ' -prune -o';
    }
    $cmd .= ' -user ' . escapeshellarg($web_user) . ' -print 2>/dev/null';

    $out = [];
    @exec($cmd . ' | head -n ' . (int) $limit, $out);
    return array_values(array_filter(array_map('trim', $out), fn($s) => $s !== ''));
}

function moop_permission_web_ids(string $web_user, string $web_group): array {
    static $memo = [];
    $key = "$web_user:$web_group";
    if (isset($memo[$key])) return $memo[$key];
    $uid = null;
    $gid = null;
    if (function_exists('posix_getpwnam')) {
        $pw = $web_user !== '' ? @posix_getpwnam($web_user) : false;
        if ($pw !== false) $uid = $pw['uid'];
        $gr = $web_group !== '' ? @posix_getgrnam($web_group) : false;
        if ($gr !== false) $gid = $gr['gid'];
    } else {
        $o = []; if ($web_user !== '') @exec('id -u ' . escapeshellarg($web_user) . ' 2>/dev/null', $o);
        if (!empty($o[0]) && is_numeric(trim($o[0]))) $uid = (int)trim($o[0]);
        $o = []; if ($web_group !== '') @exec('getent group ' . escapeshellarg($web_group) . ' 2>/dev/null', $o);
        if (!empty($o[0])) { $p = explode(':', $o[0]); if (isset($p[2])) $gid = (int)$p[2]; }
    }
    return $memo[$key] = [$uid, $gid];
}

function moop_permission_web_can_write(string $path, string $web_user, string $web_group): bool {
    $st = @stat($path);
    if ($st === false) return false;
    [$uid, $gid] = moop_permission_web_ids($web_user, $web_group);
    $m = $st['mode'];
    return ($uid !== null && $st['uid'] === $uid && ($m & 0200))
        || ($gid !== null && $st['gid'] === $gid && ($m & 0020))
        || ($m & 0002);
}

function performPermissionCheck($path, $item, $web_group = 'www-data') {
    $mode = moop_permission_item_mode($item);
    $sensitive = !empty($item['sensitive']);
    $result = [
        'name' => $item['name'],
        'path' => $path,
        'exists' => file_exists($path),
        'type' => $item['type'],
        'required_perms' => $item['required_perms'] ?? '',
        'required_group' => $item['required_group'] ?? $web_group,
        'reason' => $item['reason'] ?? '',
        'why_write' => $item['why_write'] ?? '',
        'sticky_bit' => $item['sticky_bit'] ?? false,
        'check_mode' => $mode,
        'sensitive' => $sensitive,
        'category' => moop_permission_category($item['name']),
        'severity' => 'low',
        'issues' => [],
    ];

    // A cache the web writes the first time it is needed is not missing before then: on a new
    // site (cuttingclass, 2026-11-05) .gene_set_identity.json does not exist until some page
    // resolves a gene set, and this used to report it -- with chgrp/chmod advice for a file
    // that is not there. Its directory is checked by its own rule.
    if (!$result['exists'] && !empty($item['created_on_demand'])) {
        $result['note'] = 'Not created yet -- the site writes it the first time it is needed';
        return $result;
    }
    if (!$result['exists']) {
        $result['issues'][] = 'Path does not exist';
        $result['severity'] = 'medium';
        return $result;
    }

    $perms_full = substr(sprintf('%o', fileperms($path)), -4);
    // Remove leading zero for comparison (0664 -> 664, 02775 -> 2775)
    $perms = ltrim($perms_full, '0') ?: '0';
    $mode_bits = octdec($perms_full) & 07777; // numeric perm bits for bit tests
    $file_uid = fileowner($path);
    $file_gid = filegroup($path);
    $owner = 'unknown';
    $group = 'unknown';
    if (function_exists('posix_getpwuid')) {
        $pw = posix_getpwuid($file_uid);
        if ($pw) { $owner = $pw['name']; }
    }
    if (function_exists('posix_getgrgid')) {
        $gr = posix_getgrgid($file_gid);
        if ($gr) { $group = $gr['name']; }
    }
    // Fallback: use stat command if posix not available
    if ($owner === 'unknown' || $group === 'unknown') {
        $stat_out = [];
        @exec("stat -c '%U:%G' " . escapeshellarg($path) . " 2>/dev/null", $stat_out);
        if (!empty($stat_out[0])) {
            $parts = explode(':', $stat_out[0]);
            if ($owner === 'unknown' && !empty($parts[0])) { $owner = $parts[0]; }
            if ($group === 'unknown' && !empty($parts[1])) { $group = $parts[1]; }
        }
    }

    $result['current_perms'] = $perms;
    $result['current_owner'] = $owner;
    $result['current_group'] = $group;
    $result['is_readable'] = is_readable($path);
    $result['is_writable'] = is_writable($path);

    $rank = ['low' => 1, 'medium' => 2, 'high' => 3];
    $sev  = 'low';
    $bump = function (string $s) use (&$sev, $rank) { if ($rank[$s] > $rank[$sev]) $sev = $s; };

    $world_writable = ($mode_bits & 0002) === 0002;
    $any_exec       = ($mode_bits & 0111) !== 0;
    $world_any      = ($mode_bits & 0007) !== 0;

    if ($mode === 'data') {
        // Read-only data the web serves. World-readability is NOT required.
        if (!$result['is_readable']) {
            $result['issues'][] = "Not readable by the web server ($web_group) — BLAST and sequence views will fail";
            $bump('high');
        }
        if ($world_writable) {
            $result['issues'][] = "World-writable ($perms) — any user on the host can overwrite it";
            $bump('high');
        }
        if ($any_exec && $result['type'] !== 'directory') {
            // Directories legitimately carry the traverse (x) bit; only flag executable FILES.
            $result['issues'][] = "Marked executable ($perms) — data files should not be executable";
            $bump('medium');
        }
        // Data-tree DIRECTORIES must stay web-writable even though their FILES need not be:
        // makeblastdb and samtools faidx create NEW files, which needs write on the
        // directory. Nothing checked this until 2026-07-16 — 'data' mode tested readable /
        // world-writable / exec and stopped, so 22 assembly dirs sat at 2755 (group r-x, no
        // write) with the dashboard reporting a clean bill of health while every in-app index
        // build there would fail. moop_permission_is_data_tree() was written for exactly this
        // ("future-build concern, medium — not live breakage") but was only ever wired into
        // the 'writable' branch, which these never reach.
        if ($result['type'] === 'directory'
            && moop_permission_needs_build_write($item['name'])
            && !$result['is_writable']) {
            $result['issues'][] = "Not writable by the web server ($web_group) — in-app builds"
                . ' here (Build BLAST Index, samtools faidx, assembly rename) will fail';
            $bump('medium');
        }
        // ...and what it builds must stay readable to the next tool along. The web server
        // and CLI scripts both create files in these directories; SGID makes every new
        // file inherit the directory's group instead of its creator's. The rules always
        // SAID this ('SGID required for assembly rename operations') but only the
        // 'writable' branch ever checked it, and these directories are 'data' -- so it was
        // enforced only by the Organism Setup Checklist's private copy of the rule.
        // (SGID on a DIRECTORY is not what the SCAP baseline's unauthorized-SGID rule is
        // about -- that one audits SGID executables.)
        if ($result['type'] === 'directory' && moop_permission_needs_build_write($item['name'])) {
            $want_group = $item['required_group'] ?? $web_group;
            if (($mode_bits & 02000) === 0) {
                $result['issues'][] = "Missing the SGID bit ($perms) — files built here will not inherit the $want_group group";
                $bump('medium');
            }
            if ($group !== $want_group) {
                $result['issues'][] = "Group is $group, should be $want_group — files built here inherit the wrong group";
                $bump('medium');
            }
        }
        // A tree the web server must NOT be able to write (jbrowse2/: JavaScript every visitor's
        // browser runs). 'data' mode only ever asked "can the web READ it", so jbrowse2/ sat at
        // 2775 group apache -- web-writable by its mode bits -- and passed (found 2026-10-20).
        // The SELinux label happened to block the write on this host; on Debian nothing would.
        // Predicted from mode bits + the web user's numeric ids, never is_writable() (CLI = smr).
        if (!empty($item['must_not_be_web_writable'])
            && moop_permission_web_can_write($path, (string)($item['_web_user'] ?? ''), $web_group)) {
            $result['issues'][] = "Writable by the web server ($perms) — this tree must be read-only to it;"
                . ' remove group write (chmod g-w) so a write bug cannot plant code here';
            $bump('medium');
        }
        // Does the web server write here despite being classified read-only? Skip the data
        // trees (organisms/, data/tracks): those ARE web-written by design and are only
        // 'data' here because their FILES need not be writable — see moop_permission_check_mode.
        if ($result['type'] === 'directory' && !moop_permission_is_data_tree($item['name'])) {
            $evidence = moop_web_owned_evidence($path, (string) ($item['_web_user'] ?? ''), $item['prune_paths'] ?? []);
            if ($evidence) {
                $result['issues'][] = 'Contains file(s) owned by the web server ('
                    . ($item['_web_user'] ?? '?') . ') — e.g. ' . $evidence[0]
                    . '. This path is classified read-only, so nothing here checks its SELinux'
                    . ' label. Either it belongs in the writable set, or these are leftovers'
                    . ' from a retired feature and should be chowned back.';
                $bump('medium');
            }
        }
    } elseif ($mode === 'secret') {
        if (!$result['is_readable']) {
            $result['issues'][] = "Not readable by the web server — JWT signing/verification will fail";
            $bump('high');
        }
    } else { // 'writable'
        // Under enforcing SELinux the LABEL decides writability, not the Unix mode —
        // is_writable() below sees only DAC and would false-green a wrong label.
        if (moop_selinux_enforcing()) {
            $type = moop_selinux_type($path);
            if ($type !== null && $type !== 'httpd_sys_rw_content_t') {
                $result['issues'][] = "SELinux label is '$type' — php-fpm (httpd_t) cannot write here regardless of Unix perms; needs httpd_sys_rw_content_t (see docs/SELINUX_AND_HARDENING.md / scripts/fix_moop_selinux.sh)";
                $bump('high');
            }
        }
        if (!$result['is_writable']) {
            $is_tree = moop_permission_is_data_tree($item['name']);
            $result['issues'][] = "Not writable by the web server ($web_group)"
                . ($is_tree ? ' — admin builds/renames into this tree will fail' : ' — admin saves/logging/caching here will fail');
            $bump($is_tree ? 'medium' : 'high');
        }
        if (isset($item['required_group']) && $group !== $item['required_group']) {
            $result['issues'][] = "Group is $group, should be " . $item['required_group'] . ' — new files here inherit the wrong group';
            $bump('medium');
        }
        if ($world_writable) {
            $result['issues'][] = "World-writable ($perms)";
            $bump('high');
        }
        if ($any_exec && $result['type'] !== 'directory') {
            // Same rule as the 'data' branch: directories legitimately carry the traverse (x)
            // bit, files never do. A file that is BOTH web-writable and executable is strictly
            // worse than a read-only one, so this matters more here, not less.
            $result['issues'][] = "Marked executable ($perms) — data files should not be executable";
            $bump('medium');
        }
    }

    // Credentials must not be readable by other users on the host.
    //
    // Deliberately OUTSIDE the mode branches, because sensitivity is a SEPARATE AXIS from
    // writability. The site-data backup directory holds users.json and secrets.php *and* is
    // rewritten by housekeeping, so it is 'writable' and secret at the same time — and the
    // 'writable' branch tests only world-WRITE (0002), never world-READ. That is exactly why
    // a mode 664 users.json full of bcrypt hashes passed this checker clean: no rule covered
    // the file, and the mode that did cover its directory could not see the problem.
    if ($sensitive && $world_any) {
        $result['issues'][] = "Readable by other users on the host ($perms) — this path holds credentials "
            . "and must not be accessible to `other`";
        $bump('high');
    }

    $result['severity'] = empty($result['issues']) ? 'low' : $sev;
    return $result;
}

function moop_build_permission_items($config, array $ctx): array {
    $web_group            = $ctx['web_group'];
    $moop_owner           = $ctx['moop_owner'];
    $metadata_path        = $ctx['metadata_path'];
    $organism_data        = $ctx['organism_data'];
    $cache_path           = $ctx['cache_path'];
    $site_path            = $ctx['site_path'];
    $absolute_images_path = $ctx['absolute_images_path'];
    $docs_path            = $ctx['docs_path'];
    $site_data_path       = $ctx['site_data_path'] ?? '';

    return [
        // Site Configuration Files - Require Write
        [
            'name' => 'Site Configuration Files',
            'description' => 'Site configuration files edited through admin interface',
            'type' => 'file',
            'paths' => [
                $config->getPath('root_path') . '/' . $config->getString('site') . '/config/config_editable.json',
            ],
            'required_perms' => '664',
            'required_owner' => $moop_owner,
            'required_group' => $web_group,
            'reason' => 'Site configuration is edited by admins through the web interface',
            'why_write' => 'Admin interface needs to save changed site settings (title, email, etc.)',
        ],

        // Metadata Configuration Files - Require Write
        [
            'name' => 'Metadata Configuration Files',
            'description' => 'JSON configuration files for annotations, taxonomy, and groups',
            'type' => 'file',
            'paths' => [
                $metadata_path . '/annotation_config.json',
                $metadata_path . '/taxonomy_tree_config.json',
                $metadata_path . '/group_descriptions.json',
                $metadata_path . '/organism_assembly_groups.json',
                // Admin-editable through Manage Glossary, so the web server writes it.
                // Absent here — and therefore unchecked — until 2026-08-04.
                $metadata_path . '/glossary.json',
                // Written by admin/api/dismiss_group_suggestion.php when a curated
                // group is deliberately allowed to differ from the taxonomy tree.
                // Seeded from .example by setup.php: a MISSING path is reported as a
                // medium issue here, so it must exist rather than appear on first use.
                $metadata_path . '/group_taxon_exceptions.json',
                // Admin -> News (lib/home_panel.php). Optional: only sites showing news have it,
                // so it is checked once it exists rather than reported missing everywhere.
                ...array_filter([$metadata_path . '/news.json'], 'file_exists'),
            ],
            'required_perms' => '664',
            'required_owner' => $moop_owner,
            'required_group' => $web_group,
            'reason' => 'Configuration files are edited by admins and read by the web server',
            'why_write' => 'Admin interface needs to modify these files when you change settings',
        ],

        // Site Data Backup — the housekeeping snapshot writes here every run.
        //
        // This had NO rule at all until 2026-08-04, and the cost was exactly what §11
        // predicts: metadata/glossary.json in the backup was mode 640 owned by smr while
        // housekeeping runs as apache, so every snapshot from 2026-07-23 onward failed to
        // write it and reported success anyway. Twelve days of Manage Glossary edits were
        // never backed up, and nothing on this page could have said so, because the
        // directory the backup lives in was not among the things it looks at.
        //
        // scripts/fix_moop_selinux.sh ALREADY labels this path — so the SELinux half was
        // covered and the ownership half was not, which is why the failure was invisible
        // rather than loud. A correct label on an unwritable file looks fine from every
        // angle except the one that matters.
        [
            'name' => 'Site Data Backup Directory',
            'description' => 'Where housekeeping snapshots config, metadata and user accounts',
            'type' => 'directory',
            'sensitive' => true,   // holds users.json (bcrypt hashes) and config/secrets.php
            'paths' => array_values(array_filter([$site_data_path])),
            // 2770, NOT 2775. This field drives no logic (nothing reads required_perms — see
            // moop_permission_fix_commands), but admins read it and act on it, and the value
            // here said 2775 on a directory whose own description says it holds user accounts.
            // housekeeping_snapshot_site_data() creates this directory 0750; 2775 was never
            // the intent, it was advice drift.
            'required_perms' => '2770',
            // No required_owner: the web server CREATES these files, so apache owning
            // them is correct, not a fault. The writable branch does not evaluate
            // required_owner anyway — it checks is_writable, the SELinux label,
            // required_group and world-writable — so asserting an owner here would
            // be inert today and wrong the day it stopped being inert.
            'required_group' => $web_group,
            'reason' => 'Housekeeping copies site data here on every run',
            'why_write' => 'The snapshot task writes config, metadata and organism.json files into this directory',
        ],

        [
            'name' => 'Site Data Backup Files',
            'description' => 'The snapshot copies themselves — overwritten in place on each run',
            'type' => 'file',
            'paths' => $site_data_path === '' ? [] : array_values(array_filter([
                $site_data_path . '/metadata/annotation_config.json',
                $site_data_path . '/metadata/organism_assembly_groups.json',
                $site_data_path . '/metadata/taxonomy_tree_config.json',
                $site_data_path . '/metadata/group_descriptions.json',
                $site_data_path . '/metadata/glossary.json',
                $site_data_path . '/config/config_editable.json',
            ], 'file_exists')),
            'required_perms' => '664',
            // No required_owner: the web server CREATES these files, so apache owning
