function moop_permission_issue_summary($config, ?array $collected = null): array {
    if ($collected === null) {
        $collected = moop_collect_permission_checks($config);
    }
    $findings = moop_permission_findings($config, $collected);
    $sev = ['high' => 0, 'medium' => 0, 'low' => 0];
    $affected = 0;
    foreach ($findings as $f) {
        $sev[$f['severity']]++;
        $affected += $f['count'];
    }
    $worst = $sev['high'] > 0 ? 'high' : ($sev['medium'] > 0 ? 'medium' : ($sev['low'] > 0 ? 'low' : null));
    return [
        'findings'       => $findings,
        'finding_count'  => count($findings),
        'high'           => $sev['high'],
        'medium'         => $sev['medium'],
        'low'            => $sev['low'],
        'affected_files' => $affected,
        'worst'          => $worst,
        'checked_at'     => date('Y-m-d H:i:s'),
    ];
}

public static function load($gene_set_path, array $transcript_ids)
    {
        $file = rtrim($gene_set_path, '/') . '/' . self::FILENAME;
        if (!is_readable($file) || empty($transcript_ids)) {
            return [];
        }

        $wanted = array_flip(array_values($transcript_ids));
        $found  = [];
        $left   = count($wanted);

        $fh = fopen($file, 'r');
        if (!$fh) {
            return [];
        }

        while (($line = fgets($fh)) !== false) {
            // Compare only the id field. Substring-matching the whole line would
            // hit a chromosome name or a coordinate and return another gene's
            // exons under the id asked for -- wrong blocks, drawn confidently.
            $tab = strpos($line, "\t");
            if ($tab === false) {
                continue;
            }
            $id = substr($line, 0, $tab);
            if (!isset($wanted[$id]) || isset($found[$id])) {
                continue;
            }

            $record = self::parseRow($line);
            if ($record !== null) {
                $found[$id] = $record;
                if (--$left === 0) {
                    break;   // every id answered; no reason to read the rest
                }
            }
        }
        fclose($fh);

        return $found;
    }

public static function parseRow($line)
    {
        $parts = explode("\t", rtrim($line, "\r\n"));
        if (count($parts) < 5) {
            return null;
        }

        $outer = explode(',', $parts[3]);
        if (count($outer) !== 2) {
            return null;
        }

        $exons = [];
        foreach (explode(';', $parts[4]) as $span) {
            $se = explode(',', $span);
            if (count($se) !== 2) {
                return null;
            }
            $s = (int)$se[0];
            $e = (int)$se[1];
            if ($s <= 0 || $e < $s) {
                return null;
            }
            $exons[] = [$s, $e];
        }
        if (empty($exons)) {
            return null;
        }

        // The writer sorts ascending, but sorting here too costs nothing and the
        // minus-strand walk below depends on the order being right.
        usort($exons, function ($a, $b) { return $a[0] <=> $b[0]; });

        return [
            'transcript_id' => $parts[0],
            'chr'           => $parts[1],
            'strand'        => $parts[2] === '-' ? '-' : '+',
            'start'         => (int)$outer[0],
            'end'           => (int)$outer[1],
            'exons'         => $exons,
        ];
    }

functions.comment:
/**
* Parse one index line, or null if it is not usable.
*
* A malformed row returns null rather than a partial record: half an exon
* list maps to plausible-looking blocks in the wrong place, and there is no
* way to notice that downstream.
*
* @return array|null ['transcript_id','chr','strand','start','end','exons'=>[[s,e],…]]
*/
public static function parseRow($line)
{
$parts = explode("\t", rtrim($line, "\r\n"));
if (count($parts) < 5) {
return null;
}

$outer = explode(',', $parts[3]);
if (count($outer) !== 2) {
return null;
}

$exons = [];
foreach (explode(';', $parts[4]) as $span) {
$se = explode(',', $span);
if (count($se) !== 2) {
return null;
}
$s = (int)$se[0];
$e = (int)$se[1];
if ($s <= 0 || $e < $s) {
return null;
}
$exons[] = [$s, $e];
}
if (empty($exons)) {
return null;
}

// The writer sorts ascending, but sorting here too costs nothing and the
// minus-strand walk below depends on the order being right.
usort($exons, function ($a, $b) { return $a[0] <=> $b[0]; });

return [
'transcript_id' => $parts[0],
'chr'           => $parts[1],
'strand'        => $parts[2] === '-' ? '-' : '+',
'start'         => (int)$outer[0],
'end'           => (int)$outer[1],
'exons'         => $exons,
];
}

/** Transcript length = total exonic length. */

functions.code:
public static function transcriptLength(array $record)
    {
        $len = 0;
        foreach ($record['exons'] as list($s, $e)) {
            $len += $e - $s + 1;
        }
        return $len;
    }

public static function toGenomicBlocks(array $record, $tstart, $tend)
    {
        $a = (int)min($tstart, $tend);
        $b = (int)max($tstart, $tend);

        // STRICT containment, deliberately. A BLAST hit can never run off the
        // end of its own subject, so a range outside the exon total does not
        // mean "clip it" -- it means the exon index and the FASTA disagree
        // (a stale index, or a CDS-only FASTA against full-transcript exons,
        // or a poly-A tail present in the sequence but absent from the genome).
        // In every one of those cases the right answer is no picture, not a
        // picture shifted by an unknown offset.
        $length = self::transcriptLength($record);
        if ($a < 1 || $b > $length || $a > $b) {
            return [];
        }

        $exons = $record['exons'];
        if ($record['strand'] === '-') {
            $exons = array_reverse($exons);
        }

        $blocks = [];
        $offset = 0;                       // transcript bases consumed before this exon

        foreach ($exons as list($s, $e)) {
            $len       = $e - $s + 1;
            $exon_from = $offset + 1;      // this exon's transcript range
            $exon_to   = $offset + $len;
            $offset   += $len;

            if ($b < $exon_from || $a > $exon_to) {
                continue;
            }

            $from = max($a, $exon_from);   // overlap, in transcript coordinates
            $to   = min($b, $exon_to);

            if ($record['strand'] === '-') {
                // Transcript runs right-to-left across the exon: the LOWEST
                // transcript position in the overlap is the HIGHEST genomic one.
                $blocks[] = [$e - ($to - $exon_from), $e - ($from - $exon_from)];
            } else {
                $blocks[] = [$s + ($from - $exon_from), $s + ($to - $exon_from)];
            }
        }

        return self::mergeBlocks($blocks);
    }

public static function mergeBlocks(array $blocks)
    {
        if (count($blocks) < 2) {
            return array_values($blocks);
        }

        usort($blocks, function ($x, $y) { return $x[0] <=> $y[0]; });

        $merged = [array_shift($blocks)];
        foreach ($blocks as list($s, $e)) {
            $last = count($merged) - 1;
            if ($s <= $merged[$last][1] + 1) {
                $merged[$last][1] = max($merged[$last][1], $e);
            } else {
                $merged[] = [$s, $e];
            }
        }

        return $merged;
    }

public static function genomicStrand($transcript_strand, $hit_strand)
    {
        if ($transcript_strand !== '-') {
            return $hit_strand;
        }
        return $hit_strand === '-' ? '+' : '-';
    }

public static function mapProduct(array $record, array $product)
    {
        $blocks = self::toGenomicBlocks($record, $product['start'], $product['end']);
        if (empty($blocks)) {
            return null;
        }

        $hits    = [];
        $spliced = false;
        foreach ($product['hits'] as $hit) {
            $hit_blocks = self::toGenomicBlocks($record, $hit['start'], $hit['end']);
            if (empty($hit_blocks)) {
                return null;
            }
            if (count($hit_blocks) > 1) {
                $spliced = true;
            }
            $hits[] = [
                'primer'   => $hit['primer'],
                'mismatch' => $hit['mismatch'] ?? 0,
                'strand'   => self::genomicStrand($record['strand'], $hit['strand']),
                'blocks'   => $hit_blocks,
                'spliced'  => count($hit_blocks) > 1,
            ];
        }

        return [
            'chr'     => $record['chr'],
            'strand'  => $record['strand'],
            'span'    => self::span($blocks),
            'blocks'  => $blocks,
            'hits'    => $hits,
            'spliced' => $spliced,
            // How many introns the AMPLICON crosses. This is the number behind
            // the genomic-vs-cDNA size difference, now stated rather than left
            // for the reader to infer from two numbers.
            'introns' => count($blocks) - 1,
        ];
    }

public static function span(array $blocks)
    {
        if (empty($blocks)) {
            return null;
        }
        $starts = array_column($blocks, 0);
        $ends   = array_column($blocks, 1);
        return [min($starts), max($ends)];
    }

public static function binary()
    {
        require_once __DIR__ . '/../functions_system.php';
        return moop_tool('primer3_core', 'primer3_tools');
    }

public static function configPath()
    {
        $configured = trim((string)ConfigManager::getInstance()->getString('primer3_config_path'));

        $candidates = $configured !== ''
            ? [rtrim($configured, '/')]
            : self::CONFIG_CANDIDATES;

        foreach ($candidates as $dir) {
            if (is_readable($dir . '/' . self::SENTINEL)) {
                return $dir . '/';   // primer3 wants the trailing slash
            }
        }
        return '';
    }

public static function status()
    {
        $binary = self::binary();
        if ($binary === '') {
            return [
                'ok' => false, 'binary' => '', 'config' => '',
                'problem' => 'missing',
            ];
        }

        $config = self::configPath();
        if ($config === '') {
            return [
                'ok' => false, 'binary' => $binary, 'config' => '',
                'problem' => 'no_parameters',
            ];
        }

        return ['ok' => true, 'binary' => $binary, 'config' => $config, 'problem' => ''];
    }

public static function optionParams(array $input, array $base = [])
    {
        $params = [];
        $errors = [];

        foreach (self::OPTIONS as $field => $spec) {
            if (!array_key_exists($field, $input)) {
                continue;
            }

            $raw = trim((string)$input[$field]);
            if ($raw === '') {
                continue;
            }

            if (!is_numeric($raw)) {
                $errors[] = $spec['label'] . ': "' . $raw . '" is not a number.';
                continue;
            }

            $value = $spec['type'] === 'int' ? (int)$raw : (float)$raw;

            // Rejected, not clamped. Silently substituting a different number
            // would run a design the user did not ask for and report it as
            // theirs — and the two values that matter most here (a salt
            // correction of 3, a GC clamp of 6) return zero pairs with no error
            // at all, so a clamp would be covering up the one case where saying
            // something is essential.
            if ($value < $spec['min'] || $value > $spec['max']) {
                $errors[] = $spec['label'] . ' must be between ' . $spec['min']
                          . ' and ' . $spec['max'] . ' — you gave ' . $raw . '.';
                continue;
            }

            $params[$spec['tag']] = $value;
        }

        // Ordering, checked against the values that will really be used.
        $effective = array_merge(self::DEFAULTS, $base, $params);
        foreach (self::ORDERED as $triple) {
            $min = $effective[$triple['min']] ?? null;
            $opt = $effective[$triple['opt']] ?? null;
            $max = $effective[$triple['max']] ?? null;

            if ($min === null || $max === null) {
                continue;
            }
            if ($min > $max) {
                $errors[] = 'The minimum ' . $triple['label'] . ' (' . $min . $triple['unit']
                          . ') is above the maximum (' . $max . $triple['unit'] . ').';
                continue;
            }
            if ($opt !== null && ($opt < $min || $opt > $max)) {
                $errors[] = 'The optimum ' . $triple['label'] . ' (' . $opt . $triple['unit']
                          . ') is outside the range you set, ' . $min . '–' . $max . $triple['unit'] . '.';
            }
        }

        return ['params' => $params, 'errors' => $errors];
    }

public static function productSizeLadder($max, $min = 100)
    {
        $max = (int)$max;
        $min = (int)$min;

        if ($max < $min) {
            return '';
        }

        $ranges = [];
        foreach ([0.75, 0.50, 0.25] as $fraction) {
            $low = (int)floor($max * $fraction);
            if ($low >= $min) {
                $ranges[] = $low . '-' . $max;
            }
        }
        $ranges[] = $min . '-' . $max;

        // 75% of 400 and 50% of 600 can coincide; a repeated range is not wrong,
        // just noise in a field the user can see.
        return implode(' ', array_unique($ranges));
    }

public static function buildInput(array $records, array $params = [])
    {
        // No ConfigManager here on purpose. This is a pure function — input in,
        // boulder-IO out — so it stays testable with no site config, no
        // installed primer3 and no filesystem. run() is what knows where this
        // deployment keeps its thermodynamic tables and injects the path.
        $globals = array_merge(self::DEFAULTS, $params);

        $out   = '';
        $first = true;
        foreach ($records as $rec) {
            $id = preg_replace('/[^A-Za-z0-9._:|-]/', '_', (string)($rec['id'] ?? 'seq'));
            $out .= "SEQUENCE_ID=$id\n";
            $out .= 'SEQUENCE_TEMPLATE=' . strtoupper(preg_replace('/\s+/', '', (string)$rec['template'])) . "\n";

            // Force a primer ACROSS a point — an exon junction, a fusion
            // breakpoint, a scaffold join. Callers speak ONE convention:
            // "the junction follows 1-based base K".
            //
            // 🚨 THE −1 IS LOAD-BEARING, AND THE MANUAL WILL TELL YOU IT IS NOT.
            // primer3's docs print "SEQUENCE_OVERLAP_JUNCTION_LIST=20 # 1-based
            // indexes" next to an example whose junction follows the 20th base.
            // 2.6.1 does not behave that way. Holding a junction at 450 and
            // lowering PRIMER_MIN_3_PRIME_OVERLAP_OF_JUNCTION from 4 to 3 moved
            // the chosen primer's edge from 3 bases left of base 450 to 2 —
            // always exactly one fewer than the constraint demands. primer3
            // counts the junction as following base N+1, so its values are
            // effectively 0-based and a caller's K must go in as K−1.
            //
            // Without this, every junction is enforced one base 3' of the real
            // boundary: the primer still LOOKS like it spans, it just has one
            // fewer genuine base on the far side than promised — which is
            // precisely the margin that decides whether it rejects genomic DNA.
            // Nothing in the output would ever say so.
            if (!empty($rec['junctions'])) {
                $zero_based = [];
                foreach ($rec['junctions'] as $k) {
                    $k = (int)$k;
                    if ($k > 0) {
                        $zero_based[] = $k - 1;
                    }
                }
                if ($zero_based) {
                    $out .= 'SEQUENCE_OVERLAP_JUNCTION_LIST=' . implode(' ', $zero_based) . "\n";
                }
            }

            // Regions the product must contain, as primer3's start,length pairs
            // (0-based start). Several are allowed; primer3 requires the product
            // to span ALL of them, which is why [ ] markup and the "Region to
            // include" box must not both be in play at once.
            if (!empty($rec['targets'])) {
                $spans = [];
                foreach ($rec['targets'] as $t) {
                    $spans[] = (int)$t[0] . ',' . (int)$t[1];
                }
                $out .= 'SEQUENCE_TARGET=' . implode(' ', $spans) . "\n";
            }

            if ($first) {
                foreach ($globals as $k => $v) {
                    // ⚠️ A NEWLINE INSIDE A VALUE TRUNCATES THE RECORD SILENTLY.
                    // Boulder-IO ends a record at a lone '=' and stops reading
                    // tags at a blank line: primer3 then echoes back everything
                    // up to that point, emits no primers, no PRIMER_ERROR, and
                    // EXITS 0. Verified on 2.6.1. No current caller can produce
                    // one — every value here is an int, a float, or a string
                    // from a table in this class — but the failure is invisible
                    // enough, and the guard cheap enough, that it is not worth
                    // relying on that staying true. The likeliest source is a
                    // config value with a stray newline, such as the
                    // thermodynamic parameters path.
                    $out .= $k . '=' . str_replace(["\r", "\n"], '', (string)$v) . "\n";
                }
                $first = false;
            }
            $out .= "=\n";
        }

        return $out;
    }

public static function parseOutput($raw)
    {
        $results = [];

        // Records are separated by a lone '='. Splitting on that rather than
        // on SEQUENCE_ID keeps a record that FAILED — one with an error and no
        // primers still has to be reported, or a bad input silently vanishes.
        foreach (preg_split('/^=\s*$/m', (string)$raw) as $chunk) {
            $chunk = trim($chunk);
            if ($chunk === '') {
                continue;
            }

            $tags = [];
            foreach (explode("\n", $chunk) as $line) {
                $eq = strpos($line, '=');
                if ($eq === false) {
                    continue;
                }
                $tags[substr($line, 0, $eq)] = substr($line, $eq + 1);
            }
            if (empty($tags)) {
                continue;
            }

            $entry = [
                'id'       => $tags['SEQUENCE_ID'] ?? '',
                'template' => $tags['SEQUENCE_TEMPLATE'] ?? '',
                'error'    => $tags['PRIMER_ERROR'] ?? ($tags['SEQUENCE_ID_ERROR'] ?? ''),
                'explain'  => [
                    'left'  => $tags['PRIMER_LEFT_EXPLAIN'] ?? '',
                    'right' => $tags['PRIMER_RIGHT_EXPLAIN'] ?? '',
                    'pair'  => $tags['PRIMER_PAIR_EXPLAIN'] ?? '',
                ],
                'pairs'    => [],
            ];

            $n = isset($tags['PRIMER_PAIR_NUM_RETURNED']) ? (int)$tags['PRIMER_PAIR_NUM_RETURNED'] : 0;
            for ($i = 0; $i < $n; $i++) {
                $pair = ['rank' => $i + 1];

                foreach (self::PAIR_FIELDS as $name => $pattern) {
                    $tag = sprintf($pattern, $i);
                    if (isset($tags[$tag])) {
                        $pair[$name] = $tags[$tag];
                    }
                }

                // "start,length" pairs. primer3 reports the LEFT primer's start
                // 0-based at its 5' end, and the RIGHT primer's start 0-based at
                // its 5' end too — which for the right primer is its RIGHTMOST
                // base, because it is on the other strand. Converted to 1-based
                // inclusive spans here so nothing downstream has to remember.
                if (isset($tags["PRIMER_LEFT_$i"])) {
                    list($s, $len) = array_map('intval', explode(',', $tags["PRIMER_LEFT_$i"]));
                    $pair['left_start']  = $s + 1;
                    $pair['left_end']    = $s + $len;
                    $pair['left_length'] = $len;
                }
                if (isset($tags["PRIMER_RIGHT_$i"])) {
                    list($s, $len) = array_map('intval', explode(',', $tags["PRIMER_RIGHT_$i"]));
                    $pair['right_end']    = $s + 1;          // 5' end, highest coordinate
                    $pair['right_start']  = $s - $len + 2;   // 3' end, lowest coordinate
                    $pair['right_length'] = $len;
                }

                $entry['pairs'][] = $pair;
            }

            $results[] = $entry;
        }

        return $results;
    }

public static function splitRecords($text)
    {
        $records = [];
        $current = null;

        foreach (preg_split('/\r\n|\r|\n/', (string)$text) as $line) {
            if (strlen($line) && $line[0] === '>') {
                if ($current !== null) {
                    $records[] = $current;
                }
                $current = ['header' => trim(substr($line, 1)), 'body' => ''];
                continue;
            }
            if ($current === null) {
                $current = ['header' => '', 'body' => ''];
            }
            $current['body'] .= $line;
        }
        if ($current !== null) {
            $records[] = $current;
        }

        // A header with nothing under it, or leading blank lines, are not
        // sequences. A header with no sequence IS worth reporting, so it is left
        // for the caller to notice — only the genuinely empty lead-in goes.
        if ($records && $records[0]['header'] === '' && trim($records[0]['body']) === '') {
            array_shift($records);
        }

        return $records;
    }

public static function productSequence($template, array $pair)
    {
        $template = (string)$template;
        $start    = isset($pair['left_start']) ? (int)$pair['left_start'] : 0;
        $end      = isset($pair['right_end'])  ? (int)$pair['right_end']  : 0;

        if ($template === '' || $start < 1 || $end < $start || $end > strlen($template)) {
            return '';
        }

        $amplicon = substr($template, $start - 1, $end - $start + 1);

        if (isset($pair['product_size']) && $pair['product_size'] !== ''
            && strlen($amplicon) !== (int)$pair['product_size']) {
            return '';
        }

        return $amplicon;
    }

public static function parseTarget($input, $template)
    {
        $none = ['target' => null, 'error' => '', 'first' => 0, 'last' => 0];

        $input = trim((string)$input);
        if ($input === '') {
            return $none;
        }

        if (!preg_match('/^(\d+)\s*,\s*(\d+)$/', $input, $m)) {
            return array_merge($none, ['error' =>
                'Region to include: give it as start,length — for example 300,100 for 100 bases '
                . 'starting at position 300.']);
        }

        $start  = (int)$m[1];
        $length = (int)$m[2];

        if ($start < 1 || $length < 1) {
            return array_merge($none, ['error' =>
                'Region to include: the start and the length both have to be at least 1.']);
        }

        $last = $start + $length - 1;
        if ($last > $template) {
            return array_merge($none, ['error' =>
                'Region to include: ' . number_format($start) . '–' . number_format($last)
                . ' runs past the end of your ' . number_format($template) . ' bp sequence.']);
        }

        return ['target' => [$start - 1, $length], 'error' => '', 'first' => $start, 'last' => $last];
    }

public static function friendlyError($error, $template = 0)
    {
        if (strpos($error, 'SEQUENCE_INCLUDED_REGION length < min PRIMER_PRODUCT_SIZE_RANGE') !== false) {
            return 'The product size you asked for is larger than the sequence you gave'
                 . ($template > 0 ? ', which is ' . number_format($template) . ' bp' : '')
                 . '. Ask for a smaller product, or paste a longer sequence — a primer pair '
                 . 'cannot amplify more than it is given.';
        }

        return $error;
    }

public static function run(array $records, array $params = [])
    {
        $status = Primer3::status();
        if (!$status['ok']) {
            return [
                'success' => false,
                'error'   => $status['problem'] === 'missing'
                    ? 'primer3 is not installed on this server.'
                    : 'primer3 is installed but its thermodynamic parameters are missing, so it '
                      . 'cannot run. Ask an administrator to re-run scripts/install_primer3.sh.',
                'results' => [],
            ];
        }

        // Injected HERE, not in buildInput(): where the thermodynamic tables live
        // is an installation fact, and it is never the caller's to supply — a
        // hardcoded value would be wrong on whichever install route this
        // deployment did not take.
        $params['PRIMER_THERMODYNAMIC_PARAMETERS_PATH'] = $status['config'];

        $input = self::buildInput($records, $params);

        // An explicit temp file, not a pipe through /tmp by name: php-fpm runs
        // with PrivateTmp, so anything exec'd from a web request gets its own
        // /tmp that is invisible from a shell (CLAUDE.md §11).
        require_once __DIR__ . '/../temp_dir.php';
        $in_file = tempnam(moop_temp_dir(), 'moop_p3_');
        if ($in_file === false) {
            return ['success' => false, 'error' => 'Could not create a temporary file.', 'results' => []];
        }
        file_put_contents($in_file, $input);

        $cmd = escapeshellarg($status['binary']) . ' ' . escapeshellarg($in_file) . ' 2>&1';
        $raw = shell_exec($cmd);
        @unlink($in_file);

        if ($raw === null || trim((string)$raw) === '') {
            return ['success' => false, 'error' => 'primer3 produced no output.', 'results' => []];
        }

        $results = self::parseOutput($raw);

        // A global failure (bad parameters path, malformed input) shows up as an
        // error on the FIRST record with no primers anywhere. Surfaced as a run
        // failure rather than as an empty table, which reads as "no primers
        // found" — a scientific answer, not a broken install.
        $any_pairs = false;
        foreach ($results as $r) {
            if (!empty($r['pairs'])) { $any_pairs = true; break; }
        }
        if (!$any_pairs && !empty($results[0]['error'])) {
            return ['success' => false, 'error' => $results[0]['error'], 'results' => $results];
        }

        return ['success' => true, 'error' => '', 'results' => $results];
    }

public static function run(array $pairs, $db, array $options = [])
    {
        $result = [
            'success'       => false,
            'error'         => '',
            'hits'          => [],
            'below_floor'   => 0,
            'over_mismatch' => 0,
            'discards'      => [],
            'repetitive'    => [],
            'out_of_memory' => [],
        ];

        if (empty($pairs)) {
            $result['error'] = 'No primer pairs to search.';
            return $result;
        }

        if (!self::databaseExists($db)) {
            $result['error'] = 'BLAST database not found: ' . basename($db);
            return $result;
        }

        $max_mismatch = isset($options['max_mismatch']) ? (int)$options['max_mismatch'] : self::SEARCH_MAX_MISMATCH;
        // The configured blastn, like BLAST itself -- this used to run a bare 'blastn' and
        // ignore blast_tools, so a site that set a full path got it everywhere but here.
        require_once __DIR__ . '/../functions_system.php';
        $blastn       = $options['blastn'] ?? moop_tool('blastn', 'blast_tools');
        if ($blastn === '') {
            $result['error'] = "blastn is not installed or not on the web server's PATH.";
            return $result;
        }

        // Query ids are positional (q0f, q0r, q1f, ...) rather than the user's
        // names: a primer name may contain spaces or characters BLAST would
        // truncate at, and a mangled id would silently attach hits to the wrong pair.
        $fasta   = '';
        $id_map  = [];
        $lengths = [];
        foreach ($pairs as $i => $pair) {
            foreach (['forward' => 'f', 'reverse' => 'r'] as $side => $tag) {
                $id = 'q' . $i . $tag;
                $fasta .= ">$id\n" . $pair[$side] . "\n";
                $id_map[$id]  = ['index' => $i, 'side' => $side];
                $lengths[$id] = strlen($pair[$side]);
            }
        }

        require_once __DIR__ . '/../temp_dir.php';
        $query_file = tempnam(moop_temp_dir(), 'moop_primer_q');
        if ($query_file === false) {
            $result['error'] = 'Could not create a temporary query file.';
            return $result;
        }
        file_put_contents($query_file, $fasta);

        // blastn writes its table to a FILE, read back one line at a time. Collecting stdout
        // with exec() held every line in PHP memory: a poly-A pair gave 876,050 lines (47 MB of
        // text, 105 MB as a PHP array) and killed the request before a verdict was reached.
        $out_file = tempnam(moop_temp_dir(), 'moop_primer_o');
        if ($out_file === false) {
            @unlink($query_file);
            $result['error'] = 'Could not create a temporary output file.';
            return $result;
        }

        // The heap cap (HEAP_LIMIT_MB). --core=0: a capped blastn aborts, and would otherwise
        // leave a core dump the size of its heap. SOFT limits only ("N:"): changing a HARD
        // limit needs SELinux process:setrlimit, which php-fpm may lack -- and blastn never
        // raises its own. No prlimit: run uncapped, as before.
        $prlimit = moop_find_executable('prlimit');
        $cap     = $prlimit === '' ? ''
                 : escapeshellarg($prlimit) . ' --data=' . (self::HEAP_LIMIT_MB * 1048576) . ': --core=0: -- ';

        $cmd = $cap . escapeshellarg($blastn)
             . ' -task blastn-short'
             . ' -evalue ' . escapeshellarg(self::EVALUE)
             . ' -word_size ' . escapeshellarg(self::WORD_SIZE)
             . ' -dust no'
             . ' -max_target_seqs ' . escapeshellarg(self::MAX_TARGET_SEQS)
             . ' -db ' . escapeshellarg($db)
             . ' -query ' . escapeshellarg($query_file)
             // btop carries WHERE the mismatches are. Position dominates count for
             // priming -- a mismatch in the last few bases at the 3' end all but
             // stops extension, while the same mismatch at the 5' end is tolerated --
             // and plain outfmt 6 gives only a total, which cannot express that.
             . ' -outfmt ' . escapeshellarg('6 qseqid sseqid length mismatch gapopen qstart qend sstart send btop')
             . ' -out ' . escapeshellarg($out_file)
             . ' 2>&1';   // what is left on stdout/stderr is BLAST's own messages

        // Through the BLAST queue like every other search, and under the same run-time cap.
        require_once __DIR__ . '/../blast_queue.php';
        $output = [];
        $return_code = 0;
        $queued = blast_queue_run(
            function () use ($cmd, &$output, &$return_code) {
                exec(blast_queue_wrap_command($cmd), $output, $return_code);
            },
            // The heap cap, not blast_queue_cost_units()' 1.2x the .nsq: that counts the
            // memory-mapped database, which is shared page cache, and missed the heap -- a
            // poly-A check was charged ~1 GB on wallaby and took 5.2 GB.
            $prlimit === '' ? blast_queue_cost_units('blastn', $db)
                            : max(1, (int)ceil(self::HEAP_LIMIT_MB / BLAST_QUEUE_UNIT_MB)),
            blast_queue_ticket(null)
        );
        @unlink($query_file);

        $fail = function ($message) use (&$result, $out_file) {
            @unlink($out_file);
            $result['error'] = $message;
            return $result;
        };
        if (!$queued['ran']) {
            return $fail($queued['error']);
        }
        if (blast_queue_timed_out($return_code)) {
            return $fail(blast_queue_timeout_message());
        }
        if (self::ranOutOfMemory($return_code, $output)) {
            @unlink($out_file);
            // One run holds every pair, so the cap says only that SOME primer is too
            // repetitive. Calling every pair non-specific would be wrong, so with several
            // pairs each is searched alone (only in this rare case) to find the one.
            if (count($pairs) > 1) {
                return self::runEachPairAlone($pairs, $db, $options, $result);
            }
            // A failed search here used to leave the pair with no products on this template,
            // which the verdict read as "no product". It is the opposite: non-specific.
            foreach ($pairs as $i => $pair) {
                $result['hits'][$i]          = ['forward' => [], 'reverse' => []];
                $result['discards'][$i]      = ['below_floor' => 0, 'over_mismatch' => 0];
                $result['repetitive'][$i]    = ['forward' => 0, 'reverse' => 0];
                $result['out_of_memory'][$i] = true;
            }
            $result['success'] = true;
            return $result;
        }
        if ($return_code !== 0) {
            // A non-zero exit with an empty .blastout is exactly the failure mode
            // that made the original scripts report a header-only table as success.
            return $fail('BLAST failed (exit ' . $return_code . '): '
                . trim(implode(' ', array_slice($output, 0, 3))));
        }
        $fh = fopen($out_file, 'r');
        if ($fh === false) {
            return $fail('Could not read the BLAST output.');
        }

        foreach ($pairs as $i => $pair) {
            $result['hits'][$i]       = ['forward' => [], 'reverse' => []];
            $result['discards'][$i]   = ['below_floor' => 0, 'over_mismatch' => 0];
            $result['repetitive'][$i] = ['forward' => 0, 'reverse' => 0];
            $result['out_of_memory'][$i] = false;
        }
        $kept   = [];   // qid => sites passing both filters, counted past the ceiling
        $stored = 0;    // sites held in memory, whole run

        while (($line = fgets($fh)) !== false) {
            $f = explode("\t", rtrim($line, "\r\n"));
            if (count($f) < 9) {
                continue;   // not a table row
            }

            list($qid, $sid, $length, $mismatch, $gapopen, $qstart, $qend, $sstart, $send) = $f;
            $btop = $f[9] ?? '';

            if (!isset($id_map[$qid])) {
                continue;
            }

            $length   = (int)$length;
            $qstart   = (int)$qstart;
            $qend     = (int)$qend;
            $qlength  = $lengths[$qid];

            $pair_index = $id_map[$qid]['index'];

            if ($length < $qlength * self::MIN_LENGTH_FRACTION) {
                $result['below_floor']++;
                $result['discards'][$pair_index]['below_floor']++;
                continue;
            }

            // Over the WHOLE primer, not just the aligned part. BLAST's mismatch column
            // counts substitutions inside the alignment only: a 20-mer aligned over 16
            // bases read "0 mismatches", and gaps were not counted at all. (BLAT, used
            // for this before, reports the full primer -- this restores that.)
            $aligned_mismatch = (int)$mismatch;
            $mismatch = self::fullLengthMismatches($btop, $qstart, $qend, $qlength);

            if ($mismatch > $max_mismatch) {
                $result['over_mismatch']++;
                $result['discards'][$pair_index]['over_mismatch']++;
                continue;
            }

            // The primer's FULL footprint on the subject: extend the alignment by the
            // primer bases it left uncovered, so product sizes and browser boxes cover
            // the whole primer. Query start maps to the low end on the + strand and to
            // the high end on the - strand.
            list($sstart, $send) = self::fullFootprint((int)$sstart, (int)$send, $qstart, $qend, $qlength);

            $meta = $id_map[$qid];

            // Past the ceiling the primer is repetitive: keep COUNTING (the number shown is
            // exact) but drop its stored sites -- a partial list would make products and the
            // verdict look like a real, smaller answer.
            $kept[$qid] = ($kept[$qid] ?? 0) + 1;
            if ($kept[$qid] > self::MAX_SITES_PER_PRIMER) {
                if ($kept[$qid] === self::MAX_SITES_PER_PRIMER + 1) {
                    $stored -= count($result['hits'][$meta['index']][$meta['side']]);
                    $result['hits'][$meta['index']][$meta['side']] = [];
                }
                $result['repetitive'][$meta['index']][$meta['side']] = $kept[$qid];
                continue;
            }
            if (++$stored > self::MAX_SITES_PER_RUN) {
                fclose($fh);
                return $fail('These primers match too many places in total to check at once. '
                    . 'Check fewer pairs at a time.');
            }

            $result['hits'][$meta['index']][$meta['side']][] = [
                'subject'  => $sid,
                // In -outfmt 6 the subject strand is IMPLIED by coordinate order.
                // There is no strand column, and the pairing rule depends entirely
                // on reading this correctly.
                'strand'   => ($sstart > $send) ? '-' : '+',
                'start'    => min($sstart, $send),
                'end'      => max($sstart, $send),
                'length'   => $length,
                'mismatch' => $mismatch,           // whole primer: substitutions + gaps + uncovered ends
                'aligned_mismatch' => $aligned_mismatch,  // BLAST's own column, aligned part only
                'gapopen'  => (int)$gapopen,
                'qstart'   => $qstart,
                'qend'     => $qend,
                'qlength'  => $qlength,
                // Mismatches inside the 3'-end window, INCLUDING any part of that
                // window the alignment never reached: an unaligned 3' tail is not a
                // match, and treating it as one would call a truncated hit clean.
                'three_prime_mismatch' => self::threePrimeMismatches(
                    $btop, $qstart, $qend, $qlength
                ),
            ];
        }

        fclose($fh);
        @unlink($out_file);

        $result['success'] = true;
        return $result;
    }

public static function ranOutOfMemory($return_code, array $output)
    {
        if ($return_code === 0) {
            return false;
        }
        $text = implode("\n", $output);
        return stripos($text, 'out of memory') !== false
            || stripos($text, 'bad_alloc') !== false
            || in_array($return_code, [134, 139], true);
    }

private static function runEachPairAlone(array $pairs, $db, array $options, array $result)
    {
        $stored = 0;
        foreach ($pairs as $i => $pair) {
            $one = self::run([$pair], $db, $options);
            if (!$one['success']) {
                $result['error'] = $one['error'];
                return $result;
            }
            foreach (['hits', 'discards', 'repetitive', 'out_of_memory'] as $key) {
                $result[$key][$i] = $one[$key][0];
            }
            $result['below_floor']   += $one['below_floor'];
            $result['over_mismatch'] += $one['over_mismatch'];
            $stored += count($one['hits'][0]['forward']) + count($one['hits'][0]['reverse']);
            // The same whole-run bound as one combined search.
            if ($stored > self::MAX_SITES_PER_RUN) {
                $result['error'] = 'These primers match too many places in total to check at once. '
                    . 'Check fewer pairs at a time.';
                return $result;
            }
        }
        $result['success'] = true;
        return $result;
    }

public static function fullLengthMismatches($btop, $qstart, $qend, $qlength)
    {
        // Strip the match run-lengths; what is left is two characters per operation.
        $ops = (int)(strlen(preg_replace('/\d+/', '', $btop)) / 2);
        return $ops + max(0, $qstart - 1) + max(0, $qlength - $qend);
    }

public static function fullFootprint($sstart, $send, $qstart, $qend, $qlength)
    {
        $lead  = max(0, $qstart - 1);         // uncovered 5' bases
        $trail = max(0, $qlength - $qend);    // uncovered 3' bases
        if ($sstart <= $send) {               // + strand: 5' end is the low coordinate
            return [max(1, $sstart - $lead), $send + $trail];
        }
        return [$sstart + $lead, max(1, $send - $trail)];
    }

public static function threePrimeMismatches($btop, $qstart, $qend, $qlength)
    {
        $window_start = max(1, $qlength - self::THREE_PRIME_WINDOW + 1);

        // Bases of the window the alignment never covered count against it.
        $unaligned = max(0, $qlength - $qend);

        $bad = 0;
        $pos = $qstart;
        $i   = 0;
        $len = strlen($btop);

        while ($i < $len) {
            if (ctype_digit($btop[$i])) {
                $run = '';
                while ($i < $len && ctype_digit($btop[$i])) {
                    $run .= $btop[$i];
                    $i++;
                }
                $pos += (int)$run;          // a run of matches
                continue;
            }

            // A two-character operation: query base then subject base.
            $q = $btop[$i];
            $s = $btop[$i + 1] ?? '';
            $i += 2;

            if ($q === '-') {
                continue;                    // insertion in the subject: query does not advance
            }

            if ($pos >= $window_start && $pos <= $qlength) {
                $bad++;
            }
            $pos++;                          // mismatch or query gap consumes a query base
        }

        return $bad + min($unaligned, self::THREE_PRIME_WINDOW);
    }

public static function cleanSubjectId($id)
    {
        if (preg_match('/^(?:ref|gb|emb|dbj|lcl)\|([^|]+)\|?$/', $id, $m)) {
            return $m[1];
        }
        return $id;
    }

