functions.code:
public static function cardParams(array $card): array
    {
        $params = [];
        $range = (string)($card['size_range'] ?? '');
        if ($range !== '') $params['PRIMER_PRODUCT_SIZE_RANGE'] = $range;
        foreach (self::CARD_FIELDS as $field) {
            $v = $card[$field] ?? null;
            if ($v === null || $v === '') continue;
            $spec = Primer3Design::OPTIONS[$field];
            $params[$spec['tag']] = $spec['type'] === 'int' ? (int)$v : (float)$v;
        }
        return $params;
    }

public static function validateCard(array $in, array $langs, array $tail_ids): array
    {
        $errors = [];
        $card = ['label' => [], 'blurb' => []];
        foreach (array_unique(array_merge(['en'], $langs)) as $l) {
            $label = trim((string)($in['label'][$l] ?? ''));
            $blurb = trim((string)($in['blurb'][$l] ?? ''));
            if (mb_strlen($label) > 80)  $errors[] = "The name ($l) is longer than 80 characters.";
            if (mb_strlen($blurb) > 400) $errors[] = "The description ($l) is longer than 400 characters.";
            if ($label !== '') $card['label'][$l] = $label;
            if ($blurb !== '') $card['blurb'][$l] = $blurb;
        }
        if (!isset($card['label']['en'])) $errors[] = 'The card needs a name in English.';

        $range = preg_replace('/\s+/', '', (string)($in['size_range'] ?? ''));
        if ($range === '') {
            $errors[] = 'The card needs a product size, as low-high (e.g. 1000-2500).';
        } elseif (!preg_match('/^(\d+)-(\d+)$/', $range, $m) || (int)$m[1] < 1 || (int)$m[1] >= (int)$m[2]) {
            $errors[] = 'Product size must be low-high with low below high, e.g. 1000-2500.';
        } elseif ((int)$m[2] > 20000) {
            $errors[] = 'Product size above 20,000 bp is not something PCR will make.';
        } else {
            $card['size_range'] = $range;
        }

        foreach (self::CARD_FIELDS as $field) {
            $raw = trim((string)($in[$field] ?? ''));
            if ($raw === '') continue;
            $spec = Primer3Design::OPTIONS[$field];
            if (!is_numeric($raw)) { $errors[] = $spec['label'] . ' must be a number.'; continue; }
            $v = $spec['type'] === 'int' ? (int)round((float)$raw) : round((float)$raw, 1);
            if ($v < $spec['min'] || $v > $spec['max']) {
                $errors[] = $spec['label'] . " must be between {$spec['min']} and {$spec['max']}.";
                continue;
            }
            $card[$field] = $v;
        }
        $eff = array_merge(Primer3Design::DEFAULTS, self::cardParams($card));
        $tag = fn($f) => $eff[Primer3Design::OPTIONS[$f]['tag']] ?? null;
        foreach (['size' => 'Primer length', 'tm' => 'Tm'] as $p => $name) {
            [$lo, $opt, $hi] = [$tag("{$p}_min"), $tag("{$p}_opt"), $tag("{$p}_max")];
            if ($lo !== null && $opt !== null && $hi !== null && !($lo <= $opt && $opt <= $hi)) {
                $errors[] = "$name must be minimum ≤ optimum ≤ maximum (it would run as $lo / $opt / $hi).";
            }
        }
        [$glo, $ghi] = [$tag('gc_min'), $tag('gc_max')];
        if ($glo !== null && $ghi !== null && $glo > $ghi) {
            $errors[] = "GC content minimum must not be above the maximum (it would run as $glo / $ghi).";
        }

        $tail = trim((string)($in['tail'] ?? ''));
        if ($tail !== '' && $tail !== 'none') {
            if (!in_array($tail, $tail_ids, true)) $errors[] = 'That tag is not one Primer Maker offers.';
            else $card['tail'] = $tail;
        }
        return [$card, $errors];
    }

public static function catalogue(array $configured = [])
    {
        $out = [];
        foreach (array_merge(self::BUILTIN, $configured) as $entry) {
            if (!is_array($entry) || !isset($entry['id'])) {
                continue;
            }

            $forward = self::normalise($entry['forward'] ?? '');
            $reverse = self::normalise($entry['reverse'] ?? '');

            // A configured entry with no usable sequence is dropped rather than
            // offered: picking it would silently produce untailed oligos, which
            // is the failure that looks most like success.
            if ($forward === '' && $reverse === '') {
                continue;
            }
            if (self::validate($forward) !== '' || self::validate($reverse) !== '') {
                continue;
            }

            $out[(string)$entry['id']] = [
                'id'      => (string)$entry['id'],
                'label'   => (string)($entry['label'] ?? $entry['id']),
                'forward' => $forward,
                'reverse' => $reverse,
                'note'    => (string)($entry['note'] ?? ''),
            ];
        }

        return $out;
    }

functions.comment:
/**
* Strip whitespace and upper-case. Does NOT validate — see validate().
*/

functions.code:
public static function normalise($seq)
    {
        return strtoupper(preg_replace('/\s+/', '', (string)$seq));
    }

public static function validate($seq)
    {
        $seq = self::normalise($seq);
        if ($seq === '') {
            return '';
        }
        if (preg_match('/[^ACGT]/', $seq)) {
            // Not N, and not degenerate codes: a tail is synthesised exactly as
            // written, so an ambiguity code is an order the vendor cannot fill.
            return 'A tag can only contain A, C, G and T — it is synthesised exactly as written.';
        }
        if (strlen($seq) > self::MAX_LENGTH) {
            return 'That tag is ' . strlen($seq) . ' bases; ' . self::MAX_LENGTH
                 . ' is the most this tool accepts. Check you have not pasted a template sequence.';
        }
        return '';
    }

public static function resolve($id, $custom_f, $custom_r, array $catalogue)
    {
        $none = ['id' => 'none', 'label' => '', 'forward' => '', 'reverse' => '',
                 'note' => '', 'errors' => []];

        if ($id === '' || $id === 'none') {
            return $none;
        }

        if ($id === 'custom') {
            $forward = self::normalise($custom_f);
            $reverse = self::normalise($custom_r);

            $errors = [];
            foreach (['forward' => $forward, 'reverse' => $reverse] as $side => $seq) {
                $err = self::validate($seq);
                if ($err !== '') {
                    $errors[] = ucfirst($side) . ' tag: ' . $err;
                }
            }

            // Asking for a custom tail and giving no sequence is a mistake worth
            // naming. Falling through to "no tail" would design exactly what was
            // asked for and quietly ignore the part the user cared about.
            if ($errors === [] && $forward === '' && $reverse === '') {
                $errors[] = 'You chose a custom tag but did not enter a sequence for either primer.';
            }

            return [
                'id'      => 'custom',
                'label'   => 'Custom tag',
                'forward' => $forward,
                'reverse' => $reverse,
                'note'    => '',
                'errors'  => $errors,
            ];
        }

        if (!isset($catalogue[$id])) {
            // ⚠️ array_merge, NOT the + operator. $none already carries an empty
            // 'errors', and + keeps the LEFT side's value for a duplicate key —
            // so `$none + ['errors' => [...]]` throws the message away and
            // returns a clean "no tail". An unknown adapter would then design
            // untailed primers and say nothing, which is precisely the silent
            // failure this class exists to avoid. Caught by a test, not by
            // reading it.
            return array_merge($none, ['errors' => ['That tag is not one this site offers.']]);
        }

        return array_merge($catalogue[$id], ['errors' => []]);
    }

public static function apply(array $pair, array $tail)
    {
        $forward = $tail['forward'] ?? '';
        $reverse = $tail['reverse'] ?? '';

        if ($forward === '' && $reverse === '') {
            return $pair;
        }

        $left  = (string)($pair['left_sequence']  ?? '');
        $right = (string)($pair['right_sequence'] ?? '');

        // ⚠️ THE SIDE'S OWN TAIL DECIDES, not "a tail was chosen". A custom tail
        // may be forward-only (resolve() rejects only the case where BOTH boxes
        // are empty), and this branch used to test the PRIMER for emptiness — so
        // the untailed side got a *_tailed key holding the bare primer. The table
        // hid it, but oligoRecords() emitted it as a second FASTA record labelled
        // "(with tail)", identical to the first: a duplicate oligo on the order
        // form, and an inflated count on the button beside it.
        if ($forward !== '' && $left !== '') {
            $pair['left_tailed'] = $forward . $left;
            $pair['left_oligo_length'] = strlen($pair['left_tailed']);
        }
        if ($reverse !== '' && $right !== '') {
            $pair['right_tailed'] = $reverse . $right;
            $pair['right_oligo_length'] = strlen($pair['right_tailed']);
        }

        // The amplicon that comes out of the tube carries both tails. The
        // untailed number is the insert; this is the band on the gel. Both
        // matter, so both are reported — the workflow this replaces only ever
        // gave the first, which is the one you do NOT measure.
        if (isset($pair['product_size']) && $pair['product_size'] !== '') {
            $pair['product_size_tailed'] = (int)$pair['product_size']
                                         + strlen($forward) + strlen($reverse);
        }

        // ...and so does its SEQUENCE. The forward tag is copied onto the top
        // strand as written; the reverse tag is copied onto the BOTTOM strand,
        // so on the top strand it reads as its reverse complement at the far
        // end. Writing $reverse here unreversed would produce a string that
        // looks right, is the right LENGTH — product_size_tailed agrees with it
        // either way — and is not the molecule.
        if (($pair['product_sequence'] ?? '') !== '') {
            $pair['product_sequence_tailed'] = $forward . $pair['product_sequence']
                                             . self::reverseComplement($reverse);
        }

        return $pair;
    }

private static function reverseComplement($seq)
    {
        return strrev(strtr(strtoupper((string)$seq),
                            ['A' => 'T', 'T' => 'A', 'C' => 'G', 'G' => 'C']));
    }

public static function oligoRecords($record_id, array $pairs, array $tail)
    {
        $tailed  = ($tail['forward'] ?? '') !== '' || ($tail['reverse'] ?? '') !== '';
        $records = [];

        foreach ($pairs as $pair) {
            $rank = $pair['rank'] ?? 0;
            foreach (['left', 'right'] as $side) {
                $seq = $pair[$side . '_sequence'] ?? '';
                if ($seq === '') {
                    continue;
                }

                // Naming is PrimerNames' job, not this class's — the table, the
                // TSV and the Check hand-off all have to read the same name, and
                // this file is about tails.
                $name = PrimerNames::primer($record_id, $rank, $side);

                $records[] = [
                    'name'     => $name,
                    'sequence' => $seq,
                    'side'     => $side,
                    'rank'     => $rank,
                    'tailed'   => false,
                    'length'   => strlen($seq),
                ];

                if ($tailed && !empty($pair[$side . '_tailed'])) {
                    $records[] = [
                        'name'     => $name . '_' . ($tail['id'] ?? 'tail'),
                        'sequence' => $pair[$side . '_tailed'],
                        'side'     => $side,
                        'rank'     => $rank,
                        'tailed'   => true,
                        'length'   => strlen($pair[$side . '_tailed']),
                    ];
                }
            }
        }

        return $records;
    }

public static function parse($raw)
    {
        $result = ['sequence' => '', 'junctions' => [], 'targets' => [],
                   'errors' => [], 'notes' => []];

        $clean         = '';
        $bases         = 0;       // bases emitted so far = 1-based position of the last one
        $open_at       = null;    // where the current '[' started, in base coordinates
        $legacy_used   = false;
        $bracket_depth = 0;

        $length = strlen($raw);
        for ($i = 0; $i < $length; $i++) {
            $ch = $raw[$i];

            if (ctype_space($ch)) {
                continue;
            }

            if ($ch === self::JUNCTION || $ch === self::JUNCTION_LEGACY) {
                if ($ch === self::JUNCTION_LEGACY) {
                    $legacy_used = true;
                }
                // A mark before any base, or two in a row, points at nothing.
                // Dropped rather than recorded as a junction at position 0, which
                // primer3 would take as a real constraint one base into the
                // sequence and quietly satisfy somewhere unintended.
                if ($bases === 0) {
                    $result['notes'][] = 'A junction mark at the very start of the sequence was '
                                       . 'ignored — there is nothing before it for a primer to cross.';
                    continue;
                }
                if (in_array($bases, $result['junctions'], true)) {
                    continue;                       // "||" is one junction, not two
                }
                $result['junctions'][] = $bases;    // junction FOLLOWS this base
                continue;
            }

            if ($ch === '[') {
                if ($bracket_depth > 0) {
                    $result['errors'][] = 'The sequence has a "[" inside another "[…]". Regions to '
                                        . 'include cannot be nested.';
                    return $result;
                }
                $bracket_depth++;
                $open_at = $bases + 1;              // the region starts at the NEXT base
                continue;
            }

            if ($ch === ']') {
                if ($bracket_depth === 0) {
                    $result['errors'][] = 'The sequence has a "]" with no matching "[" before it.';
                    return $result;
                }
                $bracket_depth--;
                $len = $bases - $open_at + 1;
                if ($len < 1) {
                    $result['errors'][] = 'The sequence has an empty "[]" — put the bases you want '
                                        . 'included between the brackets.';
                    return $result;
                }
                $result['targets'][] = [$open_at, $len];
                $open_at = null;
                continue;
            }

            $clean .= $ch;
            $bases++;
        }

        if ($bracket_depth > 0) {
            $result['errors'][] = 'The sequence has a "[" that is never closed. Add the matching "]".';
            return $result;
        }

        $result['sequence'] = strtoupper($clean);

        // ---- report what was found; a mark must never take effect silently ----
        if ($result['junctions']) {
            $n = count($result['junctions']);
            $result['notes'][] = $n . ' junction mark' . ($n === 1 ? '' : 's')
                               . ' found in the sequence, at position'
                               . ($n === 1 ? ' ' : 's ')
                               . implode(', ', array_map('number_format', $result['junctions']))
                               . '. A primer must cross '
                               . ($n === 1 ? 'it' : 'at least one of them') . '.';
        }
        if ($legacy_used) {
            // The likeliest cause of a surprise here is a pasted ALIGNMENT.
            $result['notes'][] = 'Dashes were read as junction marks. If you meant them as alignment '
                               . 'gaps, remove them and use "|" for junctions instead.';
        }
        if ($result['targets']) {
            foreach ($result['targets'] as list($s, $l)) {
                $result['notes'][] = 'Every product will contain bases ' . number_format($s)
                                   . '–' . number_format($s + $l - 1) . ', marked with [ ].';
            }
        }

        return $result;
    }

public static function hasMarkup($raw)
    {
        return strpbrk((string)$raw, self::JUNCTION . self::JUNCTION_LEGACY . '[]') !== false;
    }

public static function annotate($sequence, array $junctions)
    {
        $sequence  = strtoupper(preg_replace('/\s+/', '', (string)$sequence));
        $positions = array_values(array_unique(array_filter(
            array_map('intval', $junctions),
            fn($p) => $p > 0 && $p < strlen($sequence)      // a mark after the last base is a no-op
        )));
        sort($positions);

        $out  = '';
        $prev = 0;
        foreach ($positions as $p) {
            $out .= substr($sequence, $prev, $p - $prev) . self::JUNCTION;
            $prev = $p;
        }

        return $out . substr($sequence, $prev);
    }

function moop_registry_source_files(string $type, ?string $base = null): array
{
    $base = $base ?? dirname(__DIR__);

    if ($type === 'js') {
        // Mirrors tools/generate_js_registry_json.php: top-level js/ plus js/modules/, and
        // NOT recursive — which is what keeps js/vendor/ (third-party code we do not
        // document) out of the registry.
        $files = array_merge(
            glob("$base/js/*.js") ?: [],
            glob("$base/js/modules/*.js") ?: []
        );
        $files = array_filter($files, function ($f) {
            return strpos($f, '.min.js') === false && strpos($f, 'unused') === false;
        });
        sort($files);
        return array_values($files);
    }

    // Mirrors tools/generate_registry_json.php: these six directories RECURSIVELY, plus the
    // top-level scripts. Recursive matters — an earlier glob-based version silently skipped
    // lib/jbrowse/, admin/api/ and admin/pages/.
    $scan_dirs = ["$base/lib", "$base/tools", "$base/admin", "$base/includes", "$base/api", "$base/scripts"];
    $files     = glob("$base/*.php") ?: [];

    foreach ($scan_dirs as $dir) {
        if (!is_dir($dir)) continue;
        $it = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::LEAVES_ONLY,
            RecursiveIteratorIterator::CATCH_GET_CHILD
        );
        foreach ($it as $f) {
            if ($f->isFile() && strtolower($f->getExtension()) === 'php') {
                $files[] = $f->getPathname();
            }
        }
    }

    // Same exclusions the generator applies.
    $exclude = ['.backup', 'generate_registry', 'function_registry'];
    $files = array_filter($files, function ($f) use ($exclude) {
        foreach ($exclude as $pattern) {
            if (strpos($f, $pattern) !== false) return false;
        }
        return true;
    });

    $files = array_values(array_unique($files));
    sort($files);
    return $files;
}

function moop_registry_relpath(string $path): string {
    $base = realpath(dirname(__DIR__)) . '/';
    $real = realpath($path) ?: $path;
    return strpos($real, $base) === 0 ? substr($real, strlen($base)) : $real;
}

functions.comment:
/**
* Newest modification time across a registry's source files, and which file it was.
*
* @return array{time:int,file:string|null,count:int}
*/

functions.code:
function moop_registry_newest_source(string $type, ?string $base = null): array
{
    $newest = 0;
    $newest_file = null;
    $files = moop_registry_source_files($type, $base);
    foreach ($files as $f) {
        $t = @filemtime($f);
        if ($t !== false && $t > $newest) {
            $newest = $t;
            $newest_file = $f;
        }
    }
    return ['time' => $newest, 'file' => $newest_file, 'count' => count($files)];
}

function moop_metrics_dir(): string {
    require_once __DIR__ . '/cache_paths.php';   // functions only; access_control.php does not load it
    return moop_cache_root() . '/metrics';
}

functions.comment:
/**
* Parameters worth keeping to reproduce a slow request — an ALLOWLIST, never "everything but".
* Search words ARE kept here (search_keywords, quoted, and the gene-ID lookup's q): Sofia,
* 2026-10-28 — for a slow or failed search they are what is needed to see what went on. Only
* for those requests, admin-only, 30 days; the usage tables still never record them.
* Deliberately absent: BLAST sequences (query — can be unpublished data, and large), pasted
* gene-ID lists (uniquenames), tokens (JBrowse puts its JWT in the URL), anything password-like.
*/
const MOOP_METRICS_PARAM_ALLOW = ['organism', 'organisms', 'assembly', 'gene_set', 'uniquename', 'transcript', 'loc',
'sequence_type', 'group', 'range', 'feature_type', 'source_names',
'search_keywords', 'quoted', 'scope', 'no_annotations', 'q'];

function moop_metrics_dir(): string {
require_once __DIR__ . '/cache_paths.php';   // functions only; access_control.php does not load it
return moop_cache_root() . '/metrics';
}

/** Run once per request, from access_control.php. */

functions.code:
function moop_metrics_register(): void {
    static $done = false;
    if ($done || PHP_SAPI === 'cli') return;
    $done = true;
    moop_metrics_disk_read_bytes(true);    // baseline for this request
    register_shutdown_function('moop_metrics_record');
}

function moop_metrics_disk_read_bytes(bool $reset = false): ?int {
    static $start = null;
    $ru = function_exists('getrusage') ? getrusage() : [];
    if (!isset($ru['ru_inblock'])) return null;
    $bytes = (int) $ru['ru_inblock'] * 512;
    if ($reset) { $start = $bytes; return 0; }
    return $start === null ? null : max(0, $bytes - $start);
}

functions.comment:
/**
* Bytes this process has read from storage — NOT from the RAM page cache. With $reset, remember the
* current value as the request's starting point; otherwise return the bytes read since then.
*
* getrusage()'s ru_inblock (512-byte blocks the kernel had to read from the device), not
* /proc/self/io: php-fpm workers switch from root to the web user at start, which makes a
* process "non-dumpable", and a non-dumpable process cannot read its own /proc/self/io — the
* first version recorded nothing. Measured 2026-10-28: a just-evicted database read 16 MB in
* 20 ms; the same query again read 0 KB in 3.9 ms.
*/
function moop_metrics_disk_read_bytes(bool $reset = false): ?int {
static $start = null;
$ru = function_exists('getrusage') ? getrusage() : [];
if (!isset($ru['ru_inblock'])) return null;
$bytes = (int) $ru['ru_inblock'] * 512;
if ($reset) { $start = $bytes; return 0; }
return $start === null ? null : max(0, $bytes - $start);
}

/** The allowlisted parameters of this request, as a query string ('' when none). */

functions.code:
function moop_metrics_params(array $params): string {
    $keep = [];
    foreach (MOOP_METRICS_PARAM_ALLOW as $k) {
        if (!isset($params[$k])) continue;
        $v = is_array($params[$k]) ? array_slice(array_filter($params[$k], 'is_scalar'), 0, 20) : $params[$k];
        if (is_scalar($v) && strlen((string) $v) > 300) continue;
        $keep[$k] = $v;
    }
    $q = http_build_query($keep);
    return strlen($q) > 1000 ? substr($q, 0, 1000) : $q;
}

function moop_metrics_record(): void {
    $dir = moop_metrics_dir();
    if ($dir === '' || !moop_ensure_cache_dir($dir)) return;

    $start  = (float) ($_SERVER['REQUEST_TIME_FLOAT'] ?? microtime(true));
    $status = http_response_code();
    $ms     = (int) round((microtime(true) - $start) * 1000);
    $notable = $ms >= MOOP_METRICS_SLOW_MS || (int) $status >= 500;
    $date   = date('Y-m-d', (int) $start);
    $file   = $dir . "/requests-$date.tsv";

    // Safety cap (see MOOP_METRICS_DAILY_CAP_MB): count, do not write, ordinary requests.
    if (!$notable) {
        clearstatcache(true, $file);
        $total = @disk_total_space($dir);
        $free  = @disk_free_space($dir);
        if ((is_file($file) && filesize($file) > MOOP_METRICS_DAILY_CAP_MB * 1048576)
            || ($total && $free !== false && 100 * $free / $total < MOOP_METRICS_MIN_FREE_PCT)) {
            @file_put_contents($dir . "/skipped-$date.cnt", '.', FILE_APPEND);
            return;
        }
    }

    $disk = moop_metrics_disk_read_bytes();
    $line = moop_metrics_line([
        'ts'      => sprintf('%.3f', $start),
        'script'  => moop_metrics_script_name($_SERVER['SCRIPT_FILENAME'] ?? ''),
        'method'  => $_SERVER['REQUEST_METHOD'] ?? '',
        'status'  => $status === false ? '' : (string) $status,
        'ms'      => (string) $ms,
        'peak_mb' => sprintf('%.1f', memory_get_peak_usage(true) / 1048576),
        'user'    => (string) ($_SESSION['username'] ?? ''),
        'level'   => (string) ($_SESSION['access_level'] ?? 'PUBLIC'),
        'ip'      => (string) ($_SERVER['REMOTE_ADDR'] ?? ''),
        'agent'   => substr((string) ($_SERVER['HTTP_USER_AGENT'] ?? ''), 0, 160),
        'db_ms'   => class_exists('MoopDbTimer', false) ? (string) (int) round(MoopDbTimer::$ms) : '',
        'db_n'    => class_exists('MoopDbTimer', false) ? (string) MoopDbTimer::$n : '',
        'disk_kb' => $disk === null ? '' : (string) (int) round($disk / 1024),
        'params'  => $notable ? moop_metrics_params($_GET + $_POST) : '',
        'visitor' => isset($GLOBALS['moop_human_check_outcome']) ? 'turned_away' : (string) ($GLOBALS['moop_verified_crawler']
                     ?? (function_exists('moop_human_verified') && session_status() === PHP_SESSION_ACTIVE
                         && empty($_SESSION['logged_in']) && moop_human_verified() ? 'human' : '')),
        'sid'     => session_status() === PHP_SESSION_ACTIVE && session_id() !== '' ? substr(sha1(session_id()), 0, 12) : '',
        'nav'     => ($_SERVER['REQUEST_METHOD'] ?? '') === 'GET'
                     && strcasecmp($_SERVER['HTTP_X_REQUESTED_WITH'] ?? '', 'XMLHttpRequest') !== 0
                     && stripos($_SERVER['HTTP_ACCEPT'] ?? '', 'text/html') !== false ? '1' : '',
        'ref'     => moop_metrics_referrer((string) ($_SERVER['HTTP_REFERER'] ?? ''), (string) ($_SERVER['HTTP_HOST'] ?? '')),
    ] + moop_metrics_context($_GET + $_POST));
    @file_put_contents($file, $line, FILE_APPEND);
}

