$t = $t ?? ['count' => 0, 'total_ms' => 0, 'max_mb' => 0, 'level' => $v['level'], 'ip' => $v['ip']];
$t['count'] += $v['count'];
$t['total_ms'] += $v['total_ms'];
$t['max_mb'] = max($t['max_mb'], $v['max_mb']);
