/** Remove a bundle's now-empty directories (bottom up); anything still holding a file stays. */

functions.code:
function moop_retire_rmdir_empty(string $dir): void {
    foreach (glob("$dir/*", GLOB_ONLYDIR) ?: [] as $sub) moop_retire_rmdir_empty($sub);
    @rmdir($dir);
}

function moop_rows_to_tsv(array $rows): string
{
    if (!$rows) return '';
    $rows   = array_values($rows);
    $header = array_map('strval', array_keys($rows[0]));
    $lines  = [implode("\t", $header)];
    foreach ($rows as $row) {
        $cells = [];
        foreach ($header as $key) {
            $cells[] = str_replace(["\t", "\r", "\n"], ' ', moop_js_cell_string($row[$key] ?? null));
        }
        $lines[] = implode("\t", $cells);
    }
    return implode("\n", $lines) . "\n";
}

