/**
* Rows of named cells -> TSV, byte-for-byte what the browser's moopRowsToTsv()
* (js/modules/utilities.js) writes for the same rows.
*
* Why the twin: the Primer Maker and Primer BLAST pages build their download in the browser from
* rows the server embedded as JSON; the API (api/v1/primer_*.php) writes the SAME rows as TSV on
* the server. A person and an agent asking the same question must get the same file, so the rules
* live in two languages and tests/js_smoke_tests.js runs both on one set of rows and compares.
*
* The rules (both sides): header = the FIRST row's keys; a later row's missing key is an empty
* cell and its extra keys are dropped; null is empty; tab, CR and LF inside a value become a
* space; lines end "\n", including the last. A number is written the way JavaScript's String()
* writes it after the page's JSON round trip (PHP alone would write 1.0 as "1" but 1e-7 as
* "1.0E-7"); true/false as "true"/"false".
*/

function moop_rows_to_tsv(array $rows): string
{
if (!$rows) return '';
$rows   = array_values($rows);
$header = array_map('strval', array_keys($rows[0]));
$lines  = [implode("\t", $header)];
foreach ($rows as $row) {
$cells = [];
foreach ($header as $key) {
$cells[] = str_replace(["\t", "\r", "\n"], ' ', moop_js_cell_string($row[$key] ?? null));
}
$lines[] = implode("\t", $cells);
}
return implode("\n", $lines) . "\n";
}

/** One cell as JavaScript's String() writes the value JSON.parse() gave it. */

functions.code:
function moop_js_cell_string($v): string
{
    if ($v === null)  return '';
    if (is_bool($v))  return $v ? 'true' : 'false';
    if (is_int($v))   return (string) $v;
    if (is_float($v)) return moop_js_number_string($v);
    if (is_array($v)) return implode(',', array_map('moop_js_cell_string', $v));   // String([a, b]) = "a,b"
    return (string) $v;
}

function moop_js_number_string(float $f): string
{
    if (is_nan($f))      return 'NaN';
    if (is_infinite($f)) return $f > 0 ? 'Infinity' : '-Infinity';
    if ($f == 0.0)       return '0';   // -0 too: String(-0) is "0"

    // The shortest round-trip digits, as JSON writes them (serialize_precision -1 -- set here
    // rather than trusted, since a host can configure it otherwise).
    $old = ini_get('serialize_precision');
    ini_set('serialize_precision', '-1');
    $s = json_encode($f);
    ini_set('serialize_precision', $old);

    $neg = $s[0] === '-';
    if ($neg) $s = substr($s, 1);
    if (!preg_match('/^(\d+)(?:\.(\d+))?(?:[eE]([+-]?\d+))?$/', $s, $m)) return ($neg ? '-' : '') . $s;

    $all    = $m[1] . ($m[2] ?? '');
    $lead   = strlen($all) - strlen(ltrim($all, '0'));
    $digits = rtrim(ltrim($all, '0'), '0');           // the significant digits
    $k      = strlen($digits);
    $n      = strlen($m[1]) + (int) ($m[3] ?? 0) - $lead;   // value = 0.<digits> x 10^n

    // ECMAScript Number::toString, steps 6-10.
    if ($k <= $n && $n <= 21) {
        $out = $digits . str_repeat('0', $n - $k);
    } elseif (0 < $n && $n <= 21) {
        $out = substr($digits, 0, $n) . '.' . substr($digits, $n);
    } elseif (-6 < $n && $n <= 0) {
        $out = '0.' . str_repeat('0', -$n) . $digits;
    } else {
        $e   = $n - 1;
        $out = $digits[0] . ($k > 1 ? '.' . substr($digits, 1) : '') . 'e' . ($e >= 0 ? '+' : '-') . abs($e);
    }
    return ($neg ? '-' : '') . $out;
}

function moop_scope_selector_data(bool $include_blast_only = false): array {
    $organism_data    = ConfigManager::getInstance()->getPath('organism_data');
    $sources_by_group = getAccessibleGeneSets(null, null, null, $include_blast_only);
    $sources          = flattenSourcesList($sources_by_group);

    $tree = [];
    $organism_info = [];
    $assembly_names = [];
    $blast_only = [];   // [organism][assembly] = true: a BLAST-only genome (its "gene set" is 'blast_only')
    foreach ($sources as $src) {
        $org = $src['organism'];
        $asm = $src['assembly'];
        $gs  = (string)($src['gene_set'] ?? '');

        $tree[$org][$asm] ??= [];
        if (!empty($src['blast_only'])) $blast_only[$org][$asm] = true;
        if ($gs !== '' && !in_array($gs, $tree[$org][$asm], true)) {
            $tree[$org][$asm][] = $gs;
        }
        if (!isset($organism_info[$org])) {
            $info = loadOrganismInfo($org, $organism_data) ?: [];
            $organism_info[$org] = [
                'genus'       => $info['genus']       ?? '',
                'species'     => $info['species']     ?? '',
                'common_name' => $info['common_name'] ?? '',
            ];
        }
        if (!isset($assembly_names[$org][$asm])) {
            $assembly_names[$org][$asm] = genome_display_name($src['genome_name'] ?? '', $asm);   // '' for none / "NA"
        }
    }

    ksort($tree);
    foreach ($tree as &$asms) {
        ksort($asms);
        foreach ($asms as &$gene_sets) sort($gene_sets);
        unset($gene_sets);
    }
    unset($asms);

    return [
        'tree'             => $tree,
        'organism_info'    => $organism_info,
        'assembly_names'   => $assembly_names,
        // From the visitor's own sources, so a chip never names a group they cannot see.
        'organism_groups'  => moop_organism_groups_map($sources),   // sorted, one order site-wide
        'blast_only'       => $blast_only,
        'sources_by_group' => $sources_by_group,
    ];
}

function moop_scope_context_from_request(array $scope): ?array {
    $tree = $scope['tree'];
    $ctx  = parseContextParameters();

    if ($ctx['organism'] !== '') {
        if (!isset($tree[$ctx['organism']])) return null;
        $out = ['organisms' => [$ctx['organism']]];
        if ($ctx['assembly'] !== '') $out['assembly'] = $ctx['assembly'];
        if ($ctx['gene_set'] !== '') $out['gene_set'] = $ctx['gene_set'];
        return $out;
    }

    if ($ctx['group'] !== '') {
        $orgs = array_keys($scope['sources_by_group'][$ctx['group']] ?? []);
    } else {
        // Array or comma-separated string, as the other tools accept it.
        $orgs = parseOrganismParameter($_POST['organisms'] ?? $_GET['organisms'] ?? '')['organisms'];
    }
    $orgs = array_values(array_unique(array_filter(
        array_map('strval', array_filter($orgs, 'is_scalar')),
        fn($o) => isset($tree[$o])
    )));
    return $orgs ? ['organisms' => $orgs] : null;
}

function moop_scope_single_state(array $scope, string $fallback = '', bool $auto_first = true): array {
    $tree = $scope['tree'];
    $ctx  = parseContextParameters();
    $is_row = function (string $key) use ($tree): bool {
        $p = explode('|', $key);
        return count($p) === 3 && in_array($p[2], $tree[$p[0]][$p[1]] ?? [], true);
    };

    $filter = '';
    $group_or_list = false;
    if ($ctx['organism'] !== '' && isset($tree[$ctx['organism']])) {
        $info   = $scope['organism_info'][$ctx['organism']] ?? [];
        $filter = trim(($info['genus'] ?? '') . ' ' . ($info['species'] ?? '')) ?: str_replace('_', ' ', $ctx['organism']);
    } elseif ($ctx['group'] !== '') {
        $filter = $ctx['group'];
        $group_or_list = true;
    }
    // An organisms list narrows the list to those organisms (names this visitor cannot see are
    // dropped). Only without an organism context, which already names the one to show.
    $only = [];
    if ($ctx['organism'] === '') {
        $only = array_values(array_unique(array_filter(
            array_map('strval', parseOrganismParameter($_POST['organisms'] ?? $_GET['organisms'] ?? '')['organisms']),
            fn($o) => isset($tree[$o])
        )));
        if ($only) $group_or_list = true;
    }

    $posted = (string)($_POST['selected_source'] ?? '');
    if ($posted !== '' && $is_row($posted)) {
        $selected = $posted;
    } elseif ($group_or_list) {
        $selected = '';
    } elseif ($fallback !== '' && $is_row($fallback)) {
        $selected = $fallback;
    } elseif (!$auto_first) {
        $selected = '';   // the tool starts with nothing chosen (Primer BLAST always has)
    } else {
        // The first gene set in group order -- the row the old source list selected first,
        // so opening a tool directly starts where it always did.
        $selected = '';
        foreach (flattenSourcesList($scope['sources_by_group']) as $src) {
            $key = $src['organism'] . '|' . $src['assembly'] . '|' . ($src['gene_set'] ?? '');
            if ($is_row($key)) { $selected = $key; break; }
        }
    }
    return ['selected' => $selected, 'filter' => $filter, 'only' => $only];
}

function moop_scope_restrict(array $scope, array $organisms): array {
    $tree = [];
    foreach ($scope['tree'] as $org => $asms) {
        if (!isset($organisms[$org])) continue;
        $keep = $organisms[$org];
        foreach ($asms as $asm => $gss) {
            if (is_array($keep) && $keep && !in_array($asm, $keep, true)) continue;
            $tree[$org][$asm] = $gss;
        }
    }
    $scope['tree'] = $tree;
    return $scope;
}

function moop_atlas_dir(string $organism, string $assembly, string $gene_set): string {
    $clean = fn(string $s) => preg_replace('/[^A-Za-z0-9_.-]/', '', $s);
    return rtrim(ConfigManager::getInstance()->getPath('organism_data'), '/') . '/'
         . $clean($organism) . '/' . $clean($assembly) . '/' . $clean($gene_set) . '/spatial_atlas';
}

function moop_atlas_file(string $organism, string $assembly, string $gene_set, string $name): string {
    return moop_atlas_dir($organism, $assembly, $gene_set) . '/' . preg_replace('/[^a-z0-9_-]/', '', $name) . '.sqlite';
}

