const MOOP_ATLAS_ENCODINGS = ['uint8' => 255, 'uint16' => 65535, 'float32' => 0];
const MOOP_ATLAS_REQUIRED  = ['name', 'title', 'organism', 'assembly', 'gene_set', 'citation'];

