/** @return array [vmin, vmax, blob] */
function moop_atlas_encode(array $vals, string $encoding): array {
if (!isset(MOOP_ATLAS_ENCODINGS[$encoding])) throw new InvalidArgumentException("unknown encoding $encoding");
$min = min($vals);
$max = max($vals);
