function moop_monitor_fmt_bytes(float $b): string {
    foreach (['B', 'KB', 'MB', 'GB', 'TB'] as $i => $u) {
        if ($b < 1024 || $u === 'TB') return ($i ? round($b, 1) : (int) $b) . ' ' . $u;
        $b /= 1024;
    }
    return '';
