function moop_monitor_capacity(array $points, array $pages, ?array $now, ?int $max_children): array {
    // Hourly records (7 d) carry both an average and a peak: averages from averages, peaks from
    // peaks. Minute records (24 h) have one value, used for both.
    $vals = function (string $k, bool $peak) use ($points) {
        return array_values(array_filter(array_map(fn($p) => $peak ? ($p[$k . '_max'] ?? ($p[$k] ?? null)) : ($p[$k] ?? null), $points), 'is_numeric'));
    };
    $cpu = $vals('cpu_pct', false);
    $cpu_peaks = $vals('cpu_pct', true);
    $mem = $vals('mem_used_pct', true);
    $avg = fn($a) => $a ? array_sum($a) / count($a) : null;
    $total_mb = (int) ($now['mem_total_mb'] ?? 0);
    $per_worker = ($pages['peak_p95_mb'] ?? 0) + MOOP_FPM_WORKER_BASE_MB;
    $reached = array_sum(array_map(fn($p) => (int) ($p['fpm_max_children_reached'] ?? 0), $points));
    $queued = count(array_filter($points, fn($p) => (int) ($p['fpm_queue_max'] ?? ($p['fpm_queue'] ?? 0)) > 0));
    $suggested = ($total_mb > 0 && $per_worker > 0) ? (int) floor(0.6 * $total_mb / $per_worker) : null;
    return [
        'samples'        => count($points),
        'cpu_avg'        => $avg($cpu) !== null ? round($avg($cpu), 1) : null,
        'cpu_peak'       => $cpu_peaks ? max($cpu_peaks) : null,
        'cpu_busy_share' => $cpu ? round(100 * count(array_filter($cpu, fn($v) => $v >= 80)) / count($cpu)) : null,
        'mem_peak'       => $mem ? max($mem) : null,
        'swap_peak_mb'   => ($s = $vals('swap_used_mb', true)) ? max($s) : 0,
        'workers_reached'=> $reached,
        'queued_samples' => $queued,
        'per_worker_mb'  => round($per_worker, 1),
        'largest_mb'     => (float) ($pages['peak_max_mb'] ?? 0),
        'php_worst_mb'   => $max_children ? (int) round($max_children * $per_worker) : null,
        'total_mb'       => $total_mb,
        'suggested_max_children' => $suggested,
        'iowait_avg'     => ($io = $vals('iowait_pct', false)) ? round($avg($io), 1) : null,
        'iowait_peak'    => ($iop = $vals('iowait_pct', true)) ? max($iop) : null,
    ];
}

function moop_monitor_recommendations(array $cap, array $pages7, array $heavy, ?array $now, array $traffic,
                                      ?array $sync, ?int $max_children, bool $turnstile_on, array $ranges,
                                      string $span = 'in this period', array $self = []): array {
    $out = [];
    $add = function ($level, $title, $detail, $action = null) use (&$out) {
        $out[] = ['level' => $level, 'title' => $title, 'detail' => $detail, 'action' => $action];
    };

    if (($sync['state'] ?? '') === 'error') {
        $add('critical', 'nginx rate-limit settings were not applied', (string) ($sync['message'] ?? ''));
    }

    // ── Capacity ──
    if ($cap['workers_reached'] > 0 || $cap['queued_samples'] > 0) {
        $fits = $cap['suggested_max_children'] !== null && $max_children !== null && $cap['suggested_max_children'] > $max_children;
        $add('critical', 'All PHP workers were busy — visitors waited',
            "Every one of the {$max_children} PHP workers was in use " . ($cap['workers_reached'] ?: $cap['queued_samples']) . ' time(s) in this window; requests queued until one was free. '
            . ($fits ? "RAM allows more workers: raise pm.max_children toward {$cap['suggested_max_children']} (see “How to change the number of PHP workers” below)."
                     : 'RAM does not allow more workers at the measured memory per request — this is the point to add RAM (or to limit the heaviest pages).'));
    }
    // Judge memory by how much is IN USE (MemAvailable), not by swap. Swap here is an amount, not
    // activity: Linux moves idle pages to disk even with plenty free (2026-11-23: 491 MB swapped at
    // 40% used called for "add RAM" -- wrong, and the IT report repeated it). Swap is mentioned
    // only alongside real memory pressure.
    $swap_note = $cap['swap_peak_mb'] > 0 ? ' and ' . $cap['swap_peak_mb'] . ' MB sat in swap' : '';
    if (($cap['mem_peak'] ?? 0) >= 90) {
        $add('critical', 'Memory ran short — time to add RAM',
            'Memory reached ' . $cap['mem_peak'] . '% used' . $swap_note
            . '. Near-full memory pushes pages to disk and makes every page slow. More RAM is the fix; lowering pm.max_children trades it for queueing.');
    } elseif (($cap['mem_peak'] ?? 0) >= 80) {
        $add('warning', 'Memory is getting tight', 'Memory peaked at ' . $cap['mem_peak'] . '% used' . $swap_note . '. Watch it; at 90%, add RAM.');
    }
    if ($cap['php_worst_mb'] !== null && $cap['total_mb'] > 0 && $cap['php_worst_mb'] > 0.7 * $cap['total_mb']) {
        $add('warning', 'Too many PHP workers for this much RAM',
            "If all {$max_children} workers were busy at once with a typical-heavy request ({$cap['per_worker_mb']} MB each, measured), PHP alone would need "
            . round($cap['php_worst_mb'] / 1024, 1) . ' GB of the server’s ' . round($cap['total_mb'] / 1024, 1) . ' GB. '
            . "About {$cap['suggested_max_children']} workers fit while leaving room for the OS and the page cache SQLite depends on. Either lower pm.max_children or add RAM.");
    }
    // Cold databases: many requests read from disk AND the CPUs spend real time waiting on it.
    $io = $pages7['io'] ?? ['measured' => 0, 'cold' => 0];
    $cold_share = $io['measured'] ? 100 * $io['cold'] / $io['measured'] : 0;
    if ($io['measured'] >= 200 && $cold_share >= 25 && ($cap['iowait_avg'] ?? 0) >= 5) {
        $add('warning', 'The databases often are not in RAM — more RAM would make the site faster',
            round($cold_share) . '% of requests over 7 days had to read from disk, and the CPUs spent on average '
            . $cap['iowait_avg'] . '% of their time waiting for it. '
            . (isset($now['db_total_mb'], $now['cache_mb']) ? 'The databases total ' . round($now['db_total_mb'] / 1024, 1) . ' GB; '
                . round($now['cache_mb'] / 1024, 1) . ' GB of RAM is caching files. ' : '')
            . 'See “Databases: warm or cold” for which organisms read the most — that working set is what the cache needs to hold.');
    }
    if (($cap['cpu_busy_share'] ?? 0) >= 25 || ($cap['cpu_avg'] ?? 0) >= 70) {
        $add('warning', 'CPU is busy much of the time — consider more CPUs',
            "CPU averaged {$cap['cpu_avg']}% and was above 80% in {$cap['cpu_busy_share']}% of samples. Short spikes are normal; sustained load like this means more cores would help — but first check the busiest addresses for a crawler.");
    }

    // ── Heavy-group candidates: measurably expensive, not yet limited as heavy ──
    foreach ($pages7['by_script'] ?? [] as $script => $s) {
        $cls = moop_monitor_class($script, $heavy);
        if ($cls === 'heavy' || $cls === 'jbrowse' || !moop_monitor_valid_heavy($script) || $s['count'] < 5) continue;
        if ($s['p95_ms'] < MOOP_METRICS_SLOW_MS && $s['max_mb'] < MOOP_METRICS_BIG_MB) continue;
        $cost = "Over 7 days: {$s['count']} requests, slowest 5% took " . moop_monitor_fmt_ms($s['p95_ms']) . ", peak memory {$s['max_mb']} MB.";
        $limit = 'In the heavy group one address may run it 20 times a minute (3 at once) instead of 2 a second.';
        if (!isset($s['costly'])) {   // a summary without per-address detail: judge on cost alone
            $add('warning', "Add {$script} to the heavy group?", "$cost $limit", ['type' => 'heavy_add', 'script' => $script]);
            continue;
        }
        // Rate limits never apply to this server or the auto-login ranges, so only costly requests
        // from outside are a reason to add it. Until 2026-11-20 internal use alone (an admin, the
        // page audit's curl) produced this advice, where adding the script would change nothing.
        $net = ['n' => 0, 'ips' => 0, 'last' => 0];
        $own = 0;
        foreach ($s['costly'] as $ip => [$n, $last]) {
            $o = moop_monitor_ip_origin((string) $ip, $ranges, $self);
            if ($o === 'internet') { $net['n'] += $n; $net['ips']++; $net['last'] = max($net['last'], $last); }
            else $own += $n;
        }
        if ($net['n'] === 0) continue;
        $who = "Of its slow or memory-hungry requests, {$net['n']} came from " . ($net['ips'] === 1 ? '1 address' : "{$net['ips']} addresses")
            . ' on the internet, the last on ' . date('M j, H:i', (int) $net['last']) . '.'
            . ($own ? " The other {$own} came from your own network or this server, which the rate limits never touch." : '')
            . ($net['ips'] >= 5 && $net['n'] <= 2 * $net['ips']
                ? ' That is one or two requests per address, which a per-address limit would not have slowed; the human check is what stops a crawler spread that thin.' : '');
        $stale = time() - $net['last'] > 2 * 86400
            ? ' If the page has been made faster since then, this advice clears by itself once those requests are 7 days old.' : '';
        $add('warning', "Add {$script} to the heavy group?", "$cost $who $limit$stale",
            ['type' => 'heavy_add', 'script' => $script]);
    }

    // ── Errors ──
    foreach ($pages7['by_script'] ?? [] as $script => $s) {
        if ($s['errors'] > 0) {
            $add('warning', "{$script} failed {$s['errors']} time(s) in 7 days", 'Server errors (5xx). The details are in the PHP error log (Admin → Error Logs).');
        }
    }

    // ── Exposure: is anyone on the public internet reaching the site? ──
    // Counted only from public addresses — never this server, a private address, or an auto-login
    // range (moop_monitor_traffic). Where older records had to be estimated there is no client
    // breakdown, so make no claim about what kind of client it was.
    $net = $traffic['internet'] ?? ['measured' => true, 'req' => 0, 'ua' => [], 'ips' => []];
    if ($net['req'] > 0) {
        $top = array_slice($net['ips'], 0, 3, true);
        $who = implode(', ', array_map(fn($ip, $n) => "{$ip} (" . number_format($n) . ')', array_keys($top), $top));
        $n_addr = count($net['ips']);
        $from = ($net['measured'] ? '' : 'At least ') . number_format($net['req']) . ' request' . ($net['req'] === 1 ? '' : 's')
              . " from public internet addresses {$span}"
              . ($n_addr ? ' — busiest: ' . $who . ($n_addr > 3 ? ', and ' . ($n_addr - 3) . ' more' : '') : '') . '.';
        $auto = $net['measured'] ? (int) (($net['ua']['ai'] ?? 0) + ($net['ua']['script'] ?? 0)) : null;
        if ($auto !== null && $auto > 1000 && !$turnstile_on) {
            $add('warning', 'Crawlers on the internet are reaching the site — turn on the browser check',
                $from . ' ' . number_format($auto) . ' of them came from scripts or AI crawlers ('
                . number_format($net['ua']['ai'] ?? 0) . ' AI). '
                . 'To stop them: Admin → Site Configuration → Turnstile. Logged-in and internal users never see the check.');
        } elseif (!$turnstile_on) {
            // With the human check on, the site is public on purpose: nothing to report here
            // (Who got in, on the Protection view, shows the outside traffic).
            $add('warning', 'The site is reachable from the internet',
                $from . ($auto !== null ? ' ' . number_format($auto) . ' came from scripts or AI crawlers.' : '')
                . ' If the site should be internal-only, ask IT why these addresses can reach it. '
                . 'If it is meant to be public, nothing to do; turn on Turnstile (Site Configuration) if crawlers become a load.');
        }
    }
    foreach (($now['disks'] ?? []) as $label => $d) {
        if ($d['used_pct'] >= 80) {
            $add($d['used_pct'] >= 90 ? 'critical' : 'warning', "Disk {$d['path']} is {$d['used_pct']}% full", $d['free_gb'] . ' GB free.');
        }
    }

    $rank = ['critical' => 0, 'warning' => 1, 'info' => 2];
    usort($out, fn($a, $b) => $rank[$a['level']] <=> $rank[$b['level']]);
    return $out;
}

function moop_monitor_why_slow(array $r): ?string {
    if (($r['disk_kb'] ?? null) === null) return null;
    $ms = max(1, (int) ($r['ms'] ?? 0));
    $db_heavy = ($r['db_ms'] ?? 0) >= 0.5 * $ms;
    $cold = $r['disk_kb'] > MOOP_METRICS_COLD_KB;
    if ($db_heavy && $cold) return 'Cold database';
    if ($db_heavy) return 'Database (warm)';
    if ($cold) return 'Reading files from disk';
    return 'PHP / other';
}

function moop_monitor_unused_data(array $usage): array {
    $sum = function (string $level, string $name) use ($usage): array {
        $in = $out = 0;
        foreach ($usage as $kind => $levels) {
            $c = $levels[$level][$name] ?? null;
            if ($c) { $in += $c['in_v']; $out += $c['out_v']; }
        }
        return [$in, $out];
    };
    $rows = [];
    foreach (getAccessibleGeneSets() as $by_org) {
        foreach ($by_org as $org => $sets) {
            foreach ($sets as $gs) {
                $key = $org . '/' . $gs['assembly'] . '/' . $gs['gene_set'];
                if (isset($rows[$key])) continue;
                [$oi, $oo] = $sum('organism', $org);
                [$gi, $go] = $sum('gene_set', $key);
                $rows[$key] = ['organism' => $org, 'assembly' => $gs['assembly'], 'gene_set' => $gs['gene_set'],
                               'public' => is_public_assembly($org, $gs['assembly']),
                               'org_in' => $oi, 'org_out' => $oo, 'gs_in' => $gi, 'gs_out' => $go];
            }
        }
    }
    uasort($rows, fn($a, $b) => [$a['org_in'] + $a['org_out'], $a['gs_in'] + $a['gs_out'], $a['organism']]
                                <=> [$b['org_in'] + $b['org_out'], $b['gs_in'] + $b['gs_out'], $b['organism']]);
    return array_values($rows);
}

function ncbi_load_local_dump_meta($metadata_path) {
    $f = "$metadata_path/.ncbi_taxonomy_meta.json";
    if (!file_exists($f)) return [];
    return loadJsonFile($f, []);
}

function ncbi_save_local_dump_meta($metadata_path, array $meta) {
    $f = "$metadata_path/.ncbi_taxonomy_meta.json";
    @file_put_contents($f, json_encode($meta, JSON_PRETTY_PRINT));
    @chmod($f, 0664);
}

function ncbi_fetch_remote_md5($md5_url) {
    $ch = curl_init($md5_url);
    curl_setopt_array($ch, [
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_CONNECTTIMEOUT => 5,
        CURLOPT_TIMEOUT        => 5,
        CURLOPT_USERAGENT      => 'MOOP/1.0 Taxonomy Sync',
    ]);
    $body = curl_exec($ch);
    $err  = curl_errno($ch);
    $http = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);

    if ($err || $http !== 200 || !$body) return null;
    // File format: "<md5hash>  new_taxdump.tar.gz\n"
    $parts = preg_split('/\s+/', trim($body));
    return (!empty($parts[0]) && strlen($parts[0]) === 32) ? $parts[0] : null;
}

function ncbi_scan_local_dump(array $taxid_set, string $stored_gz): array {
    if (!file_exists($stored_gz) || empty($taxid_set)) return [];

    $rank_fields = [
        'superkingdom' => 9, 'kingdom' => 8, 'phylum' => 7,
        'class'        => 6, 'order'   => 5, 'family' => 4,
        'genus'        => 3, 'species' => 1,
    ];

    $results = [];
    $needed  = $taxid_set;

    $gz = gzopen($stored_gz, 'r');
    if (!$gz) return [];

    while (!empty($needed) && ($line = gzgets($gz)) !== false) {
        $tab = strpos($line, "\t");
        if ($tab === false) continue;
        $tid = substr($line, 0, $tab);
        if (!isset($needed[$tid])) continue;

        $stripped = rtrim($line, "\r\n");
        if (substr($stripped, -2) === "\t|") $stripped = substr($stripped, 0, -2);
        $parts   = explode("\t|\t", $stripped);
        $lineage = [];
        foreach ($rank_fields as $rank => $idx) {
            $name = isset($parts[$idx]) ? trim($parts[$idx]) : '';
            if ($name !== '') $lineage[] = ['rank' => $rank, 'name' => $name];
        }
        if (!empty($lineage)) {
            $results[$tid] = [
                'lineage' => $lineage,
                'image'   => null,
                'fetched' => date('Y-m-d'),
                'source'  => 'ncbi_dump',
            ];
        }
        unset($needed[$tid]);
    }
    gzclose($gz);

    return $results;
}

function load_lineage_cache($metadata_path) {
    $cache_file = "$metadata_path/taxonomy_lineage_cache.json";
    if (!file_exists($cache_file)) return [];
    $data = loadJsonFile($cache_file, []);
    if (!is_array($data)) return [];
    unset($data['generated']);
    return $data;
}

functions.comment:
/**
* Persist the taxonomy lineage cache to disk.
*/

functions.code:
function save_lineage_cache($lineage_cache, $metadata_path) {
    $cache_file = "$metadata_path/taxonomy_lineage_cache.json";
    $data = $lineage_cache;
    ksort($data);
    $data['generated'] = date('Y-m-d H:i:s');
    if (@file_put_contents($cache_file, json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) !== false) {
        @chmod($cache_file, 0664);
        return true;
    }
    return false;
}

function refresh_lineage_cache($organisms, $lineage_cache, $progress_cb = null) {
    $to_fetch = [];
    foreach ($organisms as $org_name => $data) {
        if (empty($data['taxon_id'])) continue;
        $tid = (string)$data['taxon_id'];
        if (!isset($lineage_cache[$tid])) {
            $to_fetch[$org_name] = $data;
        }
    }

    if (empty($to_fetch)) return $lineage_cache;

    $config    = ConfigManager::getInstance();
    $stored_gz = $config->getPath('metadata_path') . '/ncbi_rankedlineage.dmp.gz';

    if (!file_exists($stored_gz)) {
        $missing = implode(', ', array_keys($to_fetch));
        error_log("refresh_lineage_cache: local NCBI dump not found at $stored_gz. "
            . "Run scripts/sync_ncbi_taxonomy_dump.php to download it. "
            . "Skipped organisms: $missing");
        return $lineage_cache;
    }

    $taxid_set = [];
    foreach ($to_fetch as $data) {
        if (!empty($data['taxon_id'])) $taxid_set[(string)$data['taxon_id']] = true;
    }

    $from_dump = ncbi_scan_local_dump($taxid_set, $stored_gz);
    foreach ($from_dump as $tid => $entry) {
        $lineage_cache[$tid] = $entry;
    }

    // Report any taxon_ids that weren't found in the dump (dump may be stale)
    $still_missing = [];
    foreach ($to_fetch as $org_name => $data) {
        if (!isset($lineage_cache[(string)$data['taxon_id']])) {
            $still_missing[] = "$org_name (taxon_id={$data['taxon_id']})";
        }
    }
    if (!empty($still_missing)) {
        error_log("refresh_lineage_cache: " . count($still_missing) . " taxon_id(s) not found in local dump — "
            . "dump may be stale. Re-run scripts/sync_ncbi_taxonomy_dump.php. "
            . "Missing: " . implode(', ', $still_missing));
    }

    return $lineage_cache;
}

function build_tree_from_lineage_cache($organisms, $lineage_cache) {
    $tree = ['name' => 'Life', 'children' => []];

    foreach ($organisms as $org_name => $data) {
        if (empty($data['taxon_id'])) continue;
        $tid = (string)$data['taxon_id'];
        if (empty($lineage_cache[$tid]['lineage'])) continue;

        // The LAST entry is the taxon itself (rankedlineage's tax_name column), whatever its
        // rank -- ncbi_scan_local_dump() labels it 'species' even for a genus. An unnamed
        // species ("Girardia sp.") carries its GENUS id; until 2026-10-30 its last step matched
        // the genus node a named species had made, so no leaf was ever added and the organism
        // vanished from the tree (and the homepage selector) with only "Not in tree" to say so.
        $levels = $lineage_cache[$tid]['lineage'];
        $own    = array_pop($levels);
        $genus_level = strpos(trim($own['name']), ' ') === false;   // not a binomial: a genus id
        if ($genus_level) {
            $levels[] = ['rank' => 'genus', 'name' => $own['name']];
            $sp = trim((string)($data['species'] ?? ''));
            $leaf_name = trim(($data['genus'] ?? $own['name']) . ' ' . ($sp === '' || $sp === 'sp' ? 'sp.' : $sp));
        } else {
            $leaf_name = $own['name'];
        }

        $current = &$tree;
        foreach ($levels as $level) {
            $found = false;
            foreach ($current['children'] as &$child) {
                // Only an inner node can be walked into; a leaf of the same name is an organism.
                if ($child['name'] === $level['name'] && isset($child['children'])) {
                    $current = &$child;
                    $found = true;
                    break;
                }
            }
            unset($child);
            if (!$found) {
                $current['children'][] = ['name' => $level['name'], 'children' => []];
                $current = &$current['children'][count($current['children']) - 1];
            }
        }
        // Every organism gets its own leaf -- never merged into a node that happens to share
        // its name.
        $node = ['name' => $leaf_name, 'organism' => $org_name, 'common_name' => $data['common_name'] ?? ''];
        if (!empty($lineage_cache[$tid]['image'])) $node['image'] = $lineage_cache[$tid]['image'];
        $current['children'][] = $node;
        unset($current);
    }

    return ['tree' => $tree];
}

function moop_temp_dir_path(): string {
    $app = dirname(__DIR__);
    return dirname($app) . '/.' . basename($app) . '-tmp';
}

function moop_temp_dir(): string {
    static $dir = null;
    if ($dir !== null) return $dir;
    $want = moop_temp_dir_path();
    if (is_dir($want) && is_writable($want)) return $dir = $want;
    // is_writable() answers for whoever runs this: in a web request, apache. Logged only when the
    // directory exists but cannot be used; before setup it is simply not there yet.
    if (is_dir($want)) error_log("MOOP: temp dir $want is not writable by " . get_current_user() . '; using ' . sys_get_temp_dir());
    return $dir = sys_get_temp_dir();
}

function moop_hex_rgb(string $hex): ?array {
    if (!preg_match('/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i', $hex, $m)) return null;
    return [hexdec($m[1]), hexdec($m[2]), hexdec($m[3])];
}

function moop_rgb_hex(array $rgb): string {
    return sprintf('#%02x%02x%02x', ...array_map(fn($v) => max(0, min(255, (int) round($v))), $rgb));
}

functions.comment:
/**
* Site colors -- one main color repaints the whole site (cuttingclass, 2026-11-05).
*
* css/moop.css defines MOOP's palette as variables (--moop-tool-header, --moop-tool-hover,
* --moop-main-rgb, --moop-main-dark, --moop-main-tint, --moop-main-lightest, --moop-organism-header,
* --moop-main-strong, --moop-search-wash, --moop-assembly-header, --moop-action, --moop-action-hover, and the
* --moop-attention-* family), and every main-color use on the site
* goes through them. A site that sets 'theme_colors' in Site Configuration gets those variables
* RECOMPUTED from its colors, emitted after the stylesheets (moop_theme_style_tag()). A site that
* sets nothing gets nothing emitted -- simrbase's teal, byte for byte.
*
* Data colors are deliberately NOT themed: the expression scale, gene-type chips and result-count
* badges mean the same thing on every MOOP site.
*
* ONE implementation: the Site Configuration preview asks the server for the palette
* (admin/api/theme_preview.php) rather than repeating this arithmetic in JavaScript.
*/

/** '#rrggbb' -> [r, g, b] (0-255), or null. */
function moop_hex_rgb(string $hex): ?array {
if (!preg_match('/^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i', $hex, $m)) return null;
return [hexdec($m[1]), hexdec($m[2]), hexdec($m[3])];
}

function moop_rgb_hex(array $rgb): string {
return sprintf('#%02x%02x%02x', ...array_map(fn($v) => max(0, min(255, (int) round($v))), $rgb));
}

/** [r, g, b] -> [h 0-360, s 0-1, l 0-1]. */

functions.code:
function moop_rgb_hsl(array $rgb): array {
    [$r, $g, $b] = array_map(fn($v) => $v / 255, $rgb);
    $max = max($r, $g, $b); $min = min($r, $g, $b); $l = ($max + $min) / 2;
    if ($max === $min) return [0.0, 0.0, $l];
    $d = $max - $min;
    $s = $l > 0.5 ? $d / (2 - $max - $min) : $d / ($max + $min);
