if (isset($palette[$k]) && ($r = moop_contrast_with_white($palette[$k])) < 4.5) $out[$k] = $r;
}
return $out;
}

/** The lightest shade of $hex that carries white text at 4.5:1 -- the "use this instead" suggestion. */

