function moop_accessible_shade(string $hex): string {
    if (!moop_hex_rgb($hex)) return $hex;
    [$h, $s, $l] = moop_rgb_hsl(moop_hex_rgb($hex));
    $out = $hex;
    for (; $l > 0.05 && moop_contrast_with_white($out) < 4.5; $l -= 0.01) $out = moop_hsl_hex($h, $s, $l);
    return $out;
}

