/** Log $jar in as the admin in $login_file; for 'public', then enter the "view as PUBLIC" preview. */

functions.code:
function viewer_login(string $viewer, string $jar, string $site, string $login_file): void {
    $lines = is_readable($login_file) ? file($login_file, FILE_IGNORE_NEW_LINES) : [];
    if (count($lines) < 2) throw new RuntimeException("$viewer viewer needs $login_file (username, password)");
    $base = viewer_base($viewer, $site); $from = viewer_from($viewer);
    [, $login_page] = http("$base/login.php", $jar, null, $from);
    preg_match('/name="csrf_token" value="([^"]+)"/', $login_page, $m);
    http("$base/login.php", $jar, ['username' => trim($lines[0]), 'password' => $lines[1], 'csrf_token' => $m[1] ?? ''], $from);
    [$st, $dash] = http("$base/admin/admin.php", $jar, null, $from);
    if ($st !== 200) throw new RuntimeException("admin login failed (dashboard answered $st)");
    if ($viewer === 'public') {
        // Into the PUBLIC preview: what an anonymous visitor sees, minus the human check.
        http("$base/view_as.php", $jar, ['action' => 'enter', 'csrf_token' => csrf_from($dash)], $from);
        [, $home] = http("$base/index.php", $jar, null, $from);
        if (stripos($home, 'name="action" value="leave"') === false) throw new RuntimeException('could not enter the "view as PUBLIC" preview');
    }
}

function usage(): void {
    fwrite(STDERR, "usage: php scripts/render_compare.php capture <dir> | compare <dirA> <dirB> | check <baseline>\n"
                 . "       [--pages=FILE] [--login-file=FILE]\n");
    exit(2);
}

function normalise(string $body, array $rules): string {
    foreach ($rules as $patterns) {
        foreach ($patterns as $re) $body = preg_replace($re, '$1<blanked>', $body);
    }
    return $body;
}

function capture(string $dir, string $pages_file, string $login_file, string $site, array $rules): int {
    $pages = json_decode((string) @file_get_contents($pages_file), true);
    if (!is_array($pages) || !$pages) { fwrite(STDERR, "No pages in $pages_file\n"); return 2; }
    if (!is_dir($dir) && !mkdir($dir, 0700, true)) { fwrite(STDERR, "Cannot create $dir\n"); return 2; }

    $jars = [];
    $jar_for = function (string $viewer) use (&$jars, $site, $login_file): string {
        if (isset($jars[$viewer])) return $jars[$viewer];
        $jar = tempnam(sys_get_temp_dir(), 'rc_jar_');
        $jars[$viewer] = $jar;
        if ($viewer === 'admin' || $viewer === 'public') {
            viewer_login($viewer, $jar, $site, $login_file);
        }
        return $jar;
    };

    $n = 0; $bad = 0;
    foreach ($pages as $p) {
        $name = $p['name'] ?? ''; $viewer = $p['viewer'] ?? 'public'; $path = $p['path'] ?? '';
        if (!preg_match('/^[A-Za-z0-9_.-]+$/', $name) || $path === '') { fwrite(STDERR, "skipping bad entry: " . json_encode($p) . "\n"); continue; }
        try {
            $jar  = $jar_for($viewer);
            $base = viewer_base($viewer, $site); $from = viewer_from($viewer);
            if (isset($p['post'])) {
                [, $form] = http($base . ($p['form'] ?? $path), $jar, null, $from);   // a POST needs this session's token
                [$st, $body] = http($base . $path, $jar, $p['post'] + ['csrf_token' => csrf_from($form)], $from);
            } else {
                [$st, $body] = http($base . $path, $jar, null, $from);
            }
        } catch (Throwable $e) {
            fwrite(STDERR, "  $name: " . $e->getMessage() . "\n"); $bad++; continue;
        }
        file_put_contents("$dir/$viewer.$name.html", "HTTP $st\n" . normalise($body, $rules));
        printf("  %-8s %-34s %d  %7d bytes\n", $viewer, $name, $st, strlen($body));
        $n++;
    }
    foreach ($jars as $j) @unlink($j);
    file_put_contents("$dir/.captured", date('c') . "\n" . implode("\n", array_keys($rules)) . "\n");
    echo "Captured $n pages into $dir" . ($bad ? " ($bad failed)" : '') . "\n";
    return $bad ? 1 : 0;
}

function compare(string $a, string $b, array $rules): int {
    $files = array_unique(array_merge(array_map('basename', glob("$a/*.html") ?: []), array_map('basename', glob("$b/*.html") ?: [])));
    sort($files);
    if (!$files) { fwrite(STDERR, "Nothing to compare\n"); return 2; }
    $changed = [];
    foreach ($files as $f) {
        $x = @file_get_contents("$a/$f"); $y = @file_get_contents("$b/$f");
        if ($x === false || $y === false) { $changed[$f] = $x === false ? 'only in ' . $b : 'only in ' . $a; continue; }
        if ($x !== $y) $changed[$f] = 'differs';
    }
    echo "Blanked before comparing: " . implode(', ', array_keys($rules)) . "\n";
    if (!$changed) { echo "IDENTICAL: all " . count($files) . " pages match.\n"; return 0; }
    echo count($changed) . " of " . count($files) . " pages CHANGED:\n";
    foreach ($changed as $f => $why) {
        echo "\n=== $f ($why)\n";
        if ($why === 'differs') {
            passthru('diff -u ' . escapeshellarg("$a/$f") . ' ' . escapeshellarg("$b/$f") . ' | head -40');
        }
    }
    return 1;
}

function fail(string $msg, int $code = 1): void
{
    fwrite(STDERR, "reset_password: $msg\n");
    exit($code);
}

function read_hidden(string $prompt): string
{
    fwrite(STDOUT, $prompt);
    // Checked once, before anything is read: asking again after a piped read warns that
    // buffered input is lost. stream_isatty is core PHP (posix is not installed everywhere).
    static $tty = null;
    $tty ??= stream_isatty(STDIN);
    if ($tty) {
        shell_exec('stty -echo');
    }
    $line = fgets(STDIN);
    if ($tty) {
        shell_exec('stty echo');
        fwrite(STDOUT, "\n");
    }
    if ($line === false) {
        fail('no password entered');
    }
    return rtrim($line, "\r\n");
}

function label_name(string $label, string $id): string {
    // The app shows "Szt2 | NV2g000006000.1" for a named gene and the bare ID otherwise.
    $label = trim($label);
    if ($label === $id) return '';
    $suffix = ' | ' . $id;
    return substr($label, -strlen($suffix)) === $suffix ? trim(substr($label, 0, -strlen($suffix))) : $label;
}

function getPasswordInput() {
    if (PHP_OS_FAMILY === 'Windows') {
        // Windows doesn't support stty, so we echo the input
        $handle = fopen('php://stdin', 'r');
        $password = trim(fgets($handle));
        fclose($handle);
        echo "\n";
        return $password;
    } else {
        // Unix/Linux: disable terminal echo
        system('stty -echo');
        $handle = fopen('php://stdin', 'r');
        $password = trim(fgets($handle));
        fclose($handle);
        system('stty echo');
        echo "\n";
        return $password;
    }
}

function pass($label) {
    global $passes;
    $passes++;
    echo "  " . C_GREEN . "[PASS]" . C_RESET . " $label\n";
}

function fail($label, $fix = '') {
    global $fails;
