function detectWebUser() {
    $user  = 'www-data';
    $group = 'www-data';

    // Look for non-root worker processes. PHP-FPM is checked first because
    // it's the process that actually runs PHP — its user is what matters for
    // file permissions, even if a different user runs the nginx/httpd frontend.
    $detect_cmds = [
        "ps -eo user,comm --no-headers | awk '\$2 ~ /php-fpm/ && \$1 != \"root\" {print \$1; exit}'",
        "ps -eo user,comm --no-headers | awk '\$2 ~ /apache2|httpd/ && \$1 != \"root\" {print \$1; exit}'",
        "ps -eo user,comm --no-headers | awk '\$2 ~ /nginx/ && \$1 != \"root\" {print \$1; exit}'",
    ];

    foreach ($detect_cmds as $cmd) {
        $output = [];
        @exec($cmd, $output);
        $detected = trim($output[0] ?? '');
        if (!empty($detected)) {
            $user = $detected;
            // Resolve primary group for this user
            if (function_exists('posix_getpwnam')) {
                $pwinfo = posix_getpwnam($user);
                if ($pwinfo !== false) {
                    $grinfo = posix_getgrgid($pwinfo['gid']);
                    if ($grinfo !== false) {
                        $group = $grinfo['name'];
                    }
                }
            } else {
                // Fallback without posix: parse `id` command output
                $id_output = [];
                @exec("id " . escapeshellarg($user) . " 2>/dev/null", $id_output);
                if (!empty($id_output[0]) && preg_match('/gid=\d+\(([^)]+)\)/', $id_output[0], $m)) {
                    $group = $m[1];
                }
            }
            break;
        }
    }

    return ['user' => $user, 'group' => $group];
}

function detectWebServer() {
    static $flavor = null;
    if ($flavor !== null) return $flavor;

    $out = [];
    @exec("ps -eo comm --no-headers 2>/dev/null | sort -u", $out);
    $procs = implode(' ', $out);
    if (preg_match('/\bnginx\b/', $procs))          return $flavor = 'nginx';
    if (preg_match('/\b(apache2|httpd)\b/', $procs)) return $flavor = 'apache';

    // Nothing running (fresh install, or checking before starting the server).
    if (is_dir('/etc/nginx'))                        return $flavor = 'nginx';
    if (is_dir('/etc/httpd') || is_dir('/etc/apache2')) return $flavor = 'apache';
    return $flavor = 'unknown';
}

function webUserIds($web_user, $web_group) {
    static $ids = null;
    if ($ids !== null) return $ids;

    $uid = $gid = null;
    if (function_exists('posix_getpwnam')) {
        $p = @posix_getpwnam($web_user);
        if (is_array($p)) $uid = (int) $p['uid'];
        $g = @posix_getgrnam($web_group);
        if (is_array($g)) $gid = (int) $g['gid'];
    }
    if ($uid === null) {
        $o = [];
        @exec('id -u ' . escapeshellarg($web_user) . ' 2>/dev/null', $o);
        if (!empty($o[0]) && ctype_digit(trim($o[0]))) $uid = (int) trim($o[0]);
    }
    if ($gid === null) {
        $o = [];
        @exec('getent group ' . escapeshellarg($web_group) . ' 2>/dev/null', $o);
        if (!empty($o[0])) {
            $parts = explode(':', $o[0]);
            if (isset($parts[2]) && ctype_digit($parts[2])) $gid = (int) $parts[2];
        }
    }
    return $ids = ['uid' => $uid, 'gid' => $gid];
}

function webCanWrite($path, $web_user, $web_group) {
    $st = @stat($path);
    if ($st === false) return false;

    $mode = $st['mode'];
    $ids  = webUserIds($web_user, $web_group);

    if ($ids['uid'] !== null && $st['uid'] === $ids['uid'] && ($mode & 0200)) return true; // owner
    if ($ids['gid'] !== null && $st['gid'] === $ids['gid'] && ($mode & 0020)) return true; // group
    if ($mode & 0002) return true;                                                         // world
    // Ids unresolvable (no posix, no id/getent): fall back rather than cry wolf.
    if ($ids['uid'] === null && $ids['gid'] === null) return is_writable($path);
    return false;
}

function toolExists($tool) {
    return moop_find_executable($tool) !== '';
}

function getWebUser() {
    $user  = 'www-data';
    $group = 'www-data';

    if (function_exists('posix_getuid')) {
        $pwinfo = posix_getpwuid(posix_getuid());
        if ($pwinfo !== false) {
            $user = $pwinfo['name'];
        }
        $grinfo = posix_getgrgid(posix_getgid());
        if ($grinfo !== false) {
            $group = $grinfo['name'];
        }
    } else {
        // Fallback without posix: parse `id` command output
        $id_output = [];
        @exec("id 2>/dev/null", $id_output);
        if (!empty($id_output[0])) {
            if (preg_match('/uid=\d+\(([^)]+)\)/', $id_output[0], $m)) {
                $user = $m[1];
            }
            if (preg_match('/gid=\d+\(([^)]+)\)/', $id_output[0], $m)) {
                $group = $m[1];
            }
        }
    }

    return ['user' => $user, 'group' => $group];
}

function toolExists($tool) {
    return moop_find_executable($tool) !== '';
}

functions.comment:
/**
* Run all environment checks. Returns array of check results.
*/

functions.code:
function checkEnvironment($base, $config) {
    $checks = [];

    // PHP version
    $checks[] = [
        'label' => 'PHP ' . PHP_VERSION,
        'status' => version_compare(PHP_VERSION, '8.0.0', '>=') ? 'pass' : 'fail',
        'detail' => 'Requires 8.0+',
        'category' => 'PHP',
    ];

    // Required extensions
    $extensions = ['sqlite3', 'pdo_sqlite', 'mbstring', 'json', 'openssl', 'curl'];
    foreach ($extensions as $ext) {
        $checks[] = [
            'label' => "Extension: $ext",
            'status' => extension_loaded($ext) ? 'pass' : 'fail',
            'category' => 'PHP',
        ];
    }

    // Optional extension
    $checks[] = [
        'label' => 'Extension: posix',
        'status' => extension_loaded('posix') ? 'pass' : 'warn',
        'detail' => 'Optional — permission detection uses fallback if missing',
        'category' => 'PHP',
    ];

    // CLI tools
    $tools = [
        'blastn'          => ['required' => true],
        'blast_formatter' => ['required' => true,  'detail' => 'Part of NCBI BLAST+ suite — required for BLAST result display'],
        'blastdbcmd'      => ['required' => true,  'detail' => 'Part of NCBI BLAST+ suite — required for sequence retrieval'],
        'samtools'        => ['required' => true],
        'tabix'           => ['required' => true],
        'bgzip'           => ['required' => true],
        'sqlite3'         => ['required' => true],
        'jbrowse'         => ['required' => false, 'detail' => 'Optional — required for JBrowse text-index (gene name search in browser)'],
        'bigWigSummary'   => ['required' => false, 'detail' => 'Optional — required for the RNA-seq Expression Explorer'],
        'jq'              => ['required' => false],
    ];

    foreach ($tools as $tool => $info) {
        $exists = toolExists($tool);
        $checks[] = [
            'label' => $tool,
            'status' => $exists ? 'pass' : ($info['required'] ? 'fail' : 'warn'),
            'detail' => $exists ? '' : ($info['detail'] ?? ($info['required'] ? 'Required' : 'Optional')),
            'category' => 'CLI Tools',
        ];
    }

    // Composer
    $hasComposer = toolExists('composer') || file_exists("$base/composer.phar");
    $checks[] = [
        'label' => 'composer',
        'status' => $hasComposer ? 'pass' : 'fail',
        'category' => 'CLI Tools',
    ];

    return $checks;
}

function _downloads_format_size(int $bytes): string {
    if ($bytes >= 1073741824) return round($bytes / 1073741824, 1) . ' GB';
    if ($bytes >= 1048576)    return round($bytes / 1048576,    1) . ' MB';
    if ($bytes >= 1024)       return round($bytes / 1024,       1) . ' KB';
    return $bytes . ' B';
}

function _downloads_list_files(string $dir, array $excluded_exts, array $excluded_filenames, array $ext_priority): array {
    $files = [];
    foreach (scandir($dir) as $fname) {
        if ($fname === '.' || $fname === '..') continue;
        $fpath = "$dir/$fname";
        if (!is_file($fpath)) continue;
        $ext = strtolower(pathinfo($fname, PATHINFO_EXTENSION));
        if (isset($excluded_exts[$ext]))       continue;
        if (isset($excluded_filenames[$fname])) continue;

        $size = (int) filesize($fpath);

        // Determine display color class from the CONFIGURED sequence-type patterns.
        // These four filenames used to be hardcoded here, which made this comment untrue:
        // renaming a pattern in Site Configuration left the matching files uncoloured.
        // The colour per type stays local — it is a download-list text colour, deliberately
        // not the badge background in sequence_types[*]['color'].
        static $seq_type_colors = [
            'protein'    => 'feature-color-protein',
            'transcript' => 'feature-color-mrna',
            'cds'        => 'feature-color-gene',
            'genome'     => 'text-assembly',
        ];
        $color_class = '';
        $fname_lower = strtolower($fname);
        foreach (ConfigManager::getInstance()->getSequenceTypes() as $seq_type => $seq_config) {
            $pattern = strtolower($seq_config['pattern'] ?? '');
            if ($pattern !== '' && isset($seq_type_colors[$seq_type]) && str_contains($fname_lower, $pattern)) {
                $color_class = $seq_type_colors[$seq_type];
                break;
            }
        }
        if ($color_class === '' && in_array($ext, ['gff', 'gff3', 'gtf'])) $color_class = 'text-success';

        $files[] = [
            'name'        => $fname,
            'size'        => $size,
            'size_label'  => _downloads_format_size($size),
            'color_class' => $color_class,
        ];
    }

    usort($files, function ($a, $b) use ($ext_priority) {
        $ea = strtolower(pathinfo($a['name'], PATHINFO_EXTENSION));
        $eb = strtolower(pathinfo($b['name'], PATHINFO_EXTENSION));
        $pa = $ext_priority[$ea] ?? 999;
        $pb = $ext_priority[$eb] ?? 999;
        return $pa !== $pb ? $pa - $pb : strcmp($a['name'], $b['name']);
    });

    return $files;
}

function moop_js_body_end(string $code, int $start): int {
    $len = strlen($code);
    // Where does the body begin? After "=>" for arrows, else at the first "{" after the ")".
    $head = substr($code, $start, 600);
    $arrow = preg_match('/^[^{;]*?=>\s*/s', $head, $am) ? $start + strlen($am[0]) : null;
    if ($arrow !== null && ($code[$arrow] ?? '') !== '{') {
        // Expression body: up to the ; or newline at depth 0.
        $depth = 0;
        for ($i = $arrow; $i < $len; $i++) {
            $c = $code[$i];
            if ($c === '(' || $c === '[' || $c === '{') $depth++;
            elseif ($c === ')' || $c === ']' || $c === '}') { if (--$depth < 0) return $i; }
            elseif (($c === ';' || $c === "\n") && $depth === 0) return $i;
        }
        return $len;
    }
    $i = $arrow ?? $start;
    $depth = 0;
    $opened = false;
    for (; $i < $len; $i++) {
        $c = $code[$i];
        if ($c === "'" || $c === '"' || $c === '`') {
            for ($i++; $i < $len && $code[$i] !== $c; $i++) {
                if ($code[$i] === '\\') $i++;
            }
            continue;
        }
        if ($c === '/' && ($code[$i + 1] ?? '') === '*') {
            $close = strpos($code, '*/', $i + 2);
            $i = $close === false ? $len : $close + 1;
            continue;
        }
        if ($c === '/' && ($code[$i + 1] ?? '') === '/') {
            $nl = strpos($code, "\n", $i);
            $i = $nl === false ? $len : $nl;
            continue;
        }
        if ($c === '{') { $depth++; $opened = true; }
        elseif ($c === '}' && --$depth === 0 && $opened) return $i + 1;
    }
    return $len;
}

