/**
* Determine tags for JS function
*/

functions.code:
function determineJsTags($comment, $code, $funcName) {
    $tags = [];

    // DOM manipulation
    // Changes the page (reading it with getElementById/querySelector is not manipulation).
    if (preg_match('/\.(?:innerHTML|outerHTML|textContent|value)\s*=(?!=)|\b(?:appendChild|removeChild|insertBefore|insertAdjacentHTML|replaceChildren|setAttribute|removeAttribute)\s*\(|\.classList\.(?:add|remove|toggle)\s*\(|\.style\.\w+\s*=(?!=)|\$\([^)]*\)\.(?:html|append|prepend|empty|remove|addClass|removeClass|toggleClass|show|hide|text)\s*\(/', $code)) {
        $tags[] = 'dom-manipulation';
    }

    // Asynchronous
    if (preg_match('/\basync\b|\bawait\b|\.then\s*\(|\bPromise\b|\bsetTimeout\s*\(|\bsetInterval\s*\(/', $code)) {
        $tags[] = 'asynchronous';
    }

    // AJAX/HTTP
    // Network calls. The old /\.get/i matched every getElementById and getAttribute.
    if (preg_match('/\bfetch\s*\(|\bXMLHttpRequest\b|\$\.(?:ajax|get|post|getJSON)\s*\(|\.ajax\s*\(|\bnavigator\.sendBeacon\s*\(/', $code)) {
        $tags[] = 'ajax';
    }

    // Event listener
    // /on\w+\s*=/i used to match "const option =", "json =" ...
    if (preg_match('/\baddEventListener\s*\(|\.on[a-z]+\s*=(?!=)|\.on\s*\(|\.(?:click|change|submit|keyup|keydown)\s*\(\s*(?:function|\()/', $code)) {
        $tags[] = 'event-listener';
    }

    // State modification
    // Changes something OUTSIDE its own local variables: a property, an array element, a
    // global, or a mutating array call. (The old /\w+\s*=/ matched any assignment -- even
    // "===" -- so 480 of 587 functions were "state modifying".)
    if (preg_match('/(?:[\w$\])]\.[\w$]+|\])\s*(?:[+\-*\/|&]?=)(?!=)|\b(?:window|globalThis)\.\w+\s*=(?!=)|\.(?:push|pop|shift|unshift|splice|sort|reverse)\s*\(|\bdelete\s+[\w$]/', $code)) {
        $tags[] = 'state-modifying';
    }

    // Loop operations
    if (preg_match('/forEach|for\s*\(|while\s*\(/i', $code)) {
        $tags[] = 'loops';
    }

    // Error handling
    if (preg_match('/\btry\s*\{|\.catch\s*\(|\bthrow\b|\bonerror\b|\.fail\s*\(|\berror\s*:\s*(?:function|\()/', $code)) {
        $tags[] = 'error-handling';
    }

    // Validation
    // 'check' alone matched every ".checked".
    if (preg_match('/\bvalidat\w*|\bverify\w*|\bcheckValidity\s*\(|\bisValid\w*/i', $code)) {
        $tags[] = 'validation';
    }

    return array_values(array_unique($tags));
}

function moop_gene_not_found(string $uniquename, string $organism_name = '', string $organism_label = '',
                             ?array $browser_only = null): void {
    global $site;
    http_response_code(404);
    echo render_display_page(__DIR__ . '/pages/gene_not_found.php', [
        'uniquename' => $uniquename, 'organism_name' => $organism_name,
        'organism_label' => $organism_label, 'site' => $site, 'browser_only' => $browser_only,
    ], 'Gene not found');
    exit;
}

function moop_gene_browser_only(string $organism, string $assembly, string $gene_set, string $id): ?array {
    if ($organism === '' || $assembly === '' || $gene_set === '' || $id === '') return null;
    require_once __DIR__ . '/../lib/jbrowse/config_functions.php';
    require_once __DIR__ . '/../lib/feature_coords.php';
    // The access list holds only real names, so this is also the path check.
    if (!moop_jbrowse_can_open_gene_set($organism, $assembly, $gene_set)) return null;
    $dir = ConfigManager::getInstance()->getPath('organism_data') . "/$organism/$assembly/$gene_set";
    $row = moop_feature_coords_find($dir, $id);
    if (!$row) return null;
    $url = moop_tool_on('genome_browser')
        ? moop_url('jbrowse2.php') . '?' . http_build_query([
            'organism' => $organism, 'assembly' => $assembly,
            'loc' => $row['chr'] . ':' . $row['start'] . '-' . $row['end']])
        : null;
    return ['chr' => $row['chr'], 'start' => $row['start'], 'end' => $row['end'], 'browser_url' => $url];
}

function view_as_return_target($site) {
    $candidate = $_POST['return'] ?? ($_SERVER['HTTP_REFERER'] ?? '');

    if ($candidate !== '') {
        // Strip any scheme/host: keep only the path+query the browser should go to.
        $path = parse_url($candidate, PHP_URL_PATH);
        $query = parse_url($candidate, PHP_URL_QUERY);

        // Must be an absolute path on this site, and must not be "//evil.com" (which a
        // browser reads as a protocol-relative URL to another host).
        if (is_string($path) && $path !== '' && $path[0] === '/' && strpos($path, '//') !== 0) {
            return $path . ($query ? '?' . $query : '');
        }
    }

    return moop_url_base() . '/index.php';
}
